window.__D("text/zohar-chadash/c008",{"p":[[9514015021,"<p>וְעָאל וְחָמֵי הַהוּא רְקִיעָא דְּעַל גַּבֵּי הַהוּא גִּנְתָא. דְּהַהוּא רְקִיעָא אִתְפְּרַשׁ מֵהַהוּא רָקִיעַ דְּקָאִים עַל שְׁאָר בְּנֵי עָלְמָא. רָקִיעַ דָּא אִתְתְּחַם בִּתְחוּמָא מִכָּל גְּוָונִין דְּעָלְמָא. אַרְבַּע חַלּוֹנֵי מַשְׁקוֹפִין פְּתִיחִין בֵּיהּ בְּאַרְבַּע סִיטְרֵי עָלְמָא, וְחַד בְּאֶמְצָעִיתָא.</p>"],[9514015022,"<p>חַלּוֹן חַד דְּבִסְטַר מִזְרָח, בֵּיהּ קָיְימִין אַרְבַּע מַשְׁקוֹפִין מְרַקְמָן, בְּרָזָא דְּאַרְבַּע אַתְוָון יהו\"ה, סָלְקִין לִתְרֵיסַר, תְּלַת אַתְוָון לְכָל חַד וְחַד.</p>"],[9514015023,"<p>תְּלַת זִמְנֵי בְּיוֹמָא, מִתְחַבְּרָן אִינוּן מַשְׁקוֹפִין, וְאַתְוָון כּוּלְּהוּ מִתְחַבְּרָן לִשְׁמָא קַדִּישָׁא. חַד מְמַנָּא קָיְימָא לְהַהוּא סִטְרָא, יעזריאל שְׁמֵיהּ. וְאַרְבַּע מַפְתְּחִין בִּידֵיהּ, דְּאִיהוּ פָּתַח בְּהוּ אַרְבָּעָה תַּרְעִין, דְּאִינוּן עַל גַּבֵּיהּ דְּהַהוּא רְקִיעָא. וְלֵית מַאן דְּיָדַע בְּהוּ.</p>"],[9514015024,"<p>בַּר בְּרֵישׁ יַרְחֵי וְשַׁבַּתֵּי, דְּאַתְיָין אִינוּן נַפְשָׁן דְּמִשְׁתַּתְּפָן עִם גּוּפָא בְּקִבְרֵי, לְמִכְרַע וּלְמִסְגַּד קַמֵּי אִינוּן תַּרְעִין לְמָארֵי כּוֹלָּא. כְּמָה דְאַתְּ אָמֵר, (ישעיה סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ יָבוֹא כָל בָּשָׂר לְהִשְׁתַּחֲוֹת לְפָנַי. כָּל, לְאַסְגָּאָה אִינוּן נַפְשָׁאן דְּדָיְירֵי עִם גּוּפָא, וְאִיתְקְרוּן כָּל בָּשָׂר.</p>"],[9514015025,"<p>חַלּוֹן אָחֳרָא דְּבִסְטַר דָּרוֹם, בֵּיהּ קָיְימִין שִׁית מַשְׁקוֹפִין, לָא עָאלִין לְהַאי אֲתַר, אֶלָּא אִינוּן דְּלָעָן קְרִיאַת שְׁמַע בִּרְעוּתָא, וּבְכַוָּנָה בְּכָל יוֹמָא.</p>"],[9514015026,"<p>אֲמַר רַבִּי פְּרַחְיָא, הָאֱלֹהִים, כַּד אִסְתַּכַּלְנָא בְּהַהוּא חַלּוֹנָא, קָרֵיב הַהוּא מְמַנָּא, וענאל שְׁמֵיהּ, דִּי מְמוּנֶּה עַל תַּרְעָא דִּסְטַר דָּרוֹם, אֲמַר לִי, קוּם בְּקִיּוּמָךְ, וְחָמֵי הַאי חַלּוֹן, דְּלֵית רְשׁוּ לְאָעֳלָא תַּמָּן, וְלָא לְמֶחֱמֵי בֵּיהּ, בַּר אִינוּן דְּלָעָן בִּקְרִיאַת שְׁמַע כִּדְקָא יָאוֹת.</p>"],[9514015027,"<p>וְכָל אִינוּן דְּלָעָאן בִּקְרִיאַת שְׁמַע כִּדְקָא יָאוֹת, שִׁתִּין מְמַנָּן עָאלִין קַמֵּיהּ, וּמַכְתִּירִין לֵיהּ בְּכִתְרִין קַדִּישִׁין, וְאָמְרִין לֵיהּ, דָּא הוּא כִּתְרָא דִּפְלוֹנִי דְּלָעָא בִּקְרִיאַת שְׁמַע כִּדְקָא יָאוֹת.</p>"],[9514015028,"<p>שְׁאֵילְנָא לֵיהּ, וְאָמְרֵי לֵיהּ, מָארֵי, הַאי קְרִיאַת שְׁמַע כִּדְקָא יָאוֹת מָה הוּא. אֲמַר לִי, אִי חֲסִידָא, רָזָא עִילָּאָה אִיהוּ הָכָא. בִּקְרִיאַת שְׁמַע אִית בָּהּ אַרְבַּע פָּרְשְׁיָין.</p>"],[9514015029,"<p>פָּרָשָׁה קַדְמָאָה דְּיִחוּדָא, דְּאִיהוּ תְּרֵין יִחוּדִין, בִּתְרֵיסַר תֵּיבִין. שִׁית תֵּיבִין בְּיִחוּדָא עִילָּאָה. וְשִׁית תֵּיבֵין בְּיִחוּדָא אָחֳרָא. פָּרָשָׁה תִּנְיָינָא וְאָהַבְתָּ, בְּמ\"ב תֵּיבִין, בְּרָזָא דְשֵׁם דמ\"ב אַתְוָון.</p>"],[9514015030,"<p>פָּרָשָׁה תְּלִיתָאָה, וְהָיָה אִם שָׁמוֹעַ, דְּאִתְכְּלֵיל יְמִינָא בִּשְׂמָאלָא, וּשְׂמָאלָא בִּימִינָא. וְאִיהוּ בְּרָזָא וְסִתְרָא דִּרְתִיכָא קַדִּישָׁא, עַד וְשַׂמְתֶּם. דְּאִיהוּ פָּרְשָׁתָא דְּשָׁלְטָא עַל כּוֹלָּא. אִיהִי בְּרָזָא דְּע\"ב תֵּיבִין, גּוֹ רָזָא דְּע\"ב שְׁמָהָן דִּרְתִיכָא קַדִּישָׁא.</p>"],[9514015031,"<p>פָּרָשָׁה רְבִיעָאָה, וְשַׂמְתֶּם, דְּאִיהִי חַמְשִׁין תֵּיבִין, דְּאִיהוּ לָקֳבֵיל חַמְשִׁין תַּרְעִין דְּבִינָה. פָּרָשָׁה דְצִיצִית כְּלִילָא מִכּוּלְּהוּ. וְסָלְקִין פָּרְשְׁיָין לְמִנְיָינָא דְּאָדָם.</p>"],[9514015032,"<p>וְכָל שְׁאָר דּוּכְתִּין, בֵּין בְּפִקּוּדֵי דְאוֹרַיְיתָא, בֵּין כָּל שְׁאָר דּוּכְתֵּי דְאוֹרַיְיתָא, דְּכוּרָא לְחוּד, וְנוּקְבָא לְחוּד. וְהָכָא דְּאִיהוּ יִיחוּדָא, דְּאִתְיַיחֵד בֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, דְּכַר וְנוּקְבָא אִתְכְּנִישׁוּ כַּחֲדָא, וְסָלְקִין בְּשִׁעוּרָא חָדָא.</p>"],[9514015033,"<p>דְּכוּרָא אִשְׁתְּלֵים בָּהּ, מַה דְּלָאו הָכֵי בְּכָל שְׁאָר דּוּכְתֵּי דְאוֹרַיְיתָא. וְדָא שִׁבְחָא דִּמְהֵימְנוּתָא עִילָּאָה, לְמִנְדַע דְּהָא ה' הוּא הָאֱלֹהִים. דְּכוּרָא אִשְׁתְּלֵים בְּנוּקְבָא, וְאִתְכְּלֵל חַד בְּחַד, דְּכוּרָא אִתְבְּנֵי בְּנוּקְבָא. וְדָא אִיהוּ יִיחוּדָא שְׁלִים, וְלָא אִית שְׁלִימוּ אֶלָּא דְכוּרָא וְנוּקְבָא כַּחֲדָא.</p>"],[9514015034,"<p>וְתָא חֲזֵי, כָּל מַאן דְּאַשְׁלֵים יִיחוּדָא כִּדְקָא יָאוֹת, וּמְכַוֵּין בְּפָרָשִׁיּוֹת אִלֵּין בְּכָל יוֹמָא. זָכֵי לְאִלֵּין מַשְׁקוֹפִין וְחַלּוֹנִין, לְמֶהֱוֵי שְׁלִים הָכָא. וְלֵית מַאן דִּיעַכֵּב עַל יְדוֹי, וּבִלְבָד דְּיִקְּרֵי כִּדְקָא יָאוֹת, וִיכַוֵּין בְּהַנֵּי רָזִין עִילָּאִין.</p>"],[9514015035,"<p>וְאָחֵיה בִּימִינָא דִילִי וְאָמַר לֵיהּ, אִי חֲסִידָא, תָּא חָמֵי יְקָר דְּאִינוּן דִּמְיַחֲדֵי שְׁמָא קַדִּישָׁא כִּדְקָא יָאוּת, וְלָעָאן בִּקְרִיאַת שְׁמַע כְּגַוְונָא דָא.</p>"],[9514015036,"<p>אָעֵילְנָא בְּחַד הֵיכָלָא, וּבְהַהוּא הֵיכָלָא הֲווֹ שס\"ה הֵיכָלִים, כְּחוּשְׁבַּן יוֹמֵי שַׁתָּא. אַבְרָהָם יִצְחָק וְיַעֲקֹב שַׁלִּיטִין בְּהַהוּא הֵיכָלָא, וְאָדָם הָרִאשׁוֹן בְּגַוַּיְיהוּ.</p>"],[9514015037,"<p>וְחָמֵינָא כַּמָּה חֲבִילֵי נִשְׁמָתִין, מִתְלַבְּשִׁין בִּרְקִימוּ דְּאִילָנָא דְחַיֵּי, וְכַמָּה גְוָונִין דִּיְקָרָא עִילָּאָה. וְעַיְילִין גּוֹ הֵיכָלָא, וְיופיאל רַב מְמַנָּא עַל כּוֹלָּא, רַב מְמַנָּא דְאוֹרַיְיתָא בַּהֲדַיְיהוּ.</p>"],[9514015038,"<p>פָּתַח וְאָמַר, אִתְעָרוּ קַדִּישֵׁי עַלְמָא, הָא בְּנֵיכוֹן קַדִּישִׁין, דְּקָא מְיַיחֲדֵי שְׁמָא קַדִּישָׁא, וּמְכַוְּונֵי בִּרְעוּתָא דְפָרְשְׁיָין דִּקְרִיאַת שְׁמַע.</p>"],[9514015039,"<p>וְאָדָם הָרִאשׁוֹן חָמֵינָא דְּמִשְׁתַּדֵּל בְּהוּ. וּבְשַׁעֲתָא דְּעָאלַת קְרִיאַת שְׁמַע דְּקָרֵי בַּר נָשׁ, סְלִיקָא בְּקַדְמִיתָא לְהַאי הֵיכָלָא, וְאָרַח בָּהּ אָדָם הָרִאשׁוֹן, אִי חָסַר אוֹת אַחַת מִקְּרִיַּת שְׁמַע, לָא מְקַבֵּל לָהּ. דְּהָא חָסֵר בִּנְיָינָא דְאָדָם, דְּאִיהוּ רמ\"ח, בְּאִינוּן תֵּיבִין דְּחוֹזֵר שְׁלִיחַ צִבּוּר.</p>"],[9514015040,"<p>וְאִי אַשְׁכַּח יָתָהּ כִּדְקָא יָאוֹת, מְקַבֵּל לָהּ, וְנָטְלִין אַבְרָהָם יִצְחָק וְיַעֲקֹב מִנֵּיהּ, וְנָשְׁקִין לָהּ. מַאן חָמֵי חֶדְוָה, מַאן חָמֵי עִרְבּוּבְיָא, בְּכָל אִינוּן צַדִּיקַיָּיא דִּבְגִינְתָּא דְעֵדֶן, דְּקָא אַתְיָין בְּהַהוּא חֶדְוָה.</p>"],[9514015041,"<p>וּבְשַׁעֲתָא דְיֵיתֵי לְהַהוּא עַלְמָא, מַאן יֶחֱמֵי חֶדְוָה דִילֵיהּ, דְּאוֹתְבִין לֵיהּ אֲבָהָן לְגַבַּיְיהוּ תְּרֵי זִימְנֵי בְּיוֹמָא, וּבְכָל יוֹמָא נָחֵית עֲלֵיהּ טַלָּא מֵרֵישָׁא דְמַלְכָּא.</p>"],[9514015042,"<p>וּבְהַהוּא טַלָּא, יָדְעֵי וְאָכְלֵי מֵיכְלָא, דִּי מַלְאֲכֵי עִילָּאִין אָכְלִין. וְיָדְעִין מַה דְּהֲוָה, וּמַה דִּיהֱוֵי, וּמַה דְּזַמִּין לְמֶהֱוֵי, עַד זִמְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא יוֹקִים לְגוּפֵי דִסְרִיחָן בְּהַאי עַלְמָא, וְיוֹקִים לוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא, בְּבִנְיָינָא מִתְתַּקְּנָא כִּדְקָא יָאוֹת.</p>"],[9514015043,"<p>בְּחַלּוֹן דְּבִסְטַר דָּרוֹם, הֲווֹ רְשׁוּמִין ש', דְּבִסְטַר דָּא ו', וּבִסְטַר אָחֳרָא ו', וּבִסְטַר אָחֳרָא ו'. שְׁאֵילְנָא לְהַהוּא גַבְרָא, וַאֲמֵינָא, מַאי הַנֵּי אַתְוָון, אֲמַר לָא יְדַעְנָא.</p>"],[9514015044,"<p>עַד דַּאֲתָא הַהוּא מְמַנָּא, וַאֲמַר לִי, אִי חֲסִידָא, אִינוּן אַתְוָון, סִימָנִין דְּפָרְשִׁיָּיתָא דִּקְרִיַּת שְׁמַע. זַכָּאָה חוּלָקֵיהּ דְּמַאן דֲּאֲמַר לוֹן בְּכָל יוֹמָא בִּרְעוּתָא דְלִבָּא.</p>"],[9514015045,"<p>חַלּוֹן אָחֳרָא דְּבִסְטַר צָפוֹן, בֵּיהּ קָיְימָן תְּרֵין מַשְׁקוֹפִין, וְחָמֵשׁ אַתְוָון מְלַהֲטִין וּמִתְנַצְּצִין בְּגַוַּיְיהוּ. תְּרֵין אַתְוָון בְּסִטְרָא דָא, וּתְרֵין אַתְוָון בְּסִטְרָא דָא, וְחַד לְעֵילָא מִנַּיְיהוּ תַּלְיָא עֲלַיְיהוּ. וְאִינוּן בְּרָזָא דִּשְׁמָא קַדִּישָׁא אִיקְרֵי אֱלֹהִים.</p>"],[9514015046,"<p>בְּחַלּוֹן דָּא וּבְאִינוּן מַשְׁקוֹפִין, שַׁרְיָין תְּרֵין מְמַנָּן בְּהַהוּא רְקִיעָא, וְאִינוּן צורטק וְגזריאל, דִּי מְמַנָּן תַּמָּן בְּהַהוּא סִטְרָא דְּלָא אִתְפַּתְּחַת.</p>"],[9514015047,"<p>וְתַמָּן אִית חַד הֵיכָלָא, מְרַקְמָא בְּכַמָּה גְוָונִין, וְכַמָּה צִיּוּרִין. וּבֵיהּ קָיְימִין כָּל אִינוּן דִּמְקַדְּשֵׁי שְׁמָא דְמָארֵיהוֹן בַּאֲמִירָה בְּכָל יוֹמָא, לְבָתַר דִּמְבָרְכִין לֵיהּ, וְאוֹמְרִין בָּרוּךְ ה' הַמְבוֹרָךְ לְעוֹלָם וָעֶד, וּמַקְדִּישִׁים לֵיהּ לְבָתַר בִּקְדוּשָׁה מְשׁוּלֶשֶׁת.</p>"],[9514015048,"<p>וְהַהוּא הֵיכָלָא אִיקְרֵי מְשׁוּלָשׁ, כְּמָה דְאַתְּ אָמֵר, (ירמיהו ז׳:ד׳) הֵיכַל ה' הֵיכַל ה' הֵיכַל ה' הֵמָּה. וְהַהוּא הֵיכָלָא אִיהוּ מְשׁוּלָשׁ. וְשָׁאֵילְנָא מַאי הַאי. אֲמַר הַהוּא גַבְרָא, אִלֵּין אִינוּן דְּלָא אָכְלֵי כָּל יוֹמֵיהוֹן עַל דִּמְהוֹן.</p>"],[9514015049,"<p>בְּגִין דְּנִשְׁמָתָא דְּבַר נָשׁ בְּהַאי עַלְמָא, נָפְקַת מִינֵיהּ בְּכָל לֵילְיָא וְלֵילְיָא. בְּצַפְרָא אִתְהַדְּרָא לֵיהּ, וְשַׁרְיָיא בְּחוֹטְמָא דְבַר נָשׁ, וְלָא עָאלַת וְלָא אִתְיַישְׁבָא בְּמֵעוֹי, עַד דִּמְבָרֵךְ לְהַקָּדוֹשׁ בָּרוּךְ הוּא, ומַצְלֵי עַל דְּמֵיהּ, כְּדֵין מִתְיַיְשְׁבָא בְּדוּכְתָּהּ.</p>"],[9514015050,"<p>וְעַל דָּא כְּתִיב, (ישעיהו ב׳:כ״ב) חִדְּלוּ לָכֶם מִן הָאָדָם אֲשֶׁר נְשָׁמָה בְּאַפּוֹ. מַאי אֲשֶׁר נְשָׁמָה בְּאַפּוֹ. בְּגִין דְּנַחֲתָא בְּצַפְרָא, וְאוֹמֵר לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, זִילִי, וּשְׁרִי לֵיהּ בְּחוֹטְמוֹי, עַל מְנָת דְּיִצְלֵי צְלוֹתֵיהּ. אִי מְבָרֵךְ הוּא כִּדְקָא יָאוֹת, תִּשְׁרֵי בְּגַוֵּיהּ, וְאִי לָא, פָּרְחָא וּסְלֵיקַת, וְאִשְׁתַּכַּח בַּר נָשׁ דְּחַסְרָא מִינֵיהּ הַהוּא קְדוּשָׁתָא דְּנִשְׁמָתָא.</p>"],[9514015051,"<p>וְכֵיוָן דְּנִשְׁמָתֵיהּ חָסְרָא מִינֵיהּ, בַּמֶּה נֶחְשַׁב הוּא, לָא אִתְחַשַּׁב לִכְלוּם, כְּאִלּוּ לָא הֲוָה בְּעָלְמָא. וְעַל דָּא, אָסִיר לֵיהּ לְאִינִישׁ לְבָרְכָא לְחַבְרֵיהּ, עַד דִּמְבָרֵךְ לְמָארֵיהּ בְּשֵׁירוּתָא דִצְלוֹתָא.</p>"],[9514015052,"<p>וְהַחַזָּן אוֹמֵר בָּרְכוּ אֶת ה', וְהוּא אוֹמֵר בָּרוּךְ ה' הַמְבוֹרָךְ לְעוֹלָם וָעֶד. וְכֵיוָן דִּמְבָרֵךְ לְמָארֵיהּ, מִתַּמָּן שֵׁרוּתָא דִּצְלוֹתָא לְצַלָּאָה. וְעַל דָּא שְׁרִיאָן קְדוּשָׁאן. זַכָּאִין אִינוּן דִּמְבָרְכֵי וּמְקַדְּשֵׁי לְמָארֵיהוֹן בְּכָל יוֹמָא, בִּרְעוּתָא דְלִבָּא.</p>"],[9514015053,"<p>בְּהַהִיא שַׁעֲתָא אוֹלִיפְנָא, דְּלֵית רְשׁוּ לְצַלָּאָה צְלוֹתָא בַּעֲשָׂרָה, עַד דִּמְבָרְכִין לְּקוּדְשָׁא בְּרִיךְ הוּא בְּשֵׁירוּתָא דְּכוֹלָּא. וְכֵיוָן דִּמְבָרְכִין לֵיהּ, צַלּוּ צְלוֹתְהוֹן.</p>"],[9514015054,"<p>אֲמַר הַהוּא גַבְרָא, רַבִּי, הַהִיא בְּרָכָה, לָאו אִיהוּ אֶלָּא לְאַתְקָנָא שִׁבְחָא לְמָארֵיהוֹן. דְּאַהֲדַר לוֹן נִשְׁמַתְהוֹן, דְּאִיתְקַרְיָא בְּה' שְׁמָהָן. וּבִרְכְתָא בְּה' תֵּיבִין, בָּרוּךְ ה' הַמְבוֹרָךְ כו'. וְעַל בְּרָכָה דָא שַׁרְיָיא צְלוֹתָא. וּקְדוּשָׁה לָא שַׁרְיָא אֶלָּא עַל בְּרָכָה, לְאִתַּקְפָא לְמָארֵיהוֹן בְּכוֹלָּא, וּבְרָכָה דָא, וּקְדוּשָׁה דָא, לָאו אִיהוּ אֶלָּא בַּעֲשָׂרָה.</p>"],[9514015055,"<p>שָׁאֵילְנָא לֵיהּ, אַמַּאי הֵיכָלָא לִסְטַר צָפוֹן. אֲמַר לִי, בְּהַאי הֵיכָלָא אִתְכַּפְיָין כָּל סִטְרִין בִּישִׁין, דְּלָא יִשְׁלְטוּן בְּעָלְמָא.</p>"],[9514015056,"<p>חַלּוֹן דָּא, אִיקְרֵי חַלּוֹן דְּנוֹגַהּ. וְלֵית רְשׁוּ לְאִסְתַּכָּלָא בֵּיהּ, בַּר אִינוּן דְּדִיּוּרֵיהוֹן תַּמָּן, וְכֹלָּא אִינוּן חָמָאן, וּמִסְתַּכְּלִין, וְיָכְלִין לְאִסְתַּכָּלָא. כָּל אִינוּן דְּתַמָּן, אָזְלֵי בְּמַלְבּוּשִׁין בִּדְיוֹקְנִין דְּהַאי עָלְמָא.</p>"],[9514015057,"<p>וְתַמָּן חָמֵינָא סַגִּיאִין מִן חַבְרַיָיא, וְלָא אִתְיְהֵיב לִי רְשׁוּ לְאִתְקְרָבָא לְגַבַּיְיהוּ, וְכוּלְּהוּ אִשְׁתְּמוֹדְעָן דָּא לְדָא, וְאָכְלֵי מֵיכְלָא דְּתַקִּיפֵי עֶלְיוֹנִים.</p>"],[9514015058,"<p>רְקִיעָא דָא, נָטֵיל בְּכָל יוֹמָא לְאַרְבַּע סִטְרֵי עָלְמָא. וְכַד נָטֵיל, אַרְעִיף טַלָּא דְחַיֵּי לְגוֹ גִנְתָא. וְאַתְיָין כּוּלְּהוּ צַדִּיקַיָּא דְּתַמָּן, וְאִסְתַּחְיָין בְּהַהוּא טַלָּא, וְאַזְהֳרָן כְּזוֹהַר הָרָקִיעַ, וְאָעֳלִין קַמֵּי מְשִׁיחָא, וּלְקַמֵי אֲבָהָן, וְאָדָם הָרִאשׁוֹן, וְלָא אִתְיְהֵיב לִי רְשׁוּ לְמִנְדַע בְּהוּ.</p>"],[9514015059,"<p>חַלּוֹן דְּבִסְטַר מַעֲרָב, מְשַׁנְיָא מִכָּל שְׁאָר חַלּוֹנִין, בִּגְוָונִין וּבִנְהוֹרִין. מִתְתַּחְמָא בְּאַרְבַּע אַתְוָון דִּשְׁמָא קַדִּישָׁא, דְּזָהֲרִין וְנָצְצִין עַל גַּבֵּי הַהוּא חַלּוֹנָא. זִימְנִין אִתְגַלְּיָין, זִימְנִין אִתְטַמְּרָן. וְאַחֲזֵי לִי בַּאֲתַר חַד, כִּתּוֹת שֶׁל צַדִּיקִים, בְּדַרְגִּין יַתִּיר עַל כּוּלְּהוּ.</p>"],[9514015060,"<p>שָׁלְחוּ לְהוֹ בְּנֵי בָבֶל לִבְנֵי אַרְעָא קַדִּישָׁא, לָן יָאוֹת לְמִבְכֵּי, לָן יָאוֹת לְמֶעְבַּד הֶסְפֵּדָא עַל חוּרְבַּן בֵּית אֱלָהָנָא, עַל דְּאִתְבַּדַּרְנָא בֵּינֵי עַמְמַיָא, וְאִית לָן לְמִיפְתַּח הֶסְפֵּידָא, וּלְפָרְשָׁא אַלְפָ\"א בֵּיתָא, דְּשָׁלַח מָארֵי עַלְמָא לְהֶסְפֵּידָא דְּחוּרְבַּן בֵּיתֵיהּ.</p>"],[9514015061,"<p>שָׁלְחוּ לְהוֹ בְּנֵי אַרְעָא קַדִּישָׁא, יָאוֹת דְּאַתּוּן אִתְבַּדַּרְתּוּן בֵּינֵי עַמְמַיָא, וְאַתּוּן לְבַר מֵאַרְעָא קַדִּישָׁא, וְיָאוֹת לְכוֹ לְמִבְכֵּי עֲלַיְיכוּ וְעַל גַּרְמַיְיכוּ, דִּנְפַקְתּוּן מִנְהוֹרָא לַחֲשׁוֹכָא, כְּעַבְדָא דְּנָפֵיק מִבֵּי מָארֵיהּ. אֲבָל אֲנַן אִית לָן לְמִבְכֵּי וּלְמֶעְבַּד הֶסְפֵּידָא, וְלָן שַׁדַּר קוּדְשָׁא בְּרִיךְ הוּא סִפְרָא דְהֶסְפֵּידָא, דַּאֲנַן בְּנָהָא דְּמַטְרוֹנִיתָא, וַאֲנַן מִבְּנֵי בֵיתָהּ, וְיָדְעִין יְקָרָא דְּמָארֵי עָלְמָא. וְלָן יָאוֹת לְמִבְכֵּי, וּלְפָרְשָׁא אִינוּן אַלְפָ\"א בֵּיתִי\"ן.</p>"],[9514015062,"<p>וַאֲנַן יַתְמִין בְּלָא אַבָּא וְאִמָּא, וּמִסְתַּכְּלִין עַיְינִין לְכוֹתְלֵי בֵיתָא דְּאִימָּנָא, וְהָא אִתְחָרַב, וְלָא אַשְׁכַּחְנָא לָהּ. דַּהֲוַת יַנְקָא לָן בְּכָל יוֹמָא, בְּיוֹמִין קַדְּמָאִין, מִשַׁפִּירוּ דִּילָהּ. וַהֲוֵית נְחִימַת לָן, וּמְמַלֶּלֶת עַל לִבָּנָא, כְּאִמָּא לִבְרָהּ. כְּמָה דְאַתְּ אָמֵר (ישעיהו ס״ו:י״ג) כְּאִישׁ אֲשֶׁר אִמּוֹ תְּנַחֲמֶנּוּ וְגו'.</p>"],[9514015063,"<p>וְהַשְׁתָּא אִסְתַּכְּלָן עַיְינִין לְכָל סְטַר, וַאֲתַר בֵּית מוֹתָבָא דְּאִימָּנָא אִתְבַּלְבֵּל, וְהָא אִתְחָרַב. נְבַטַשׁ רֵישָׁא לְכוֹתְלֵי בֵיתָא וּמוֹתָבָהּ. מַאן יְנַחֵם לָן, וּמַאן יְמַלֵּל עַל לִבָּנָא, וְיָגֵין עֲלָנָא קַמֵּי מַלְכָּא.</p>"],[9514015064,"<p>כַד הֲוֵינָן חָטָאן קַמֵּי אֲבוּנָא, וְסָלֵיק רְצוּעָא לְאַלְקָאָה לָן, אִיהִי קָיְימַת לְקַמָּן, וּמְקַבֶּלֶת מַלְקִיּוּתָא דְמַלְכָּא, בְּגִין לַאֲגָנָא עֲלָנָא. כְּמָה דְאַתְּ אָמֵר (שם נג) וְהוּא מְחֹלָל מִפְּשָׁעֵינוּ מְדֻכָּא מֵעֲוֹנוֹתֵינוּ כו' וּבַחֲבֻרָתוֹ נִרְפָּא לָנוּ. וְהַשְׁתָּא אִימָּא לֵית לָן, וַוי. וַוי לָן, וַוי לְכוֹ. לָן יָאוֹת לְמִבְכֵּי, לָן יָאוֹת לְמִסְפֵּד, לָן יָאוֹת לְפָתְרָא אִינוּן מִילִּין דִּמְרִירוּ, לְאוֹדָעָא לְהוֹ, לְאִינוּן דְּיָדְעִין לְמִבְכֵּי מִלִּין דְּהֶסְפֵּידָא.</p>"],[9514015065,"<p>נִקְרַב בְּכָל יוֹמָא לְגַבֵּי עַרְסָא דְּאִימָּנָא, וְלָא נִשְׁכַּח לָהּ תַּמָּן. נִשְׁאַל עֲלָהּ, לֵית מַאן דְּיַשְׁגַּח עֲלָן. נִשְׁאַל לְעַרְסָא דִילָהּ, אִתְבַּלְבְּלָא. נִשְׁאַל לְכוּרְסְיָיא, נָפְלַת. נִשְׁאַל לְהֵיכָלִין דִּילָהּ, אוֹמָאָן אִינוּן דְּלָא יָדְעִין מִינָהּ. נִשְׁאַל לְעַפְרָא, רְשִׁימוּ דְּעִקְבְתָא לֵית תַּמָּן.</p>"],[9514015066,"<p>נִשְׁאַל לְאִיגְרָא, הָא אִיגְרָא אָתֵיב לָן, דְּתַמָּן יָתְבָה מְבַכָּה וּמְיַילֶּלֶת עֲלָן וְאָזְלַת מְבַכָּה, צווַֹחַת בְּקוֹל מְרִירוּ עֲלָן, מֵאִיגְרָא לְאִיגְרָא. כְּמָה דְאַתְּ אָמֵר, (שם כב) מַה לָּךְ אֵפוֹא כִּי עָלִית כֻּלָּךְ לַגַּגּוֹת. נִשְׁאַל לְאוֹרְחִין וּשְׁבִילִין, כֻּלְּהוּ אָמְרִין דִּשְׁמָעוּ קָל מְרִירוּ דִּבְכִיָּה, דִּמְבַכָּה עַל בְּנָהָא, וְלָא יָדְעִין לְאָן אִסְתַּלָּקַת.</p>"],[9514015067,"<p>לָן יָאוֹת לְמִבְכֵּי, לָן יָאוֹת לְמִיסְפֵּד. נְנַשֵּׁק עַפְרָא דְּרַגְלָהָא, נְנַשֵּׁק אֲתַר בֵּי מוֹתָבָהּ, נְנַשֵּׁק כּוֹתְלֵי הֵיכָלָא, וְנִבְכֵּי בִּמְרִירוּ. אֲנַן נִפְתַּח בְּהֶסְפֵּידָא, דְּחָמֵינָן בְּכָל יוֹמָא כָּל הַאי. נִבְכֵּי תָּדִיר וְלָא אִיתְנְשֵׁי מְרִירוּ דִּבְכִיָּה מִינָן.</p>"],[9514015068,"<p>פָּתְחוּ אִינְהוּ וְאָמְרֵי, (איכה א׳:א׳) אֵיכָה יָשְׁבָה בָדָד הָעִיר, כְּתִיב (ישעיהו כ״ב:ה׳) כִּי יוֹם מְהוּמָה וּמְבוּסָה וּמְבוּכָה וְגו'. כִּי יוֹם. חַד יוֹמָא אִית לְקוּדְשָׁא בְּרִיךְ הוּא, רְחִימָא דְנַפְשֵׁיהּ, כְּלִילָא מִכָּל שְׁאָר יוֹמִין, שִׁית יוֹמִין כְּלִילָן בֵּיהּ, וְהוּא כְּלָלָא דְּכֻלְּהוּ. וְעַל דְּאַסְגִיאוּ חוֹבִין, אִסְתַּלַּק לְעֵילָא, לְבֵי עַלְמָא דְחַיִּין.</p>"],[9514015069,"<p>כְדֵין מִתְּחוֹת שִׁפּוּלֵי מַשְׁכְּנָא, קָם יוֹמָא דִמְרִירוּ, יוֹמָא דִּבְכִיָה, יוֹמָא דְּצַעֲרָא, יוֹמָא דְאִיקְרֵי מְהוּמָה וּמְבוּסָה וּמְבוּכָה, וְעָאל בְּגוֹ מַשְׁכְּנָא, וְשֵׁיצֵי וְסָאֵיב. וְרִבּוֹנָא דְמַשְׁכְּנָא, אֲזַל וַעֲרַק וְאִתְתָּרַךְ מִגּוֹ מוֹתָבֵיהּ לְגוֹ טוּרָא דִלְבַר, וּלְגוֹ טוּרָא דְּחָרוּב, וּמַשְׁכְּנָא אִתְחָרַב.</p>"],[9514015070,"<p>לְבָתַר, נָחַת הַהוּא יוֹמָא עִילָּאָה, דְּאִסְתַּלַּק, שְׁאַל עַל מִשְׁכָּנֵיהּ, וְהָא אִתְחָרַב. עָאל וְאַשְׁגַּח עַל מָארֵי דְּמַשְׁכְּנָא, מַטְרוּנִיתָא רְחִימְתָּא דְּנַפְשֵׁיהּ, וְהִיא אִתְתְּרָכַת וְעָרְקַת, וְכָל בִּנְיָינָהּ סָתִיר. כְּדֵין שָׁארֵי לְמִגְעֵי, גּוֹעָא בָּתַר גּוֹעָא, כִּנְהִימוּ דְּתַרְנְגוֹלָא עַל נוּקְבֵיהּ. הֲדָא הוּא דִכְתִיב, (שם) מְקַרְקַר קִר, נְהִימוּ כְּתַרְנְגוֹלָא. קִיר, רִבּוֹן שַׁלִּיטָא.</p>"],[9514015071,"<p>וְשׁוֹעַ אֶל הָהָר, עָבִיד שׁוֹעָה וְצָוַוח לְגַבֵּי טוּרָא, דְּעָרְקַת תַּמָּן מַטְרוּנִיתָא. עָבִיד שׁוֹעַ צָוַוח וְקָרֵי בִּנְהִימוּ דִּבְכִיָּה אֵיכָה. אֵיכָה רְחִימְתָּא דְּנַפְשָׁאי, אֵיכָה שַׁפְנִינָתִי שְׁלֵימָתִי, אֵיכָה יְחִידָתָא דִילִי, דְּאִתְיַחֲדָא עִמִּי בְּיִחוּדָא. אֵיכָה דַּהֲוִית נָטְלָא בְּכָל יוֹמָא, חָמֵשׁ וְעֶשְׂרִים אַתְוָון דְּיִחוּדָא, וְאִתְקְרִיאַת כֹּ\"ה עַל דָּא.</p>"],[9514015072,"<p>אֲחָתִי בְּרַתִּי אִמִּי, לְאָן אָזְלַת, לְאָן פָּנִית לְמֵיהַךְ. אֲנַן דְּשָׁמְעִין בְּכָל יוֹמָא קִרְקוּרָא דָא דְּרִבּוֹנָנָא, לָן יָאוֹת לְמִבְכֵּי, לָן יָאוֹת לְמִסְפֵּד, לָן יָאוֹת לְמִפְתַּח אֵיכָה. אֵיכָה יָשְׁבָה בָדָד וְגו'.</p>"],[9514015073,"<p>רַבִּי לְוִיטַס חוֹזָאָה פָּתַח, (בראשית ג׳:ט״ו) וְאֵיבָה אָשִׁית בֵּינְךָ וּבֵין הָאִשָּׁה וּבֵין זַרְעֲךָ. דְּבָבוֹ סַגֵּי הֲוָה מִן יוֹמָא דְאִתְבְּרֵי עַלְמָא, עַל עִילָה דְּעֵיטָא דְּנָחָשׁ, מֵהַהִיא שַׁעֲתָא דְּאִתְלַטְיָיא, אִתְדַּחְיָיא מִקַּמֵּי תַּרְעָא דְמַלְכָּא, וְהוּא כָּמִין תָּדִיר בֵּין גְּדָרִין דְּעַלְמָא, בֵּין אִינוּן גְּדָרִין דְּאוֹרַיְיתָא, כָּל אִינוּן דְּדָשִׁין בְּעָקֵב, בְּאִינוּן גְּדָרִין, נָשֵׁיךְ לוֹן.</p>"],[9514015074,"<p>וַוי דְּאַשְׁכַּח, וַוי דְנָשֵׁיךְ. וַוי עַל דְּבָבוּ בִּישָׁא דְּאִתְנְטֵיר. עַל דְּבָבוּ בִּישָׁא דַּהֲוַות לֵיהּ בְּהַאי אִשָּׁה, דְאִתְקַרְיָא אִשָּׁה יִרְאַת ה'. דְּבָבוּ בִישׁ נָטַר לָהּ מִן יוֹמָא דְאִתְבְּרֵי עָלְמָא, עַד דְּתָבַר לָהּ בִּתְבִירוּ, לְמִשְׁכַּב לְעַפְרָא.</p>"],[9514015075,"<p>(איכה א׳:א׳) \"אֵיכָה \"יָשְׁבָה \"בָדָד \"הָעִיר \"רַבָּתִי \"עָם \"הָיְתָה, אִסְתַּכַּל בְּאַתְוָון דְּרֵישׁ כָּל תֵּיבָה וְתֵיבָה, וְתִשְׁכַּח נְטִירוּ דְּבָבוּ בִישָׁא, דְּאִתְנַטְרָא, עַד דְּאִתְחָרַב בֵּי מַקְדְּשָׁא. אֵיבָ\"ה רָעָ\"ה בְּרֵישֵׁי אַתְוָון, אִתְנְטֵיר לָהּ לְהַהִיא אֵשֶׁת חַיִל, בִּתְבִירוּ דְבֵי מַקְדְּשָׁא, לְמִשְׁכַּב לְעַפְרָא.</p>"],[9514015076,"<p>הֲדָא הוּא דִכְתִיב, (איכה א׳:א׳) \"כְּאַלְמָנָה \"רַבָּתִי \"בַּגּוֹיִם \"שָׂרָתִי \"בַּמְדִינוֹת \"הָיְתָה \"לָמַס, תִּקְרָא לְמַפְרֵעַ בְּרֵישֵׁי אַתְוָון, לָ\"ה בְּשִׁבְרֵ\"ךְ. בִּתְבִירוּ דְּבֵי מַקְדְּשָׁא, בִּתְבִירוּ דִּכְנִישְׁתָּא דְיִשְׂרָאֵל, דְּבָבוּ בִישָׁא אַדְבֵּיק לָ\"ה בְּשִׁבְרֵ\"ךְ.</p>"],[9514015077,"<p>אֵיכָה דְּאִתְדַּבְּקַת לְהַהִיא אֵיבָה רָעָה דָא, קָל דְּנָחָשׁ, קָל מְרִירוּ דִּבְכִיָה בָּרְקִיעִין. אִלֵּין קָרָאן אֵיכָה, וּמִסִּטְרָא אָחֳרָא קָרָאן אֵיבָה. הֲדָא הוּא דִכְתִיב, וְאֵיבָה אָשִׁית בֵּינְךָ וּבֵין הָאִשָּׁה, בֵּין סִטְרָא דָא, וּבֵין סִטְרָא דָא, אִשְׁתַּכַּח בְּחֻרְבַּן בֵּי מַקְדְּשָׁא. וּבִקְרָא קַדְמָאָה אִתְרְשִׁים כֹּלָּא לְמִנְדַע דְּהַאי כ\"ה, אַדְבֵּיק לָהּ אֵיבָ\"ה רָעָה, דְּנָטֵיר לָהּ מִיּוֹמָא דְאִתְבְּרֵי עָלְמָא.</p>"],[9514015078,"<p>אֵיכָה יָשְׁבָה בָדָד, רַבִּי הָרְכִּינַס פָּתַח, (בראשית ג׳:כ״ד) וַיְגָרֶשׁ אֶת הָאָדָם וַיַּשְׁכֵּן מִקֶּדֶם לַגַּן עֵדֶן. וַיְגָרֶשׁ אֶת, דָּא כְּנֶסֶת יִשְׂרָאֵל. בְּחֻרְבַּן בֵּי מַקְדְּשָׁא, דְּאִתְתָּרְכַת בְּתֵירוּכִין, דְּאִשְׁתְּלָחַת בְּשִׁלּוּחִין, כָּרְסְיָיא דְמַלְכָּא נָפְלַת.</p>"],[9514015079,"<p>וַיְגָרֶשׁ אֶת, דָּא כָּרְסְיָיא דְמַלְכָּא. וַוי דְּאִתְתְּרָכַת, וַוי דְּנָפְלַת. הָאָדָם, הַהוּא דְּשַׁלֵּיט עַל כּוּרְסְיָיא, דִּכְתִיב בֵּיהּ (יחזקאל א׳:כ״ו) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם כו'. נָפְלַת כָּרְסְיָיא, נָפַל כֹּלָּא.</p>"],[9514015080,"<p>וַיַּשְׁכֵן, הַהוּא דְתָרֵיךְ לְדָא, אַשְׁכֵּין וְאַשְׁרֵי יִישׁוּבָא אָחֳרָא, בְּהִיפּוּכָא. בְּשַׁעֲתָא דְּאִתְחְרֵיב בֵּי מַקְדְּשָׁא, סָלֵיק לְכָבוֹד עִילָּאָה לְעֵילָא, וְאַזְעִיר דְּיוֹקְנֵיהּ מִכְּמָה דַּהֲוַות. וְכוּרְסְיָיא נָטֵיל מִנֵּיהּ וְאִתְפְּרַשׁ.</p>"],[9514015081,"<p>כִבְיָכוֹל אַשְׁרֵי לְגַּן עֵדֶן עִם כְּרוּבִים לְתַתָּא, וְאִתְפְּרַשׁ מֵהַהוּא כָּבוֹד עִילָּאָה. וְאַשְׁרֵי לְהַהִיא לַהַט הַחֶרֶב, לְמֵיקַם בְּדוּכְתָּא דְּרַבָּנוּתֵיהּ, לְמִיטַר וּלְמִישְׁאַב וּלְמַסְתִּיר, הַהוּא אוֹרַח דְּאִנְגִיד מֵעֵץ הַחַיִּים.</p>"],[9514015082,"<p>וּשְׁלֹמֹה מַלְכָּא צָוַוח וְאָמַר, (משלי ל׳:כ״א) תַּחַת שָׁלוֹשׁ רָגְזָה אֶרֶץ כו' תַּחַת עֶבֶד כִּי יִמְלוֹךְ כו' וְשִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ. שִׁפְחָה לְגוֹ, גְּבִירְתָּהּ לְבַר. אֵיכָה יָשְׁבָה בָדָד, מַאי בָדָד. כְּמָא דְאַתְּ אָמֵר, בָּדָד יֵשֵׁב מִחוּץ לַמַּחֲנֶה מוֹשָׁבוֹ.</p>"],[9514015083,"<p>אֵיכָה יָשְׁבָה בָדָד, ר' חֲנִינָאי וְרַבָּנָן פָּתְחֵי קְרָא בְּאָדָם הָרִאשׁוֹן. (בראשית ב׳:ט״ו) וַיִּקַּח ה' אֱלֹהִים אֶת הָאָדָם וַיַּנִּיחֵהוּ בְגַן עֵדֶן וְגו'. וַיִּקַּח, בַּמֶּה לְקָחוֹ. ר' חֲנִינָאי אָמַר, לְקָחוֹ בִּדְבָרִים. כְּמָה דְאַתְּ אָמֵר (ויקרא ח׳:ב׳) קַח אֶת אַהֲרֹן. וְרַבָּנָן אָמְרוּ, לְקָחוֹ בְּרוּחַ. כְּמָה דְאַתְּ אָמֵר, (מלכים ב ב׳:ג׳) הַיּוֹם ה' לֹקֵחַ אֶת אֲדֹנֶיךָ מֵעַל רֹאשֶׁךָ.</p>"],[9514015084,"<p>וַיַּנִּיחֵהוּ בְגַן עֵדֶן, כְּדֵי לִהְיוֹת לוֹ מְנוּחָה, לָדַעַת וּלְהַכִּיר הַחָכְמָה וְהַתּוֹרָה. דְּאָמַר רִבִּי חֲנִינָאי, הַתּוֹרָה לִימְדָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָדָם. הֲדָא הוּא דִכְתִיב, (איוב כ״ח:כ״ז) אָז רָאָהּ וַיְסַפְּרָהּ וְגו', וַיֹּאמֶר לָאָדָם. וְהָיוּ מַלְאֲכֵי הַשָּׁרֵת מְקַלְסִין לְפָנָיו.</p>"],[9514015085,"<p>עַד שֶׁרָאָה סמאָמַר לֵיהּ בַּשָּׁמַיִם, וְנִתְקַנֵּא בּוֹ, וְיָרַד מִן הַשָּׁמַיִם כִּדְמוּת צֵל עַל נָחָשׁ. הַנָּחָשׁ נִרְאָה, וְהַצֵּל עָלָיו, תָּקְפָא וְחֵילָא דִילֵיהּ.</p>"],[9514015086,"<p>קָרֵיב הַהוּא נָחָשׁ לְגַבֵּי אִיתְּתָא, דְּדַעְתָּא קַלָּה מִן הָאִישׁ. מִכָּאן דְּאִתְּתָא לָא אִתְפַּתַּת, אֶלָּא בְּאִתְּתָא אָחֳרָא. (בראשית ג׳:א׳) וַיֹּאמֶר אֶל הָאִשָּׁה אַף כִּי אָמַר אֱלֹהִים, מִיָּד פָּתַח בְּאַף. מֵהָכָא, דְּבִתְחִלַּת דְּבָרָיו שֶׁל אָדָם נִיכָּר מִי הוּא. כָּךְ הוּא פָּתַח בְּאַף, לְהוֹדִיעַ מִי הוּא.</p>"],[9514015087,"<p>נָטַל סִימָן זֶה, אִם תְּקַבֵּל, אִם לֹא תְקַבֵּל. וְהִמְשִׁיכָהּ בִּדְבָרִים, עַד שֶׁפָּתְחָה בְּאוֹת מ\"ם, וְאָמְרָה מִכָּל עֵץ הַגָּן אָכֹל נֹאכֵל. מִיָּד נָטַל הַנָּחָשׁ הָאוֹת, וַיָּשֶׂם אוֹתָהּ עַל זְרוֹעוֹ הַשְּׂמָאלִית, וְהָיָה מַמְתִּין עַל וא\"ו תי\"ו מִפִּיהָ, כְּדֵי לִהְיוֹת מו\"ת נָכוֹן לִפְנֵיהֶם.</p>"],[9514015088,"<p>הִתְחִיל לְפַתּוֹתָהּ, עַד דִּכְתִיב, (שם) וַתֵּרֶא הָאִשָּׁה, בְּטַעְמָא סַגֵּי וְתַקִּיף. מְלַמֵּד, שֶׁפָּרְחוּ הָאוֹתִיּוֹת וא\"ו תי\"ו, וְסָלְקוּ לְהִתְחַבֵּר עִם אוֹת מ\"ם. וְאוֹת מ\"ם הָיְתָה עוֹלָה וְיוֹרֶדֶת, וְלֹא הָיְתָה מִתְחַבֶּרֶת עִמָּהֶם, עַד שֶׁנִתְפַּתֵּת.</p>"],[9514015089,"<p>וּפָרְחוּ וא\"ו תי\"ו, ד' זִמְנִין, וַאֲקִיפוּ לְאוֹת מ\"ם לְד' סִטְרִין. דִּכְתִיב, (בראשית ג׳:ו׳) וַתִּקַּח מִפִּרְיוֹ וַתֹּאכַל וַתִּתֵּן גַּם לְאִישָׁהּ וַתִּפָּקַחְנָה עֵינֵי שְׁנֵיהֶם. הָא ד' זִמְנִין ו' ת'. מְלַמֵּד, שֶׁסִּבְבוֹ לָאוֹת מ\"ם לְאַרְבַּע צְדָדִין, וְהַמ\"ם בָּאֶמְצַע, מָוֶת בְּכָל סִטְרִין.</p>"],[9514015090,"<p>כמדָּבָר אַחֵר, (ירמיהו ט׳:כ׳) כִּי עָלָה מָוֶת בַּחֲלוֹנֵינוּ. דָא סמאל, דְּאִיהוּ חַד מֵחַלּוֹנֵי שְׁמַיָא. וְעַל דָּא מִי גֶּבֶר יִחְיֶה וְלֹא יִרְאֶה מָוֶת. מִיָּד שָׁלַט בָּהּ, וְהִטִיל בָּהּ זוּהֲמָא. נָחַת קוּדְשָׁא בְּרִיךְ הוּא לְמֶיחֱמֵי, וַיִּתְחַבֵּא הָאָדָם וְאִשְׁתּוֹ.</p>"],[9514015091,"<p>תָּא חֲזֵי, קוֹדֶם שֶׁחָטְאוּ, הָיְתָה הַשְּׁכִינָה עֲטָרָה עַל רָאשֵׁיהֶם, לִהְיוֹת בִּשְׁבִילָם שׁוֹרָה עַל הָעוֹלָם. כֵּיוָן שֶׁחָטְאוּ, כִּבְיָכוֹל, תַּשׁ כֹּחָהּ, וְאִסְתַּלְּקַת וְלֹא שַׁלִּיטַת. וְקוּדְשָׁא בְּרִיךְ הוּא שָׁארֵי לְקוֹנֵן, וְאָמַר אֵיכָה, מַה תְּהֵא מִינָהּ, שָׁלְטָנוּתָא אַעֲדוּ מִינָהּ. אוּף הָכָא בְּחוּרְבַּן בֵּי מַקְדְּשָׁא, שׁוּלְטָנוּתָא אַעֲדוּ, וְקוּדְשָׁא בְּרִיךְ הוּא שָׁארֵי לְמִיסְפֵּד, וְאָמַר אֵיכָה, מַה תְּהֵא עָלֶיהָ.</p>"],[9514015092,"<p>אֵיכָה, רַבִּי פִּנְחָס פָּתַח, (ירמיהו ל״א:ט״ו) קוֹל בְּרָמָה נִשְׁמָע נְהִי בְּכִי תַּמְרוּרִים וְגו'. בְּשַׁעֲתָא דְּאִתְחָרַב בֵּי מַקְדְּשָׁא, וְאִתּוֹקַּד. אָתָא קָלָא וְאִיתְעַר עַל קִבְרֵי אֲבָהָן קַדְמָאֵי, וַאֲמַר, אֲבָהָן קַדְמָאֵי, אַתּוּן דְּמִיכִין בְּשֵׁינְתָא, וְלָא יָדְעִיתוּן צַעֲרָא דְעָלְמָא, בְּנֵיכוֹן דְּגַדֵּלְתּוּן בְּצַעֲרָא, וְאָעֵילְתּוּן בְּהֵימְנוּתָא סַגֵּי דְקוּדְשָׁא בְּרִיךְ הוּא, הָא מִיתוּ, וְהָא אִתְקְטָלוּ, וְהָא אֲזָלוּ בְּגָלוּתָא בֵּין שַׂנְאֵיהוֹן, יְדֵיהוֹן מְהַדְּקָן לַאֲחוֹרָא, מַיְיתִין בְּכַפְנָא, בָּתֵּיהוֹן אִתּוֹקַד. אָן רַחֲמִין דִּילְכוֹן, אָן מְהֵימְנוּתָא דִילְכוֹן, קוּמוּ אִיתְעָרוּ לְגַבַּיְיהוּ.</p>"],[9514015093,"<p>מִיָּד אִתְעָרוּ אֲבָהָן וְאִמָּהָן, וַאֲזָלוּ לְגַבֵּי משֶׁה, אֲמָרוּ לֵיהּ, משֶׁה רַעֲיָא מְהֵימְנָא, אָן אִינוּן בְּנִין, אָן שְׁבַקְתְּ לוֹן. מִיָּד אִיתְעַר משֶׁה, וַאֲזַל עִמְּהוֹן לְגַבֵּי יְהוֹשֻׁעַ. אֲמַר לֵיהּ, בְּנֵי אֲבָהָן אִלֵּין, בְּנֵי יִשְׂרָאֵל, דְּפַקְדַנִּי קוּדְשָׁא בְּרִיךְ הוּא עֲלֵיהוֹן, וְשַׁבְקֵית לוֹן בִּידָךְ, אָן אִינוּן.</p>"],[9514015094,"<p>אֲתֵיב יְהוֹשֻׁעַ וַאֲמַר, רַבֵּינוּ משֶׁה, בְּאַרְעָא קַדִּישָׁא שַׁבְקֵית לוֹן, וּפְלֵיגִית לוֹן אַרְעָא עַל פּוּם עַדְבָא, כְּמָה דְּפַקְדַּתַּנִי, וְכֻלְּהוּ שַׁבְקֵית גְּבַר עַל אַחְסַנְתֵּיהּ וְעַל עַדְבֵיהּ.</p>"],[9514015095,"<p>וּמִיָּד אֲזָלוּ כּוּלְּהוּ לְאַרְעָא קַדִּישָׁא, וְאַשְׁכָּחוּ לָהּ דְּאִתְחֲרָבָא, דְּלָא אִשְׁתַּמַּע בָּהּ קָלָא. עָאלוּ גַּבֵּי מַקְדְּשָׁא, וְחָמוּ דְּאִתּוֹקַד. עֲבָדוּ בֵּיהּ הֶסְפֵּידָא, עַד דְּאִשְׁתַּמַּע קָל מְרִירוּ דִּבְכִיָּה לְרוּם שְׁמַיָא, וְכָל מַלְאֲכֵי עִילָּאֵי בְּכוֹ עִמְּהוֹן לְעֵילָא.</p>"],[9514015096,"<p>אִיתְעַר קוּדְשָׁא בְּרִיךְ הוּא וַאֲתָא לְגַבֵּיהוֹן, וְאַשְׁכַּח לוֹן מְמָרְרִין בְּקָל בְּכִיָּה, גּוֹ עַפְרָא דְמַקְדְּשָׁא. אֲמַר לוֹן, רְחִימִין דְּנַפְשָׁאי, מָה אַתּוּן הָכָא, (ירמיהו י״א:ט״ו) מַה לִּידִידִי בְּבֵיתִי.</p>"],[9514015097,"<p>קָם אַבְרָהָם סָבָא בְּקַדְמִיתָא, אֲמַר קַמֵּיהּ מָארֵי דְעָלְמָא, אַתְּ יְדַעְתְּ דְּאָזְלֵית קַמָּךְ בְּאוֹרַח קְשׁוֹט. עֶשֶׂר זִמְנִין נִסֵּית לִי, וְקָיְימִית בְּכֹלָּא. בָּנַי אָן אִינוּן, לָא שְׁמַעֲנָא קָל מִלֵּיהוֹן בְּאַרְעָא דְּאוֹמֵית לִי, לְקָיְימָא לְהוֹן בָּהּ.</p>"],[9514015098,"<p>אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, אִי אַבְרָהָם רְחִימָא דְּנַפְשָׁאי, (שם) וּבְשַׂר קֹדֶשׁ יַעַבְרוּ מֵעָלָיִךְ. בְּטִילוּ מִינַיְיהוּ בְּרִית קַדִּישָׁא, וּפָלְחוּ עֲבוֹדָה זָרָה, וְעַל דָּא אִיתָּקְפַת רוּגְזָאי בְּהוֹן, וּבְגִינָךְ אוֹרִיךְ לוֹן כַּמָּה זִמְנִין, וְלָא תָבוּ קֳדָמַי.</p>"],[9514015099,"<p>כֵיוָן דְּשָׁמַע אַבְרָהָם כָּךְ אָמַר יִמָּחוּ עַל קְדוּשַּׁת שְׁמֶךָ כָּל אִינוּן חוֹבֵיהוֹן בֵּינֵי עַמְּמַיָא, עַד דִּיהֵא רַעֲוָוא דִּילָךְ לַאֲתָבָא לוֹן לְגַבָּךְ. וְכֵן כֻּלְּהוּ כְּגַוְּונָא דָא, וַאֲזָלוּ לְהוֹ.</p>"],[9514015100,"<p>אִשְׁתָּאֲרַת תַּמָּן רָחֵל, וַאֲרֵימַת קָל בְּכִיָה בִּמְרִירוּ דְתַמְרוּרִים, אֲמַר לָהּ קוּדְשָׁא בְּרִיךְ הוּא, רָחֵל, מָה אַתְּ מְבַכָּה. אֲמָרָה קַמֵּיהּ, וְלָא אֶבְכֶּה, בָּנַי אָן אִינוּן, וּמָה חָטָאן לְגַבָּךְ. אֲמַר לָהּ עָאֳלוּ צָרָתִי לָקֳמַי, וְאָעֵילוּ לָהּ בְּבֵיתִי. מִיָּד אָמְרָה, וְכִי לָא עֲבָדִית אֲנָא יַתִּיר, דְּאָעֵילְנָא צָרָתִי בְּבֵיתִי.</p>"],[9514015101,"<p>דִּתְנַן, בְּשַׁעֲתָא דִּכְתִיב, (בראשית כ״ט:י״ב) וַיַּגֵּד יַעֲקֹב לְרָחֵל כִּי אֲחִי אָבִיהָ הוּא, אֲמַר הִזְדַּוְּוגִי לְגַבָּאי, אָמְרָה לֵיהּ אֵין, אֲבָל אֲחָתָא אִית לִי קְשִׁישָׁא מִינָאי, וּמִסְתָּפֵינָא מֵאַבָּא, דְּרַמָּאָה אִיהוּ. מִיָּד וַיַּגֵּד יַעֲקֹב לְרָחֵל, כִּי אֲחִי אָבִיהָ הוּא בְּרַמָּאוּתָא.</p>"],[9514015102,"<p>מִיָּד יְהַב לָהּ סִימָנִין. כֵּיוָן דְּעָאלַת לֵאָה בְּהַהוּא לֵילְיָא, אָמְרָה רָחֵל, הַשְׁתָּא מִתְכַּסְּפָא אֲחָתִי, אֲזָלַת וּמָסְרָהּ לָהּ סִימָנִין.</p>"],[9514015103,"<p>וְעַל דָּא אָמְרָה לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, וַאֲנָא לָא עֲבָדִית יַתִּיר, דְּאָעֵילְנָא צָרָתִי בְּבֵיתִי. וְאַתְּ דִּכְתִיב בָּךְ, רַחוּם וְחַנּוּן אֶרֶךְ אַפַּיִם, הֲוָה לָךְ לְאַעֲבָרָא עַל חוֹבֵיהוֹן.</p>"],[9514015104,"<p>וּבְכָל מַה דַּאֲמַר לָהּ, לָא קַבֵּילַת תַּנְחוּמִין. הֲדָא הוּא דִכְתִיב, (ירמיהו ל״א:ט״ו) קוֹל בְּרָמָה נִשְׁמָע וְגו' כִּי אֵינֶנּוּ. לָא בָּעַאת לְקַבָּלָא תַּנְחוּמִין. מַאי טַעְמָא. בְּגִין כִּי אֵינֶנּוּ, כְּיוֹמִין קַדְמָאִין לְאַשְׁרָאָה בֵּינַיְיהוּ, וְהָא אִסְתַּלַּק לְעֵילָא.</p>"],[9514015105,"<p>וּבְגִין דְּכִי אֵינֶנּוּ בְּגוֹ בְּנָהָא, לָא קַבָּלִית תַּנְחוּמִין, עַד דְּאוֹמֵי לָהּ. דִּכְתִיב, (ירמיהו ל״א:ט״ז) כֹּה אָמַר ה' מִנְעִי קוֹלֵךְ מִבֶּכִי וְעֵינַיִךְ מִדִּמְעָה.</p>"],[9514015106,"<p>כְמָה דַּעֲבָדַת רָחֵל, אוּף הָכֵי שְׁכִינְתָּא לְעֵילָא. כְּדִמְתַרְגֵּם קָל בְּרוּם שְׁמַיָּיא אִשְׁתְּמַע, שְׁכִינְתָּא מְבַכָּה עַל בְּנָהָא. בְּהַהִיא שַׁעֲתָא דְּאִיהִי הֲוַת מְבַכָּה, אִתְעָרוּ לְגַבָּהּ שִׁתִּין רִבּוֹא מַשִּׁרְיָין עִילָּאִין, וְכֻלְּהוּ אִיתְעָרוּ בְּכִיָה לְגַבָּהּ.</p>"],[9514015107,"<p>בְּהַהוּא שַׁעֲתָא, אִשְׁתַּמַּע קָלָא לִרְקִיעַ עֲרָבוֹת, וְאִזְדַּעְזָעוּ מָאתָן אֶלֶף עָלְמִין, דַּהֲווֹ גְנִיזֵי מִן יוֹמָא דְאִתְבְּרֵי עָלְמָא, עַד דְּאִשְׁתְּמַע הַהוּא קָלָא לְרוּם שְׁמַיָּיא. וּמַאן אִיהוּ, דָּא רָקִיעַ כְּעֵין הַקֶּרַח הַנּוֹרָא, דְּאִיהוּ עַל גַּבֵּי הַחַיּוֹת.</p>"],[9514015108,"<p>עַד דְּאִתְגַּלֵּית אִימָּא לִבְרַתָּא, וְאָמְרָה לָהּ, מִנְּעִי קוֹלֵךְ. כְּדֵין אִתְפָּרְשַׁת מִתַּמָּן, וַאֲזָלַת הִיא וְכָל אוּכְלוּסָהָא בְּגָלוּתָא. וְאִצְטְרִיכוּ לְאִתְבַּדְּרָא לְכַמָּה סִטְרִין, לְמֶהֱוֵי גָלוּתָא לְכוֹלָּא, וְהִיא יָשְׁבָה בָדָד.</p>"],[9514015109,"<p>רַבִּי נְחוּנְיָא אָמַר, אֵיכָה, מַאן אָמַר דָּא, הַהוּא רוּחַ עִילָּאָה נְעִימָאָה, עַלְמָא דְאָתֵי. וְעַל דָּא, תֵּיבָה דָא רוּחָנִי אִיהוּ, וְלָא אִית בָּהּ שׁוּתָּפוֹ כְּלָל, לָאו לִישָׁן וְשִׁינַּיִין, וְלָאו שִׂפְוָון כְּלָל.</p>"],[9514015110,"<p>אִימָּא שָׁאֲלָה עַל בְּרַתָּה, דָּא קִרְקוּרָא דְּקִיר, אָדוֹן רִבּוֹן רַב וְשַׁלִּיט, יָשְׁבָה, וְלָא עוֹמֶדֶת, בַּתְּחִלָּה עוֹמֶדֶת, וְכָל אוּכְלוּסֶיהָ עוֹמְדִים, הַשְׁתָּא יוֹשֶׁבֶת וְשׁוֹמֵמָה. בָּדָד, כְּמָה דְאַתְּ אָמֵר בָּדָד יֵשֵׁב, כְּמַאן דִּמְסָאֵיב בִּמְסָאֲבוּ, וְשִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ, הַהִיא דַּהֲוַות מְסָאֲבָא, יַתְבָא בְּדוּכְתָּהָא.</p>"],[9514015111,"<p>שָׁלְחוּ לְהוֹ בְּנֵי בָּבֶל לִבְנֵי אַרְעָא קַדִּישָׁא, יָאוֹת דְּאַתּוּן צְרִיכִין לְמִבְכֵּי, וּלְכוֹן יָאוֹת לְמִסְפֵּד, וּלְמֶעְבַּד אֶבְלָא, בְּמֶחֱזֵיכוֹן הֵיכָלִין דְּאִיּמָא חֲרֵיבִין, וַאֲתַר עַרְסָה דְּאִתְהַפַּךְ בְּאֶבְלָא, וְהוּא לֵית תַּמָּן, וּפָרְחָא מִנְּכוֹן, וְלָא יְדַעְתּוּן מִינָהּ.</p>"],[9514015112,"<p>תֵּימְרוּן דְּאִיהִי עִמָּנָא גּוֹ גָּלוּתָא, וְנָחֲתַת דִּיּוּרָהּ בְּגַוָונָא. אִי הָכֵי, אֲנַן צְרִיכִין לְמֶחֱדֵי, דְּהָא יְחֶזְקֵאל נְבִיאָה חָמָא לָהּ הָכָא, וְכָל אוּכְלוּסָהָא.</p>"],[9514015113,"<p>וַדַּאי, עַל דָּא אָנוּ צְרִיכִין לְמִבְכֵּי, וּלְמִסְפֵּד כְּתַנִּינָא, וּכְיַעֲנֵי מַדְבְּרָא, דְּאִיהוּ אִתְתְּרָכַת לְבַר מֵהֵיכָלָהּ, וַאֲנַן בְּגָלוּתָא, וְהִיא אָתַת עֲלָנָא בִּמְרִירוּ, וְחָמַאת לָנָא בְכָל יוֹמִין בְּכַמָּה עָאקוֹ, בְּכַמָּה נִימוּסִין גָּזְרִין עֲלָנָא בְּכָל זְמַן, וְלָא יָכְלָא לְאַעֲדָאָה מִינָן עָאקִין, וְכָל אִינוּן מַכְתְּשִׁין דַּאֲנַן סָבְלִין.</p>"],[9514015114,"<p>שָׁלְחוּ לְהוֹ בְּנֵי אַרְעָא קַדִּישָׁא, יָאוֹת דְּאִימָּנָא עָרְקַת, וְאִתְתְּרָכַת מִגּוֹ הֵיכָלָהָא, וְנָחֲתַת לְגַבַּיְיכוּ בִּמְרִירוּ וּבְקָל עָצִיב, כְּאִיתְּתָא דְּיָתְבָא בְּלָא דַעְתָּא, וּכְגַבְרָא דְּלָא יָכֵיל לְשֵׁיזָבָא, וְיָאוֹת לְכוֹן לְמִסְפֵּד.</p>"],[9514015115,"<p>אֲבָל אֲנַן, אִית לָן לְמִבְכֵּי וּלְמִסְפֵּד בִּנְהִי וּמְרִירוּ, דַּאֲנַן חָמָאן בְּכָל יוֹמָא הֵיכָלָא חָרֵיב, וְתַעֲלִין דְּמַדְבְּרָא עָאלִין וְנָפְקִין, וְשָׁרְקִין יַעֲנִים בְּגַוֵּיהּ, וַאֲנַן חָמָאן וּבָכָאן.</p>"],[9514015116,"<p>וּבְעוֹד דַּאֲנַן יָתְבִין נְבוֹכִין, וּשְׁכִיבִין פּוּמָנָא בְּעַפְרָא, אֲנַן שָׁמְעִין קָל נְעִימוּ דְרַגְלָהָא, בִּתְלַת מִשְׁמָרוֹתָא דְּלֵילְיָא, נְחָתַת וְחָמַאת לְהֵיכָלָאָה, אֵיךְ חֲרֵבִין מִתּוֹקְדָן, אָעֳלַת מֵהֵיכָלָא לְהֵיכָלָא, מִדּוּךְ לְדוּךְ, וְגָעַת וּמְיַילֶלֶת, וּבְכַת עֲלָנָא וְעַל נַפְשָׁנָא.</p>"],[9514015117,"<p>וַאֲנַן מִתְעָרִין לְקָל נְעִימוּ דִּבְכִיָּיתָהּ וִילָלוּתָהּ. וְרוּחָנָא אָזְלַת אֲבַתְרָהּ, וּפָרַח לְגַבָּהּ. וּלְפוּם שַׁעֲתָא פָּרְחַת וְאָזְלַת, וְלָא שְׁמַעְנָא, וְלָא יְדַעְנָא מִידֵי, דְּהָא אָזְלַת, וְאִשְׁתָּאַרְנָא נְבוֹכִין, דְּמִיכִין, בְּלָא רוּחָא, בְּלָא דַעְתָּא. צָעֲקִין, וְאָמְרִין אֵיכָה.</p>"],[9514015118,"<p>תָּנִינָן, בְּכָל לֵילְיָא וְלֵילְיָא, קָל מְרִירוּת דִּכְאִיבָא דְצִיּוֹ\"ן אִשְׁתְּמַע מֵרוּם רְקִיעָא לְתַתָּא, וּמִתַּתָּא לִרְקִיעָא. כְּמָה דְאַתְּ אָמֵר, (ירמיהו כ״ה:ל׳) ה' מִמָּרוֹם יִשְׁאַג וּמִמְּעוֹן קָדְשׁוֹ יִתֵּן קוֹלוֹ שָׁאֹג יִשְׁאַג עַל נָוֵהוּ.</p>"],[9514015119,"<p>בְּשֵׁירוּתָא דְלֵילְיָא, הִיא אִתְכַּוְּונַת בִּבְכִיָּה, וְשָׁאֲגַת מֵרוּם רְקִיעָא לְעֵילָא. נָחֲתַת לְתַתָּא, לַאֲתַר מִדְבַּח הַחִיצוֹן, וְחָמַת דּוּכְתָּהּ חָרֵיב, מְסָאַב בִּמְסָאֲבוּ, וְכָל אֲתַר לָא אִשְׁתְּכַח בֵּיהּ. גָּעַת וּמְיַלֶּלֶת, צווַֹחַת בְּקָל מְרִירוּ, וַאֲמָרַת, מִדְבְּחִי מִדְבְּחִי, פַּרְנָסָתִי דְּמַרְוֵית לִי בְּכַמָּה נִיסּוּכִין, בְּכַמָּה עִלַּוָּון דָּכְיָין קַדִּישִׁין.</p>"],[9514015120,"<p>כָל גֻּבְרִין קַדִּישִׁין, רַבְרְבָן מְמַנָּן, הֲווֹ מַרְוָון וְחָדָאן מִינָךְ, אָכְלִין עִידוּנִין, וּפַלְגִין חוּלָקֵיהוֹן, בְּרוּמֵי רְקִיעָא. יַהֲבוּ בָךְ נִיבְלַת חֲסִידִים קְדוֹשִׁים. בָּנַי דְּאִתְדַּבָּחוּ עֲלָךְ, וַוי לִי מִדְּמֵיהוֹן. וְכָל גֻּבְרִין רַבְרְבִין מְמַנָּן, נָפְלוּ מִדּוּכְתֵּיהוֹן לְקוֹל צְוָוחֵיהוֹן.</p>"],[9514015121,"<p>יָתְבִין לְבַר צְוָוחִין וּבָכָאן, אִינוּן אֶרְאֶלִים קַדִּישִׁין, דְּאָת שְׁמֵיהּ קַדִּישָׁא הֲוָה מִתְעַטֵר עֲלַיְיהוּ, וּבֵיהּ אִינוּן חָדָאן וְקָיְימִין. לְקָל בְּכִיּוּתְהוֹן אָת דָּא פָּרְחָא מִנַּיְיהוּ, וְסָלְקָא לְרוּמֵי מְרוֹמִים, וְאִשְׁתָּאֲרוּ כְּנוּקְבָא דְּבָכַאת וּמְיַלֶּלֶת. הֲדָא הוּא דִכְתִיב, (ישעיהו ל״ג:ז׳) הֵן אֶרְאֶלָּם צָעֲקוּ חֻצָה. אֶרְאֶלָם בְּלָא יוּ\"ד, צָעֲקוּ חוּצָה.</p>"],[9514015122,"<p>מִהְבְּחִי מִדְבְּחִי, לְבָתַר דְּמַרְוֵית לִי בְּנִיבְלוּת בְּנִין חֲסִידִין קַדִּישִׁין, דְּמָסְרוּ נַפְשֵׁיהוֹן וְגִשְׁמֵיהוֹן עֲלָךְ, אִיתְגְּנִיזַת. אָן אֶשְׁכַּח לָךְ, אָן אֶשְׁתָא דַּעֲלָךְ. גָּעַת וּמְיַילֶלֶת וּבָכַת בְּקָל עָצִיב.</p>"],[9514015123,"<p>שִׁתָּא אַלְפֵי גַבְרֵי קַדִּישִׁין, בְּכָל סִטְרָא דְאַרְבַּע סִטְרֵי עַלְמָא, אִינוּן דַּהֲווֹ אָכְלֵי קָרְבָּנָא בְּכָל יוֹמָא, נַחֲתֵי בַּהֲדָהּ, וּמְיַילְלִין וּבְכָיָין עַל מִדְבַּח דַּעֲלָוָון. וְיַתִּיר הֲווֹ, אֶלָּא אִתְמָעֲטוּ.</p>"],[9514015124,"<p>וַאֲפִילּוּ אִינוּן דְּקָיְימִין לְבַר, בְּרוּחַ אָחֳרָא, דְּמַרְוָון מֵאִינוּן אִימְרִין וּפְדָרִין. בְּשֵׁירוּתָא דְּלֵילְיָא צְוָחִין גָעָאן וּמְיַילְלִין עַל הַאי מִדְּבַּח. וַוי לְחַמְרָא דְּאָבֵיד אֵבוּסָה, אֲתַר דְּמִתְרַוֶּה מִנֵּיהּ. מַאן חָמֵי נְהִימוּ דְּגֻבְרִין קַדִּישִׁין בְּמַטְרוּנִיתָא, מִתַּתָּא לְעֵילָא, וּמֵעֵילָא לְתַתָּא.</p>"],[9514015125,"<p>בְּפַלְגוּ לֵילְיָא, עָאל לְגוֹ הַהִיא נְקוּדָה דְצִיּוֹן, אֲתַר דְּבֵית קֹדֶשׁ הַקֳּדָשִׁים, חָמַת לֵיהּ דְּאִתְחָרֵיב, וְאִסְתָּאַב אֲתַר בֵּית מוֹתָבָהּ וְעַרְסָהּ, גָּעַת וּמְיַילֶלֶת, סָלְקָא מִתַּתָּא לְעֵילָא, וּמֵעֵילָא לְתַתָּא, אִסְתַּכֵּל בַּאֲתַר דִּכְרוּבִים, צָוְוחָא בְּקוֹל מְרִירוּ, וַאֲרֵימַת קָלָא וְאָמְרָה, עַרְסִי עַרְסִי, אֲתַר בֵּית מוֹתָבִי. עַל הַאי דוּכְתָּא כְּתִיב, (שה\"ש ג) עַל מִשְׁכָּבִי בַּלֵּילוֹת. מִשְׁכָּבִי, עַרְסָא דְּמַטְרוּנִיתָא. גָּעַת בִּבְכִיָּה וְאָמְרָה, עַרְסִי אֲתַר מִקְדָּשִׁי, אֲתַר דְּמַרְגָּלָאִין טָבָאן, בֵּי פָּרוֹכְתָּא וְכַפּוֹרְתָּא, דַּהֲווֹ סָמְכִין עֲלוֹהִי שִׁתִּין אַלְפִין רִבְוָון אַבְנֵי יְקָר, סִדְרִין סִדְרִין, שׁוּרִין שׁוּרִין, מִסְתַּכְּלָאן דָּא לְדָא. סִדְרִין דְּרִמּוֹנִין מִתְצְעָן עֲלָךְ לְד' סִטְרִין. עַלְמָא קָיְימָא בְּגִינָךְ.</p>"],[9514015126,"<p>רִבּוֹן עָלְמָא, בַּעֲלִי, הֲוָה אָתֵי לְגַבִּי, וְהוּא שָׁכַב בֵּין דְּרוֹעִי, וְכָל מַה דִּבְעֵינָא מִנֵּיהּ, וְכָל בָּעוּתִי עָבִיד בְּעִידָנָא דָא. כַּד הֲוָה אָתֵי לְגַבִּי, וְשַׁוֵּי בִּי מְדוֹרֵיהּ, וּמִשְׁתַּעֲשֵׁעַ בֵּין שָׁדַי.</p>"],[9514015127,"<p>עַרְסִי עַרְסִי, לֵית אַתְּ דְּכִיר כַּד הֲוֵינָא אָתָא לְגַבָּךְ בְּחֶדְוָה וּבְשַׁפִּירוּ דְלִבָּא, וְאִינוּן רַבְיָין עוּלֵמִין, הֲוֵי נָפְקִי לָקֳדָמוּתִי, בַּטְשֵׁי בְּגַדְפַיְיהוּ בְּחֶדְוָה, לְקַבָּלָא לִי.</p>"],[9514015128,"<p>עַפְרָא דְבָךְ, הֲוָה קָם מִדּוּכְתֵּיהּ, וְחָזוּ אֵיךְ אִיתְנַשְׁיָא אֲרוֹנָא דְאוֹרַיְיתָא דַּהֲוַת הָכָא, מֵהָכָא נַפְקָא מְזוֹנָא לְכָל עַלְמָא, וּנְהוֹרָא, וּבִרְכָאן לְכֹלָּא.</p>"],[9514015129,"<p>אַשְׁגַּח עַל בַּעֲלִי, לֵית הָכָא. אַשְׁגַּח לְכָל סְטַר. בְּעִידָנָא דָא כַּד הֲוָה אָתֵי בַּעֲלִי לְגַבִּי, וְסָחֳרָנֵיהּ כַּמָּה בְּנִין חֲסִידִין, וְכָל אִינוּן עוּלֵמְתָאן זְמִינִין לְקַבְּלָא לֵיהּ.</p>"],[9514015130,"<p>וַהֲוֵינָא שָׁמְעִין מֵרָחוֹק, קָל זוּגִין דְּפַעֲמוֹנִים מְקַשְׁקְשִׁין בֵּין רַגְלוֹי, בְּגִין דְּאֶשְׁמַע קָלֵיהּ עַד דְּלָא יֵעוֹל לְגַבִּי. כָּל עוּלֵימְתָאן דִּילִי, מְשַׁבְּחָן וְאוֹדָן קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, לְבָתַר אָזְלִין כָּל חַד עַל בֵּי מוֹתָבֵיהּ, מְחַבְּקָן בִּנְשִׁיקַתְהוֹן בִּרְחִימוּ.</p>"],[9514015131,"<p>בַּעֲלִי בַּעֲלִי, אָן פָּנִיתָ, הַשְׁתָּא הוּא עִדָּנָא דַּהֲוֵינָא אַשְׁגַּח בָּךְ. אִסְתַּכַּלְנָא בְּכָל סְטַר, וְלֵית אַנְתְּ. אָן אַשְׁגַּח לָךְ, וְלָא אֶתְבַּע בְּגִינָךְ.</p>"],[9514015132,"<p>דָּא הוּא אַתְרָךְ בְּעִידָנָא דָא, לְמֵיתֵי לְגַבִּי, הָא אֲנָא זְמִינָא הָכָא. הָא אִתְנְשֵׁית מִנָּאי, לֵית אַנְתְּ דְּכִיר יוֹמֵי דִּרְחִימוּ, כַּד הֲוֵינָא שָׁכְבַת בְּתוּקְפָּךְ, וּמְחַקְּקָא בִּדְיוֹקְנָךְ, וּדְיוֹקְנִי הֲוַות מְחַקְּקָא בָּךְ, כְּהַאי חוֹתָם דְּשָׁבֵיק דְּיוֹקְנֵיהּ בִּגְלִיפוּ דִּכְתָבָא, הָכֵי שַׁבַקְנָא דְּיוֹקְנִי בָּךְ, בְּגִין דְּתִשְׁתַּעְשַׁע בִּדְיוֹקְנִי, בְּעוֹד דַּאֲנָא בְּגוֹ חֵילִי.</p>"],[9514015133,"<p>גָּעַת בִּבְכִיָה, וְצָוְחַת, בַּעֲלִי בַּעֲלִי, נְהִירוּ דְּעַיְינֵי הָא אִיתְחֲשָׁךְ. לֵית אַנְתְּ דְּכִיר, כַּד הֲוֵית אוֹשִׁיט שְׂמָאלָךְ מִתְּחוֹת רֵישִׁי, וַאֲנָא מִתְעַנְּגָא עַל סְגִיאוּ דִשְׁלָם, וִימִינָךְ מְחַבְּקָא בְּאַחְוָה וּבִנְשִׁיקִין. וְנָדַרְתְּ לִי דְּלָא תִשְׁבּוֹק רְחִימוּתָא דִילִי לְעָלְמִין. וְאוֹמֵית לִי, (תהילים קל״ז:ה׳) אִם אֶשְׁכָּחֵךְ יְרוּשָׁלַיִם תִּשְׁכַּח יְמִינִי, הָא אִיתְנְשֵׁינָא מִנָּךְ.</p>"],[9514015134,"<p>לֵית אַנְתְּ דְּכִיר, כַּד קָאֵימְנָא לְגַבָּךְ בְּטוּרָא דְסִינַי, שְׁלֵימִין שִׁתִּין רִבּוֹ דְּקַבִּילוּ לָךְ עֲלַיְיהוּ, וְאִתְעַטַרְנָא לָךְ בְּהוּ, יַתִּיר מִכָּל עַמְמַיָיא, וַהֲוֵינָא אָזְלִין אֲבַתְרָךְ לְכָל רְעוּתָךְ. וְהַהִיא שִׁפְחָה קָטְלָא בְּהוּ לַאֲלָפִים וְרִבְוָון, וְלָא אַשְׁגַּחְנָא. וְאִתְאֲבִידוּ כֻּלְּהוּ בְּמַדְבְּרָא, וְשַׁבְקֵית לוֹן תַּמָּן, וְאָעֵילְנָא בְּנֵיהוֹן זְעִירִין לְקָיְימָא קַמָּךְ בְּאַרְעָא דָא. וּבָדֵילְנָא לוֹן לְקָיְימָא קַמָּךְ, בְּגִין רְעוּתָךְ.</p>"],[9514015135,"<p>בַּעֲלִי הֱוֵי דְכִיר, בְּכַמָּה בְּנִין קַדִּישִׁין קָאֵימְנָא קַמָּךְ בְּכָל דָּרָא וְדָרָא, בְּיוֹמֵי דְדָוִד וּשְׁלֹמֹה בְּרֵיהּ. לֵית אַנְתְּ דְּכִיר כַּמָּה טָבָאן דַּעֲבָדוּ קַמָּךְ. יָאוֹת לָךְ לְמִידְכַּר חוֹבִין, וְלָא תִדְכַּר זַכְוָון. אָן אִתְהַפִּיכוּ עֲלָךְ.</p>"],[9514015136,"<p>בָּעֵינָא עֲלָךְ, לֵית אַנְתְּ. בָּעֵינָא עַל בְּנָאי, לֵית אִינוּן. בָּעֵינָא עַל קְדוּשָּׁתָא דַּאֲתַר דָּא, הָא אִסְתָּאַב. כָּל עַלְמָא הֲוָה בִּשְׁלָם בְּגִין אֲתַר דָּא. כְּלָבִין לָא נָבְחִין בְּעִידָנָא דָא, כּוּלְּהוּ הֲווֹ בִּשְׁלָם. גָּעָה וּמְיַילֶלֶת, וְכָל אִינוּן אוּכְלוּסִין לְעֵילָא. וּכְלָבִים צָוְוחִין לְתַתָּא, בְּשֵׁרוּתָא דְּמִשְׁמוֹרָה תְּלִיתָאָה.</p>"],[9514015137,"<p>נָפְקַת וַאֲתַת, קָיְימָא עַל אֲתַר דְּמַדְבְּחָא קְטוֹרֶת בּוּסְמִין, גָּעַת וּמְיַילֶלֶת, וְסָלְקַת לְעֵלָּא, וְאַשְׁכְּחָא חַד כְּרוּב מֵאִינוּן תְּרֵין כְּרוּבִין דַּהֲווֹ בַּהֲדָהּ, וּמֵהַהוּא זִמְנָא לָא הֲוָה לָהּ אֶלָּא חַד. וְהַהוּא רַבְיָיא עוּלֵימָא דְּאִשְׁתָּאַר, יָנְקָא מִינָהּ בְּכִיָּיה וִילָלוּתָא.</p>"],[9514015138,"<p>כְדֵין קוּדְשָׁא בְּרִיךְ הוּא אִזְדַּמַּן לְגַבָּהּ, וְנָחֵית לָהּ, וּמְמַלֵּל עִמָּהּ. וְעַל דָּא כְּתִיב, (ירמיהו ל״א:ט״ז) כֹּה אָמַר ה' מִנְעִי קוֹלֵךְ מִבֶּכִי וְעֵינַיִךְ מִדִּמְעָה כִּי יֵשׁ תִּקְוָה לְאַחֲרִיתֵךְ. וְעַל דָּא תָּנִינָן, תִּינוֹק יוֹנֵק מִשְּׁדֵי אִמּוֹ, וְאִשָּׁה מְסַפֶּרֶת עִם בַּעֲלָהּ. עַד הָכָא פְּתִיחָתָא, מִכָּאן וּלְהָלְאָה שֵׁירוּתָא דִּמְגִילַּת אֵיכָה.</p>"],[9514015139,"<p>אֵיכָה יָשְׁבָה בָדָד, רַבָּנָן פָּתְחֵי הַאי קְרָא, (קהלת י״ב:א׳) וּזְכוֹר אֶת בּוֹרְאֶךָ בִּימֵי בְחוּרוֹתֶיךָ עַד אֲשֶׁר לֹא יָבוֹאוּ יְמֵי הָרָעָה. הַאי קְרָא, אוֹקִימְנָא לֵיהּ בְּיִשְׂרָאֵל כַּד הֲווֹ בְּאַרְעָא קַדִּישָׁא. וּזְכוֹר אֶת בּוֹרְאֶיךָ, הֱוֵי דְכִיר כָּל אִינוּן טָבָאן, וְכָל אִינוּן אָתִין וְנִסִּין, דַּעֲבַד לָךְ קוּדְשָׁא בְּרִיךְ הוּא בְּיוֹמִין קַדְמָאִין, כַּד הֲוַות רַבְיָא בִּמְהֵימְנוּתָא, כְּמָה דְאַתְּ אָמֵר, (הושע י״א:א׳) כִּי נַעַר יִשְׂרָאֵל וָאֹהֲבֵהוּ.</p>"],[9514015140,"<p>בִּימֵי בְחוּרוֹתֶיךָ, בְּזִמְנָא דְּאִיהוּ אִיתְרְעֵי בָּךְ מִכָּל עַמִּין דְּעַלְמָא. עַד אֲשֶׁר לֹא יָבֹאוּ יְמֵי הָרָעָה, יוֹמִין דְּזִקְנָה, דְּשָׁלְטִין בָּךְ שְׁאָר עַמִּין, וִיבַדְּרוּן לָךְ בְּכָל עַמְמַיָא.</p>"],[9514015141,"<p>בִּימֵי בְחוּרוֹתֶיךָ, יוֹמִין דְּשַׁתָּא, דְּאִינוּן בְּרִירִין לָךְ, וּנְטִירוּ דִּלְעֵילָא עֲלָךְ. וְאִינוּן ד' יַרְחֵי דְשַׁתָּא, אֲדָר נִיסָן אִיָּיר סִיוָן. אִלֵּין אִינוּן יוֹמִין דְּבָחַר קוּדְשָׁא בְּרִיךְ הוּא בְּיִשְׂרָאֵל, וַעֲבַד בְּהוֹן עִמְּהוֹן נִסִּין. וּכְּנֶסֶת יִשְׂרָאֵל מִתְעַטְרָא בְּבַעֲלָהּ, וְאִתְקְרֵיבַת בַּהֲדֵיהּ.</p>"],[9514015142,"<p>עַד אֲשֶׁר לֹא יָבֹאוּ יְמֵי הָרָעָה, יְמֵי הַזִּקְנָה, יְמֵי הָרָעָה מַמָּשׁ, וְאִינוּן: תַּמּוּז אָב טֵבֵת שְׁבָט. אַף עַל גַּב דְּלָא אִיתְגַּלְּיָיא כָּל כָּךְ, וְסִימָנָךְ (משלי י) וְשֵׁבֶט לְגֵו חֲסַר לֵב.</p>"],[9514015143,"<p>וְהִגִּיעוּ שָׁנִים, שָׁנִים דְּגָלוּתָא, דְּאָזְלִין יִשְׂרָאֵל מְטוּלְטָלִין. אֵין לִי בָּהֶם חֵפֶץ, דְּתָנִינָן, זְמִינִין בְּיוֹמָא דְגָלוּתָא, דְּלָא יִשְׁתַּכַּח בִּידָא דְּבַר נָשׁ לְמִיזְבַּן בְּשׁוּקָא, וּכְדֵין תִּכְלֶה פְּרוּטָה מִן הַכִּיס.</p>"],[9514015144,"<p>עַד אֲשֶׁר לֹא תֶּחְשַׁךְ הַשֶּׁמֶשׁ, דָּא קְלַסְתֵּר פָּנִים שֶׁל שְׁכִינָה, מִלְּעֵילָא וּמִתַּתָּא. מִתַּתָּא מַאן אִינוּן. מָארֵי מַתְנִיתִין דַּהֲווֹ בְּאַרְעָא דְיִשְׂרָאֵל, פַּטִישֵׁי דְפַרְזְלָא, מְהַדְקִין טִנָּרִין, וְתָלְשִׁין טוּרִין רָמָאִין.</p>"],[9514015145,"<p>וְהָאוֹר, זֶה הַתַּלְמוּד יְרוּשַׁלְמִי, דְּנָהֵיר נְהוֹרָא דְאוֹרַיְיתָא, לְבָתַר דְּאִתְבַּטֵל דָּא, כִּבְיָכוֹל, אִשְׁתָּאֲרוּ בַּחֲשׁוֹכָא. דִּכְתִיב, (איכה ג) בְּמַחֲשַׁכִּים הוֹשִׁיבַנִּי, זֶה תַּלְמוּד בַּבְלִי, דְּאָזְלִין בֵּיהּ בְּנֵי עַלְמָא בְּמַחֲשַׁכִּים.</p>"],[9514015146,"<p>וְהַיָּרֵחַ, אִלֵּין אִינוּן הַבָּרַיְיתוֹת, דַּהֲווֹ נְהִירִין נְהִירוּ דְּחָכְמָה סְתִימָאָה. וְהַכֹּכָבִים, אִלֵּין אִינוּן מַשְׂכִּילִים דַּהֲווֹ בְּאַרְעָא קַדִּישָׁא, כָּל אִינוּן תַּנָּאִים וָאֳמוֹרָאִים, דְּכָל עָלְמָא קָיְימָא בְּגִינַיְיהוּ. דְּכַד הֲווֹ קָיְימֵי כַּחֲדָא, הֲוָה אָמַר בַּר נָשׁ לְחַבְרֵיהּ, מִגּוֹ מִלָּה דָא דְּפָרַח מִפּוּמוֹי, אֲנָא חָמָא מַה דִּיהֵא יוֹמָא דָא, אוֹ לְמָחָר, כָּךְ וְכָךְ.</p>"],[9514015147,"<p>דָּבָר אַחֵר (קהלת יב) עַד אֲשֶׁר לֹא תֶּחְשַׁךְ הַשֶּׁמֶשׁ, נְהִירוּ דִּקְלַסְתֵּר פְּנֵי שְׁכִינָה, דְּהֲוָה נָהֵיר לָהּ בְּכָל יוֹמָא, וּמֵהַהוּא נְהִירוּ עַלְמָא אִתְקַיֵּים, וְיִשְׂרָאֵל שָׁרָאן עַל אַרְעָא לְרוֹחֲצָנוּ.</p>"],[9514015148,"<p>וְהָאוֹר, אוֹר שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַעֲשֵׂה בְרֵאשִׁית, דְּהֲוָה נָהֵיר מִסֵיְיפָי עַלְמָא לִסֵיְיפָי עַלְמָא, וְאִתְגְּנֵיז. וְהַקָּדוֹשׁ בָּרוּךְ הוּא הֲוָה נָהֵיר, וְאַפֵּיק מִינֵיהּ חַד חוּטָא דִּימִינָא דְקוּדְשָׁא בְּרִיךְ הוּא, וְאָחֵיד לְסִיהֲרָא. וּבְהַהוּא זִימְנָא כְּתִיב, (איכה ב) הֵשִׁיב אָחוֹר יְמִינוֹ.</p>"],[9514015149,"<p>וְהַיָּרֵחַ, דִּכְתִיב (ישעיהו א׳:כ״א) צֶדֶק יָלִין בָּהּ. וְהַכֹּכָבִים, מַלְאֲכֵי הַשָּׁרֵת, שֶׁהָיוּ בָּאִים בָּהּ וִידוּעִים אֶצְלָהּ, וּבָטְלוּ מִקִּיּוּמַיְיהוּ, וְאִלֵּין אִיקְרוּן מַלְאֲכֵי שָׁלוֹם. וְשָׁבוּ הֶעָבִים אַחַר הַגֶּשֶׁם, דִּכְתִיב (שם לג) מַלְאֲכֵי שָׁלוֹם מַר יִבְכָּיוּן.</p>"],[9514015150,"<p>(קהלת י״ב:ג׳) בַּיּוֹם שֶׁיָּזְעוּ שֹׁמְרֵי הַבַּיִת, אִלֵּין תְּלַת בָּתֵּי דִינִין, דַּהֲווֹ אוֹלְפֵי תּוֹרָה בְּלִשְׁכַּת הַגָּזִית. וְהִתְעַוְּתוּ אַנְשֵׁי הֶחָיִל, אֵלּוּ סַנְהֶדְּרֵי גְדוֹלָה וְסַנְהֶדְּרֵי קְטַנָּה. וּבָטְלוּ הַטֹחֲנוֹת, אֵלּוּ כֹּהֲנִים וּלְוִיִם, וְכֻלְּהוּ מִשְׁמָרוֹת דַּהֲווֹ קָיְימֵי בִּירוּשָׁלָיִם.</p>"],[9514015151,"<p>וְחָשְׁכוּ הָרֹאוֹת בָּאֲרֻבּוֹת, אִלֵּין נְבִיאִים וְצוֹפִים, דַּהֲווֹ חָמָאן בִּנְבוּאָה וּבְרוּחַ הַקֹּדֶשׁ. (שם) וְסֻגְּרוּ דְלָתַיִם בַּשּׁוּק, דִּבְנֵי נָשָׁא צְוָוחִין, וְלֵית מַאן דְּיָתֵיב עֲלַיְיהוּ, דְּהָא כָּל תַּרְעִין נִנְעֲלוּ, מִן יוֹמָא דְּאִתְחָרַב בֵּי מַקְדְּשָׁא, וּבְטֵילַת עֲבִידַת בֵּית אֱלָּהָנָא.</p>"],[9514015152,"<p>בִּשְׁפַל קוֹל הַטַחֲנָה, אִלֵּין אִינוּן כּוֹתְשֵׁי קְטוֹרֶת, דַּהֲווֹ יַהֲבֵי קָלָא בְּכָל יוֹמָא, בִּכְתִּישׁוּ דִּילֵיהּ. דָּבָר אַחֵר קוֹל הַטַחֲנָה, קָלָא דִּשְׁכִינְתָּא, צְוָוחָא בְּכָל יוֹמָא, שׁוּבוּ בָּנִים שׁוֹבָבִים, וְלֵית מַאן דְּיַשְׁגַּח בָּהּ.</p>"],[9514015153,"<p>וְיִשַּׁחוּ כָּל בְּנוֹת הַשִּׁיר, אִלֵּין אִינוּן דְּסָלְקִין בְּדוּכָנָא בְּכָל יוֹמָא, וּמְנַגְנֵי נִיגוּנָא דְשִׁיר. כָּל, לְאַסְגָּאָה מַלְאֲכֵי עִילָּאָה לְעֵילָא, דַּהֲווֹ מִתְחַלְּקֵי מִשְׁמָרוֹת לְעֵילָא, לָקֳבֵל אִינוּן מִשְׁמָרוֹת לְתַתָּא. שַׁחוּ, אִלֵּין דִּלְתַתָּא. כִּבְיָכוֹל, אַף אִלֵּין דִּלְעֵילָא שַׁחוּ. גַּם מִגָּבֹהַּ יִירָאוּ. וְאַף עַל גַּב דְּמִגָּבוֹהַּ הֲווֹ נַנָּסָא, הֲווֹ דַּחֲלִין.</p>"],[9514015154,"<p>שַׁחוּ אִינוּן בְּנוֹת שִׁיר, בְּגִין דְּהָא פ' אֶלֶף לְוִיִּים, הֲווֹ יְדֵיהוֹן מְהַדְּקָן לַאֲחוֹרָא. כַּד מְטוֹ לְנַהֲרוֹת בָּבֶל, כִּנּוֹרֵיהוֹן הֲווֹ תַּלְיָין עַל אִילָנִין דְּתַמָּן. הֲווֹ שָׁאֲלִין לוֹן לְנַגְנָא. וְאָמְרֵי, (תהילים קל״ז:ד׳) אֵיךְ נָשִׁיר אֶת שִׁיר ה' עַל אַדְמַת נֵכָר. נָשְׁכוּ בְּשִׁנֵּיהוֹן בּוֹהֲנֵי יְדֵיהוֹן וְכָרְתוּ לוֹן, וְלָא יָכִילוּ לְנַגְנָא, וּקְטָלוּ לוֹן.</p>"],[9514015155,"<p>וְחַתְחַתִּים בַּדֶּרֶךְ, דְּהָא הֲווֹ אָזְלִין בְּרֵיחַיָּין עַל צַוָּארֵיהוֹן, וּמֵהַדּוֹקָא דְּהֲוָה תַּקִּיף, הֲווֹ נָפְלוּ אֶצְבְּעוֹתַיְיהוּ בְּאוֹרְחָא. וְיִרְמְיָה הֲוָה לָקֵיט לוֹן בְּטַלִּיתֵיהּ, וְנָשֵׁיק לוֹן, וּבָכֵי עֲלַיְיהוּ. וַהֲוָה אָמַר לְהוֹ, בָּנַי, וְלָא אֲמָרִית לְכוֹ, (ירמיהו י״ג:ט״ז) תְּנוּ לַה' אֱלֹהֵיכֶם כָּבוֹד בְּטֶרֶם יַחְשִׁיךְ וְגו'. וְעַל דָּא כְתִיב, (שם ט) עַל הֶהָרִים אֶשָּׂא בְּכִי וָנֶהִי וְעַל נְאוֹת מִדְבָּר כו'.</p>"],[9514015156,"<p>(קהלת י״ב:ה׳) וְיָנֵאץ הַשָּׁקֵד, מִן יוֹמָא דְּנָצֵיץ אִילָנָא דָא לַבְלְבִין, עַד יוֹמָא דַּעֲבֵיד אִיבָּה, חַד וְעֶשְׂרִים יוֹמָא נִינְהוּ. כָּךְ מִי\"ז בְּתַמּוּז עַד ט' בְּאָב, כ\"א יוֹם בֵּינַיְיהוּ. הֲדָא הוּא דִכְתִיב, (ירמיהו א׳:י״א) מַקֵּל שָׁקֵד אֲנִי רוֹאֶה.</p>"],[9514015157,"<p>וְיִסְתַּבֵּל הֶחָגָב, דְּאִתְיְהֵב מָטוֹלָא עַל כִּתְפוֹי דְּזַרְעָא דְדָוִד. וְתָפֵר הָאֲבִיּוֹנָה, דְּאִתְבַּטֵל עֲבֵידַת בֵּית אֱלָהָנָא. כִּי הוֹלֵךְ הָאָדָם לְבֵית עוֹלָמוֹ, דָּא הוּא כָּבוֹד, דְּאִסְתַּלַּק לְעֵילָא. וּבְנֵי נָשָׁא צָוְוחִין, וְלֵית מַאן דְּיַשְׁגַּח בְּהוּ.</p>"],[9514015158,"<p>(קהלת י״ב:ו׳) עַד אֲשֶׁר לֹא יֵרָתֵק חֶבֶל הַכֶּסֶף, אֲתַר דְכַהֲנָא מַקְטִיר קְטוֹרֶת עַל מַדְבְּחָא דִּלְגַאו. וְתָרֻץ גֻּלַּת הַזָּהָב, דָּא הוּא בֵּית קֹדֶשׁ הַקֳּדָשִׁים, דְּתַמָּן כְּרוּבִים דִּדְהַב. וְתִשָּׁבֵר כַּד עַל הַמַּבּוּעַ, דָּא מַלְכוּת בֵּית דָּוִד דְּאִיתְבַּר.</p>"],[9514015159,"<p>וְיָשֹׁב הֶעָפָר עַל הָאָרֶץ כְּשֶׁהָיָה, יִתְחָרַב בֵּי מַקְדְּשָׁא, וִיהֵא כְּעַפְרָא. וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ, דָּא שְׁכִינְתָּא, וְאִסְתַּלְּקוּתָא דְרוּחַ נְבוּאָה מִן עָלְמָא.</p>"],[9514015160,"<p>רַבִּי יוּדָאי פָּתַח, (שם) בַּיּוֹם שֶׁיָּזְעוּ שֹׁמְרֵי הַבַּיִת, אִלֵּין תַּנָּאִים וָאֳמוֹרָאִים, דַּהֲווֹ נָטְרֵי עַמָּא דְאַרְעָא דְיִשְׂרָאֵל, וְאִזְדַּעְזְעוּן מִדּוּכְתַּיְיהוּ.</p>"],[9514015161,"<p>וְהִתְעַוְּתוּ אַנְשֵׁי הֶחָיִל, כְּמָה דְאַתְּ אָמֵר, (בראשית מ״ז:ו׳) וְיֵשׁ בָּם אַנְשֵׁי חַיִל. חוֹבָא דִבְנֵי יַעֲקֹב, דַּהֲווֹ אַנְשֵׁי חָיִל, וְסָבְלֵי עִוּוּת דִּינָא, כְּמָה דְאַתְּ אָמֵר, (איוב ח׳:ג׳) הָאֵל יְעַוֵּת מִשְׁפָּט. קַבִּילוּ עִוּוּת דִּינָא. אִינוּן אַנְשֵׁי חָיִל. דְּכָךְ אוֹרְחוֹי דְּנָחָשׁ, לְבָתַר דְּקָטֵיל לְבַר נָשׁ, אַהֲדַר וְנָשֵׁיךְ לֵיהּ נְשִׁיכוּ בְּלָא רַחֲמִין, (\"חילופי גרסאות\") דָּא אִיהוּ עִוּוּת דִּינָא.</p>"],[9514015162,"<p>שָׁלְחוּ לְהוֹ בְּנֵי אַרְעָא קַדִּישָׁא, יָאוֹת דְּאַתּוּן אִית לְכוֹן לְמִבְכֵּי, כְּמַאן דְּבָכֵי מֵרָחִיק. דְּהָא אֶבְלָא וּבְכִיָה וּמִסְפְּדָא בִּנְהִי וּמְרִירוּ לָא מָטָא לְכוֹ. דְּהָא רְחַצְתִּין רַגְלֵיכוֹן, וְלָא בְּעִיתוּ לְטַנְפָא לוֹן כְּמִלְּקַדְמִין. כְּמָה דְאַתְּ אָמֵר, (שיר השירים ה׳:ג׳) רָחַצְתִּי אֶת רַגְלַי אֵיכָכָה אֲטַנְּפֵם.</p>"],[9514015163,"<p>אֲבָל אֲנַן דְּשָׁכְנִין בֵּין גִּדְרֵי נָחָשׁ, וְכָמִין לוֹן בְּכָל יוֹמָא, קָטֵיל, וְנָשֵׁיךְ, וַאֲנַן חָמֵינָן בְּעַיְינִין עִוּוּת הַדִּין דְּאִתְעֲבֵיד בֵּינָנָא, בְּאִינוּן אַנְשֵׁי חָיִל, דִּי בְּיוֹמֵיהוֹן שָׁתֵיק, וְלָא בָּעָא דִינָא. דְּדָחֵיל מִינַיְיהוּ דְּחִילוּ סַגֵּי, וְלָא יָכֵיל לְקָיְימָא קַמַּיְיהוּ. וְכֵיוָן דַּעֲבָרוֹ לְהַהוּא עַלְמָא בִּתְיוּבְתָּא, קָיְימָא נָחָשׁ קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְתָבָע דִינָא.</p>"],[9514015164,"<p>וְהַיֵּיק קְרָא דִּכְתִיב, (שמות כ״א:ט״ז) וְגוֹנֵב אִישׁ וּמְכָרוֹ וְנִמְצָא בְיָדוֹ מוֹת יוּמָת. אָמַר קוּדְשָׁא בְּרִיךְ הוּא לַנָּחָשׁ, יוֹסֵף לֹא הָיָה אִישׁ. וְנִמְצָא בְיָדוֹ וְגו', הָא בִידֵיהוֹן לָא אִשְׁתַּכַּח. אַהֲדַר וְקָאֲמַר, (דברים כ״ד:ז׳) כִּי יִמָּצֵא אִישׁ גּוֹנֵב נֶפֶשׁ מֵאֶחָיו מִבְּנֵי יִשְׂרָאֵל וְהִתְעַמֶּר בּוֹ וּמְכָרוֹ וּמֵת הַגַּנָּב הַהוּא.</p>"],[9514015165,"<p>תְּמַנֵּי מְאָה שְׁנִין הֲוָה קָיְימָא הַהוּא נָחָשׁ וְתָבַע דִּינָא. וַאֲנַן תָּנִינָן, מַאן דְּאִתְחַיָּיב בִּתְרֵי דִינִין, אִתְדָּן בַּחֲמִירָא. וַוי מַאן דַּקַבֵּיל עוֹנָשָׁא עַל חוֹבוֹי, דְּהָא מִיתָה מְכַפְּרָה עַל חוֹבִין, וְאַהֲדַר לְקַבֵּל עוֹנָשָׁא אוֹחֲרָא, וַוי דִי הִתְעַוְּתוּ אַנְשֵׁי הֶחָיִל, וּסמאל וְנָחָשׁ קָיְימוּ לְתָבְעָא דִינָא. עַל דָּא יָאוֹת לָן לְמִבְכֵּי וּלְמִסְפֵּד, דְּקַרְתָּא קַדִּישָׁא אִשְׁתָּאֲרַת בָּדָד מִכָּל טָבִין דַּהֲווֹ בָהּ. בְּהַהִיא שַׁעֲתָא נָחַת סמאל וּבִלְבֵּל עַלְמָא, וְאָעֵיל רוּחָא דָא בְּמֵעוֹי דְּהַהוּא רָשָׁע מַלְכָּא דְרוֹמִי, וְתָבַע דִּינָא מִתַּקִּיפֵי עַלְמָא. וַוי לְדָא, וַוי לְעַלְמָא, עִוּוּת דִּינָא לָא אִשְׁתַּכַּח מִן יוֹמָא דְּאִתְבְּרֵי עָלְמָא, כְּדָא.</p>"],[9514015166,"<p>אֵיכָה בָּנַיִךְ עַמּוּדִים דְּעָלְמָא, קָיְימִין סָמְכִין, דְּעַלְמָא קָיְימָא עֲלֵיהוֹן, וַאֲנָא מִתְעַטְרָא עֲלֵיהוֹן בְּכָל יוֹמָא. הֵיךְ הִתְעַוְּותוּ עַל יְדֵי דְּנָחָשׁ, הֵיךְ הִתְעַוְּותוּ רוּחִין קַדִּישִׁין, לְאִתְלַבְּשָׁא בִּלְבוּשִׁין נֻכְרָאִין אָחֳרָנִין, לְמֵידַן לוֹן בִּקְלָנָא סַגֵּי, וַוי לְדָא, וַוי לְעִוּוּתָא דָא.</p>"],[9514015167,"<p>מַאן חָמָא גּוֹ גִּנְתָא דְעֵדֶן, בְּשַׁעֲתָא דְּאִתְמְסַר דִּינָא לְעֵילָא. עֶשֶׂר מַרְגְּלָאן שַׁפִּירָאן, נְהִירוּ דְּכָל גִּנְתָא, בֵּין כָּל אִינוּן אִילָנִין. מִתְפַּשְׁטִין וְנָפְקִין כֻּלְּהוּ לְבַר. וְכָל אִינוּן אִילָנִין דְּגִנְתָא דְעֵדֶן, צְוָוחִין וְאָמְרִין, וַוי דְּהִתְעַוְּותוּ אַנְשֵׁי הֶחָיִל. וּנְטוּרֵי תַּרְעָא דְּגִנְתָא דְעֵדֶן מִזְדַּעְזְעָן, אִינוּן כְּרוּבִים, סָלְקִין וְנָחֲתִין, וְלָא יַהֲבֵי דוּכְתָּא לַאֲפָקָא אִלֵּין נְהוֹרִין.</p>"],[9514015168,"<p>כַד אִתְפַּשְּׁטוּ מִגּוֹ נְהוֹרִין דִּלְבוּשֵׁיהוֹן. וְעִילָּאִין וְתַתָּאִין צָוְוחִין לָקֳדָמוּתְהוֹן, וְאִינוּן נְטוּרֵי חוֹמוֹת לְעֵילָא מִזְדַּעְזְעִין, וְכָל חַיָּילֵי רוּם שְׁמַיָּיא בָּכָאן וּמְיַילְלָן. מַאן חָמָא לְאִימָּנָא גָּעַת וּמְיַילְלָא. נָחֲתַת לְגַבֵּי כְּרוּבִים, נְטוּרֵי תַּרְעִין דִּבְגִנְתָא, וְאִינוּן מִזְדַּעְזְעִין. סָלְקַת אִימָּנָא, וְחַד כְּרוּב בַּהֲדָהּ.</p>"],[9514015169,"<p>וּכְדֵין לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, שְׁנָנָא סַגֵּי, בָּטַשׁ לְגוֹ תַּרְעִין, וּנְפָקוֹ אִינוּן עֶשֶׂר נְהוֹרִין. עִילָּאִין וְתַתָּאִין צָוְוחִין, וַוי לְעַלְמָא, וַוי לְדָרָא.</p>"],[9514015170,"<p>אֲנַן יָאוֹת לָן לְמִסְפֵּד כְּתַנִּים, כַּד נָחֲתַת אִימָּא, וְלָא אַשְׁכָּחַת לוֹן תַּמָּן בְּגִנְתָא, וְכָל אִינוּן נְהוֹרִין וּבוּסְמִין, גָּעָאן וּמְיַילְלָן, כְּדֵין גָּעַת וּמְיַילֶלֶת. אִינוּן כְּרוּבִים נְטוֹרֵי תַּרְעִין בָּכָאן וּמְיַילְלָן, פָּתְחִין בִּבְכִיָּה, אֲנַן עַל אַחַת כַּמָּה וְכַמָּה יָאוֹת לָן לְמִבְכֵּי עַל כּוֹלָּא, וְעַל עִוּוּתָא דָא.</p>"],[9514015171,"<p>תוּ פְּתַח, (בראשית נ׳:י״ז) וַיְצַוּוּ אֶל יוֹסֵף לֵאמֹר וְגו' (שם) אָנָא שָׂא נָא פֶּשַׁע אַחֶיךָ וְחַטָאתָם וְגו' וַיֵּבְךִָֹּ יוֹסֵף בְּדַבְּרָם אֵלָיו. חוֹבָא לֵיהּ עֲבָדוּ, וְהוּא מְכַפֵּר כּוֹלָּא, וּמְכַפֵּר עַל חוֹבַיְיהוּ. כֵּיוָן דְּאִיהוּ מָחֵיל, מַאן אִית לֵיהּ לְתָבְעָא עַל חוֹבַיְיהוּ. הֱוֵי וְהִתְעַוְּתוּ אַנְשֵׁי הֶחָיִל. עִוּוּת הַדִּין סַגֵּי, הֲוָה לְאִינוּן אַנְשֵׁי הֶחָיִל, וַוי לָן, מַאן יְנַחֵם לָן.</p>"],[9514015172,"<p>אַמַּאי הֲוָה עִוּוּת דִּינָא דָא. בְּגִין דְּהָא אִימָּנָא אִתְתָּרְכַת וְעָרְקַת, וַאֲזָלַת לָהּ, וּבְגִין דָּא עַוִּית דִּינָא אִשְׁתַּכַּח, דְּאִשְׁתַּכְּחָא בִּלְחוֹדָהָא הַהוּא דְּאַשְׂטָנָא עֲלָנָא, וְלָא הֲוָה מַאן דְּיִמְחֵי בִּידֵיהּ, וְיַטְעִין עֲלָנָא טַעֲנָתָא. עַל דָּא אִתְמְסָרוּ בִּידָהָא כָּל תִּיקּוּנֵי דְּאִימָּנָא.</p>"],[9514015173,"<p>דְּאִלּוּ אִימָּנָא אִשְׁתַּכְּחַת תַּמָּן. לְגוֹ מִשּׁוּרַת הַדִּין אָעֳלַת לוֹן. עַל דָּא הִיא בָּכַאת, עַל דָּא הִיא מְיַילְלָא, עַל בְּנָהָא דְּאִתְגָּלוּ, וְּדאִתְקְטָלוּ, וּדְאִשְׁתֵּצִיאוּ עַל מַגָּן.</p>"],[9514015174,"<p>וּבְהִינַיְיהוּ לָא אִשְׁתַּכְּחַת, וַעֲבֵיד הַהוּא נָחָשׁ רְעוּתֵיהּ בְּהוּ. וְעַל דָּא כְּתִיב, (ישעיהו נ׳:א׳) וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם. שֻׁלְּחָה אִמְּכֶם, דְּלָא תְּהֵא זְמִינַת בְּדִינֵיכוֹן. אֵיכָה יָשְׁבָה בָדָד בְּהַהוּא שַׁעֲתָא, דְּאִיהִי הֲוַת נָסְבָה טַעֲנַת בְּנָהָא, וּבְגִינָהּ אִתְקְרַע דִּינָא.</p>"],[9514015175,"<p>וְכַד אִינוּן עֶשֶׂר מַרְגְּלָן נְפָקוּ מִגַּן עֵדֶן, לְאִתְלַבְּשָׁא בִּלְבוּשִׁין אָחֳרָנִין, כֻּלְּהוּ לְבוּשִׁין אִתְמְסָרוּ בִּידָא דְנָחָשׁ, בַּר חַד, דְּאִיהוּ רְאוּבֵן. דִּכְתִיב וַיָּשָׁב רְאוּבֵן אֶל הַבּוֹר.</p>"],[9514015176,"<p>וְעַל דִּיהַב עֵיטָא לְמִרְמֵי לְבֵירָא, אִיתְפַּס אִיהוּ בְּבֵירָא, וְאִשְׁתְּזֵיב. וְדָא אִיהוּ רַבִּי אֱלִיעֶזֶר הַגָּדוֹל, כַּד תְּפָשׂוּהוּ לְמִינוּת, וִיהֲבוּהוּ בְּבֵירָא, וְאִשְׁתְּזֵיבַת נִשְׁמְתֵיהּ דִּרְאוּבֵן.</p>"],[9514015177,"<p>[ח ס ר]</p>"],[9514015178,"<p>בְּרֵאשִׁית בָּרָא אֱלֹהִים. תָּא חֲזֵי תְּרֵין תֵּיבִין אִלֵּין אִתְפְּלָגוּ לִתְרֵין סִטְרִין כָּל חַד. בְּרֵאשִׁי\"ת בָּרָא שִׁי\"ת אֱלֹהִים מִי אֵלֶּה. מַאי שִׁית. אִלֵּין שִׁית סִטְרִין דְּמַשְׁכְּנָא דְּאִיהוּ כְּגַוְנָא דְּשָׁמַיִם וָאָרֶץ. וּבְגִינַיְהוּ אִתְּמַר אֵלֶּה פִּקּוּדֵי הַמִּשְׁכָּן. וְדָא הוּא מִי אֵלֶּה. הָדָא הוּא דִּכְתִיב (ישעיהו מ׳:כ״ו) שְׂאוּ מָרוֹם עֵינֵיכֶם וּרְאוּ מִי בָּרָא אֵלֶּה. וּתְרֵין מִשְׁכָּנוֹ' אִנּוּן דְּאִתְרְמִיזוּ בְּהַאי קְרָא, אֵלֶּה פִּקּוּדֵי הַמִּשְׁכָּן מִשְׁכַּן הָעֵדוּת. מִשְׁכָּן עִלָּאָה. מִי, וְדָא עָלְמָא עִלָּאָה מִשְׁכָּן תַּתָּאָה.</p>"],[9514015179,"<p>מַה מִּשְׁכָּן עִלָּאָה בְּגִינָהּ אִתְּמַר מִי בָּרָא אֵלֶּה, מַאי אֵלֶּה. אִלֵּין אֵלֶּה מוֹעֲדֵי ה'. וּמַאי אִנּוּן מוֹעֲדֵי ה' אִלֵּין אִנּוּן חַג הַמַּצּוֹת וְחַג הַשָּׁבוּעוֹת וְחַג הַסֻּכּוֹת הֲרֵי תְּלָת. תְּלָת אָחֳרָנִין רֹאשׁ הַשָּׁנָה חֲנֻכָּה פּוּרִים. תְּלָתָא מִנְּהוֹן אִקְּרוּן מוֹעֲדֵי ה'. וְאִנּוּן מִקְרָאֵי קֹדֶשׁ. תְּלָתָא אָחֳרָנִין אִקְּרוּן אֵלֶּה הֵם מוֹעֲדֵי. וְלָקָבְלֵיהוֹן אִתְּמַר (איוב ל״ג:כ״ט) הֵן כָּל אֵלֶּה יִפְעַל אֵל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר.</p>"],[9514015180,"<p>וְהַאי מִשְׁכָּן עִלָּאָה דְּעָלַיְהוּ אִתְקְרֵי מִי. הָדָא הוּא דִּכְתִיב מִי בָּרָא אֵלֶּה. וְהַאי מִי אִיהִי בִּינָה. (ודא שמא) וְדַרְגָּא דִּילֵהּ יוֹם הַכִּפּוּרִים אִיהוּ וַדַּאי, וְהַאי דַּרְגָּא דְּאִתְקְרֵי בִּינָה אִתְקְרֵי הָעוֹלָם הַבָּא. וּבָעוֹלָם הַבָּא, לֵית בֵּהּ אֲכִילָה וּשְׁתִיָּה. כְּגַוְנָא דָּא יוֹם הַכִּפּוּרִים דִילֵהּ לֵית תַּמָּן אֲכִילָה וּשְׁתִיָּה. מַלְכוּת אִתְקְרֵי מַ\"ה, דָּא מִשְׁכַּן הָעֵדוּת. וּבְגִין דְּבֵהּ אִשְׁתְּכַח עֵדוּת, אִתְּמַר בֵּהּ מָה אֲעִידֵךְ.</p>"],[9514015181,"<p>וּכְמָה דְּעָלְמָא עִלָּאָה אַפִּיק שִׁית מוֹעֲדִים, כָּךְ עָלְמָא תַּתָּאָה אַפִּיק שִׁית. וְאִנּוּן אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, וּמִנַּיִן דְּאִנּוּן שִׁית בַּשָּׁמַיִם וְהָאָרֶץ, הָדָא הוּא דִּכְתִיב כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. כִּי שֵׁשֶׁת וַדַּאי דְּאִנּוּן שִׁית. וּבְגִין דָּא לֹא אָמַר כִּי בְּשֵׁשֶׁת יָמִים.</p>"],[9514015182,"<p>וּכְמָה דְּאִתְּמַר עֵדוּת בְּעָלְמָא תַּתָּאָה. הָדָא הוּא דִּכְתִיב מָה אֲעִידֵךְ, הָכֵי אִית עֵדוּת בַּשָּׁמַיִם וּבָאָרֶץ. הָדָא הוּא דִּכְתִיב הֲעִידוֹתִי בָּכֶם הַיּוֹם אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. הָא עָלְמָא עִלָּאָה בְּרֵאשִׁי\"ת וְעָלְמָא תַּתָּאָה בָּרָא שִׁית, וְאִלֵּין אִנּוּן תְּרֵין מִשְׁכְּנוֹת לַאֲבִיר יַעֲקֹב. אִם כֵּן בָּתַר דְּאָמַר אֵלֶּה מוֹעֲדֵי ה' מִקְרָאֵי קֹדֶשׁ דְּאִנּוּן שִׁית. מַאי נִיהוּ בְּמוֹעֲדָם דְּאָמַר בָּתַר כֵּן. אֶלָּא לֵית רְשׁוּ לְמִקְרֵי לוֹן אֶלָּא בְּמוֹעֲדָם דְּאִיהִי מַלְכוּת. וּבַאֲתַר אָחֳרָא אָמַר אֵלֶּה הֵם מוֹעֲדֵי. הֵ\"ם אִיהוּ בְּהִפּוּךְ אַתְוָן מָ\"ה. וְדָא אִיהוּ אֵלֶּה הֵ\"ם מוֹעֲדֵי. וְדָא אִיהוּ שְׁמִינִי חַג עֲצֶרֶת דְּאִיהוּ חַג בִּפְנֵי עַצְמוֹ. תָּא חֲזֵי אִלֵּין מוֹעֲדֵי ה', אָזְלִין עַל תִּקּוּנָא דְּגוּפָא דְּמַלְכָּא קַדִּישָׁא, ואִלֵּין אִנּוּן פֶּסַח דְּרוֹעָא יְמִינָא דְּמַלְכָּא, וְדָא חֶסֶד. וּבְגִינַהּ אִתְּמַר יָמִין מְקָרֶבֶת, רֹאשׁ הַשָּׁנָה דְּרוֹעָא שְׂמָאלָא דְּמַלְכָּא וְדָא גְּבוּרָה. וּבְגִינַהּ אִתְּמַר שְׂמֹאל דּוֹחָה שָׁבוּעוֹת דָּא גּוּפָא דְּמַלְכָּא, וְדָא ת\"ת עַמּוּדָא דְּאֶמְצָעִיתָא חֲנֻכָּה וּפוּרִים אִלֵּין אִנּוּן תְּרֵין שׁוֹקִין דְּמַלְכָּא, דְּעָלַיְהוּ שַׁרְיָא נֵס וּבְגִינַיְהוּ אִתְּמַר אֵלֶּה פִּקּוּדֵי, תְּרֵין פִּקּוּדִין וַדַּאי, דבְּגִינַיְהוּ אִתְּמַר פָּקֹד פָּקַדְתִּי. תְּרֵין נְבִיאִים תְּרֵין מְשִׁיחִין אִנּוּן וַדַּאי. כָּל הָעוֹבֵר עַל הַפְּקוּדִים, דָּא יְסוֹד וְדָא חַג הַסֻּכּוֹת כָּלִיל מִכֻּלְּהוּ, וְאִיהוּ הָעוֹבֵר עַל הַפְּקֻדִּים. דְּאִנּוּן נֶצַח וָהוֹד אוֹת הוּא בַּצָּבָא שֶׁלּוֹ. וְלָמָּה אִתְקְרֵי כֹּל, בְּגִין דְּעָלֵהּ שַׁרְיָא בִּינָה דְּאִיהִי שְׁבִיעָאָה. יָם, דָּא יוֹם הַכִּפּוּרִים, אִיהִי וַדַּאי וְעִמָּהּ חַמְשִׁין תַּרְעִין דְּחִירוּ בְּחֻשְׁבָּן כָּל בִּינָה בֶּן יָהּ כְּתִיב דְּאִיהוּ אָזִיל מַהֲלַךְ חָמֵשׁ מֵאָה שְׁנִין, וּמָטֵי לִיסוֹד דְּאִיהִי חַג הַסֻּכּוֹת. בְּגִין לְאִתְחַבְּרָא בְּכַלָּה דִּילֵהּ דְּאִיהִי חַג שְׁמִינִי עֲצֶרֶת. וּבִשְׁעַת' דְּאִנּוּן בְּחִבּוּרָא חֲדָא, אִתְקְרִיאוּ תַּרְוַיְהוּ כֹּ'ל כַּלָּ'ה פֶּסַח צְרִיכִין יֵשׁ לְמֵימַר בֵּהּ הַלֵּל גָּמוּר וְהַלֵּל שֶׁאֵינוֹ גָּמוּר. הַלֵּל גָּמוּר לְקָבְעוֹ (חסר כאן).</p>"],[9514015183,"<p>וְהַמַּשְׂכִילִים יַזְהִרוּ כְּזֹהַר הָרָקִיעַ (דניאל י״ב:ג׳) וּמַצְדִּיקֵי הָרַבִּים כַּכּוֹכָבִים לְעוֹלָם וָעֶד. וְהַמַּשְׂכִּילִים אִלֵּין רִבִּי שִׁמְעוֹן וְחַבְרוֹי, יַזְהִרוּ כַּד אִתְכְּנָשׁוּ לְמֶעֱבַד הַאי חִבּוּרָא דְּאִיהוּ מִזִּיהֲרָא עִלָּאָה דִּלְעֵלָּא, רְעוּתָא עִלָּאָה אִתְגַּלְּיָא, רְשׁוּתָא אִתְיְהִיב לְרִבִּי שִׁמְעוֹן וְחַבְרוֹי לְגַלָּאָה בֵּהּ רָזִין סְתִימִין עֲמִיקִין, וּלְכָל נִשְׁמָתִין דִּמְתִיבְתָּא דִּלְעֵלָּא, וּמְתִיבְתָּא תַּתָּאָה, וְלִשְׁבַע טוּרִין עִלָּאִין, דְּאִנּוּן תְּלָת אֲבָהָן וְרָעֲיָא מְהֵימָנָא וְאַהֲרֹן וְדָוִד וּשְׁלֹמֹה וְאֵלִיָּהוּ עִמְּהוֹן, וּלְכָל נִשְׁמָתִין דִּמְתִיבְתָאן דְּאָזְלִין עַרְטִילָאִין, וּמַלְאָכִין דִּמְמָנָן עָלַיְהוּ, וְאָזְלִין עַרְטִילָאִין בְּגִינַיְהוּ, דְּאִנּוּן בְּתוּלוֹת אַחֲרֶיהָ רְעוּתֶיהָ דִּשְׁכִינְתָּא, דְּאִיהִי עַרְטִילָאָה מִנְּהוֹן וְאִנּוּן עַרְטִילָאִין מִנַּהּ. וְהָכֵי אִנּוּן חַיָּלִין דְּמַלְכָּא עַרְטִילָאִין מִנַּהּ, דִּכְתִיב (ישעיהו ל״ג:ז׳) הֵן אֶרְאֶלָּם צָעֲקוּ חוּצָה מַלְאֲכֵי שָׁלוֹם מַר יִבְכָּיוּן. וּמְנָא לָן דִּשְׁכִינְתָּא יְחִידָא מִחַיָּלָהָא, הָדָא הוּא דִּכְתִיב אֵיכָה יָשְׁבָה בָּדָד. אֵ'י כֹּ'ה יָשְׁבָה בָּדָד, דְּאִתְּמַר בֵּהּ (תהלים קמה) וַחֲסִידֶךָ יְבָרְכוּ כ'ה. וְעַל קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּהּ אָמַר קְרָא (משלי כ״ז:ח׳) כְּצִפּוֹר נוֹדֶדֶת מִקִּנָּהּ כֵּן אִישׁ נוֹדֵד מִמְּקוֹמוֹ, דְּאִתְּמַר בֵּהּ (שמותטו) ה' אִישׁ מִלְחָמָה. וּבְזִמְנָא דְּאִיהִי עַרְטִילָאָה, תַּלְמִידֵי חֲכָמִים וְצַדִּיקִים וְאַנְשֵׁי מִדּוֹת דִּילֵהּ, כֻּלְּהוּ אָזְלִין מְנַדְּדִין מִדּוּךְ לְדוּךְ, מֵאֲתַר לַאֲתַר. כְּמָה דְּאוֹקְמוּהּ מָארֵי מַתְנִיתִין דּוֹר שֶׁבֶּן דָּוִד בָּא, אַנְשֵׁי חַיִל יְסוֹבְבוּ מֵעִיר לְעִיר וְלֹא יְרֻחֲמוּ, וּבְגִין דָּא אִסְתְּכַם קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּהּ לְמֶעֱבַד הַאי חִבּוּרָא, עַל יַד הַהוּא דְּאִתְגַּלְּיָא וְכָנִיס בֵּהּ עִלָּאִין וְתַתָּאִין לְאַשְׁכָּחָא בֵּהּ נִיחָא לִשְׁכִינְתָּא בְּגָלוּתָא, וְחִירוּ לָהּ וְלִבְנָהָא. הָדָא הוּא דִּכְתִיב (תהלים פד) גַּם צִפּוֹר מָצְאָה בַּיִת וּדְרוֹר קֵן לָהּ. הַהִיא דְּאִתְּמַר בָּהּ (ויקרא כ״ה:י׳) וּקְרָאתֶם דְּרוֹר בָּאָרֶץ לְכָל יוֹשְׁבֶיהָ. אֲשֶׁר שָׁתָה אֶפְרוֹחֶיהָ, אִלֵּין דְּאִתְּמַר בְּהוֹן (דברים כ״ב:ו׳) וְהָאֵם רֹבֶצֶת עַל הָאֶפְרוֹחִים. וְאִנּוּן מָארֵי דְּגַדְפִין דְּאִתְּמַר בְּהוּ (יחזקאל א׳:ו׳) וְד' פָּנִים לְאֶחָת וְאַרְבַּע כְּנָפַיִם לְאַחַת לָהֶם. דְּאִלֵּין אִנּוּן דִּמְמָנָן עַל מָארֵי מַתְנִיתִין דְּרוּחֵיהוֹן פַּרְחִין מִנְּהוֹן. אִלֵּין רִבֵּי שִׁמְעוֹן וְחַבְרוֹי וּמָארֵי מְתִיבְתָּא דְּעַבְדֵי הַאי חִבּוּרָא. אוֹ עַל הַבֵּיצִים, אִלֵּין אוֹפַנִּים דִּמְמָנָן עַל מָארֵי מִקְרָא. דִּבְגִין הַאי חִבּוּרָא וְהָאֵם רֹבֶצֶת עַל הָאֶפְרוֹחִים אוֹ עַל הַבֵּיצִים לֹא תִּקַּח הָאֵם עַל הַבָּנִים, אִלֵּין אִנּוּן דְּאִתְּמַר בְּהוֹן בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם. וְהַאי חִבּוּרָא הֲוָא כְּגַוְנָא דְּתֵבַת נֹחַ דְּאִתְכְּנַשׁ בָּהּ כָּל מִין וָמִין, הָכֵי מִתְכַּנְּשִׁין בְּהַאי חִבּוּרָא כָּל נִשְׁמָתִין דְּצַדִּיקַיָּא וְאַנְשֵׁי מִדּוֹת, דְּאִתְּמַר בְּהוֹן (תהילים קי״ח:כ׳) זֶה הַשַּׁעַר לַה' צַדִּיקִים יָבֹאוּ בּוֹ, וָאָחֳרָנִין דְּלָא צַדִּיקִים, אִתְדַּחְיָן מִתַּמָּן. וְכַד אִתְגַּלְּיָא הַאי חִבּוּרָא בְּעָלְמָא, סַגִּיאִין מִתְכַּנְּשִׁין לְגַבֵּהּ דְּאִתְּמַר בְּהוֹן (דברים כ״ט:י״ד) כִּי אֶת אֲשֶׁר יֶשְׁנוֹ פֹּה וְגוֹ', וְאֶת אֲשֶׁר אֵינֶנּוּ פֹּה בְּהַאי חִבּוּרָא עִמָּנוּ הַיּוֹם. וְעָלֵהוּ אִתְּמַר (דניאל י״ב:ג׳) וּמַצְדִּיקֵי הָרַבִּים כַּכּוֹכָבִים לְעוֹלָם וָעֶד, כְּאִנּוּן כּוֹכְבַיָּא דִּיהוֹן קַיְּמִין לְעָלָם וּלְעָלְמֵי עָלְמַיָּא, וְאִתְּמַר בְּהוֹן וְהָיָה זַרְעֲךָ כְּכוֹכְבֵי הַשָּׁמַיִם, דְּאִיהוּ עַמּוּדָא דְּאֶמְצָעִיתָא, דְּאִיהוּ אַתָּה תִּשְׁמַע הַשָּׁמַיִם, וְלֹא כְּכוֹכְבַיָּא מִשְּׁמַיָּא דְּאִתְּמַר בְּהוֹן (ישעיהו נ״א:ו׳) כִּי שָׁמַיִם כְּעָשָׁן נִמְלָחוּ (תהילים ק״ב:כ״ז) הֵמָּה יֹאבֵדוּ וְאַתָּה תַעֲמֹד.</p>"],[9514015184,"<p>וְעוֹד וְהַמַּשְׂכִּילִים, אִלֵּין דְּאִית בְּהוֹן שֶׁכָּל לְמִנְדַּע גְּזִירוּ דְּנִשְׁמָתִין דִּילְהוֹן, מֵאִלֵּין סַפִּירִין דְּאִנּוּן מִלִּין גְּזֵירָן מֵעֶשֶׂר סְפִירָן, דְּעָלַיְהוּ אִתְּמַר (תהילים י״ט:ב׳) הַשָּׁמַיִם מְסַפְּרִים כְּבוֹד אֵל. דְּכֻלְּהוּ מַלְּיָן סְגֻלּוֹת, וְאִנּוּן אַנְשֵׁי מִדּוֹת, נִשְׁמָתִין דִּילְהוֹן רְשִׁימִין תַּמָּן, וּמִתַּמָּן אֲצִילוֹתְהוֹן, מִסִּטְרָא דְּמַלְכוּת אִנּוּן בְּנֵי מְלָכִים, דְּאִתְּמַר בְּהוּ כָּל יִשְׂרָאֵל בְּנֵי מְלָכִים, וּמִסִּטְרָא דָּא נָפְקִין מִיִּשְׂרָאֵל מְלָכִים, וּמִסִּטְרָא דְּצַדִּיק אִתְקְרִיאוּ צַדִּיקִים, הָדָא הוּא דִּכְתִיב (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים, וּמִסִּטְרָא דְּנֶצַח וָהוֹד אִתְקְרִיאוּ נְבִיאִים, וּמִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא, אִתְּמַר בְּהוּ וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק כֻּלֹּה זֶרַע אֱמֶת, וְעָלַיְהוּ אִתְּמַר (מלאכי ג) תּוֹרַת אֱמֶת הָיְתָה בְּפִיהוּ, וּמִסִּטְרָא דִּגְבוּרָה אִתְקְרִיאוּ גִּבּוֹרִים עוֹמְדִים בַּפֶּרֶץ דּוֹחִים אֶת הַגְּזֵרוֹת. וּמִסִּטְרָא דְּחֶסֶד אִתְקְרִיאוּ חֲסִידִים. וּמִסִּטְרָא דְּחָכְמָה וְבִינָה אִתְּמַר בְּהוּ כֻּלָּנוּ חֲכָמִים כֻּלָּנוּ נְבוֹנִים. וּמִסִּטְרָא דְּכֶתֶר דְּאִיהוּ רֵישָׁא דְּכֹלָּא אִנּוּן רָאשֵׁי אַלְפֵי יִשְׂרָאֵל, דְּעָלַיְהוּ אִתְּמַר אַנְשֵׁי מִדּוֹת, אִלֵּין אִנּוּן הַמַּשְׂכִּילִים דְּאִית בְּהוֹן שֵׂכֶל לְמִנְדַּע לְמָארֵיהוֹן, דְּרָזִין דְּמָארֵיהוֹן לָא אִתְכַּסְּיָן מִנַּיְהוּ. דְּכֻלְּהוּ הֲווֹ בְּאַסְכָּמוּתָא בְּחִבּוּרָא דָּא. ולאִלֵּין דְּאִנּוּן בְּאִלֵּין מִדּוֹת צָרִיךְ לְגַלָּאָה רָזִין תְּמִירִין. אֲבָל מָאן דִּמְגַלֶּה רָזִין לְרַשִּׁיעַיָּא, כְּאִלּוּ מְגַלֶּה עֲרָיִין בְּאוֹרַיְתָא. דִּבְנֵי שִׁפְחָה בִּישָׁא לילית אִמָּא דְּרַשִּׁיעַיָּא עִרְבּוּבְיָא בִּישָׁא. מָאן דִּמְגַלֶּה רָזִין דְּאוֹרַיְתָא גָּרִים לַצַּדִּיק דְּאִיהוּ יְסוֹד, דְּאִתְּמַר בֵּהּ (תהילים כ״ה:י״ד) סוֹד ה' לִירֵאָיו, דְּאִסְתְּלַק נְבִיעוּ מִנֵּהּ וּמִן שְׁכִינְתָּא, הָדָא הוּא דִּכְתִיב (איוב י״ד:י״א) אָזְלוּ מַיִם מִנִּי יָם וְנָהָר יֶחֱרַב וְיָבֵשׁ. בְּהַהוּא זִמְנָא אִנּוּן צַדִּיקַיָּא לְתַתָּא עֲנִיִּים מִכֹּלָּא, עֲנִיִּים מֵרָזִין דְּאוֹרַיְתָא עֲנִיִּים בְּגוּפָא. וְכָל מָאן דִּמְגַלֶּה רָזִין לְצַדִּיקַיָּא, גָּרִים לַצַּדִּיק לְאַנְהָרָא בְּרָזִין דְּאוֹרַיְתָא, וְלִשְׁכִינְתָּא דְּאוֹר רָ\"ז אִתְקְרֵי. וּבְהַהוּא זִמְנָא וְהַמַּשְׂכִּילִים יַזְהִרוּ כְּזֹהַר הָרָקִיעַ. מַאי כְּזֹהַר, דַּרְגָּא דְּמֹשֶׁה רַבֵּנוּ עָלָיו הַשָּׁלוֹם, עַמּוּדָא דְּאֶמְצָעִיתָא, דְּעַל שְׁמֵהּ אִתְקְרֵי הַאי חִבּוּרָא סֵפֶר הַזֹּהַר. וּשְׁכִינְתָּא בֵּהּ נַהֲרָא וְזָהֳרָא בְּסִיהֲרָא מִן שִׁמְשָׁא. דְּשִׁמְשָׁא נְהִירָא בְּשִׁית טוּרִין רַבְרְבִין, וְסִיהֲרָא בִּשְׁבִיעָאָה כְּלִילָא מִשֶּׁבַע.</p>"],[9514015185,"<p>אב\"ג ית\"ץ קר\"ע שט\"ן נג\"ד יכ\"ש בט\"ר צת\"ג חק\"ב טנ\"ע יג\"ל פז\"ק שם אב\"גית\"ץ עָלַיְהוּ אִתְּמַר (ישעיהו ו׳:ב׳) שֵׁשׁ כְּנָפַיִם שֵׁשׁ כְּנָפַיִם לְאֶחָד וְהַאי שְׁמָא אִיהוּ סְגוֹלְתָּא דִּילֵהּ לְכַסָּאָה וּלְנִשְׁמָתָא, כַּד סְלִיקַת לְעֵלָּא בְּכָל לֵילְיָא וְלֵילְיָא, לְאַסְהֲדָא עַל עוֹבָדִין טָבִין דְּבַר נָשׁ, מִמַּלְאֲכֵי חַבָּלָה וּמִכָּל מַזִּיקִין וְרוּחִין וְלֵילִין וְשֵׁדִין, וּבְהוֹן פָּרְחַת לְעֵלָּא. בִּשְׁתַּיִם אַתְוָן מִכָּל שֵׁם תְּכַסֶּה אַנְפָּהָא מִנְּהוֹן, בִּשְׁתַּיִם אַתְוָן תְּכַסֶּה רַגְלָאָה, וּבִשְׁתַּיִם אַתְוָן פָּרְחַת לְעֵלָּא, וְאוֹף הָכֵי לְרוּחָא וְאוֹף הָכֵי לְנַפְשָׁא. ע\"כ.</p>"],[9514015186,"<p>שקוצי\"ת דְּנִשְׁמָתָא בְּהוֹן פָּרְחַת לְעֵלָּא בְּכָל לֵילְיָא וְלֵילְיָא, וְהַאי אִיהוּ נִשְׁמַת כָּל חַי, דַּאֲצִילוּתָא מֵאִמָּא עִלָּאָה, וְשֶׁבַע שְׁמָהָן אִלֵּין דְּפָרְחַת בְּהוֹן, אִנּוּן שֶׁבַע, דִּכְלִילָן בְּבַת שֶׁבַע דְּאִיהִי שְׁכִינְתָּא תַּתָּאָה, כְּלִילָא מִשֶּׁבַע סְפִירָן, דְּעָלַיְהוּ אָמַר דָּוִד (דברי הימים א כ״ט:י״א) לְךָ ה' הַגְּדֻלָּה וְהַגְּבוּרָה וְהַתִּפְאֶרֶת וְהַנֶּצַח וְהַהוֹד כִּי כֹל בַּשָּׁמַיִם וּבָאָרֶץ.</p>"],[9514015187,"<p>וְאִמָּא עִלָּאָה אִיהִי הַנֶּשֶׁר הַגָּדוֹל בַּעַל הַכְּנָפַיִם, אָדָם הַגָּדוֹל, חָכְמָא, וְעֶשֶׂר חָכְמוֹת אִתְקְרִיאוּ עֶשֶׂר סְפִירָן מִסִּטְרֵהּ, וְכֶתֶר עֶלְיוֹן אִתְקְרֵי מִסִּטְרֵהּ חָכְמָה קְדוּמָה, וְאִיהִי יוּ\"ד הֵ\"א וָא\"ו הֵ\"א, דְּאִתְפַּשְּׁטוּתֵהּ בְּעֶשֶׂר סְפִירָן, אֲבָל אִמָּה עִלָּאָה נשְׁרָא עִלָּאָה דְּאִתְפַּשְּׁטוּתֵהּ בְּשֶׁבַע, וְאִיהִי תְּמִינָאָה וּבָהּ שֶׁבַח מֹשֶׁה</p>"],[9514015188,"<p>אָז יָשִׁיר מֹשֶׁה. וּמִנַּהּ תִּשְׁכַּח רָזָא דְּקַן צִפּוֹר, שַׁלַּח תִּשְׁלָח אֶת הָאֵם דַּאֲצִילוּת, אַרְיֵה חֶסֶד, שׁוֹר גְּבוּרָה, הַאי אִיהִי מֶרְכַּבְתָא עִלָּאָה. מֶרְכַּבְתָּא תִּנְיָנָא תִּפְאֶרֶת אָדָם תִּנְיָנָא, דְּאִתְּמַר בֵּהּ (יחזקאל א׳:י׳) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם, דְּמוּת אַרְיֵה שׁוֹר נֶשֶׁר, נֶצַח הוֹד יְסוֹד מַלְכוּת אִיהִי תַּבְנִית כֻּלְּהוּ, הַאי אִיהוּ רָזָא דְּתִקּוּנָא חֲדָא.</p>"],[9514015189,"<p>אֲבָל מִסִּטְרָא דְּנִשְׁמָתָא אִתְקְרָאוּ שְׂרָפִים. וּמִסִּטְרָא דְּרוּחָא חַיּוֹת, דְּאִתְּמַר בְּהוֹן (שם) וּדְמוּת הַחַיּוֹת מַרְאֵיהֶן כְּגַחֲלֵי אֵשׁ בּוֹעֲרוֹת כְּמַרְאֵה הַלַּפִּידִים הִיא מִתְהַלֶּכֶת בֵּין הַחַיּוֹת. (דא) וְאִתְּמַר בְּהוֹן (שם) וּמִתּוֹכָהּ דְּמוּת ד' חַיּוֹת, וְזֶה מַרְאֵיהֶן דְּמוּת אָדָם לְהֵנָּה.</p>"],[9514015190,"<p>וְרוּחָא אִיהוּ מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא, וְאִית לָהּ אַרְבַּע אַנְפִּין, כְּגַוְנָא דְּנִשְׁמָתָא דְּאִית לָהּ ד' אַנְפִּין. אוֹפַנִּים מִסִּטְרָא דְּנֶפֶשׁ וְאִיהִי מִסִּטְרָא דִּשְׁכִינְתָּא תַּתָּאָה, וְאִית לוֹן ד' אַנְפִּין, דְּמֶרְכָּבָה דְּאִנּוּן נֶצַח וָהוֹד. וְהִנֵּה אוֹפַן א' בָּאָרֶץ דָּא צַדִּיק. אוֹפַנִּים אִנּוּן מִתַּתָּא לְעֵלָּא חֵיוָן בְּאֶמְצָעִיתָא שְׂרָפִים לְעֵלָּא.</p>"],[9514015191,"<p>וְכֻלְּהוּ לְעֵלָּא אָדוֹן יָחִיד שַׁלִּיט עַל כֹּלָּא, מֻפְלָא וּמְכֻסֶּה בְּכֶתֶר, וּבְחָכְמָה אִיהוּ שׁוּלְטָנוּ דְּקָאִים עַל כֻּלְּהוּ בְּעֶשֶׂר אַתְוָן דִּשְׁמָא מְפָרַשׁ. אֲבָל מִתַּמָּן לְתַתָּא כֻּלְּהוּ סְפִירָן מְרֻבָּעִין בְּאַרְבַּע אַתְוָן. כְּגַוְנָא דָּא בִּינָה יה'ו. הַהוּא בֵּן די'ה אִיהוּ ו' דְּאִתְפַּשְּׁטוּתֵהּ בְּשִׁית סְפִירָאָן. ה' רְבִיעָאָה בִּשְׁכִינְתָּא תַּתָּאָה בֵּהּ אִשְׁתְּלִים יהו'ה.</p>"],[9514015192,"<p>מִסִּטְרָא דְּאַרְבַּע אַתְוָן אִלֵּין אִית לְכָל חַיָּה ד' אַנְפִּין, וּמִסִּטְרָא דְּיוֹ\"ד הֵ\"א וָא\"ו הֵ\"א דְּמוּת אָדָם לְאַרְבַּעְתָּן. וְלָקֳבֵל תִּשְׁעָה סַפִּירִין אִלֵּין, חָזָא יְחֶזְקֵאל ט' מַרְאוֹת, דְּאִתְּמַר בְּהוֹן (שם) נִפְתְּחוּ הַשָּׁמַיִם וְאֶרְאֶה מַרְאוֹת אֱלֹהִים. ואִלֵּין אִנּוּן. חִיזוּ קַדְמָאָה (שם) וּמִמַּעַל לָרָקִיעַ אֲשֶר עַל רֹאשָׁם כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא. הַאי אֶבֶן אִיהוּ שְׁכִינְתָּא אֶבֶן סַפִּיר, וִיחֶזְקֵאל חָזָא מִתַּתָּא לְעֵלָּא. אִיהוּ חָזָא לָהּ כְּמָאן דְּחָזָא מִגּוֹ עֲשָׁשִׁית.</p>"],[9514015193,"<p>חִיזוּ תִּנְיָנָא וְעַל דְּמוּת הַכִּסֵא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְּמַעְלָה. הָכָא חָזָא עַמּוּדָא דְּאֶמְצָעִיתָא סָמִיךְ לִשְׁכִינְתָּא, וְחָזָא לֵהּ מִגּוֹ מְטַטְרוֹן דְּאִיהוּ שַׁדָּי. חִיזוּ תְּלִיתָאָה (שם) וָאֵרֶא כְּעֵין חַשְׁמַל כְּמַרְאֵה אֵשׁ בַּיִת לָהּ סָבִיב, וְדָא צַדִּיק חַי עָלְמִין, דְּאָחִיד בֵּין קוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ יהו'ה, וּבֵין שְׁכִינְתָּא דְּאִיהִי אדנ'י, וְצַדִּיק אִיהוּ חַשְׁמַל כְּלָלָא דִּתְרֵין שְׁמָהָן אִלֵּין, דְּאִנּוּן יאהדונה'י. וְחָזָא לֵהּ מִגּוֹ שַׂר הַפָּנִים.</p>"],[9514015194,"<p>וְד' אַנְפִּין אִנּוּן יהו'ה, וְד' גַּדְפִּין אִנּוּן אדנ'י. כָּל חַיָּה אִיהִי מְרֻבַּעַת, וּלְכָל סִטְרָא אִית לָהּ ד' אַנְפִּין, לְכָל פָּן ד' אַנְפִּין, וּלְכָל גַּדְפָּא ד' גַּדְפִּין, וְהוֹן י\"ו אַנְפִּין וָי\"ו גַּדְפִּין לְכָל חַיָּה, אִנּוּן ל\"ב מְרֻבָּעִים סַלְקִין לְד' חֵיוָן ס\"ד אַנְפִּין וס\"ד גַּדְפִּין.</p>"],[9514015195,"<p>וְאִית דְּאָמַר הָכֵי וְכֹלָּא קְשׁוֹט, ד' פָּנִים לְאַחַת וְד' כְּנָפַיִם לְאַחַת לָהֶם וְאִנּוּן לְכָל חַיָּה ד' אַנְפִּין וְד' גַּדְפִּין, הָא אִנּוּן ל'ב כְּחֻשְׁבָּן ל'ב אֱלֹהִים דְּעוֹבָדָא דִּבְרֵאשִׁית. וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם, דְּאִיהוּ עֶשֶׂר אַתְוָן דִּשְׁמָא מְפָרֵשׁ לָקֳבֵל עֶשֶׂר אֲמִירָן, הָא מ\"ב. וס\"ד אַנְפִּין וְגַדְפִּין עִם תְּמַנְיָא אַתְוָן דְּחַשְׁמַל ע\"ב. וְעָלַיְהוּ אִתְּמַר (שם) וְגַבֵּיהֶן אִלֵּין ע\"ב גַּדְפִּין. וְגֹבַהּ לָהֶם וְאִנּוּן ע\"ב אַנְפִּין. דְּאִנּוּן בְּאַתְוָן לְגַבֵּי נִקּוּדֵי, דְּעָלַיְהוּ אִתְּמַר כִּי גָּבוֹהַּ מֵעַל גָּבוֹהַּ שׁוֹמֵר. וּגְבוֹהִים עֲלֵיהֶם אִלֵּין טַעֲמֵי. וּבְגִינַיְהוּ אִתְּמַר (יחזקאל א׳:י״ח) וְגַבּוֹתָם מְלֵאוֹת עֵינַיִם סָבִיב לְאַרְבַּעְתָּם.</p>"],[9514015196,"<p>וְאִנּוּן נִקּוּדִין כְּגַוְנָא דְּפִרְקִין דְּאֶצְבְּעָן דְּאִנּוּן עִגּוּלִין, וְאִנּוּן אַתְוָן כְּגַוְנָא דְּאֶצְבְּעָן. וְאִנּוּן טַעֲמֵי כְּגַוְנָא דְּעַיְנִין דְּמִתְנַהֲגִין כָּל אֵיבָרִין דְּגוּפָא אָבַתְרַיְהוּ, וְאִנּוּן רְמִיזִין בְּהַאי שְׁמָא יהֶוָהֶ, וְעוֹד וְגַבּוֹתָם מְלֵאוֹת עֵינַיִם סָבִיב לְאַרְבַּעְתָּם כְּגַוְנָא דָּא, וְאִתְּמַר בְּגַדְפִּין שְׁתַּיִם חוֹבְרוֹת אִישׁ כְּגוֹן (שמות כ״ח:כ״ז) שְׁתֵּי כְּתֵפוֹת חוֹבְרוֹת, ושתי' מְכַסּוֹת אֶת גויותיהנה, כְּגוֹן עַל שְׁתֵּי קְצוֹתָיו וְחוֹבַר. שְׁתַּיִם חוֹבְרוֹת אִנּוּן יְמִינָא וּשְׂמָאלָא.</p>"],[9514015197,"<p>אִישׁ, ה' אִישׁ מִלְחָמָה. מָאן אִישׁ. לְזִמְנִין מֵעֵלָּא לְתַתָּא אִתְקְרִיאַת חָכְמָה אָדָם וְאִתְקְרֵי אִישׁ, וּתְלָת סְפִירָן תְּחוֹתֵהּ אִתְקְרִיאוּ תְּלָת חֵיוָן. וּלְזִמְנִין אִמָּא עִלָּאָה אִתְקְרִיאַת הָאָדָם, בְּתוֹסֶפֶת ה', חֶסֶד גְּבוּרָה תִּפְאֶרֶת תְּלָת חֵיוָן, וּלְזִמְנִין תִּפְאֶרֶת אִתְקְרֵי אָדָם נֶצַח הוֹד יְסוֹד תְּלָת חֵיוָן, לְזִמְנִין חָכְמָה אִישׁ. א' כֶּתֶר עִלָּאָה, י' חָכְמָה, ש' תְּשׁוּבָה, דְּאִיהִי אִמָּא עִלָּאָה, שְׁתַּיִם חוֹבְרוֹת אִישׁ גְּדֻלָּה גְּבוּרָה. וּשְׁתַּיִם מְכַסּוֹת אִנּוּן נֶצַח וָהוֹד. אֶת גויותיהנה, אֶת, דָּא צַדִּיק דְּאִיהוּ תַּרְגּוּם אוֹת.</p>"],[9514015198,"<p>אֶת גויותיהנה דָּא עַמּוּדָא דְּאֶמְצָעִיתָא דְּאִיהוּ גּוּפָא, וּשְׁכִינְתֵּהּ טַבּוּר דִּילֵהּ וְעַמּוּדָא דְּאֶמְצָעִיתָא, עָלַיְהוּ אִתְּמַר (שמות כ״ה:כ׳) וְהָיוּ הַכְּרֻבִים פּוֹרְשֵׂי כְּנָפַיִם לְמַעְלָה. מָאן גַּדְפִּין דִּילְהוֹן לְעֵלָּא יְמִינָא וּשְׂמָאלָא, סוֹבְבִים בְּכַנְפֵיהֶם, תְּרֵי סַמְכֵי קְשׁוֹט. עַל הַכַּפֹּרֶת דָּא צַדִּיק דְּצָרִיךְ לְכַסָּאָה לֵהּ. וּפְנֵיהֶם אִישׁ אֶל אָחִיו אִנּוּן חָכְמָה וּבִינָה דְּאִנּוּן אַנְפִּין דִּכְרוּבִים.</p>"],[9514015199,"<p>וּלְמָאן הֲווֹ פָּרְשֵׂי גַּדְפַיְהוּ וּמִסְתַּכְּלִין אִישׁ אֶל אָחִיו לְהַהוּא דְּעָאל בְּכִתְרָא עִלָּאָה, דְּאִיהוּ מְכֻסֶּה דְּעָלֵהּ אִתְּמַר בַּמֻּפְלָא מִמְּךָ אַל תִּדְרֹשׁ וּבַמְכֻסֶּה מִמְּךָ אַל תַּחֲקֹר. וּכְרוּבִים לְגַבֵּהּ גַּדְפַיְהוּ פְּתִיחָן לְעֵלָּא, לָקָבְלֵהּ לֵהּ עָלַיְהוּ (במדבר ז׳:פ״ט) וַיִּשְׁמַע אֶת הַקּוֹל, מִגּוֹ עַמּוּדָא דְּאֶמְצָעִיתָא. מְדַבֵּר אֵלָיו, מִגּוֹ שְׁכִינְתָּא תַּתָּאָה. וַיִּשְׁמַע אֶת הַקּוֹל לְעֵלָּא מִגּוֹ אַבָּא. וַיְדַבֵּר אֵלָיו, מִגּוֹ אִמָּא. וּמָאן שָׁמַע לֵהּ עַמּוּדָא דְּאֶמְצָעִיתָא. וּמִלּוּלָא אִשְׁתְּמַע לְגַבֵּי שְׁכִינְתָּא.</p>"],[9514015200,"<p>חִיזוּ רְבִיעָאָה וַחֲמִישָׁאָה מִמַּרְאֵה מָתְנָיו וּלְמַעְלָה נֶצַח, וּמִמַּרְאֵה מָתְנָיו וּלְמַטָה הוֹד. דְּאִנּוּן תְּרֵין שׁוֹקִין. חִיזוּ שְׁתִיתָאָה, רָאִיתִי כְּמַרְאֵה אִישׁ, וְדָא גְּבוּרָה דְּמִתַּמָּן אִנּוּן שְׁנַיִם כְּרוּבִים זָהָב. דְּכֶסֶף אִיהוּ לִימִינָא, זָהָב לִשְׂמָאלָא. וְשֶׁבַע מִינֵי דַּהֲבָא אִתְכְּלִילָן בֵּהּ.</p>"],[9514015201,"<p>חִיזוּ שְׁבִיעָאָה כְּמַרְאֵה הַקֶּשֶׁת אֲשֶׁר יִהְיֶה בֶּעָנָן. מָאן עֲנָנָא, דָּא חֶסֶד דְּסָלִיק ע\"ב וּבֵהּ אָתָא קוּדְשָׁא בְּרִיךְ הוּא בְּעָב הֶעָנָן, בַּעֲבוּר יִשְׁמַע עַמָּא לְמַלְּלָא עִם מֹשֶׁה. וּבֵהּ אִי ע\"ב דְּאִיהוּ חֶסֶד אִתְחַזְיָא קֶשֶׁת דְּאִיהוּ צַדִּיק בְּגווָֹנוֹי נְהִירִין, דְּאִנּוּן ג' גְּוָנִין דִּתְלָת אֲבָהָן, וּבֵהּ אִתְכְּלִילָן. וּבְגִין דָּא אִתְּמַר בַּצַּדִּיק וַיְכֻלּוּ דְּסָלִיק ע\"ב, דְּבֵהּ אִתְכְּלִילָן תְּלָת אֲבָהָן, דְּאִתְּמַר בְּהוּ בַּכֹּ'ל מִכֹּ'ל כֹּ'ל. וּבְאִלֵּין תְּלָת גְּוָנִין וּרְאִיתִיהָ לִשְׁכִינְתָּא לִזְכֹּר בְּרִית עוֹלָם.</p>"],[9514015202,"<p>דְּצַדִּיק אִיהוּ אָלֶף שְׁתִיתָאָה יוֹם הַשִּׁשִּׁי. וְנָטִיל בִּימִינָא דְּאִיהוּ חֶסֶד כָּלִיל ע\"ב וּבְגִינֵהּ אִתְּמַר (בראשית א׳:י״ג) וְאַתָּה לֵךְ לְקֵץ וְתָנוּחַ בְּצַדִּיק וְתַעֲמֹד לְגֹרָלְךָ לְקֵץ הַיָּמִין, דְּאִיהוּ יְמִינָא דְּבֵהּ (ישעיהו נ״ב:ח׳) כִּי עַיִן בְּעַיִן יִרְאוּ בְּשׁוּב ה' צִיּוֹן. וְנָטִיל בְּע\"ב דְּעַמּוּדָא דְּאֶמְצָעִיתָא, דְּבֵהּ וַיְהִי מַבְדִּיל בֵּין מַיִם לְמַיִם, וּבְגִינָא אִתְּמַר לְלִבִּי גִּלִּיתִי ולמהר\"ש לֹא גִלִּיתִי. לְלִבִּי גִלִּיתִי וּלְאֵבָרַי לֹא גִלִּיתִי. (חסר כאן) (נראה דקץ) אִית בְּכָל דָּרָא וְדָרָא כְּפוּם זִכְוָן דִּילְהוֹן. בְּכָל מָארֵהּ דְּדָרָא כְּפוּם דְּרֹב דָּרָא נוֹטִים אֲבַתְרֵהּ. וְאִם חוֹבִין מִתְרַבִּין עָלַהּ, אָמַר רִבִּי חִיָּא פֻּרְקָנָא עַד דָּרָא אָחֳרָא. וּבְגִין דָּא כָּל הַקִּצִּין כָּלוּ, וְכֹלָּא תַּלְיָא בִּתְיוּבְתָּא וּבְזִכְוָן דְּמִדּוֹת דְּכָל דָּרָא וְדָרָא. אֲבָל קֵץ וּזְמַן דְּשַׁוִּי קוּדְשָׁא בְּרִיךְ הוּא, לָא תַּלְיָא בְּזִכְוָן וּבְמִדּוֹת דְּכָל דָּרָא וְדָרָא, אֶלָּא בֵּהּ תַּלְיָא, הָדָא הוּא דִּכְתִיב (ישעיהו מ״ח:י״א) לְמַעֲנִי לְמַעֲנִי אֶעֱשֶׂה, וָאָעַשׂ לְמַעַן שְׁמִי. וּבְגִין דָּא כָּל קֵץ דְּכָל דַּרְגָּא כְּפוּם זִכְוָן דִּבְנֵי נָשָׁא אִיהוּ. וְקֵץ דְּקוּדְשָׁא בְּרִיךְ הוּא לא תַּלְיָא בְּזִכְוָן דִּלְהוֹן.</p>"],[9514015203,"<p>וְאִית ע\"ב בָּתַר אֶלֶף חֲמִישָׁאָה כְּפוּם הַהִיא מִדָּה. וְאִית ע\"ב בָּתַר אֶלֶף וּמָאתָן, כְּפוּם הַהִיא מִדָּה וְאִית מָאתָן וְחַמְשִׁין וְשִׁית דנח דִּילֵהּ, כִּי עַיִן בְּעַיִן יִרְאוּ קֵץ אָחֳרָא אִית רמ\"ה כְּפוּם מִדָּה, וְהַאי דַּרְגָּא דְּרַעֲוָא דְּאִיהוּ קוּדְשָׁא בְּרִיךְ הוּא. תְּרֵין קָצִין אַאֲרִיךְ. וְדָא וְכָל חֶשְׁבּוֹנוֹת וְגִימַטְרִיאוֹת דְּקִצִּים, אִנּוּן פַּרְפְּרָאוֹת לַחָכְמָה מִכִּתְרָא לְעֵלָּא לֵית קֵץ וְחֻשְׁבָּן, כְּמוֹ שֶׁכָּתַב בַּעַל סֵפֶר יְצִירָה וְלִפְנֵי אֶחָד מָה אַתָּה סוֹפֵר, רֵישָׁא דְּכָל קָצִין חָכְמָה, סוֹפָא דְּכָל קִצִּין אִיהוּ, דְּאִיהִי שְׁכִינְתָּא עֲשִׂירָאָה.</p>"],[9514015204,"<p>עַמּוּדָא דְּאֶמְצָעִיתָא כָּלִיל רֵישָׁא וְסוֹפָא דְּכָל קָצִין. וְכָל סוֹף אִיהוּ בְּצַדִּיק, וְכֹלָּא אִתְכָּלִיל בְּצַדִּיק דְּכָלִיל תְּלָת אֲבָהָן דִּבְהוֹן אִתְקְרֵי שְׁבִיעִי תְּלָת זִמְנִין. הָדָא הוּא דִּכְתִיב (בראשית ב׳:ב׳) וַיְכַל אֱלֹהִים בַּיּוֹם הַשְּׁבִיעִי, וַיִּשְׁבֹּת בַּיּוֹם הַשְּׁבִיעִי, וַיְבָרֶךְ אֱלֹהִים אֶת יוֹם הַשְּׁבִיעִי. וְהַאי אִיהוּ בְּעָב הֶעָנָן, וּמִנֵּהּ אִשְׁתְּכַח שֵׁם בֵּן ע\"ב שְׁמָהָן וַיִּסַּ'ע וַיָּבֹ'א וַיֵּ'ט, דְּאִנּוּן כְּלָל וּפְרָט וּכְלָל, דְּאִתְכְּלִילָן בְּמַיָּא אֶשָּׁא וְרוּחָא. וְאִנּוּן יַמָּא וַאֲוִירָא וּרְקִיעָא.</p>"],[9514015205,"<p>וְאִנּוּן יַמָּא וְתָקְפָּא דִּימִינָא, מַלְאַךְ הַחֶסֶד וְדָא מִיכָאֵל, דְּאִיהוּ עַל שֵׁם (שמות טו) מִי כָּמוֹךָ בָּאֵלִים ה', דִּי שְׁמֵהּ מכבי דְּסָלִיק ע\"ב, בְּחֻשְׁבָּן אֲתוֹי וּנְהוֹרָא דִּילֵהּ מ\"ב. וְדָא חֵילָא דִּילֵהּ (ישעיה מג) כִּי תֵּלֵךְ בְּמוֹ אֵשׁ לֹא תִכָּוֶה. דְּדָא מְכַבֵּי אֶשָּׁא, וּמִיכָאֵל אִיהוּ דְּמוּת אַרְיֵה דְּאִיהוּ אַרְיֵה מִמַּיִם. (שמות טו) וַיֵּט מֹשֶׁה אֶת יָדוֹ עַל הַיָּם, וַיָּשֶׂם אֶת הַיָּם לְחָרָבָה בְּתֻקְפָּא דְּגַבְרִיאֵל שְׁלִיחָא דִּגְבוּרָה דִּמְמָנָא עַל חֻרְבָּה. וּבְגִין דָּא אִתְּמַר בֵּהּ וַיָּשֶׂם אֶת הַיָּם לְחָרָבָה, מִסִּטְרָא דְּאוּרִיאֵל שְׁלִיחָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא, אַפְרִישׁ בֵּין מַיָּא וְאֶשָּׁא. הָדָא הוּא דִּכְתִיב וַיָּבֹא בֵּין מַחֲנֵה מִצְרַיִם דְּאִיהִי אֶשָּׁא נוּכְרָאָה, וּבֵין מַחֲנֵה יִשְׂרָאֵל דְּאִיהִי מַיָּא.</p>"],[9514015206,"<p>וַיְהִי הֶעָנָן מִימִינָא וְהַחֹשֶׁךְ דְּרַשִּׁיעַיָּא מִשְּׂמָאלָא, דְּאָזַל לְקַטְרְגָא לְסִטְרָא דִּשְׂמָאלָא דִּגְבוּרָה וְלֹא קָרַב זֶה אֶל זֶה כָּל הַלַּיְלָה, וּכְמָא דְּאִתְפְּרִישׁ בֵּין שְׂמָאלָא דְּסִטְרָא אָחֳרָא לִימִינָא דְּקוּדְשָׁא דְּלָא אִתְקְרִיב לְגַבָּהּ הָכֵי מְיַחֵד בֵן יְמִינָא וּשְׂמָאלָא דְּקוּדְשָׁא, דְּבֵהּ שְׁמָהָן וּסְפִירָן וְאַתְוָן וְהַוְיָן מְשֻׁלָּשִׁין, וּבְגִין דָּא וה\"ו וכו' מְשֻׁלָּשׁ בִּתְלָת אַתְוָן. בְּגִין דְּיִשְׂרָאֵל שְׁלִישִׁי לְכֹהֵן וְלֵוִי, אֲבָל שְׁמָהָן מְרֻבָּעִין וְאַתְוָן דְּתֵבָה אַרְבַּע אִנּוּן מִשְּׁכִינְתָּא. וְתֵשַׁע סְפִירוֹת אִנּוּן מְשֻׁלָּשִׁין בְּעַמּוּדָא דְּאֶמְצָעִיתָא'. כְּגַוְנָא דָּא חָ'כְ'מָה חֶסֶ'ד נֶצַ'ח כֶּתֶ'ר תִּפְאֶרֶת יְסוֹ'ד בִּינָ'ה גְּבוּרָ'ה הוֹ'ד, וּמַלְכוּת עֲשִׂירִי לוֹן, וּרְבִיעִי לוֹן מִסִּטְרָא דְּאִמָּא עִלָּאָה, אִיהִי תְּמִינָאָה, וּתְלָת סְפִירָן אִלֵּין, לְבוּשַׁיְהוּ חֹשֶׁךְ עָנָן וַעֲרָפֶל. חֹשֶׁךְ לִשְׂמָאלָא, עָנָן לִימִינָא, וַעֲרָפֶל בְּאֶמְצָעִיתָא, תְּחוֹת שָׁמַיִם דְּאִיהוּ עַמּוּדָא דְּאֶמְצָעִיתָא, הָדָא הוּא דִּכְתִיב (תהילים י״ח:י׳) וַיֵּט שָׁמַיִם וַיֵּרַד וַעֲרָפֶל תַּחַת רַגְלָיו. בֶּעָנָן דְּנָפִיק קָלָא, דְּאִתְּמַר בֵּהּ (שם צג) קוֹל ה' עַל הַמַּיִם.</p>"],[9514015207,"<p>וְכַמָּה קָלִים מִתְפּוֹצְצִין מִנֵּהּ, דְּאִתְּמַר בְּהוֹן מִקּוֹלוֹת מַיִם רַבִּים, מִסִּטְרָא דִּגְבוּרָה דְּתַמָּן חֹשֶׁךְ, דְּבֵהּ (בראשית כ) יִצְחָק וַתִּכְהֶיןָ עֵינָיו מִרְאוֹת, דְּנָפִיק קָלָא דְּאִתְּמַר בֵּהּ קוֹל ה' חוֹצֵב לַהֲבוֹת אֵשׁ, וּמִסִּטְרָא דַּעֲרָפֶל קָלָא דְּאִתְּמַר בֵּהּ קוֹל ה' בֶּהָדָר, הַיָּדוּעַ לְיִשְׂרָאֵל נָפִיק סָבָא, הָדָא הוּא דִּכְתִיב (ויקרא מט) וְהָדַרְתָּ פְּנֵי זָקֵן.</p>"],[9514015208,"<p>תְּלָת קָלִין אָחֳרָנִין מִנֶּצַח הוֹד יְסוֹד, דְּאִנּוּן לָקֳבֵל תְּלָת אֲבָהָן קָלָא שְׁבִיעָאָה מֵאִמָּא עִלָּאָה נַפְקָא. וְלָקֳבֵל תְּלָת אֲבָהָן אִנּוּן, זַיִת לִימִינָא. נֵר לִשְׂמָאלָא. עַמּוּדָא דְּאֶמְצָעִיתָא פְּתִילָה דְּאִתְאֲחִיד בְּתַרְוַיְהוּ. דְּאִיהִי עֵץ פְּרִי עוֹשֶׂה פְּרִי לְמִינוֹ. אֲשֶׁר זַרְעוֹ בוֹ עַל הָאָרֶץ, דָּא מָאנָא דְּשַׂרְגָּא וְנֵר דְּשַׁבָּת מִסִּטְרָא דִּגְבוּרָה אִתּוּקְדַת וְאִתְנְהָרַת. לְמָאן דְּקָרִיב אֶשָּׁא נוּכְרָא לְגַבָּהּ דִּבְגִינֵהּ מָנֵי לֹא תְבָעֲרוּ אֵשׁ בְּכָל מֹשְׁבוֹתֵיכֶם בְּיוֹם הַשַּׁבָּת, וּשְׁכִינְתָּא אוֹף הָכֵי אִתְקְרִיאַת נֵר מִסִּטְרָא דִּשְׂמָאלָא, וְאִתְקְרִיאַת אוֹר מִסִּטְרָא דִּימִינָא, דְּתַמָּן (שמות כ״ז:כ׳) זַיִת זַךְ לְהַעֲלוֹת נֵר תָּמִיד, וְאִיהוּ שֶׁמֶן לַמָּאוֹר דְּאִיהוּ כִּי נֵר מִצְוָה וְתוֹרָה אוֹר. וְאִיהִי פְּתִילָה מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא דְּאָחִיד בְּתַרְוַיְהוּ.</p>"],[9514015209,"<p>וּכְגַוְנָא דָּא, זֶרַע דְּבַר נָשׁ לָקֳבֵל מִשְׁחָא וּבְרִית מִילָה לָקֳבֵל פְּתִילָה. נֵר ה' נִשְׁמַת אָדָם, לָקֳבֵל נֵר דְּשַׂרְגָּא. חִיזוּ תְּמִינָאָה אִמָּא עִלָּאָה אִתְקְרִיאַת כֵּן מַרְאֵה הַנֹּגַהּ סָבִיב, מט'ה הָאֱלֹהִים. הַנֹּגַהּ מִסִּטְרָא דִּימִינָא מַטֶה כְּלַפֵּי חֶסֶד, לְרַחֵם עַל מָארֵי תְּיוּבְתָּא דְּבֵהּ אִתְּמַר, כִּי יְמִינְךָ פְּשׁוּטָה לְקַבֵּל שָׁבִים, מִסִּטְרָא דִּשְׂמָאלָא מַטֵה הָאֱלֹהִים, לְמָחֲאָה בֵּהּ לִרְשִׁיעֲיָא. הָדָא הוּא דִּכְתִיב וּמַטְךָ אֲשֶׁר הִכִּיתָ בוֹ אֶת הַיְאֹר קַח בְּיָדְךָ וְהָלַכְתָּ, וְשֶׁבַע שַׁבָּתוֹת, לְכָל חַד שֶׁבַע יוֹמִין סַלְקִין מ\"ט. וְהַאי אִיהוּ וְסָפַרְתָּ לְךָ שֶׁבַע שַׁבָּתוֹת שָׁנִים, אִנּוּן מ\"ט שָׁנִים. ומ\"ט יוֹמִין שֶׁבַע שַׁבָּתוֹת לָקֳבֵל שֶׁבַע שְׁמָהָן אִלֵּין דְּאִנּוּן.</p>"],[9514015210,"<p>אב\"ג ית\"ץ קר\"ע שט\"ן נג\"ד יכ\"ש בט\"ר צת\"ג חק\"ב טנ\"ע יג\"ל פז\"ק שקוצי\"ת אִנּוּן שֶׁבַע שְׁמָהָן וּלְכָל חַד שִׁית אַתְוָן, לָקֳבֵל שִׁית יוֹמֵי שָׁבוּעַ לְכָל שַׁבָּת וְשַׁבָּת. וְאִלֵּין אִנּוּן דְּאִתְּמַר (ישעיהו ו׳:ב׳) שְׂרָפִים עוֹמְדִים מִמַּעַל לוֹ שֵׁשׁ כְּנָפַיִם שֵׁשׁ כְּנָפַיִם לְאֶחָד. וְכֻלְּהוּ מ\"ט שֶׁבַע שַׁבָּתוֹת, וְאַרְבָּעִין וּתְרֵין יוֹמִין דְּחֹל. וְשֶׁבַע שַׁבָּתוֹת שֶׁבַע סְפִירָן לְכָל חַד שִׁית דַּרְגִין וְסַלְקִין מ\"ט פָּנִים טָהוֹר דְּאוֹרַיְתָא אִמָּא עִלָּאָה חֲמִשִּׁים יוֹם דִּסְפִירַת הָעֹמֶר. ה' עִלָּאָה מִן מט\"ה וּתְלָת דַּרְגִין אִנּוּן עִלָּאִין, שְׂרָפִים וְחַיּוֹת וְאוֹפַנֵּי קֹדֶשׁ.</p>"],[9514015211,"<p>שְׂרָפִים בְּהוֹן פָּרְחַת אִמָּא עִלָּאָה דְּאִיהִי נִשְׁמַת כָּל חַי, וּמִנַּהּ נִשְׁמַת חַיִּים דְּבַר נָשׁ, דְּאִתְּמַר בֵּהּ וַיִּפַּח בְּאַפּוֹ נִשְׁמַת חַיִּים. וּבַשְּׂרָפִים דְּאִתְמַשְּׁכָן מאִלֵּין אִיהִי פָּרְחַת בְּכָל לֵילְיָא לְגַבֵּי אִמָּא עִלָּאָה וּבְכָל שַׁעֲתָא דַּחֲזָרַת בִּתְשׁוּבָה, דִּבְגִינָא אִתְּמַר וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ הָאָדָ\"ם חֻשְׁבָּנֵהּ חַמְשִׁין. רוּחָא דְּקוּדְשָׁא דְּאִתְּמַר בָּהּ וְרוּחַ אֱלֹהִים מְרַחֶפֶת עַל פְּנֵי הַמַּיִם. דְּאִנּוּן בְּנֵי תּוֹרָה, מַיִם דְּאוֹרַיְתָא, אִינְטִילַת מֵעַמּוּדָא דְּאֶמְצָעִיתָא. הַאי סְלִיקַת בְּכָל לֵילְיָא בְּד' חֵיוָן, דִּלְכָל חַד ד' גַּדְפִין וּבְהוֹן פָּרְחִין לְעֵלָּא לְגַבֵּי עַמּוּדָא דְּאֶמְצָעִיתָא דְּאִיהוּ כָּלִיל יאהדונהי יהוה מִימִינָא אֲדֹנָי מִשְּׂמָאלָא. נַפְשָׁא אַתְיָא מִסִּטְרָא דְּאוֹפַנִּים, דְּאִתְּמַר עָלַיְהוּ (יחזקאל א׳:ט״ז) מַרְאֵה הָאוֹפַנִּים וּמַעֲשֵׂיהֶם כְּעֵין תַּרְשִׁישׁ. אִתְּמַר הָכָא תַּרְשִׁישׁ וְאִתְּמַר בְּשִׁיר הַשִּׁירִים (שיר השירים ה׳:י״ד) יָדָיו גְּלִילִי זָהָב מְמֻלָּאִים בְּתַרְשִׁישׁ.</p>"],[9514015212,"<p>וְאַף עַל גַּב דְּהָא אוֹקִימְנָא לְעֵיל שְׂרָפִים וְחַיּוֹת וְאוֹפַנִּים. בְּכָל אֲתַר דְּמִתְחַדֵּשׁ בֵּהּ רָזִין צָרִיךְ לְאַחֲזָרָא לוֹן שְׂרָפִים לָקֳבֵל גַּדְפִּין דִּכְרוּבִים. וְחַיּוֹת לָקֳבֵל גּוּפָא דִּכְרוּבִים. אוֹפַנִּין לָקֳבֵל רַגְלַיִן דִּכְרוּבִים דְּאִנּוּן עִגּוּלִין. מִשֶּׁגָּלוּ יִשְׂרָאֵל הֲווֹ מִתְמַעֲטִין גַּדְפִּין דְּחֵיוָן, וּכְרוּב חַד דְּאִיהוּ עַמּוּדָא דְּאֶמְצָעִיתָא אִסְתְּלַק לְגַבֵּי הַהוּא מְכֻסֶּה דְּאִתְּמַר בֵּהּ (תהילים י״ח:י״א) וַיַּרְכֵּב עַל כְּרוּב וַיָּעַף.</p>"],[9514015213,"<p>אִשְׁתְּאַר כְּרוּב תִּנְיָנָא דְּאִיהִי שְׁכִינְתָּא בְּגָלוּתָא, זַכָּאָה אִיהוּ מָאן דִּמְחַבַּר לוֹן בִּשְׂפְוָן שְׁלִים בְּחַ\"י עָלְמִין, דְּאִיהוּ לְשׁוֹן לִמּוּדִים, כָּלִיל חַ\"י בִּרְכָּאן דִּצְלוֹתָא, דְּבֵהּ מִתְכַּנְּשִׁין שְׂרָפִים וְחַיּוֹת וְאוֹפַנִּים כֻּלְּהוּ גַּדְפַיְהוּ פְּתִיחָן לָקֳבֵל, וְקָלָא דִּילֵהּ אִשְׁתְּמַע מִגּוֹ עַמּוּדָא דְּאֶמְצָעִיתָא וּשְׁמָעִין לְגַבַּיְהוּ, הָדָא הוּא דִּכְתִיב (יחזקאל א׳:כ״ד) וָאֶשְׁמַע אֶת קוֹל כַּנְפֵיהֶם.</p>"],[9514015214,"<p>בְּאָן אֲתַר אִשְׁתְּמַע בִּקְרִיאַת שְׁמַע, וּבְאָן אֲתַר אִתְפְּתָחוּ, כַּד יִשְׂרָאֵל אָמְרִין אֲדֹנָי שְׂפָתַי תִּפְתָּח, אֲדֹנָי, שְׁכִינְתָּא כַּד אִיהִי אִתְפַּתְּחַת לְקַבְּלָא לְבַעְלָהּ, מִתְפַּתְּחִין שְׂרָפִים וְחַיּוֹת וְאוֹפַנִּים. גַּדְפַיְהוּ וְגַבֵּהּ לְקַבְּלָא לוֹן לְמָארֵיהוֹן. הָדָא הוּא דִּכְתִיב (שם) וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרוּדוֹת מִלְּמַעְלָה. הָא אִנּוּן כְּרוּבִים דְּכָר וְנוּקְבָא כַּחֲדָא. בִּצְלוֹתָא דַּעֲמִידָה אִתְּמַר, בַּשְּׂרָפִים וְחַיּוֹת וְאוֹפַנִּים, (שם) בְּעָמְדָם תְּרַפֶּינָה כַּנְפֵיהֶם, בְּעָמְדָם וַדַּאי יִשְׂרָאֵל בִּצְלוֹתָא דַּעֲמִידָה, בְּהַהוּא זִמְנָא אִנּוּן כְּרוּבִים וּפְנֵיהֶם אִישׁ אֶל אָחִיו בְּהַהוּא זִמְנָא. צְלוֹתִין מִתְקַבְּלִין בְּרַעֲוָא, דְּאִתְּמַר עָלַיְהוּ תְּפִלּוֹת כְּנֶגֶד תְּמִידִין, וְעוֹד הָא אוֹקְמוּהּ מִכָּל מָקוֹם דְּאֵין עֲבוֹדָה אֶלָּא תְּפִלָּה דִּשְׁקוּלָה אִיהִי צְלוֹתָא כַּעֲבוֹדַת הַכֹּהֲנִים וּכְקָרְבָּנַיָּא דִּילְהוֹן.</p>"],[9514015215,"<p>דִּבְזִמְנָא דִּכְרוּבִים דְּאִנּוּן עַמּוּדָא דְּאֶמְצָעִיתָא, וּשְׁכִינְתָּא לָאו אִנּוּן אַנְפִּין בְּאַנְפִּין, צְלוֹתָא לָא מִתְקַבֵּל, וְנָפַק סמא\"ל דְּאִיהוּ כַּלְבָּא לְמֵיכַל קָרְבְּנִין דִּילְהוֹן, דְּאִנּוּן צְלוֹתִין, וְהַאי אִיהוּ (ויקרא ט׳:כ״ד) וַתֵּצֵא אֵשׁ מִלִּפְנֵי ה' וַתֹּאכַל אוֹתָם. וְדָא אֲכִילָה דְּקָרְבְּנִין דְּאִנּוּן צְלוֹתִין דְּיִשְׂרָאֵל, וְאִתְּמַר בְּהוֹן וַיָּמוּתוּ כְּגַוְנָא דִּבְנֵי אַהֲרֹן, וְלֵית מִיתָא לְיִשְׂרָאֵל אֶלָּא עֲנִיּוּתָא, ובְּאִלֵּין אַנְפִּין דִּכְרוּבִים אִתְּמַר (שמות ל״ג:י״א) וְדִבֵּר ה' אֶל מֹשֶׁה פָּנִים אֶל פָּנִים.</p>"],[9514015216,"<p>קָמוּ כֻּלְּהוּ מִמָּארֵי מַתְנִיתִין וּמַלְאָכִין וְאָמְרוּ מַאי נִיהוּ דְּגַלֵּי רָזִין אִלֵּין. אֶלָּא וַדַּאי דָּא אִיהוּ דְּאִתְקְרֵי סֵפֶר הַזֹּהַר, בְּדַרְגָּא דִּילֵהּ דְּאִיהוּ בִּדְיוֹקְנָא דְּמָארֵהּ, דְּאִתְּמַר בֵּהּ (דניאל ד׳:ט׳) רַבָּא אִילָנָא וְתַקִּיף, דִּבְרַגְלוֹהִי תטלל חֵיוַת בָּרָא, דְּאִנּוּן חֵיוַת הַקֹּדֶשׁ. וּבְעַנְפּוֹהִי יִדֹּדוּן צִפֳּרֵי שְׁמַיָּא דְּאִנּוּן נִשְׁמָתִין עִלָּאִין וּמִנֵּהּ יִתְזַן כָּל בִּשְׂרָא דָּא יִשְׂרָאֵל לְתַתָּא וְלֹא עוֹד אֶלָּא בִּבְבַת עֵינוֹי נַהֲרָא שְׁכִינְתָּא, דִּבְגִינֵהּ אִתְּמַר (שמות ג׳:ב׳) וַיֵּרָא מַלְאַךְ ה' אֵלָיו בְּלַבַּת אֵשׁ מִתּוֹךְ הַסְּנֶה. וְדָא בַּ\"ת לֵ\"ב בַּת כְּלִילָא מֵעֶשֶׂר אֲמִירָן וְל'ב נְתִיבוֹת דִּילָהּ. דְּאִנּוּן ל'ב אֱלֹהִים דְּעוֹבָדָא דִּבְרֵאשִׁית. דִּבְגִין הַאי ל'ב אִתְּמַר הַלֵּב רוֹאֶה הַלֵּב שׁוֹמֵעַ. בְּעַיִן דִּילֵהּ נָהִיר עַמּוּדָא דְּאֶמְצָעִיתָא.</p>"],[9514015217,"<p>בִּתְלָת גְּוָנִין דְּעֵינֵהּ יְמִינָא נַהֲרִין תְּלָת אֲבָהָן. בִּתְרֵי גַּדְפֵּי עֵינָא דִּילֵהּ, פַּתְחִין וְסַגְרִין תְּרֵי סַמְכֵי קְשׁוֹט. בְּרֹב דְּעֵינָא דְּאָחִיד בִּתְרֵי גַּדְפֵּי עֵינָא דִּילֵהּ דָּא צַדִּיק. בַּת דַּקִּיקָא זְעֵירָא אִית מִלְּגָאו, תְּחוֹת בַּת עֵינָא עִלָּאָה וְדָא שְׁכִינְתָּא תַּתָּאָה. דְּבַת עֵינָא עִלָּאָה תַּמָּן חָכְמָה לֵב אִמָּא עִלָּאָה.</p>"],[9514015218,"<p>אוֹר דְּנָהִיר בָּבַת עֵינָא דְּאִיהִי י' וְעִמֵּהּ אִתְקְרֵי אֲוִיר הַקַּדְמוֹן, דָּא כֶּתֶר עִלָּאָה. וְעוֹד בְּשִׁבְעָה גִּלְדֵי עֵינָא דִּילֵהּ, נַהֲרִין נִשְׁמָתִין דְּרִבִּי שִׁמְעוֹן וְשִׁית חַבְרוֹי. וְעָלַיְהוּ אִתְּמַר (זכריה ד׳:ב׳) שִׁבְעָה וְשִׁבְעָה מוּצָקוֹת, וְאִית דְּפָרִישׁ לוֹן הָכֵי בְּי\"ד אַתְוָן דִּשְׁמָא מְפָרַשׁ. בְּז' גִּלְדֵי עֵינָא וּתְלָת גַּוְנֵי עֵינָא, נַהֲרִין עֶשֶׂר אַתְוָן דְּאִנּוּן יוּ\"ד הֵ\"א וָא\"ו הֵ\"א, וְהַאי אִיהוּ (יחזקאל א׳:י׳) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם בִּתְרֵי כְּרוּבֵי עֵינָא וּבִתְרֵי עַפְעַפֵּי עֵינָא, נַהֲרִין פְּנֵי אָדָם דְּאִנּוּן ד' וְאִנּוּן יהו\"ה. וְעָלַיְהוּ אִתְּמַר וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם, דְּמוּת תְּלָת חֵיוָן אִנּוּן דְּמוּת אַנְפֵּי אָדָם, כָּל אֵבָר וְאֵבָר דִּילֵהּ, אִשְׁתְּכַח רְשׁוּת הַיָּחִיד, דְּרָחְבּוֹ ד' וְגָבְהוֹ עֲשָׂרָה, דְּאִנּוּן י\"ד אַתְוָן דִּשְׁמָא מְפָרַשׁ, בְּאֵבָרִין דִּילֵהּ מְקַנְּנָן כִּלְ נִשְׁמָתִין דְּשִׁשִּׁים רִבּוֹא דְּיִשְׂרָאֵל. דְּשִׁשִּׁים רִבּוֹא דְּמַלְאָכִים כֻּלְּהוּ דְּמִתְכַּנְּשִׁין בְהַאי חִבּוּרָא, מְקַנְּנִין בֵּהּ.</p>"],[9514015219,"<p>אָמְרוּ נִשְׁמָתִין דִּמְתִיבְתָּא עִלָּאָה, וַדַּאי הַאי אִיהוּ דְּדַרְגֵּהּ עַמּוּדָא דְּאֶמְצָעִיתָא דְּעָתִיד לְאִתְגַּלְּיָא בְּדָרָא דְּמַלְכָּא מְשִׁיחָא אִתְגַּלְּיָא בֵּהּ. וְרָזָא דְּמִלָּא קְרָא אוֹכַח, מַ'ה שֶּׁהָיָ'ה הוּא שֶׁיִּהְיֶ'ה. וּבָהּ מִמְּכוֹ\"ן שִׁבְתּ\"וֹ הִשְׁגִּי\"חַ אֶל כָּל יוֹשְׁבֵי הָאָרֶץ.</p>"],[9514015220,"<p>קוּם רָעֲיָא מְהֵימָנָא לְאִתְּעָרָא לְהַהוּא דְּאִתְּמַר בֵּהּ אֲנִי יְשֵׁנָה וְלִבִּי עֵר. וּכְמָה אִנּוּן דְּמִיכִין וְשֵׁינָתָא בְּעֵינֵיהוֹן, דְּלָא פַּתְחִין לוֹן לְאִתְעַסְּקָא בְּרָזִין דְּאוֹרַיְתָא, דְּכָל רָז אור אִתְקְרֵי, לְאַנְהָרָא בֵּהּ לְבַת עֵינָא וּלְאִתְּעָרָא לָהּ בֵּהּ לְגַבֵּי בַּעְלָהּ, דְּאִיהִי דְּמִיכָא בְּגָלוּתָא בֵּין אִנּוּן מָארֵי תּוֹרָה. דְּלֵית חַד מִנַּיְהוּ דְּיִתְּעַר לָהּ בְּבַעְלָהּ דְּאִיהוּ ר\"ז אוֹר דְּנָהִיר בָּהּ בָּבַת עֵינָא. דְּרָז אוֹר אִיהוּ בְּחֻשְׁבָּן.</p>"],[9514015221,"<p>דְּהָא אַנְתְּ הוּא דְּאִתְּמַר בֵּהּ מֹשֶׁה קִבֵּל תּוֹרָה מִסִּינַי. דְּהָא הֲווֹ כֻּלְּהוּ נְבִיאַיָּא וְחַכְמַיָּא וּמָארֵי קַבָּלָה לְגַבָּךְ, כְּסִיהֲרָא וְכוֹכְבַיָּא וּמַזָּלֵי דְּלֵית לוֹן נְהוֹרָא אֶלָּא מְשַׁמְּשָׁא. וּבְגִין דְּאִתְּמַר בָּךְ פְּנֵי מֹשֶׁה כִּפְנֵי חַמָּה. קוּם אַנְהִיר לוֹן דְּעַד דֶּאֱמֶת אַנְהִיר לוֹן, כֻּלְּהוּ הֲווֹ בַּחֲשׁוֹכָא וְלֵית לוֹן נְהוֹרָא. דְּבַאֲתַר דְּאַנְתְּ תִּשְׁתַּכַּח, עַמּוּדָא דְּאֶמְצָעִיתָא אִשְׁתַּכַּח תַּמָּן, דְּאִיהוּ כָּלִיל עִלָּאִין וְתַתָּאִין. אַנְתְּ הוּא חִיזוּ דְּכָל מַרְאוֹת דִּנְבוּאָה, דְּאִתְּמַר בְּהוֹן (יחזקאל א׳:כ״ח) וָאֶרְאֶה מַרְאוֹת אֱלֹהִים. חִיזוּ תְּשִׁיעָאָה (שם) מַרְאֵה דְּמוּת כְּבוֹד ה'. וְדָא חָכְמָה דְּאִית בָּהּ כ'ח מ'ה, וְכַמָּה חֶשְׁבּוֹנוֹת וְגִימַטְרִיאוֹת אִית תַּמָּן, דְּאִתְּמַר בְּהוֹן תְּקוּפוֹת וְגִימַטְרִיאוֹת פַּרְפְּרָאוֹת לַחָכְמָה. וְאִנּוּן מָ\"ה יוּ\"ד הֵ\"א וָא\"ו הֵ\"א אִיהוּ (נ\"א אנון) עֶשֶׂר סְפִירוֹת. דְּאָמַר בָּעֹל ס\"י עֶשֶׂר וְלֹא ט' וְלֹא י\"א, כְּגַוְנָא דְּעֶשֶׂר אַתְוָן דִּשְׁמָא מְפָרַשׁ, דְּלָא לְאוֹסָפָא עָלַיְהוּ יוֹתֵר מֵעֶשֶׂר, וְלֹא לְמִגְרַע מִנַּיְהוּ וְחֻשְׁבָּן דְּעֶשֶׂר אַתְוָן אִלֵּין אִנּוּן מָ\"ה. כֹּחַ דִּילֵהּ אִנּוּן כ\"ח אַתְוָן דְּאִנּוּן תּוּלְדִין דְּעֶשֶׂר אִלֵּין. וְאִנּוּן יוּ\"ד הֵ\"א וָא\"ו דָּלֶ\"ת, הֵ\"א אֶלֶ\"ף, וָא\"ו אֶלֶ\"ף וָא\"ו, הֵ\"א אָלֶ\"ף. עֶשֶׂר אַתְוָן לָקֳבֵל עֶשֶׂר אֶצְבְּעָן. כ\"ח אַתְוָן לָקֳבֵל כ\"ח פִּרְקִין דְּעֶשֶׂר אֶצְבְּעָן. וּבְגִינַיְהוּ אִתְּמַר (במדבר י״ד:י״ז) וְעַתָּה יִגְדַּל נָא כֹּ\"ח אֲדֹנָי. וּבְגִין הַאי כֹּחַ אִתְּמַר דְּמָאן דְּלָא יְדַע בְּגִימַטְרִיאוֹת וְחֶשְׁבּוֹנוֹת דִּילֵהּ, עָתִיד לְנַחְתָּא לִשְׁאוֹל, כְּמָה דְּאוֹקְמוּהּ בַּמִּדְרָשׁ (קהלת ט׳:י׳) כִּי אֵין מַעֲשֶׂה וְחֶשְׁבּוֹן וְדַעַת וְחָכְמָה בַּשְּׁאוֹל אֲשֶׁר אַתָּה הוֹלֵךְ שָׁמָּה, מָ\"ה אִיהוּ כָּב'וֹד אֶחָד. כְּגַוְנָא דָּא וָא'ו חֻשְׁבָּנֵהּ אֶחָ\"ד כָּבוֹ\"ד. אִיהוּ יוּ\"ד הֵ\"א הֵ\"א. וְכָבוֹד אִיהוּ חֻשְׁבַּן לֵ\"ב, וְאִיהוּ (נ\"א והאי איהו) לֵ\"ב אֶחָ\"ד. וּבְגִינֵהּ אִתְּמַר (יחזקאל א׳:כ״ח) הוּא מַרְאֵה דְּמוּת כְּבוֹד ה'. וְעוֹד מַה בְּאַתְוָן מֵ'ם הֵ'א דְּסָלִיק בְּגִימַטְרִיָּא אֶהְיֶ'ה אֲדֹנָ'י וְחֻשְׁבָּנֵהּ אֱלֹהִי\"ם. וְדָא כִּנּוּי דִּשְׁמָא מְפָרַשׁ דְּהָכֵי סָלִיק אֱלֹהִי\"ם בְּגִימַטְרִיָּא כּנּוּ'י. וְהַאי אִיהוּ הַשֵּׁם בְּכִנּוּי. הַכִּ'סֵּא הָכֵי סָלִיק אִיהוּ בְּחֻשְׁבָּנֵהּ כ\"ו כ\"פ וא\"ו, אִיהוּ.</p>"],[9514015222,"<p>יְהוָֹ\"ה אֱלֹהִי\"ם בְּגִימַטְרִיָּא א' תּוֹסֶפֶת אַחֲזֵי דִּשְׁמֵהּ וְכִנּוּיֵהּ אֶחָד. וְלָאו אִיהוּ כְּגַוְנָא דְּבַר נָשׁ דְּאִיהוּ אֶחָד וְכִנּוּיֵהּ אֶחָד, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא הוּא וּשְׁמֵהּ וְכִנּוּיֵהּ כֹּלָּא חַד. אִלֵּין תֵּשַׁע מַרְאוֹת חָזָא יְחֶזְקֵאל מִגּוֹ תֵּשַׁע צוּרוֹת אָחֳרָנִין. חִיזוּ עֲשִׂירָאָה דְּאִיהוּ כֶּתֶר מֻפְלָא וּמְכֻסֶּה, לָא גַּלֵּי בֵּהּ שׁוּם מַרְאֶה בְּעָלְמָא. הָדָא הוּא דִּכְתִיב (שם) וָאֶרְאֶה וָאֶפֹּל עַל פָּנַי וְלֹא אָמַר מַאי חָזָא. בְּגִין דְּאִתְּמַר עָלֵהּ בַּמֻּפְלָא מִמְּךָ אַל תִּדְרֹשׁ וּבַמְכֻסֶּה מִמְּךָ אַל תַּחֲקֹר, אֵין לְךָ עֵסֶק בַּנִּסְתָּרִים.</p>"],[9514015223,"<p>מָאן מִסְּתָרִים דִּילֵהּ. אִנּוּן שִׁית מֵאָה וְעֶשְׂרִים סִתְרֵי תּוֹרָה גְּנִיזִין (נ\"א רזין) דְּתַלְיָן מִנֵּהּ, כְּחֻשְׁבַּן כֶּתֶ\"ר וְכָל חַד אוֹלִיף רָזָא לְעֵלָּא מִנֵּהּ, וְאִנּוּן עָלְמִין גְּנִיזִין לְהַהוּא מֻפְלָא דְּאִיהוּ עִלַּת כָּל עִלָּאִין. קוּם רָעֲיָא מְהֵימָנָא גַּלֵּי שִׁבְחוֹי, דְּהָא רְשׁוּ אִתְיְהִיב לְךָ מִן עִלַּת כָּל הָעִלּוֹת. וְעָנָן וַעֲרָפֶל אַבָּא וְאִמָּא. וְז' עַנְנֵי כָּבוֹד שֶׁבַע סְפִירָן. שַׁקְיוּ דְּאִלֵּין עֲמָמִין אִנּוּן יוּ\"ד הֵ\"י וָי\"ו הֵ\"י דְּסָלִיק לְחֻשְׁבַּן ע\"ב. וְעָלֵהּ אִתְּמַר (ישעיהו י״ט:א׳) הִנֵּה ה' רוֹכֵב עַל עָב קַל וּבָא מִצְרַיִם. וְעֶשֶׂר סְפִירָן אִתְכְּלִילָן בֵּהּ מִסִּטְרָא דְּחֶסֶד, וּמִנֵּהּ שֵׁם בֵּן ע\"ב כְּתִיב בִּדְרוֹעָא דְּקוּדְשָׁא בְּרִיךְ הוּא כְּמָא דְּאוֹקְמוּהּ בְּסֵפֶר רָזִיאֵל, בְּשִׁעוּר קוֹמָה דְּאִיהוּ הֲוָה סִפְרָא דְּאָדָם קַדְמָאָה.</p>"],[9514015224,"<p>וְכַד סְלִיקַת שְׁכִינְתָּא בְּאִלֵּין עֲנָנִין, סְלִיקַת בַּחֲשַׁאי בִּצְלוֹתָא בַּחֲשַׁאי. וְכַמָּה חֵיוָן דְּאָזְלִין בָּאֲוִירָא דְּאִנּוּן שְׂרָפִים חַשְׁמַאלִּים, עֶשֶׂר כִּתּוֹת אִנּוּן כֻּלְּהוּ פַּתְחִין גַּדְפַיְהוּ לְגַבָּהּ. הָדָא הוּא דִּכְתִיב (יחזקאל א׳:י״א) וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרוּדוֹת מִלְּמַעְלָה. לְקַבְּלָא שְׁכִינְתָּא עָלַיְהוּ וְכַד סְלִיקַת, סְלִיקַת בְּכֻלְּהוֹן בְּאִלֵּין הֲבָלִים דְּפוּמָא, דְּאִנּוּן שֶׁבַע הֲבָלִים דְּאָמַר קֹהֶלֶת וּתְלָת גְּנִיזִין.</p>"],[9514015225,"<p>וְכַד סְלִיקַת עָלַיְהוּ מִיָּד נָחַת קוּדְשָׁא בְּרִיךְ הוּא לְקַבְּלָא לָהּ בְּכַמָּה חֵילִין וּמַשִּׁרְיָן. מַשִּׁרְיָן דְּשַׁכְנַת סַלְקִין עִם שְׁכִינְתָּא, וּמַשִּׁרְיָן דְּמַלְכָּא נַחְתִּין עָלַיְהוּ, וְאִנּוּן מֶרְכֶּבֶת תַּתָּאִין מֵעִלָּאִין, וּמְקַבְּלִין אִלֵּין מֵאִלֵּין בְּחֶדְוָא בִּנְשִׁיקוּ. וְרָזָא דְּמִלָּה (בראשית כ״ח:י״ב-י״ג) וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ. וְהִנֵּה מַלְאָכִים דִּשְׁכִינְתָּא דְּאִיהִי אִתְעֲבִידַת אֱלֹהִים, עוֹלִים וּמַלְאָכִים יוֹרְדִים בּוֹ לְגַבָּהּ. זַכָּאָה צְלוֹתָא דְּבַר נָשׁ דְּאִיהִי אִית עֲבִידַת סֻלָּם לִתְרֵין מַשִּׁרְיָן דְּמַלְכָּא וּמַטְרוֹנִיתָא. וּבְגִין דָּא כַּד סַלְקִין מַשִּׁרְיָן דְּמַטְרוֹנִיתָא, סַלְקִין בַּחֲשַׁאי, וְכַד נַחְתִּין מַשִּׁרְיָן דְּמַלְכָּא עָלַיְהוּ, אִנּוּן מְמַלְּלָן עָלַיְהוּ, בְּהַהוּא זִמְנָא אִיהוּ יִחוּדָא דְּקוֹל וְדִבּוּר כַּחֲדָא.</p>"],[9514015226,"<p>יאההונהי דִּבְגִינֵהּ אִתְּמַר גָּדוֹל הָעוֹנֶה אָמֵן יוֹתֵר מִן הַמְבָרֵךְ. וְהָא אוֹקְמוּהּ וְכַד נַחְתִּין מַשִּׁרְיָן דְּמַלְכָּא, נַחְתִּין בְּקָלִין הָדָא הוּא דִּכְתִיב (שמות י״ט:ט״ז) וַיְהִי קוֹלוֹת וּבְרָקִים וְעָנָן כָּבֵד עַל הָהָר וְקוֹל שׁוֹפָר חָזָק מְאֹד. דְּהָכֵי אֹרַח דְּמִטְרָא לְסַלְּקָא עֲנָנָא בַּחֲשַׁאי, וּלְנַחְתָּא נַטְרָא בְּקוֹלֵי קוֹלוֹת. וְלֵית מִטְרָא אֶלָּא שַׁקְיוּ דְּאוֹרַיְתָא לְגַבֵּי שְׁכִינְתָּא. דִּשְׁכִינְתָּא אִיהִי שְׁרָגָא, דְּאִתְּמַר בָּהּ הִיא הָעוֹלָה. יִשְׂרָאֵל פְּתִיל' מִשְׁחָא אוֹרַיְתָא לְהַעֲלֹת נֵר תָּמִיד וּבְזִמְנָא דִּצְלוֹתָא דְּאִיהִי מִצְוָה סְלִיקַת בְּאוֹרַיְתָא, לֵית לֵהּ כְּבֵהּ עוֹלָמִית.</p>"],[9514015227,"<p>וְכַד צְלוֹתָא אִיהִי עֵת רָצוֹן קֳדָם ה'. אִתְחַזְיָא קֶשֶׁת בְּגַוְנוֹי נְהִירִין בַּעֲנָנָא, בְּהַהוּא זִמְנָא וְרָאִיתִי' לִזְכֹּר בְּרִית עוֹלָם. דִּבְאִלֵּין גְּוָנִין נְהִירִין אִשְׁתְּמוֹדַע דִּשְׁכִינְתָּא סְלִיקַת קֳדָם ה' בְּעוֹבָדִין טָבִין דְּיִשְׂרָאֵל אִם לֹא אִתְחַזְיָא קֶשֶׁת בְּגַוְנִין נַהֲרִין אִיהִי קָא רְמִיזָא (בראשית ט) סַכּוֹתָה בֶּעָנָן לך מֵעֲבוֹר תְּפִלָּה. וְאִתְחַזְיָא בִּלְבוּשׁ דַּעֲנָנָא אֻכָּמָא.</p>"],[9514015228,"<p>אִם קֶשֶׁת בֵּהּ בְּגַוְנֵי חֲשִׁיכִין חדיכין אִיהִי קָא רְמִיזַת אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחֹרֶת. וְאִם גַּוְנֵי דְּקֶשֶׁת נְהִירִין, אִיהִי קָא רְמִיזַת שְחוֹרָה אֲנִי וְנָאוָה שְׁחוֹרָה אֲנִי בַּעֲנָנָא אֻכָּמָא, וְנָאוָה בְּגַוְנִין שַׁפִּירִין. נְהִירִין דְּקֶשֶׁת בְּעוֹבָדִין טָבִין דְּיִשְׂרָאֵל.</p>"],[9514015229,"<p>וְאַגְרָא דִּצְלוֹתָא דְּתִקּוּנָא דָּא, כַּד נַפְקַת נִשְׁמָתָא מִן גּוּפָא לְאַזְלָא לְעָלְמָא דְּאָתֵי, כְּמָא דְּאִיהוּ אוֹקִיר לִשְׁכִינְתָּא, וְלָבִישׁ לָהּ בְּכַמָּה עֲנָנִין דִּלְבוּשִׁין יַקִּירִין, דְּאִתְקְרִיאוּ עַנְנֵי יָקָר, וְסָלִיק לָהּ בִּצְלוֹתֵהּ לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, בְּשִׁירִין וּזְמִירוֹת וְתֻשְׁבָּחוֹת וְהוֹדָאוֹת, דִּצְלוֹתָא הָכֵי סָלִיק לָהּ קוּדְשָׁא בְּרִיח הוּא לְעָלְמָא דְּאָתֵי לְנִשְׁמָתֵהּ בִּלְבוּשׁ עַנְנֵי יְקָר וּבְכַמָּה שִׁירוֹת וְתִשְׁבָּחוֹת וְהוֹדָאוֹת כְּגַוְנָא דְּנָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם בְּעַנְנֵי יְקָר וּבְנִגּוּנֵהּ. הָדָא הוּא דִּכְתִיב (שמות ט״ו:א׳) אָז יָשִׁיר מֹשֶׁה וּבְנֵי יִשְׂרָאֵל וְגוֹ'.</p>"],[9514015230,"<p>וְכַמָּה דְּסָלִיק לָהּ בְּכַמָּה מַשִּׁרְיָן דְּמַלְאָכִים, וְנָחִית לְגַבָּהּ מַשִּׁרְיָן דְּקוּדְשָׁא בְּרִיךְ הוּא לְקַדְמוּתָה וְקוּדְשָׁא בְּרִיךְ הוּא עִמְּהוֹן, הָכֵי סָלִיק לְנִשְׁמָתָא מִן גּוּפָא בְּמַשִּׁרְיָן דִּשְׁכִינְתָּא וְנָחִית קוּדְשָׁא בְּרִיךְ הוּא לְקַדְמוּתָא בְּמַשִּׁרְיָן דִּילֵהּ.</p>"],[9514015231,"<p>וּכְמָה דְּאַעְטַר לְקוּדְשָׁא בְּרִיךְ הוּא בִּתְפִלִּין דְּרֵישָׁא, וְאַתְקִין לֵהּ כֻּרְסֵא בְּצִיצִית, כְּמָה דְּאוֹקְמוּהּ, (ישעיה ט) וְהוּכַן בְּחֶסֶד כִּסֵּא. הָכֵי קוּדְשָׁא בְּרִיךְ הוּא תִּקֵּן לְנִשְׁמָתֵהּ כֻּרְסֵא, וְתִקֵּן לֵהּ דִּירָה בִּמְזוּזָה, וְאַעְטָר לֵהּ בְּכִתְרָא דִּילֵהּ.</p>"],[9514015232,"<p>וְכַמָּה דְּקָשַׁר לִשְׁכִינְתָּא בְּקוּדְשָׁא בְּרִיךְ הוּא בְּקִשּׁוּרָא דִּתְפִלִּין, וּמֵחַד לֵהּ בֵּהּ, הָכֵי רוּחָא דִּילֵהּ קָשִׁיר עִם נַפְשָׁא, וְנִשְׁמָתָא עִם בַּעְלָהּ, דְּאִיהוּ אָדָם, וְתַקִּין לֵהּ דִּירָה עִמֵּהּ, וְסִימָנָא (משלי כ) נֵר ה' נִשְׁמַת אָדָם. נֵ\"ר נֶפֶ\"שׁ רוּ\"חַ. וְאִנּוּן אֲצִילוּת דִּשְׁכִינְתָּא, וְעַמּוּדָא דְּאֶמְצָעִיתָא דְּכָלִיל שִׁית סְפִירָן. נִשְׁמַת אָדָם אֲצִילוּתָא דְּאִמָּא עִלָּאָה וְחָכְמָה. דְּתַמָּן מָ\"ה דְּאִיהוּ אָדָם קַדְמָאָה. מַחֲשָׁבָה כֶּתֶר עִלָּאָה, תְּפִלִּין עַל רֵישָׁא דְּאַבָּא וְאִמָּא. וּבְגִין דָּא אִתְּמַר בְּבַר נָשׁ, בְּמִדָּה שֶׁאָדָם מוֹדֵד, בָּהּ מוֹדְדִין לוֹ. וּבְגִינֵיהוֹן דִּבְנֵי נָשָׁא אִתְּמַר (שמואל א ב) כִּי מְכַבְּדַי אֲכַבֵּד וּבוֹזַי יֵקַלּוּ, וְלֹא עוֹד אֶלָּא מָאן דְּיִשְׁתְּדַל בְּאוֹרַיְתָא אִית לֵהּ חֵירוּ.</p>"],[9514015233,"<p>וּכְעָן צָרִיךְ לְפָרְשָׁא עַל פּוּמָא דִּסְלִיקָא צְלוֹתָא מִנַּהּ. כְּצִפּוֹר וּכְיוֹנָה וּכְנִשְׁרָא. וְיִשְׂרָאֵל כַּד נָפְקוּ מִמִּצְרַיִם נָפְקוּ כְּיוֹנָה דְּבָרַחַת, וְנֵץ הֲוָה רָדִיף אֲבַתְרֵהּ הָכֵי אִית צְלוֹתָא דְּמִסִּטְרָא דִּילֵהּ שְׁכִינְתָּא אִיהִי פָּרְחָא בָּהּ כְּיוֹנָה וְסמא\"ל וְחֵילִהּ רָדְפִין אֲבַתְרָאָה בְּכַמָּה חוֹבִין דְּאוֹלְפִין עַל מָארֵהּ דְּהַהִיא צְלוֹתָא, וְאוֹלִיף לוֹן בִּגְבוּרָה לְעַכְּבָא שְׁכִינְתָּא תַּמָּן, דְּלָא סַלְקָא לְקוּדְשָׁא בְּרִיךְ הוּא בְּהַהִיא צְלוֹתָא. וְאִיהוּ הַהוּא צְלוֹתָא דְּיִשְׂרָאֵל עַל יַמָּא, דַּהֲווֹ בְּלָא זְכוּ דְּאוֹרַיְתָא וְעוֹבָדִין טָבִין, וְהַמַּיִם לָהֶם חוֹמָה וְהָכֵי אִנּוּן צְלוֹתִין מְעֻכָּבִין.</p>"],[9514015234,"<p>וְאִם חוֹזְרִין בִּתְיוּבְתָּא. מָארֵי דִּצְלוֹתִין אִיהוּ דְּאָמַר לְגַבֵּי שְׁלוּחָא דִּצְלוֹתִין מְטַטְרוֹן, מַה תִּצְעַק אֵלַי, מַלִּיל לִצְלוֹתִין דְּנָטְלִין בְּמַטְלְנוֹתְהוֹן הָדָא הוּא דִּכְתִיב (שמות יד) דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וַיִּסְעוּ. לְבַר נָשׁ דְּאָזִיל בְּאוֹרְחָא וְרָדִיף אֲבַתְרֵהּ הַהוּא מָארֵי מנד' דְּמַלְכָּא, וְאָחִיד בֵּהּ עַד דְּפָרַע מנדה בלו וְהָלַךְ. בְּגִין דְּבָרַח אִיהוּ צווֵֹחַ לְמָאן דְּאַפִּיק לֵהּ. יֵתֵי מָארֵי' וְיֵמָא אִמָּא לֵהּ דְּיָזִיל לְאוֹרְחֵהּ דַּאֲנָא פָּרַעְתֵּהּ. אָתָא מֶה עָבַד טָבַע רֵישֵׁהּ בַּטִיט וְקָטַל לֵהּ, הָכֵי קוּדְשָׁא בְּרִיךְ הוּא עָבַד בְּמִצְרָאֵי. הָדָא הוּא דִּכְתִיב (שמות טו) מַרְכְּבוֹת פַּרְעֹה וְגוֹ' טֻבְּעוּ בְּיַם סוּף.</p>"],[9514015235,"<p>וּמָאן גָּרִים דְּרַדְפִין אֲבַתְרַיְהוּ דְּיִשְׂרָאֵל, בְּגִין דְּעַד לָא הֲוָה לוֹן אוֹרַיְתָא לָא הֲוָה שְׁטַר חֵירוּ. בְּגִין דְּאוֹרַיְתָא אִיהִי שְׁטַר חֵירוּ לִבְנֵי נָשָׁא, מִיֵּצֶר הָרָע וּמִמַּלְאַךְ הַמָּוֶת וּמִכָּל מְקַטְרְגֵי דְּעָלְמָא. הָדָא הוּא דִּכְתִיב (שם לב) וְהַמִּכְתָּב מִכְתַּב אֱלֹהִים הוּא חָרוּת עַל הַלֻּחֹת. וְדָא אִמָּא עִלָּאָה שְׁנַת הַחֲמִשִּׁים, דְּמִתַּמָּן אוֹרַיְתָא דְּאִיהוּ עַמּוּדָא דְּאֶמְצָעִיתָא אִתְקְרֵי חֵירוּ, דְּמִתַּמָּן אִתְיְהִיב (חסר כאן) לְגַבֵּי יוֹנָה קַדִּישָׁא דְּאִיהִי שְׁכִינְתָּא, דְמִסִּטְרָא' אִתְקְרִיאוּ יִשְׂרָאֵל יוֹנָה.</p>"],[9514015236,"<p>וְהָכֵי כַּד צְלוֹתָא דְּאִיהִי יוֹנָה סְלִיקַת בְּאוֹרַיְתָא, מַה כְּתִיב בֵּהּ (ישעיה נא) כִי לֹא בְּחִפָּזוֹן תֵּצֵאוּ וּבִמְנוּסָה לֹא תֵּלֵכוּן כִּי הוֹלֵךְ לִפְנֵיכֶם ה' וְגוֹ'. ואִלֵּין אִנּוּן צְלוֹתִין דְּמָארֵי דְּאוֹרַיְתָא. דְּסָלִיק כְּנִשְׁרָא דְּלָא דַּחֲלַת מִכָּל עוֹפִין דְּעָלְמָא. וּמִסִּטְרָא דְּאִנּוּן אִיהִי מַטְרוֹנִיתָא דֶּרֶךְ הַנֶּשֶׁר בַּשָּׁמַיִם. וְאִית דְּיַמָּא הָכֵי וְכֹלָּא קְשׁוֹט.</p>"],[9514015237,"<p>וּמִסִּטְרָא דְּמָארֵי מִקְרָא סְלִיקַת צְלוֹתָא כְּצִפּוֹר. וּמִסִּטְרָא דְּמָארֵי מִשְׁנָה סְלִיקַת כַּיּוֹנָה. וּמִסִּטְרָא דְּמָארֵי קַבָּלָה סְלִיקַת כְּנִשְׁרָא, מַטְרוֹנִיתָא עַל כֹּלָּא. אֲבָל מִסִּטְרָא דְּאִלֵּין דְּלֵית בְּהוּ מִקְרָא מִשְׁנָה וְקַבָּלָה, דְּאִנּוּן עַמֵּי הָאָרֶץ, לֵהּ סְלִיקוּ בְּהוֹן. וּבְגִין דָּא אָמַר קֹהֶלֶת בְּאֹרַח רְמִיזָא, (קהלת ג) כִּי מִי יוֹדֵעַ רוּחַ בְּנֵי הָאָדָם הָעוֹלָה הִיא לְמַעְלָה וְרוּחַ הַבְּהֵמָה הַיּוֹרֶדֶת הִיא לְמַטָה לָאָרֶץ. וְרוּחַ הַבְּהֵמָה אִלֵּין אִנּוּן עַמֵּי הָאָרֶץ. וּלְזִמְנִין נַפְקִין מִנַּיְהוּ זַרְעָא מֵעַלְיָא בְּנֵי תּוֹרָה לְאִסְתַּלְּקָא בְּהוֹן בְּגִין דָּא אוֹקְמוּהּ מִכָּל מָקוֹם הִזָּהֲרוּ בְּעַמֵּי הָאָרֶץ דִּלְזִמְנִין נַפְקִין מִנְּהוֹן בְּנֵי מֵעַלְיָא מָארֵי אוֹרַיְתָא.</p>"],[9514015238,"<p>קָם בּוּצִינָא קַדִּישָׁא וְכֻלְּהוּ מַשִּׁרְיָן לְנַשְּׁקָא הַהוּא סָבָא פָּרַח. אָמַר רִבִּי שִׁמְעוֹן וַדַּאי הַהוּא סָבָא, לָא בָּעָא לְנַטְלָא אַגְרָא מִנָּן לְנַשְּׁקָא לֵהּ, וּבְגִין דָּא פָּרַח. זַכָּאָה חוּלָקָנָא דְּזָכִינָא לְמִשְׁמַע אַגְרָא דְּפִקּוּדָא דִּצְלוֹתָא בְּעָלְמָא דְּאָתֵי.</p>"],[9514015239,"<p>קָם רִבִּי אֶלְעָזָר וְאָמַר, אַבָּא מָאן הֲוָה הַהוּא סָבָא. אָמַר וַדַּאי רַב הַמְנוּנָא סָבָא, אִשְׁתְּמוֹדַע דְּנִשְׁמָתֵהּ נַחְתָּא מִתְלַבְּשָׁא בָּאֲוִירָא דְּהֶבֶל דְּאוֹרַיְתָא. דִּבְזִמְנָא דְּצַדִּיקַיָּא מִתְעַסְּקִין בְּאוֹרַיְתָא, כָּל אִלֵּין הֲבָלִים דְּסָלְקִין מִפּוּמֵיהוֹן בְּאוֹרַיְתָא, כְּמָה נִשְׁמָתִין דְּהַהוּא עָלְמָא רָכָבַן עָלַיְהוּ וּמִתְלַבְּשָׁן בְּהוּ. וְקָלִין וְדִבּוּרִין דְּאוֹרַיְתָא אִתְעֲבִידוּ לוֹן כְּסוּסְוָן, וְרַכְבִין עָלַיְהוּ וְנַחְתִּין בְּהַאי עָלְמָא. וַאֲפִלּוּ מַלְאָכִין. וְכָל שֶׁכֵּן בְּחִבּוּרָא דָּא, וּבְמָארֵי דְּהַאי חִבּוּרָא דְּבֵהּ קוּדְשָׁא בְּרִיךְ הוּא הַטֵה הַשָּׁמַיִם וּשְׁמֵי הַשָּׁמַיִם כְּגַוְנֵי דְּסִינַי, וְאִיהוּ נָחִית עָלֵהּ לְאָקָמָא שְׁכִינְתֵּהּ בְּשִׁתִּין רִבּוֹא דְּמַלְאָכִין. וּבְכָל נִשְׁמָתִין דְּאִתְבְּרִיאוּ וַעֲתִידִין לְמִבְרֵי. הָדָא הוּא דִּכְתִיב (דברים כט) כִּי אֶת אֲשֶׁר יֶשְׁנוֹ פֹּה עִמָּנוּ וְגוֹמֵר. וּבְנִשְׁמָתִין דַּאֲצִילוּתָא דְּפוּמֵהּ אִיהִי סִינַי. וְקָלָא דִּילֵהּ אָתָא כְּגַוְנָא דְּקָלָא דְּמָארֵהּ דְּאִתְּמַר בֵּהּ (דברים ד) קוֹל דְּבָרִים אַתֶּם שׁוֹמְעִים. וְכָל דִּבּוּר וְדִבּוּר אִתְעֲבִיד מִנֵּהּ מַלְאָךְ. וְנִשְׁמְתָא דִּילֵהּ בְּגִינַהּ מַכְרִיזִין לְעֵלָּא, כַּד סַלְקָא בְּכָל לֵילְיָא הָבוּ יְקָרָא לְדִיּוֹקְנָא דְּמַלְכָּא. אַדְּהָכִי הָא רָעֲיָא מְהֵימָנָא קָא אָתֵי נָטַל קִרְטָא בִּידֵהּ.</p>"],[9514015240,"<p>פָּתַח וְאָמַר זַרְקָא מקף שׁוֹפָר הוֹלֵךְ סְגוֹלְתָּא. נָטִיל תְּלָת אַבְנִין וְזָרִיק לוֹן לְגַבֵּי עֵלָּא. וְכַד זָרִיק לוֹן אִתְעֲבִידוּ אַבְנָא חֲדָא, וְאָמַר לְמָארֵי מְתִיבְתָּא, קַבִּילוּ הַאי אַבְנָא לְגַבַּיְכוּ, דְּהָא שְׁכִינְתָּא אִיהִי בְּגָלוּתָא וְלֵית בָּכוּ מָאן דְּיִתְּעַר לְגַבָּהּ לְרַצָּאָה לָהּ לְגַבֵּי בַּעְלָהּ וְלֹא עוֹד אֶלָּא כַּמָּה מָארֵי מִדְרָשׁוֹת דְּאִנּוּן חֲבֵרִין לְגַבַּיְכוּ, צַוְחִין בְּכָל יוֹמָא וְלֵילְיָא בְּאוֹרַיְתָא דִּבְעַל פֶּה, בְּכַמָּה קוּשְׁיָן. וְצַוְחִין בָּהּ בְּכַלְבִין דְּאָמְרִין הַב הַב. כְּגַוְנָא דְּגֵיהִנֹּם דְּצָוַח הַב הַב, הָדָא הוּא דִּכְתִיב (משלי ל) לַעֲלֻקָּה שְׁתֵּי בָּנוֹת הַב הַב. הַב לָן עוּתְרָא בְּעָלְמָא דֵּין. הָב לָן עוּתְרָא בְּעָלְמָא דְּאָתֵי. כְּמָה דְּאוֹקְמוּהּ לְמֹד תּוֹרָה הַרְבֵּה וְיִתְּנוּ לְךָ שָׂכָר הַרְבֵּה. וְלֵית מָאן דְּיִשְׁתְּדַל בְּאוֹרַיְתָא, לְסַלְקָא בֵּהּ שְׁכִינְתָּא מִן גָּלוּתָא, וּלְיַחֲדָא לָהּ עִם בַּעְלָהּ דְּאִנּוּן אֲטִימִין דְּעַיְנִין סְתִימִין דְּלִבָּא, וּבְגִין דָּא קָלָא נָפַק בְּכָל לֵילְיָא כַּד נָחִית קוּדְשָׁא בְּרִיךְ הוּא בְּגִנְתָּא דְּעֵדֶן, דְּסַלְקִין נִשְׁמָתִין קַמֵּהּ, וְהַהוּא קָלָא אָמַר קְרָא כְּדִכְתִיב (ישעיה מ) קוֹל אוֹמֵר קָרָא. זִיל וְאִמָּא לוֹן דְּיִשְׁתַּדְּלוּן בְּאוֹרַיְתָא לְחַבְּרָא שְׁכִינְתָּא עִם קוּדְשָׁא בְּרִיךְ הוּא. כְּגַוְנָא דְּדָוִד דְּאָמַר (תהלים קלב) אִם אֶתֵּן שְׁנַת לְעֵינַי לְעַפְעַפַּי תְנוּמָה עַד אֶמְצָא מָקוֹם לַה'. וְאִיהוּ הֲוָה מִשְׁתַּדַּל בְּאוֹרַיְתָא לְחַבְּרָא אִמָּא, דְּאִתְּמַר בָּהּ (משלי א) וְאַל תִּטֹשׁ תּוֹרַת אִמֶּךָ עִם בַּעְלָהּ. דְּהָא שְׁכִינְתָּא מִסִּטְרָא דְּחֶסֶד אִתְקְרִיאַת גְּמִילוּת חֲסָדִים. וּמִסִּטְרָא דִּגְבוּרָה אִתְקְרִיאַת עֲקֵדָה וְקָרְבְּנָא. וּמִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא אִתְקְרִיאַת תּוֹרָה. וְלֵית מָאן דְּיִתְּעַר לָהּ בְּאִלֵּין מִדּוֹת לְגַבֵּי בַּעְלָהּ. הָדָא הוּא דִּכְתִיב (ישעיה נא) אֵין מְנַהֵל לָהּ וְגוֹ'. וּבְגִין דָּא קָלָא אָמַר מָה אֶקְרָא כָּל הַבָּשָׂר חָצִיר. דְּלָא מִשְׁתַּדְּלִין אֶלָּא לְדַבְּחָא בִּשְׂרָא, ואִלֵּין אִנּוּן עַמֵּי הָאָרֶץ ואִלֵּין דְּמִשְׁתַּדְּלִין בִּגְמִילוּת חֶסֶד וּבְאוֹרַיְתָא, לֹא מִשְׁתַּדְּלִין אֶלָּא לְגַרְמַיְהוּ, וּבְגִינַיְהוּ אִתְּמַר וְכָל חַסְדּוֹ כְּצִיץ הַשָּׂדֶה. וְכָל אִלֵּין דְּלָא מִשְׁתַּדְּלִין בֵּהּ לִשְׁמָהּ, רוּחָא קוּדְשָׁא דְּאִיהִי שְׁכִינְתָּא לָא שַׁרְיָא עָלַיְהוּ, הָדָא הוּא דִּכְתִיב (תהלים עח) וַיִּזְכֹּר כִּי בָּשָׂר הֵמָּה רוּחַ הוֹלֵךְ וְלֹא יָשׁוּב.</p>"],[9514015241,"<p>וְאִית דְּלָא מִשְׁתַּדְּלִין בְּאוֹרַיְתָא דִּבְעַל פֶּה לִשְׁמָהּ, וְאִתְּמַר בְּהוֹן (שמות א) וַיְמָרַרוּ אֶת חַיֵּיהֶם בַּעֲבֹדָה קָשָׁה, דָּא קוּשְׁיָא, בְּחֹמֶר, דָּא קַל וָחֹמֶר. וּבִלְבֵנִים בְּלִבּוּן הַהֲלָכוֹת. דַּעֲלַיְהוּ אִתְּמַר וְתֹכֶן לְבֵנִים תִּתְּנוּ. בְּכָל עֲבוֹדָה בַּשָּׂדֶה, דָּא בָּרַיְתָא. אֶת כָּל עֲבוֹדָתָם, דָּא פִּסְקָא. אֲשֶׁר עָבְדוּ בָּהֶם בְּפָרֶךְ פִּרְכָא. כַּד מָטוּ לְעָמְקָא שֶל הֲלָכָה אִתְּמַר בְּהוֹן לֵית הֲלָכָה כִּפְלוֹנִי. וְאִית אָחֳרָנִין דְּאִנּוּן מָארֵי (תורה) דְּמִשְׁתַּדְּלִין בָּהּ לִשְׁמָהּ, תְּרִיסִין דְּבֵהּ מִדְרָשָׁא דְּאִתְּמַר בְּהוֹן (במדבר יט) אָדָם כִּי יָמוּת בָּאֹהֶל. כְּמָה דְּאוֹקְמוּהּ מָארֵי מַתְנִיתִין אֵין הַתּוֹרָה מִתְקַיְּמֶת אֶלָּא בְּמִי שֶׁמֵּמִית עַצְמוֹ עָלֶיהָ.</p>"],[9514015242,"<p>וְלֵית מִיתָה אֶלָּא עֹנִי. דְּאוֹקְמוּהּ בֵּהּ, פַּת בַּמֶּלַח תֹּאכַל. וְעָלַיְהוּ אִתְּמַר (ישעיהו כ״ו:י״ט) יִחְיוּ מֵתֶיךָ. אִלֵּין דְּאִתְּמַר בְּהוֹן (במדבר י״ט:י״ד) אָדָם כִּי יָמוּת בָּאֹהֶל. דְּוַדַּאי בְּהוֹן אִתְקַיְּמַת שְׁכִינְתָּא. וְעָתִיד קוּדְשָׁא בְּרִיךְ הוּא לְאָחַיָּא לוֹן בֵּהּ. כְּמָה דְּאוֹקְמוּהּ כָּל הַמְקַיִּם אֶת הַתּוֹרָה מֵעֹנִי סוֹפוֹ לְקַיְּמָהּ וְגוֹ'. נְבֵלָתִי יְקוּמוּן, אִלֵּין דְּאִתְּמַר בְּהוֹן אִם נבלת בְּהִתְנַשֵּׂא. וְאָמְרוּ מָארֵי מַתְנִיתִין כָּל הַמְנַבֵּל עַצְמוֹ עַל הַתּוֹרָה, לַסּוֹף מִתְנַשֵּׂא.</p>"],[9514015243,"<p>הָקִיצוּ וְרַנְּנוּ שֹׁכְנֵי עָפָר. אִלֵּין דְּאִתְּמַר בְּהוֹן וְעַל הָאָרֶץ תִּישַׁן. בְּגִין הַהִיא דְּאִתְּמַר בָּהּ (קהלת ג׳:כ׳) הַכֹּל הָיָה מִן הֶעָפָר וַאֲפִלּוּ גַּלְגַּל חַמָּה, דְּבֵהּ בְּרִיךְ קוּדְשָׁא בְּרִיךְ הוּא לְאַבְרָהָם כֹּה יִהְיֶה זַרְעֲךָ כַּעֲפַר הָאָרֶץ. וְדָא שְׁכִינְתָּא, דִּבְגִינֵהּ אִתְּמַר בְּאִלֵּין דְּמִשְׁתַּדְּלִין בֵּהּ לִשְׁמָהּ, (דניאל י״ב:ב׳) וְרַבִּים מִישֵׁנֵי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם. כִּי טַל אוֹרוֹת טַלֶּךָ (ישעיה כי), וְדָא יוּ\"ד הֵ\"א וָא\"ו. הַאי אִיהוּ חֻשְׁבַּן טָ\"ל אוֹרַיְתָא דִּבְעַל פֶּה. דְּאִיהוּ הֵ\"א שִׁית סִדְרֵי מִשְׁנָה אִיהוּ בְּחֻשְׁבַּן הֵ\"א שִׁית סִדְרֵי מִשְׁנָה אִיהוּ בְּחֻשְׁבַּן הֵ\"א. וּבְגִינַהּ אוֹקְמוּהּ מָארֵי מַתְנִיתִין, כָּל הָעוֹסֵק בְּטַל תּוֹרָה. טַל תּוֹרָה מְחַיֵּהוּ. וְהַאי אִיהוּ דמצילן בֵּהּ מוֹרִיד הַטָ\"ל. וְקוּדְשָׁא בְּרִיךְ הוּא אָמַר (הושע י״א:ט׳) לֹא אָבֹא בָּעִיר.</p>"],[9514015244,"<p>מָשָׁל לְבַת מֶלֶךְ דְּאָזַל בַּעְלָהּ לִמְדִינַת הַיָּם, וּלְזִמְנָא דְּאָתָא לְגַבָּהּ, אוּמֵי לָהּ דְּלָא עָאל בְּיִשּׁוּבָא. וְהַאי אִיהוּ לֹא אָבֹא בָּעִיר. וְאִם לֵית אַתְּ מְהֵימְנַת לִי, הֲרֵי לָךְ סִימָנָא שֶׁרֹאשִׁי נִמְלָא טָ\"ל. דְּהַאי אִיהוּ טַל לְהַחֲיוֹת בּוֹ מֵתִים. (שם) וְאֶרֶץ רְפָאִים תַּפִּיל אוֹקְמוּהּ מָארֵי מתנ', מָאן רְפָאִים, אִלֵּין דְּאִתְּמַר בְּהוֹן בִּקְרָא אָחֳרָא, רְפָאִים בַּל יָקוּמוּ. וְאִלֵּין אִנּוּן דמתרפין מִפִּתְגְּמֵי אוֹרַיְתָא לע\"ז, דְּיָהֲבֵי לְעוֹבְדֵי עַכּוּ\"ם מָמוֹנָא דִּילְהוֹן, לְאִתְגַּבְּרָא בְּהוֹן וארפון יְדֵיהוֹן מֵאִלֵּין דְּעָסְקִין בְּאוֹרַיְתָא לִשְׁמָהּ לְמֶעֱבַד טִיבוּ עִמְּהוֹן. אִלֵּין לֹא יְקוּמוּן וְאַפִּילַת לוֹן אַרְעָא, כְּאִתְּתָא עֻבָּרָא דְּמַפֶּלֶת נְפָלִים, וְדָא אִיהוּ וְאֶרֶץ רְפָאִים תַּפִּיל. דְּנָפַל לָאו אִיהוּ בַּר קַיָּמָא. וְהַאי הוּא דְּלָא כָּלוּ לוֹ חֳדָשָׁיו, דְּאִנּוּן ט' יַרְחִין דְּעֻבָּרָא מָאן עוֹבָדָא. אֶלָּא דָּא אוֹרַיְתָא. וְאִיהִי שְׁכִינְתָּא, הַהוּא יֶלֶד דְּאִתְיְלִיד מִנַּהּ בְּאוֹרַיְתָא, בְּיַרְחָא קַדְמָאָה מֵאִלֵּין דְּאִתְּמַר בְּהוֹן אֵין בֶּן דָּוִד בָּא עַד דְּתִתְפַּשֵּׁט מַלְכוּת הָרִשְׁעָא ט' חֳדָשִׁים עַל יִשְׂרָאֵל. בְּיַרְחָא קַדְמָאָה אִיהוּ מָשִׁיחַ אַיִ\"ן. וּבְיַרְחָא תִּנְיָנָא עָבִיד לֵהּ יֵשׁ מֵאַיִן, בִּסְפִירָה תִּנְיָנָא דְּאִתְּמַר בָּהּ וְהַחָכְמָה מֵאַיִן תִּמָּצֵא. בְּיַרְחָא תְּלִיתָאָה מוֹסִיף בֵּהּ בִּינָה. וְהַאי אִיהוּ וְנָחָה עָלָיו רוּחַ ה' רוּחַ חָכְמָה וּבִינָה. וּבְגִין דָּא אוֹקְמוּהּ מָארֵי מַתְנִיתִין אֵיזֶהוּ חָכָם הַמֵּבִין דָּבָר מִתּוֹךְ דָּבָר. דְּקֹדֶם דְּאָתָא לְעָלְמָא אוֹלְפִין לֵהּ חָכְמְתָא וּבִינָה. בְּיַרְחָא רְבִיעָאָה גָּמִיל עִמֵּהּ חֶסֶד, דְּעָאִיל לֵהּ פַּרְנָסָה מִטִבּוּרָא דְּאִמֵּהּ בְּיַרְחָא חֲמִישָׁאָה יָהִיב בֵּהּ תֻּקְפָא דִּגְבוּרָה לְאִתְגַּבְּרָא עַל יֵצֶר הָרָע מִסִּטְרָא דְּסַמָּאֵל, דְּלָא שָׁלִיט עָלֵהּ בְּבֶטֶן אִמֵּהּ לְמֶעֱבַד לֵהּ נְפַל לְקַטְלָא מְשִׁיחָא. בְּיַרְחָא שְׁבִיעָאָה יָהִיב בֵּהּ דַּעְתָּא וְכֹחַ וְשַׁפִּירוּ דאנפיו. בְּיַרְחָא שְׁבִיעָאָה וּתְמִינָאָה יָהִיב בֵּהּ רוּחָא דְּקוּדְשָׁא מִסִּטְרָא דְּנֶצַח וָהוֹד, דְּאִנּוּן תְּרֵי נְבִיאֵי קְשׁוֹט. וּבְגִין דָּא נִתְנַבֵּא רוּחָא דְּקֻדְשָׁא עָלֶיהָ (ירמיה א) בְּטֶרֶם אֶצָּרְךָ בַּבֶּטֶן יְדַעְתִּיךָ וּבְטֶרֶם תֵצֵא מֵרֶחֶם וְגוֹ'. מִסִּטְרָא דְּצַדִּיק יָהִיב לֵהּ אוֹת וּמוֹפֵת. בְּיַרְחָא תְּשִׁיעָאָה דְּנוֹלַד מָהוּל, וְהַהוּא יַנּוֹקָא אִיהוּ עֲשִׂירָאָה מִסִּטְרָא דְּמַלְכוּת, אִיהוּ טִפָּה עֲשִׂירָאָה. וּבְגִין דָּא זָכָה לְט' דַּרְגִּין אִלֵּין.</p>"],[9514015245,"<p>קָמוּ מָארֵי מַתְנִיתִין וְאָמְרוּ, רָעֲיָא מְהֵימָנָא טְלוּ אַבְנָא דִּילָךְ לְגַבָּךְ, דְּאַנְתְּ הוּא דְּאִתְּמַר עָלָךְ (שמות ה) וַתֵּרֶא אֹתוֹ כִּי טוֹב הוּא. וְאוֹקְמוּהּ מ\"מ מַאי כִּי טוֹב, דְּאִתְיְלִיד מָהוּל. וְאַנְתְּ הוּא בְּלֵיל בְּט' יַרְחִין אִלֵּין, וּמִסִּטְרָא דְּעִבּוּרָא דִּילָךְ, מַלְכוּת קַדִּישָׁא אִתְּמַר בָּהּ (דברים ל״ג:ה׳) וַיְהִי בִּישֻׁרוּן מֶלֶךְ. וְהַאי אַבְנָא טִפָּה קַדִּישָׁא כְּלִילָא מֵעֲשָׂרָה. אַנְתְּ הוּא זֶרַע דְּאִתְמַשְׁכַת מִנַּהּ. וּבָךְ תַּלְיָא פֻּרְקָנָה, וְעָלָךְ עָתִיד לְאִתְבָּנָאָה בִּנְיָנָא וְעָלָךְ תָּקוּם, טֹל לָהּ לְגַבָּךְ. אָמַר לוֹן לֵית אַתּוּן יָכְלִין לְאִשְׁתַּזְבָא. אִי אִשְׁתְּזַבְתוּן מאכנא חֲדָא. אֲנָא זָרִיק לְכוֹן שִׁית, דְּאִתְּמַר בְּהוֹן בְּד\"א שִׁי\"ת, נָטַל קִרְטָא כְּמִלְּקַדְּמִין.</p>"],[9514015246,"<p>פָּתַח וְאָמַר זַרְקָא מָקֵף שׁוֹפָר הוֹלֵךְ סְגוֹלְתָּא תְּלָת אַבְנִין עִלָּאִין אִנּוּן סְגוֹלְתָּא. תְּלָת טִפִּין עִלָּאִין דְּאִתְּמַר בְּהוֹן (איוב ל״ג:כ״ט) הֵן כָּל אֵלֶּה יִפְעַל אֵל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר. וּתְלָת טִפִּין תַּתָּאִין לְקָבְלַיְהוּ סֶגוֹל עָלַיְהוּ אִתְּמַר שָׁמְעוּ הָרִים אֶת רִיב ה' (מיכה ו׳:ב׳). מָאן הָרִים. אֶלָּא הָא תְּלָת אַבְנִין עִלָּאִין לְגַבַּיְכוּ, דְּאִנּוּן סְגוֹלְתָּא. וּלְמָאן מִנַּיְכוּ לְרַבִּ'י וְרַ'ב וְרַבָּ'א דִּמְתִיבְתָּא עִלָּאָה. דִּלְקָבְלַיְכוּ הֲווֹ כָּל רַב מִבָּבֶל. וְרִבִּי מֵאַרְעָא דְּיִשְׂרָאֵל. וְרַבָּא מִשְּׁאָר אַרְעִין. שָׁמְעוּ דְּאַתְוָן רִיב וּקְטָטָה וּמַחֲלֹקֶת בַּהֲלָכָה לְעֵלָּא. וְרַבִּ'י וְרַ'ב וְרַבָּ'א מַחֲלֹקֶת וְרִיב וּקְטָטָה בַּהֲלָכָה דִּילְהוֹן לְתַתָּא. וְלֵית בְּכוּ דִּיהֵא רִיב וּקְטָטָה וּמַחֲלֹקֶת בְּגִין שְׁכִינְתָּא, לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא לְדַחֲקָא לֵהּ בְּכַמָּה קוּשְׁיָן עַד דְּיָפִיק לֵהּ מִן גָּלוּתָא. וְהָאֵיתָנִים, אִלֵּין תַּנָּאִים דְּמַתְנִיתִין דִּמְתִיבְתָּא דִּלְתַתָּא. הָא תְּלָת אַבְנִין לְגַבַּיְכוּ, דְּאִנּוּן סֶגוֹל. דְּשִׁית נִקּוּדִין אִלֵּין, אִנּוּן שִׁית סִדְרֵי מַתְנִיתִין. וְכָל נְקֻדָּה אִיהִי. עֶשֶׂר וְסַלְקִין לְס' מַסֶּכְתּוֹת, דְּעָלַיְהוּ אָמַר שְׁלֹמֹה (שיר השירים ו׳:ח׳) שִׁשִּׁים הֵמָּה מְלָכוֹת. וְאִית לֵהּ כַּמָּה בְּתוּלוֹת אַחֲרֶיהָ רְעוּתֶיהָ דַּהֲלָכוֹת פְּסוּקוֹת דְּאִתְּמַר בְּהוֹן (שם) וַעֲלָמוֹת אֵין מִסְפָּר. וּשְׁכִינְתָּא אִיהִי תָּגָא עַל כֻּלְּהוּ. תָּגָא דְּזַרְקָא עָלֵהּ אִתְּמַר (משלי ל״א:כ״ט) רַבּוֹת בָּנוֹת עָשׂוּ חַיִל וְאַתְּ עָלִית עַל כֻּלָּנָה. וְאִיהִי רִיב וּקְטָטָה וּמַחֲלֹקֶת וְקוּשְׁיָא לְקוּדְשָׁא בְּרִיךְ הוּא בְּגִין יִשְׂרָאֵל אַחֵיכוֹן. ומ\"מ דְּמִשְׁתַּדְּלִין בְּאוֹרַיְתָא בְּכָל יוֹמָא וְלֵילְיָא בְּגָלוּתָא, אִיהִי רִיב בְּגִינַיְהוּ דְּיִפּוּק לוֹן. וְלֵית מָאן דִּיהֵא רִיב וּקְטָטָה וּמַחֲלֹקֶת לְקוּדְשָׁא בְּרִיךְ הוּא בְּגִינֵהּ בְּגָלוּתָא.</p>"],[9514015247,"<p>קָם סָבָא חֲדָא מבֵּינַיְהוּ וְאָמַר, רָעֲיָא מְהֵימָנָא כַּמָּה תַּקִּיפִין אַבְנִין דְּזָרִיקַת. דְּאִזְדַּעְזְעוּ מָארֵי מְתִיבְתָּא דִּלְעֵלָּא וְתַתָּא, וַאֲפִלּוּ מַלְאָכִין עִלָּאִין דְּאִנּוּן סַמְכִין שִׁית דַּרְגִּין דְּכֻרְסֵא וְכֻרְסֵא אִזְדַּעְזְעַת. אֲבָל הָא אֵיתָן מוֹשָׁבֶךָ לְגַבָּךְ דְּאִיהִי שְׁבִיעָאָה אִתְּמַר מִנַּהּ, דְּהָא אַבְנָא דְּזָרִיקַת הָא אִיהִי לְגַבָּךְ דְּאִיהִי תָּגָא עַל כֻּלְּהוּ. שִׂים בַּסֶּלַע קִנֶּךָ, וְשִׁית אָחֳרָנִין לְגַבָּךְ בְּגִין דְּאִיהוּ אָמַר (יחזקאל ל״ו:כ״ב) לֹא לְמַעַנְכֶם אֲנִי עוֹשֶׂה. הָא שִׁית לְגַבָּךְ כִּי אִם לְשֵׁם קָדְשִׁי הָא שְׁבִיעָאָה לְגַבָּךְ וְלֹא עוֹד אֶלָּא דְּאַנְתְּ הוּא דְּאִתְּמַר בָּךְ וַיַּךְ אֶת הַסֶּלַע וְשִׂים בַּסֶּלַע, דְּחִוְיָא לְכַפֵּר עֲוֹנֵךְ קִנֶּךָ. קוּדְשָׁא בְּרִיךְ הוּא מָנֵי לְכוּ וְדִבַּרְתֶּם אֶל הַסֶּלַע, וְאַתּוּן לָא עֲבַדְתּוּן הָכֵי. דְּאִי עֲבַדְתּוּן מֵימְרֵי בְּדִבּוּרָא, הֲווֹ אוֹלְפִין אוֹרַיְתָא בְּלָא סָפֵק וּבְלָא קוּשְׁיָא וּמַחֲלֹקֶת. וּבְגִין דְּאִתְּמַר בָּךְ (במדבר כ׳:י״א) וַיַּךְ אֶת הַסֶּלַע וְלֹא נָפְקוּ מִנֵּהּ אֶלָּא טִפִּין טִפִּין. הָכֵי מִכָּל מָקוֹם אִנּוּן כְּמָאן דְּמָחֵי בַּסֶּלַע. וְאִנּוּן לִישַׁנְהוֹן. כְּפַטִישׁ יְפוֹצֵץ סֶלַע וּפַסְקִין בָּהּ כַּמָּה פְּסָקוֹת דַּהֲלָכוֹת, וְלֹא נַפְקִין מִנַּיְהוּ אֶלָּא טִפִּין טִפִּין וְאִנּוּן לְקוּטוֹת. וּבְגִין דָּא בָּךְ תַּלְיָא כֹּלָּא. הָא אַבְנָא לְגַבָּךְ וְשִׁית אָחֳרָנִין. וּבָךְ תַּלְיָא פֻּרְקָנָא דִּשְׁכִינְתָּא וּבְנָהָא, בְּגִין דְּיִתְקַן בָּךְ מַה דאתהרס בְּקַדְמִיתָא. וּבְגִין חֲבִיבוּתָא דִּילָךְ, שִׁית טִפִּין דְּגִלְגּוּלָא אִתְחַזְּרוּן לְגַבָּךְ דְּאִנּוּן רְמִיזִין בְּרֵישֵׁי עַנְפִּין דִּלְךָ. אִנּוּן ש ש דְּכָפַל בְּהוּ מֹשֶׁה מֹשֶׁה. אַבְנָא שְׁבִיעָאָה (איכה ב׳:י״ג) מָה אֲעִידֵךְ מָה אֲדַמֶּה לָּךְ וְאִתְּמַר בֵּהּ הַבַּת יְרושָׁלַיִם. וְעָלַהּ אִתְּמַר מָה אֲשַׁוֶּה לָךְ. אִיהִי אֲשַׁוֶּה לָךְ בִּתְבִירוּ דִּילָךְ, וַאֲנַחֲמֵךְ. דְּאִית לָךְ לְהִתְנַחֵם עִמָּהּ. דְּדַיּוֹ לְעֶבֶד לִהְיוֹת כְּרַבּוֹ. וְאַף עַל גַּב דִּיהֵא רַב תְּבִירוּ דִּילָךְ כְּיַמָּא, הָדָא הוּא דִּכְתִיב (שם) כִּי גָּדוֹל כַּיָּם שִׁבְרֵךְ מִ\"י יִרְפָּא לָךְ, דְּאִיהִי אִמָּא עִלָּאָה תְּשׁוּבָה צָרִיךְ בֵּירָא דִּילָךְ אִתְבַּקְּעַת דְּאִיהִי יַמָּא דְּאוֹרַיְתָא. הָדָא הוּא דִּכְתִיב (שמות י״ד:כ״א) וַיֵּט מֹשֶׁה יָדוֹ עַל הַיָּם וַיֹּלֵךְ ה' אֶת הַיָּם בְּרוּחַ קָדִים עַזָּה כָּל הַלַּיְלָה וַיָּשֶׂם אֶת הַיָּם לְחָרָבָה. ע\"כ.</p>"],[9514015248,"<p>מִכָאן וָאֵילָךְ וַיִּבָּקְעוּ הַמַּיִם דִּילֵהּ לְגַבָּהּ. וְאִיהוּ עֵץ חַיִּים דְּאִתְּמַר בָּהּ (שם טו) וַיּוֹרֵהוּ ה' עֵץ וַיַּשְׁלֵךְ אֶל הַמַּיִם וַיִּמְתְּקוּ הַמַּיִם דְּאוֹרַיְתָא דִּבְעַל פֶּה, דְּאִתְּמַר בְּהוֹן (שם) וְלֹא יָכְלוּ לִשְׁתּוֹת מַיִם מִמָּרָה כִּי מָרִים הֵם (שמות א׳:י״ד). כְּמָה דְּאוֹקְמוּהּ וַיְמָרַרוּ אֶת חַיֵּיהֶם בַּעֲבֹדָה קָשָׁה, דְּאִיהִי קוּשְׁיָא. וּבְהַהוּא זִמְנָא וַתֵּשְׁתְּ הָעֵדָה וּבְעִירָם. וְכַד אִתְגַּלֵּי לָךְ אִילָנָא דְּחַיֵּי בְּדָרָא בַּתְרָאָה, דְּאַתְּ עָתִיד לְאִתְגַּלָּאָה בֵּינַיְהוּ כְּמָה דְּאוֹקְמוּהּ (קהלת א׳:ט׳) מַ'ה שֶּׁהָיָ'ה הוּ'א שֶׁיִּהְיֶ'ה. כַּמָּה נִסְיוֹנוֹת אִית לְאִתְנַסְּאָה יִשְׂרָאֵל. הָדָא הוּא דִּכְתִיב שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ לְמֹשֶׁה, וְאוֹרַיְתָא אִתְחַזְרַת לוֹן נִסָּיוֹן לְאִנּוּן דְּמִשְׁתַּדְּלִין בֵּהּ וְהַוְיָן בְּעָאקוּ סַגִּי. כְּגַוְנָא דְּמִצְרַיִם דְּאִתְּמַר בֵּהּ (שם א) כָּל הַבֵּן הַיִּלּוֹד הַיְאֹרָה תַּשְׁלִיכֻהוּ. וְדָא אוֹרַיְתָא דְּבִכְתָב. וְכָל הַבַּת תְּחַיּוּן אוֹרַיְתָא דִּבְעַל פֶּה, דְּתַרְוַיְהוּ אִנּוּן פֶּ'ה וּלְשׁוֹן, וּבְהוֹן תְּהֵא אַנְתְּ כְּבַד פֶּה וּכְבַד לָשׁוֹן, וְחַכִּימָא בִּרְמִיזָא. וְלֵית מִיתָה דְּמָארֵי דִּנְהוֹרָא דְּאוֹרַיְתָא אֶלָּא עֲנִיּוּתָא. וּבְפֻרְקָנָא בַּתְרַיְתָא, אוֹרַיְתָא יְהֵא לְיִשְׂרָאֵל כְּגַוְנָא דְּיַמָּא, דְּאִתְּמַר בָּךְ, רָעֲיָא מְהֵימָנָא (שם ב) וַתָּשֶׂם בַּסּוּף עַל שְׂפַת הַיְאֹר (שמות ב׳:ג׳). בְּסוֹ'ף פ\"ו יוֹמִין דַּרְגָּא דְּפֻרְקָנָא אִתְּמַר בָּךְ וַתָּשֶׂם בַּסּוּף עַל שְׂפַת הַיְאֹר, דְּאִיהוּ נְהוֹרָא דְּאוֹרַיְתָא עַמּוּדָא דְּאֶמְצָעִיתָא. שָׂפָה דִּילֵהּ שְׁכִינְתָּא בְּהַהוּא זִמְנָא אִלֵּין טִפִּין דַּהֲווֹ נַפְקִין מִן הַסֶּלַע, דְּאִנּוּן פַּסְקֵי הֲלָכוֹת אִתְּמַר בְּהוֹן (תהילים צ״ג:ג׳) נָשְׂאוּ נְהָרוֹת ה'. תְּרֵין טִפִּין דְּאִנּוּן צרי סַלְקִין בִּתְרֵין וָוִין וְאִתְעֲבָדוּ נְהָרוֹת. וְהַהִיא נִקּוּדָא עִלָּאָה דְּאִיהִי סְגוֹלְתָּא אִסְתַּלְּקַת עַל גַּדְפַיְהוּ. וּסְלִיקוּ דִילֵהּ בְּאָן אֲתַר הֲוֵי, אֶלָּא אִלֵּין אִלֵּין תְּרֵין נְהָרוֹת אִנּוּן אַבָּא וְאִמָּא. מִסִּטְרָא דִּבְרַתָּא דְּמַלְכָּא טִפִּין אִתְקְרִיאוּ דְּאִתְּמַר בְּהוֹן, וַיִּצֶר, (ישעיה כה) כִּי בֵּהּ ה' צוּר עוֹלָמִים. צִיֵּר תְּרֵין עָלְמִין דַּקִּיקִין. עָלְמִין דִּבְרַתָּא דְּמַלְכָּא אִנּוּן מִתַּתָּא לְעֵלָּא. מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא אִתְקְרִיאוּ נְהָרוֹת. וּבְגִין דָּא נָשְׂאוּ נְהָרוֹת. לְמָאן לְהַהִיא סְגוֹלְתָּא, סַלְקִין לֵהּ כֶּתֶ\"ר עַל גַּבַּיְהוּ לְמֶהֱוֵי כָּלִיל סְגוֹלְתָּא, וּמִתְעַטְרָה בֵּהּ בִּתְלָת כִּתְרִין. דְּאִנּוּן כֶּתֶר כְּהֻנָּה וְכֶתֶר מַלְכוּת וְכֶתֶר תּוֹרָה עַל גַּבֵּיהֶן. וְהָכֵי אִנּוּן תְּלָת נְהָרוֹת ו'ו'ו וּתְלָת יוֹדִין וּתְלָת וָוִין רְמִיזִין בִּתְלָת רֵישֵׁי תֵּבִין, דְּאִנּוּן וַ'יִּסַּע וַ'יָּבֹא וַ'יֵּט. תְּרֵין דְּאִנּוּן אַבָּא וְאִמָּא סַלְקִין כֶּתֶר עַל גַּדְפַיְהוּ. נָשְׂאוּ נְהָרוֹת קוֹלָם. אִנּוּן חֶסֶד גְּבוּרָה עָלַיְהוּ אִתְּמַר נָשְׂאוּ נְהָרוֹת קוֹלָם. מָאן קוֹלָם דָּא עַמּוּדָא דְּאֶמְצָעִיתָא וְדָא רָזָא דְשׁוּרֻק לְעֵלָּא. שַׁלְשֶׁלֶת אִיהוּ כָּלִיל תְּלָת נִקּוּדִין בְּקִשּׁוּרָא חֲדָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא. דְּעָלֵהּ אִתְּמַר (ירמיהו ב׳:כ״א) וְאָנֹכִי נְטַעְתִּיךְ שּׂורֵק כֻּלּוֹ זֶרַע אֱמֶת. יִשְּׂאוּ נְהָרוֹת דָכְיָם אִנּוּן נֶצַח וָהוֹד. נָשְׂאוּ לֹא כְּתִיב אֶלָּא יִשְּׂאוּ. וְאִנּוּן סֶגוֹ\"ל דְּהִיא נְקֻדָּה מִסִּטְרָא דִּשְׁכִינְתָּא אִיהִי נְקֻדָּה לְתַתָּא דְּצַדִּיק שְׁכִינְתָּא תְּחוֹת רַגְלִין, דְּאִנּוּן יַרְכְּתֵי צָפוֹן. הָדָא הוּא דִּכְתִיב (תהילים מ״ח:ג׳) יְפֵה נוֹף מְשׂוֹשׂ כָּל הָאָרֶץ וְגוֹ'. כַּד אִיהִי נְקֻדָּה וְד' תְּחוֹת יְרֵכִי קְשׁוֹט אִתְקְרִיאַת הַר צִיּוֹן טוּרָא מָאִיךְ. וְאִתְקְרִיאַת מִסִּטְרָא דְּצַדִּיק, דָּכְיָ\"ם ד\"ך יָ\"ם דַּךְ כָּלִיל מִכ\"ד אַתְוָן דְּאִנּוּן בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד, וּבְהוֹן אַל יָשׁוּב דַּךְ נִכְלָם. יָם אִתְקְרִיאַת מִסִּטְרָא דְּאִמָּא עִלָּאָה, כְּלִילָא מֵחַמְשִׁין אַתְוָן דִּכְלִילָן בִּקְרִיאַת שְׁמַע. בִּקְרָא קַדְמָאָה דִּמְיַחֲדִין לְקוּדְשָׁא בְּרִיךְ הוּא תְּרֵין זִמְנִין שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד. וּבְהוֹן וַיִּפֶן כֹּה וָכֹה וַיַּךְ אֶת הַמִּצְרִי. וּמִסִּטְרָא דְּאִמָּא עִלָּאָה אִיהוּ נִקּוּדָא עַל גַּדְפַיְהוּ קִרְיַת מֶלֶךְ רַב. וּכְעָן אִתְּמַר בֵּהּ (איכה א׳:א׳) הָעִיר רַבָּתִי עַם הָיְתָה כְּאַלְמָנָה.</p>"],[9514015249,"<p>קוּם עַמּוּדָא דְּאֶמְצָעִיתָא, דְּאַנְתְּ הוּא ו' כָּלִיל שִׁית סְפִירָן. וְאַנְתְּ אָחִיד בֵּין כֹּ\"ה עִלָּאָה וּבֵין כֹּ\"ה תַּתָּאָה. קוּם לְגַבֵּי סַמָּאֵ\"ל דְּאִיהִי מִצְרִי בְּמָאנֵי קְרָבָא דִּילָךְ, דְּאִנּוּן שְׁכִינְתָּא תַּתָּאָה קוֹרְטָא תַּתָּאָה. וּשְׁכִינְתָּא עִלָּאָה קוֹרְטָא עִלָּאָה דְּעָלֵהּ אִתְּמַר (שמואל א כ״ה:כ״ט) וְאֶת נֶפֶשׁ אֹיְבֶיךָ יְקַלְּעֶנָּה בְּתוֹךְ כַּף הַקֶּלַע מָאן נֶפֶשׁ אוֹיְבֶיךָ. סַם מָוֶת נָחָשׁ אֵשֶׁת זְנוּנִים דִּמְקַנְּנָא בְּשֶׁבַע סְלָעִים וּבַעְלָהּ בְּ-ז' טוּרִין. קוּם בְּאַבְנִין דִּילָךְ דְּאִסְתְּלָקוּ בטורי' לְתַבְרָא טוּרִין וְסַלְעִין דְּחִוְיָא, וּבְגִין טוּרִין דִּילָךְ אִתְּמַר (תהילים צ״ג:ג׳) נָשְׂאוּ נְהָרוֹת ה'. וּבְהוֹן כָּל גֵּיא הַהוּא יִנָּשֵׂא דְּכֹלָּא כָּלִיל בֵּהּ. וְדָא רָעֲיָא מְהֵימָנָא דְּאִתְּמַר בֵּהּ (דברים ל״ד:ו׳) וַיִּקְבֹּר אוֹתוֹ בַּגַּיא. דִּבְגִינֵהּ אִתְּמַר (תהילים ס׳:ב׳) וַיַּךְ אֶת אֱדוֹם בְּגֵיא מֶלַח. וְנִשְׁמָתֵהּ גָּנִיז' בְּגֵי\"א מִן אבגית\"ץ. ת' תּוֹרַת מֹשֶׁה צָפוֹנָה בְּצָדִ\"י דְּאִיהוּ ץ'. דְּצָדִי אֲרִיכָא מִסִּטְרָא דְּעָלְמָא דְּאָתֵי, מִתַּמָּן הוּא טוֹב לַצַּדִּיקִים דְּעָלְמָא דְּאָתֵי. בְּגֵי\"א אָב לְי\"ג מְכִילִין, דְּאִנּוּן וָא\"ו וַיַּעֲבֹר ה' עַל פָּנָיו. וַיַּעֲבֹר ע\"ב רי\"ו. ע\"ב חֶסֶד. רי\"ו גְּבוּרָה דְּבֵהּ קר\"ע שט\"ן מִן יַמָּא. וּבֵהּ עָתִיד לְמִקְרַע לֵהּ מִן יַמָּא דְּאוֹרַיְתָא. וּמִסִּטְרָא דְּחֶסֶד אִיהוּ אָב לְ-י\"ג מְכִילָן, דְּבֵהּ אִיהוּ יהו'ה עַמּוּדָא דְּאֶמְצָעִיתָא אֶרֶךְ אַפַּיִם, וּמַאֲרִיךְ בֵּהּ עַל בֵּינוֹנִים וּמַטֶה לוֹן כְּלַפֵּי חֶסֶד. וּבְאַתְוָן א\"ת ב\"ש. יהו\"ה אִיהוּ מצפ\"ץ אֵ\"ל ת\"ך, רחו\"ם גספ\"י וְהָכֵי עַד י\"ג תֵּבִין. בְּאִלֵּין י\"ג מַאֲרִיךְ עַל בֵּינוֹנִים דְּיַחְזְרוּן בִּתְשׁוּבָה. אֲבָל בקר'ע שט'ן יָדִין בַּגּוֹיִם מָלֵא גְּוִיּוֹת. דְּאִיהוּ שָׂטָן מָלֵא עַיְנִין. וּבְגִין דָּא אבגית\"ץ אִתְקְרֵי כֶּתֶר חָכְמָה אָב לְי\"ג מְכִילָן, דִּכְלִילָן בְּחֶסֶד דְּכָלִיל. ע'ב שְׁמָהָן דְּאִנּוּן כְּלָלָא דִּילְהוֹן וָהוּ אֲנִי וָהוּ וְחָכְמָה לִימִינָא. כד\"א הָרוֹצֶה לְהַחְכִּים יַדְרִים. אִמָּא עִלָּאָה לִגְבוּרָה בָּהּ. קר\"ע שט\"ן מִן שְׂמָאלָא. וּבָהּ (שמות י״ד:כ״א) וַיָּשֶׂם אֶת הַיָּם לְחָרָבָה. וּבָא קָרַע יַמָּא לְי\"ב קְרָעִים. וּבָהּ רֹקַע הָאָרֶץ וְצֶאֱצָאֶיהָ. וּבָהּ עָקַר טוּרִין וְתָבַר טִינָרִין דְּחִוְיָא. הָדָא הוּא דִּכְתִיב (מלכים א י״ט:י״א) וְהִנֵּה רוּחַ גְּדוֹלָה וְחָזָק מְפָרֵק הָרִים וּמְשַׁבֵּר סְלָעִים. דְּאִנּוּן טוּרִים וּסְלָעִים דְּחִוְיָא, דְּאִתְּמַר בֵּהּ דֶּרֶךְ נָחָשׁ עֲלֵי צוּר. וּבְהַאי שְׁמָא הֲוָה רָבָּה עוֹקֵר הָרִים בְּאוֹרַיְתָא דִּבְעַל פֶּה.</p>"],[9514015250,"<p>כֶּתֶר עֶלְיוֹן אִיהוּ פֶּלֶא, וּבֵהּ עַמּוּדָא דְּאֶמְצָעִיתָא, דְּאִתְקְרֵי נוּרָא עָבִיד פְּלִיאָן. הָדָא הוּא דִּכְתִיב (שמות ט״ו:י״א) נוֹרָא תְּהִלּוֹת עוֹשֶׂה פֶּלֶא. וּבֵהּ אָמַר מֹשֶׁה נֶגֶד כָּל עַמְּךָ אֶעֱשֶׂה נִפְלָאוֹת וְכוּ'. וְהַאי אִיהוּ נג\"ד יכ\"ש, נג\"ד י\"ש כ' דְּאִיהוּ כֶּתֶר. יֵ\"ש לְהַנְחִיל אוֹהֲבַי יֵשׁ. וְאִנּוּן י' חָכְמָה ש' תְּשׁוּבָה. כֻּלְּהוּ כָּלִיל עַמּוּדָא דְּאֶמְצָעִיתָא שָׁמַיִם, דְּאִתְּמַר בֵּהּ (מלכים א ח׳:ל״ב) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם שְׁמַע יִשְׂרָאֵל. בט\"ר צת\"ג דָּא נֶצַח וְאִית דְּאָמְרֵי לֵהּ גת\"ץ רט\"ב בֵּהּ וְהָיִיתָ כְּגַן רָטֹב. וְיִתְקַיֵּם בְּיִשְׂרָאֵל (ישעיהו נ״ח:י״א) וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךָ, מִסִּטְרָא דְּנֶצַח דְּאִיהוּ צַח (שם) וְעַצְמוֹתֶיךָ יַחֲלִיץ וְגוֹ'. וְאִתְּמַר בג' מִן גת\"ץ וְהָיִיתָ כְּגַן רָטֹב אִיהוּ רַחֲמִים, ת' תִּפְאֶרֶת וּבֵהּ (בראשית א׳:י״א) תּוֹצֵא הָאָרֶץ דֶּשֶׁא עֵץ פְּרִי עוֹשֶׂה פְּרִי, לְיִשְׂרָאֵל בַּמִּדְבְּרָא, וְכַמָּה מַבּוּעִין דְּמַיָּא. חק\"ב טנ\"ע דָּא הוֹד בֵּהּ (שמות ט) שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ. דְּהוֹד אִתְקַשַּׁר בִּגְבוּרָה, נֶצַח בְּחֶסֶד וְאִתְּמַר בְּהוֹד נְתַנַּנִי שׁוֹמְמָה כָּל הַיּוֹם דָּוָה בֵּהּ אִסְתַּכַּל בְּחֻרְבָּנָא דְּמַקְדְּשָׁא, וְכַמָּה קְטִילִין דְּאִתְקְטָלוּ לְנַטְלָא נוּקְמִין מֵאֻמִּין דְּעָלְמָא. וּבֵהּ אִתְּמַר (בראשית ל״ב:ל״ב) וְהוּא צוֹלֵעַ עַל יְרֵכוֹ. בְּהַהוּא זִמְנָא (ישעיהו ל״ה:ו׳) אָז יְדַלֵּג כְּאַיִל פסח וְעוֹד טנ\"ע בְּהִפּוּךְ אַתְוָן נָטַע בֵּהּ חָב אָדָם הָדָא הוּא דִּכְתִיב (שם יז) בְּיוֹם נִטְעֵךְ תְּשַׂגְשְׂגִי.</p>"],[9514015251,"<p>וּבֵהּ אִתְנְטַע וְאִשְׁתְּרַשׁ בְּעָלְמָא הָדָא הוּא דִּכְתִיב (ישעיהו ס׳:כ״א) נֵצֶר מַטָעַי מַעֲשֵׂה יָדַי לְהִתְפָּאֵר. וְעוֹד חק\"ב טנ\"ע תַּמָּן בט\"ן וְתַמָּן ע\"ב. שְׁכִינְתָּא בֵּהּ אִתְקְרִיאַת בִּטְנֵךָ עֲרֵמַת חִטִים. דְּהָא כָּל שְׁמָא כָּלִיל שִׁית לִסְפִירָן וְתַמָּן ע\"ב הָדָא הוּא דִּכְתִיב (ויקרא כ״ג:מ׳) וַעֲנַף עֵץ עָבוֹת. דְּנֶצַ\"ח וְהוֹ\"ד אִנּוּן עָבֵי שְׁחָקִים. וְעָלַיְהוּ אִתְּמַר (שם) עַרְבֵי נַחַל (שם), דּוֹמְיָא דִּתְרֵין שִׂפְוָן וּתְלָת סְפִירָן, כָּל חַד כָּלִיל ע\"ב אַתְוָן דְּאִנּוּן נֶצַח וָהוֹד יְסוֹד. כְּגַוְנָא דִּתְלָת אֲבָהָן וְכֻלְּהוּ תְּלָת כְּלִילָן שִׁבְעִין וּתְרֵין (נ\"א מ\"ב) אַתְוָן.</p>"],[9514015252,"<p>יג\"ל פז\"ק דָּא אִיהוּ צַדִּיק אָלֶף שְׁתִיתָאָה דְּבֵהּ קוּדְשָׁא בְּרִיךְ הוּא יְגַלֶּ\"ה פִּדְיוֹ\"ן זֶרַ\"ע קְדוֹשִׁי\"ם. דְּאִיהוּ יְסוֹד עָלְמִין, אִיהוּ סוֹד דְּקֵץ דְּפֻרְקָנָא דְּאִתְרְמִיז בִּשְׁכִינְתָּא דְּאִתְקְרֵי שקוצי\"ת, דְּתַמָּן שי\"ת וק\"ץ דְּאִיהִי שְׁכִינְתָּא שְׁבִיעִית לוֹן קֵץ דְּכֻלְּהוּ. עָלֵהּ אִתְּמַר (דניאל יב) וְאַתָּה לֵךְ לַקֵּץ וְתָנוּחַ וְתַעֲמֹד לְגֹרָלְךָ לְקֵץ הַיָּמִין. וְאִיהוּ קֵ\"ץ דְּדָלִיג מִן ד' מֵאָה שְׁנִין, דַּהֲווֹ עֲתִידִין לְאִשְׁתַּעְבְּדָא בְּמִצְרַיִם הִיא וּבְנָהָא, וְאִשְׁתְּאֲרוּ רְד\"וּ רְדוּ שָׁמָּה.</p>"],[9514015253,"<p>מִסִּטְרָא דִּימִינָא אִתְקְרִיאַת קֵץ הַיָּמִין. וּמִסִּטְרָא דִּשְׂמָאלָא קֵץ כָּל בָּשָׂר. לְמָאן דְּחַבִּיל אוֹת בְּשַׂר קֹדֶשׁ, אִיהִי לֵהּ דִּינָא, קֵץ כָּל בָּשָׂר. וְאִיהִי סוֹף פָּסוּק סוֹף פסק דַּהֲלָכוֹת. וּבְחִבּוּרָא דְּאָת ו' אִיהוּ פָּסוּק. אִיהוּ פְּסָק וְאִיהוּ פָּסוּק כָּלִיל כָּל פִּסְקֵי הֲלָכוֹת. דִּשְׁאֵלָה ברכ' וּפָסַק אִיהִי שְׁכִינְתָּא אוֹרַיְתָא דִּבְעַל פֶּה קָרֵינָן לֵהּ. וְאִיהוּ מִשְׁמַעְתָּא שָׁטָה תְּיוּבְתָּא תּוֹסֶפְתָּא הַגָּדָה תֵּיקוּ. תַּנְיָא קַבָּלָה הֲלָכָה מִשְׁנָה בָּרַיְתָא קוּשְׁיָא. מַחֲלֹקֶת חֻמְרָא קֻלָּא שְׁכִינְתָּא אִיהִי שְׁאֵלָה דְּבָהּ חָכָם שׁוֹאֵל כָּעִנְיָן וּמֵשִׁיב כַּהֲלָכָה. וּבָהּ (שמות ג׳:כ״ב) וְשָׁאֲלָה אִשָּׁה מִשְּׁכֶנְתָּהּ וְגוֹ'. וּבָהּ (דברים ל״ב:ז׳) שְׁאַל אָבִיךָ וְיַגֶּדְךָ דְּאִיהִי הַגָּדָה, דְּבָהּ (שם כו) הִגַּדְתִּי הַיּוֹם לַה' אֱלֹהֶיךָ. שְׁאַל מִמֶּנִּי וְאֶתְּנָה גּוֹיִם נַחֲלָתֶךָ. וּבָהּ אָמַר לִשְׁלמֹה (מלכים א ג׳:ה׳) שְׁאַל מָה אֶתֵּן לָךְ וּבָהּ תַּקִּינוּ לְמִשְׁאַל שְׁאֵלְתֵּהּ בְּבִרְכָּאן אֶמְצָעִית דִּצְלוֹתָא, דְּבִשְׁאֵלָה זוֹ לֹא יַחֲזֹר רֵיקָנֵהּ בִּצְלוֹתֵהּ קַמֵּי מַלְכָּא דְּאִיהוּ עַמּוּדָא דְּאֶמְצָעִיתָא וּבְבִרְכָּאן קַדְמָאִין אִתְקְרִיאַת תֻּשְׁבְּחָתָא, דְּבֵהּ תַּקִּינוּ לְתַקְּנָא (נ\"א לסדרא) בַּר נָשׁ שְׁבָחָא דְּמַלְכָּא. וּבִתְלָת בַּתְרָאִין אִתְקְרִיאַת קַבָּלָה דְּבָהּ עַבְדָּא דְּאִיהוּ מְטַטְרוֹ\"ן אִיהוּ כְּעֶבֶד הַמְּקַבֵּל פְּרָס מֵרַבּוֹ וְהוֹלֵךְ לוֹ, וּבֵהּ יַהֲבִין אַגְרָא דִּצְלוֹתִין לְאִלֵּין דִּמְצַלִּין עַל מְנָת לָקֳבֵל פְּרָס. אֲבָל לְאִנּוּן (נ\"א לבנין) דְּלָא מְצַלִּין אֶלָּא מִגּוֹ רְחִימוּ וּדְחִילוּ דְּמָארֵיהוֹן בְּצַדִּיק. יְסוֹד חַ\"י עָלְמִין כָּלִיל חַ\"י בִּרְכָּאִין מְקַבְּלִין.</p>"],[9514015254,"<p>דְמִסִּטְרָא דְּצַדִּיק אִתְקְרִיאַת אִיהִי קַבָּלָה, אִיהִי בֵּית קִבּוּל לְיַרְתָּא נִשְׁמָתִין לְצַדִּיקַיָּא. הַבְּרָכָה אִתְקְרִיאַת מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא, כִּד נָטִיל מִגְּבוּרָה דְּאִיהוּ שׁוֹר דְּקָרִיב אָדָם קַדְמָאָה, דְּאִיהוּ חָכְמָה דִּמְמָנָא עַל כָּל קָרְבְּנִין. דְּכֶבֶשׂ אִיהוּ מִסִּטְרָא דִּימִינָא, וְשׁוֹר מִסִּטְרָא דִּשְׂמָאלָא. וּבְגִין דָּא שׁוֹר שֶׁהִקְרִיב אָדָם קַדְמָאָה אִתְּמַר בֵּהּ (תהילים ס״ט:ל״ב) מִשּׁוֹר פָּר מַקְרִין מַפְרִיס. וְאִיהוּ מְמָנָא עַל מַדְבְּרָא וּבֵהּ סָפֵק צָרְכֵיהוֹן בְּאָרַע מַדְבְּרָא. וּמִתַּמָּן אִתְקְרִיאַת שְׁכִינְתָּא הַבְּרָכָה, וּמִנֵּהּ אִתְקְרִיאַת פְּסָק וּמִתַּמָּן פִּסְקֵי דִּינִין. וּמִתַּמָּן לָאוֵי דִּינִין לָא צְרִיכָא. וּבְגִין דָּא אִית לְאֵשֶׁת מוֹדַע לְבַר נָשׁ כָּל מִדָּה וּמִדָּה דְּאִיהִי שְׁאֵלָה וּתְשׁוּבָה דִּיהֵא בָּהּ שׁוֹאֵל וּמֵשִׁיב כַּהֲלָכָה. וְכָל רָז לָא אָנִיס לֵהּ. וְכָל עוּמְקָא דַּהֲלָכָה אִתְגַּלְּיָא לֵהּ. וצָרִיךְ לְאַחֲזָרָא עָלֵהּ דְּלָא יְהֵא בֵּהּ סְפֵיקָא בְּעָלְמָא שְׁאֵלָ\"ה אִיהִי מִימִינָא דְּאִיהוּ אֵל, הָאֵל הַגָּדוֹל דְּתַמָּן חָכְמָה. וּמִתַּמָּן שָׁאִיל שְׁלֹמֹה חָכְמְתָא. כַּד אָמַר לֵהּ לְקוּדְשָׁא בְּרִיךְ הוּא (מלכים א ג׳:ה׳) שְׁאַל מָה אֶתֵּן לָךְ. וּמִתַּמָּן תַּנְיָא דִּמְסַיַּע לֵהּ, דְּבֵהּ וְה' נָתַן חָכְמָה לִשְׁלֹמֹה, מַאי תַּנְיָא, דָּא עַמּוּדָא דְּאֶמְצָעִיתָא. וּמִתַּמָּן אִתְקְרִיאַת סִיַּעְתָּא דִּשְׁמַיָּא דְּאִתְּמַר בָּהּ (שם ח) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם. צְרִיכָא הָא אוֹקִימְנָא לֵהּ מִסִּטְרָא דִּגְבוּרָה תְּיוּבְתָּא אִתְקְרִיאַת מִסִּטְרָא דְּבִינָה, דְּאִם בַּר נָשׁ לָאו מֵבִין הַהֲלָכָה, אֵיךְ יַחֲזִיר לָהּ וּמֵשִׁיב לַשּׁוֹאֵל. פָּסַק הָא אוֹקִימְנָא לֵהּ מִסִּטְרָא דְּדִינָא פְּסַק דִּין. מִשְּׁמַעְתָּא מַשְׁמָעוּת הַהֲלָכָה, מִסִּטְרָא דְּהַהוּא דְּאִתְּמַר בֵּהּ שְׁמַע יִשְׂרָאֵל דְּהַהוּא דְּאַרְבַּע אִנּוּן תִּקּוּפָן דַּהֲלָכָה דְּאִתְרְמִיזוּ בְּבַר נָשׁ. וְאִנּוּן י' רְאִיָּה. י'ה שְׁמִיעָה. יה'ו רֵיחָא. יהו'ה דִּבּוּר. וְד' בְּגוּפָא כְּלִילָן מִד' אַתְוָן. לְקָבְלַיְהוּ א' שִׁמּוּשׁ. א\"ד תְּנוּעָה. אד\"נ מִשּׁוּשׁ. אֲדֹנָ\"י הִלּוּךְ. דְּאִנּוּן שִׁמּוּשׁ בַּיָּדַיִם. תְּנוּעָה בְּגוּפָא. מִשּׁוּשׁ בַּבְּרִית. הֲלִיכָה בָּרַגְלַיִן. אִית דְּאָמְרֵי מִשּׁוּשׁ בַּיָּדַיִם. שִׁמּוּשׁ בַּבְּרִית. וְכֹלָּא קְשׁוֹט.</p>"],[9514015255,"<p>רְאִיָּה מִסִּטְרָא דְּאַרְיֵה, דְּאִיהוּ לִימִינָא דְּאִתְּמַר בֵּהּ (יחזקאל א׳:י׳) וּפְנֵי אַרְיֵה אֶל הַיָּמִין לְאַרְבַּעְתָּם. רְאִיָּה אַרְיֵה תּוֹסֶפֶת י' תִּנְיָנָא חָכְמָה. הָרוֹצֶה לְהַחְכִּים יַדְרִים. וּמִתַּמָּן רְאוּבֵן, או'ר ב'ן אוֹר דְּיוֹמָא קַדְמָאָה.</p>"],[9514015256,"<p>שְׁמִיעָה בְּשׁוֹר גְּבוּרָא דְּתַמָּן בִּינָה דְּאִיהוּ שְׁמִיעָה כְּלִילָא חַמְשִׁין אַתְוָן דִּקְרִיאַת שְׁמַע. וּבְגִין דָּא תַּקִּינוּ בֵּהּ קְרִיאַת שְׁמַע דְּשַׁחֲרִית וְעַרְבִית. וּבְגִינָהּ אָמַר הַנָּבִיא (חבוק ג) ה' שָׁמַעְתִּי שִׁמְעֲךָ יִרְאָתִי. וְאָמְרוּ מָארֵי מַתְנִיתִין הֲבִינוֹתִי מִבְּעֵי לֵהּ. וּבְגִינָהּ אָמַר (ישעיהו ל״ז:י״ז) הַטֵה ה' אָזְנְךָ וּשְׁמַע. וּמִסִּטְרָא דְּחֶסֶד כִּי עַיִ\"ן בְּעַיִ\"ן יִרְאוּ דְּאִיהוּ ע\"ב חֶסֶד. אֲבָל מִסִּטְרָא דִּגְבוּרָא שָׁמַעְתִּי שִׁמְעֲךָ יָרֵאתִי דְּתַמָּן יִרְאָה דְּמִתַּמָּן אִיהִי שְׁכִינְתָּא תַּתָּאָה מִשְּׁמַעְתָּא, וּמִתַּמָּן שַׁמְעִין.</p>"],[9514015257,"<p>רֵיחָא (יחזקאל א׳:י׳) וּפְנֵי נֶשֶׁר לְאַרְבַּעְתָּן. וּבֵהּ אִיהִי פַּרְחָא נִשְׁרָא, וּמִתַּמָּן אִתְקְרִיאַת שְׁכִינְתָּא נִשְׁרָא. הָדָא הוּא דִּכְתִיב (משלי ל׳:י״ט) דֶּרֶךְ הַנֶּשֶׁר בַּשָּׁמַיִם. וּמִתַּמָּן לֵוִ\"י לְוִיָּה דִּימִינָא וּשְׂמָאלָא חִבּוּרָא דְּתַרְוַיְהוּ.</p>"],[9514015258,"<p>דִּבּוּר (יחזקאל א) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם וִיהוּדָה בָּהּ, אוֹדֶה אֶת ה'. וּמִתַּמָּן אִתְקְרִיאַת שְׁכִינְתָּא אַגָּדָה. בְּגִין וַיַּגֵּד יַעֲקֹב לְרָחֵל. וְאִנּוּן תְּרֵין חָכְמָה עִלָּאָה וְחָכְמָה תַּתָּאָה. וּבְגִינַיְהוּ אִתְּמַר (איוב יא) וַיַּגֵּד לְךָ תַּעֲלֻמּוֹת חָכְמָה. פִּיהָ פָּתְחָה בְּחָכְמָה. דְּמִתַּתָּא לְעֵלָּא אִיהִי אָדָם הַקָּטָן, מֵחָכְמָה עִלָּאָה אָדָם הַגָּדוֹל, וּמִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא ת\"ת אָדָם כָּלִיל בֵּהּ (נ\"א בין) תַּרְוַיְהוּ. פְּשׁוּטָה אִתְקְרִיאַת מִסִּטְרָא דִּימִינָא כִּי יְמִינְךָ פְּשׁוּטָה וּכְגוֹן תְּקִיעָה פְּשׁוּטָה לְפָנֶיהָ וּלְאַחֲרֶיהָ רַחֲמֵי, דְּלֵית תַּמָּן קוּשְׁיָא דְּדִינָא. דְּקוּשְׁיָא אִיהִי וַדַּאי קַשְׁיָא מִסִּטְרָא דְּדִינָא מִדַּת הַדִּין הַקָּשָׁה מִדָּה דְּדִינָא קַשְׁיָא. וְכַד חֲזֵי דְּאִתְקָשֵׁהּ מִינֵהּ הֲלָכָה, אִשְׁתַּדַּל בְּפִקּוּדִין דַּעֲשֵׂה, וְיִתְּעַר יְמִינָא בִּשְׂמָאלָא, רַחֲמֵי בְּדִינָא. דְּפִקּוּדִין דַּעֲשֵׂה הָא אוֹקְמוּהּ. וְזֶה זִכְרִי דְּאִיהוּ וָ\"ה עִם זִכְרִי רְמַ\"ח, מִסִּטְרָא דְּאַבְרָהָם אָבִינוּ עָלָיו הַשָּׁלוֹם דְּדַרְגֵּהּ חֶסֶד כְּמָה דְּאוֹקְמוּהּ אַהֲבַת עוֹלָם אֲהַבְתִּיךְ עַל כֵּן מְשַׁכְתִּיךְ חֶסֶד. דְּמָאן גָּרִים דְּאִתְקַשְּׁיָא מִינֵהּ הֲלָכָה דְּאַעֲבַר עַל חַד מִשְּׂסָ\"ה לֹא תַּעֲשֶׂה, דְּאִנּוּן מִשְּׂמָאלָא דְּאִתְּמַר בֵּהּ זֶה שְׁמִי עִם יָ\"הּ שְסָ\"ה. חֻמְרָא אִתְקְרֵי מִימִינֵהּ. קוֹלָא מִשְּׂמָאלָא וְהַאי אִיהוּ (שמות א) מִקַּל וָחֹמֶר. גְּזֵרָה שָׁוָה מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא. וְהַאי אִיהוּ וַיְמָרַרוּ אֶת חַיֵּיהֶם בַּעֲבֹדָה קָשָׁה בְּחֹמֶר וּבִלְבֵנִים, בְּקַל וָחֹמֶר וּבְכָל עֲבוֹדָה בַּשָּׂדֶה, בג\"ש. וְחֻמְרָא מִשְּׂמָאלָא דְּתַמָּן סְטָר סַמָּאֵ\"ל דְּאִיהוּ מָמוֹנָא עַל לֹא תַעֲשֶׂה וְאִיהוּ חֻמְרָא מִסִּטְרָא דְּאֵל אַחֵר. חָמוּר קוֹלָא מִימִינָא דְּאִתְּמַר בֵּהּ וּבִלְבֵנִים בְּלִבּוּן הַהֲלָכָה. וְאִית דְּיַמָּא הָכֵי חֻמְרָא מִימִינָא, דְּתַמָּן חֲמוֹר נוֹעֵר, דְּאִתְּמַר בֵּהּ (חבקוק ג) חֹמֶר מַיִם רַבִּים. קוֹלָא מִשְּׂמָאלָא דְּתַמָּן שׁוֹר מוּעָד דִּנְזִיקִין, דְּאִיהוּ אֲבִי אָבוֹת דִּנְזִיקִין, אִיהוּ אֵשׁ דְּגֵיהִנֹּם. אֲבָל חֲמוֹר אִיהוּ אֲבִי אֲבוֹת הַטֻמְאָה. וּבְגִין דָּא צָרִיךְ בֵּהּ חֹמֶר יַתִּיר, וְאִתְּמַר בְּהוֹן (דברים כב) לֹא תַּחֲרֹשׁ בְּשׁוֹר וּבַחֲמוֹר יַחְדָּיו. ג\"ש דָּא עַמּוּדָא דְּאֶמְצָעִיתָא, דְּאַפְלִיג בֵּינַיְהוּ מַחֲלֹקֶת לְאַפְרָשָׁא בֵּינַיְהוֹן, וְאִיהוּ שָׁוֶה בֵּין יְמִינָא וּשְׂמָאלָא דְּקֻדְשָׁא. וּבְגִין דָּא מַחֲלֹקֶת אִיהוּ עַמּוּדָא דְּאֶמְצָעִיתָא, בֵּין דַּרְגִּין דִּמְסָאֲבוּ, וְאִיהוּ פֵּרוּדָא בֵּינַיְהוּ. וְיִחוּדָא בְּדַרְגִּין קַדִּישִׁין.</p>"],[9514015259,"<p>בָּרַיְתָא אִיהִי שְׁכִינְתָּא מִשְּׂמָאלָא, הָדָא הוּא דִּכְתִיב כִּי בַּשָּׂדֶה מְצָאָהּ. וּמִשְׁנָה מִסִּטְרָא דִּימִינָא, דְּיִחוּדָא דִּילֵהּ לָאו אִיהוּ אֶלָּא מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא. וְאַמַּאי אִיהִי מִשְׁנָה וּבָרַיְתָא מִסִּטְרָא דִּימִינָא וּשְׂמָאלָא. בְּגִין חֲמוֹר וְשׁוֹר מוּעָדִים דְּאִנּוּן לִימִינָא וּשְׂמָאלָא.</p>"],[9514015260,"<p>תּוֹסֶפְתָּא אִתְקְרִיאַת מִסִּטְרָא דְּצַדִּיק, דְּאִיהוּ כָּלִיל כָּל מוּסָפִין, וּמִתַּמָּן אִיהִי שְׁכִינְתָּא קָרְבַּן הַמּוּסָפִין. וּבְגִינֵהּ אִתְּמַר (משלי יא) יֵשׁ מְפַזֵּר וְנוֹסָף עוֹד. בֵּהּ תּוֹסֶפְתָּא חָכְמָה וּבִינָה וָדַעַת וְכָל מִדּוֹת דְּקוּדְשָׁא בְּרִיךְ הוּא, וּמִנֵּהּ תּוֹסֶפֶת נְשָׁמָה יְתֵרָה, דְּאִתּוֹסָף בְּבַר נָשׁ מֵעֵרֶב שַׁבָּת לְעֵרֶב שַׁבָּת. וְאִיהוּ יוֹם הַשַּׁבָּת, שְׁבִיעִי כָּל סְפִירָן אִתְקְרִיאוּ בֵּהּ שְׁבִיעִיּוֹת. וְכָל מָאן דְּאוֹסִיף בֵּהּ בְּשַׁבָּת בְּמַאֲכָלִין בְּעִנּוּגִין, מוּסָפִין לֵהּ. וּמַאי מַאֲכָלוֹת דִּילֵהּ. קָרְבְּנִין דִּצְלוֹתָא דְּמוּסַף, דְּאִתּוֹסְפָן בֵּהּ עַמָּא קַדִּישָׁא יַתִּיר מִשְּׁאָר יוֹמִין דְּחֹל. תּוֹסֶפֶת קְדֻשָּׁה דְּקִדּוּשׁ עִנּוּג וְקָרָאתָ לַשַּׁבָּת עֹנֶג בִּתְלָת סְעֻדָּתָן. וּבְגִין דָּא כָּל הַמּוֹסִיף מוּסָפִין לֵהּ וְכָל הַגּוֹרֵעַ גּוֹרְעִין לוֹ. וְעוֹד שְׁכִינְתָּא אִתְקְרִיאַת תיק'ו, מִסִּטְרָא דְּהַהוּא דְּאִתְּמַר בֵּהּ בַּמֻּפְלָא מִמְּךָ אַל תִּדְרֹשׁ וּבַמְכֻסֶּה מִמְּךָ אַל תַּחֲקֹר. וּבְגִינֵהּ אוֹקְמוּהּ מִכָּל מָקוֹם שְׁתֹק כָּךְ עָלָה בְּמַחֲשָׁבָה.</p>"],[9514015261,"<p>קָם רָעֲיָא מְהֵימָנָא וְאָמַר, סָבָא סָבָא עֲלָךְ אִתְּמַר (ויקרא י״ט:ל״ב) מִפְּנֵי שֵׂיבָה תָּקוּם. תָּקוּם בְּיִשְׂרָאֵל עִלָּאָה עַד דְּלֵית סוֹף לִסְלִיקוּ דִּילָךְ. עִלָּאִין וְתַתָּאִין מִתְבָּרְכִין בָּךְ וּמִשְׁתַּבְּחִין בָּךְ, דְּאִתְכְּלִילוּ בָּךְ כָּל מִדּוֹת אֲחוֹרִיִּים וּפְנִימִיִּים דְּקוּדְשָׁא בְּרִיךְ הוּא. אָמַר הָא זְרִיקַת קִירְטָא. אַבְנִין דְּקִירְטָא לְגַבָּאֵי, אִמָּא לְאִנּוּן דְּאָזְלִין בָּאֲוִירָא, דְּהָא אַבְנָא לְגַבַּיְהוּ.</p>"],[9514015262,"<p>פָּתַח וְאָמַר זַרְקָא מֻקָּף שׁוֹפָר הוֹלֵךְ סְגוֹלְתָּא. מַלְאָכִין דְּאַתְוָן דְּעָלַיְכוּ אִתְּמַר (תהלים קד) עוֹשֶׂה מַלְאָכָיו רוּחוֹת מְשָׁרְתָיו אֵשׁ לוֹהֵט. קַבִּילוּ אַבְנִין אִלֵּין דְּאִנּוּן נִקּוּדִין דְּאִתְקְרִיאוּ עַל שִׁמְכֶם, דְּאִתְּמַר בְּהוֹן (דברים כז) אֲבָנִים שְׁלֵמוֹת תִּבְנֶה אֶת מִזְבַּח ה' אֱלֹהֶיךָ, אִלֵּין אִנּוּן.</p>"],[9514015263,"<p>קָמַץ. קדומיא\"ל מלכיא\"ל צוריא\"ל. פָּתַח פרא\"ל תומיא\"ל חסדיא\"ל. צֵרֵי צוריא\"ל רָזִיאֵ\"ל יופיאֵ\"ל. סֶגוֹל סטטורי\"ה גזריא\"ל לְמוּאֵ\"ל. שְׁבָ\"א שמעיא\"ל ברכיא\"ל אהניא\"ל. חֹלָ\"ם חניא\"ל להריא\"ל מהניא\"ל. חִרִ\"ק חזקיא\"ל רהטיא\"ל קדושיא\"ל. שֻׁרֻ\"ק שמועא\"ל רעמיא\"ל קניא\"ל. שֻׁרֻ\"ק שמשיא\"ל רפא\"ל קרשיא\"ל.</p>"],[9514015264,"<p>וְהַמַּשְׂכִילִים אִלֵּין דְּאִית בְּהוֹן שֵׂכֶל לְאִשְׁתְּמוֹדְעָא בִּצְלוֹתָא, אֵיךְ סַלְקָא לָהּ בְּרַתָּא בְּאַתְוָן וּנְקֻדֵּי וְטַעֲמֵי. דְּכֻלְּהוּ אִנּוּן רְחִימוּ דִּבְרַתָּא דְּמַלְכָּא בְּחָתָן דִילָהּ, לְאַעֲלָא רְחִימוּ וּשְׁלָמָא וְחִבּוּרָא וְקוּרְבָא בֵּינַיְהוּ, בְּכָל מִדּוֹת דְּתַרְוַיְהוּ לְאַכְלָלָא לוֹן כַּחֲדָא בְּכֻלְּהוּ. וְאִנּוּן קְרָבָא לְסַמָּאֵ\"ל וְנָחָשׁ וְשִׁבְעִין מְמָנָן.</p>"],[9514015265,"<p>קָם רִבִּי שִׁמְעוֹן בּוּצִינָא קַדִּישָׁא עַל רַגְלוֹי, וְסָלִיק יְדוֹי לְמָארֵי עָלְמָא וְאָמַר, רִבּוֹן עָלְמָא יְהֵא רַעֲוָא דִּילָךְ, לְמֵיהַב לָן תָּקְפָא לִי וּלְכָל חַבְרַיָּא וּלְכָל דְּעָאלִין בִּקְרָבָא דָּא, דְּאִנּוּן מִסִּטְרָא דִּילָךְ לְאַעֲלָא בִּקְרָבָא דָּא בְּלָא כִּסּוּפָא קַמָּךְ, וּלְאַפָּקָא מִתַּמָּן בְּלֹא כִּסּוּפָא קַמָּךְ וְקַמֵּי מַטְרוֹנִיתָא עִלָּאָה. דְּכַד נַצְּחִין בְּנָהָא קְרָבִין, אִתְּמַר בָּהּ (תהלים קיג) אֵם הַבָּנִים שְׂמֵחָה. וְלֹא אָהָא בְּכִסּוּפָא קַמֵּי בְּרַתָּא דְּמַלְכָּא דְּאִתְּמַר בָּהּ (שם מה) כָּל כְּבוֹדָהּ בַּת מֶלֶךְ פְּנִימָה וְגוֹ'. דְּהָא כַּמָּה כָּרוֹזִין נַפְקִין בְּגִינַהּ. הָדָא הוּא דִּכְתִיב (משלי ח) בְּרֹאשׁ הוֹמִיּוֹת תִּקְרָא בְּפִתְחֵי שְׁעָרִים בְּעִיר אֲמָרֶיהָ תֹּאמַר. וּמַאי אַמְרִין כָּרוֹזִין (שם) אֲלֵיכֶם אִישִׁים אֶקְרָא וְקוֹלִי אֶל בְּנֵי אָדָם. דְּהָא כַּמָּה פָּרְשִׁין תַּקִּיפִין הֲווֹ מִתְכַּנְּשִׁין לְאַגָּחָא קְרָבָא עִם חִוְיָא נָחָשׁ הַקַּדְמוֹנִי, דְּקָטִיל לְאָדָם קַדְמָאָה, וְקָטִיל לְכָל דָּרִין דְּאַתְיָן אֲכַתְרֵהּ. מִנְּהוֹן הֲוָה אָכִיל בְּנוּרָא דִּילֵהּ דְּאִיהוּ גֵּיהִנֹּם, וּמִנְּהוֹן הֲוָה בָּלַע לוֹן חַיִּין כְּגַוְנָא דְּקֹרַח, דְּאִתְּמַר בְּהוֹן (במדבר טז) וְיָרְדוּ הֵם וְכָל אֲשֶׁר לָהֶם חַיִּים שְׁאוֹלָה (במדבר ט\"ז, ל\"ג). מִנְּהוֹן קָטִיל בְּכַמָּה מִינֵי מִיתָה. דְּאִתְּמַר בְּהוֹן (תהלים סח) לַמָּוֶת תּוֹצָאוֹת. וְכַמָּה מָארֵי תְּרִיסִין הֲווֹ מִתְכַּנְּשִׁין לְגַבֵּהּ בְּבָתֵּי כְנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת וּפַסְקִין עָלֶיהָ כַּמָּה פְּסָקוֹת בְּקַלִּין וַחֲמוּרִין דִּילֵהּ (שמות ב) וַיִּפֶן כֹּ'ה וָכֹ'ה וַיַּרְא כִּי אֵין אִישׁ. לֵית בְּהוּ חַד דְּקָטִיל לְחִוְיָא וְכָרוֹזִין נַפְקִין מָאן דְּנָצַח קְרָבָא וְקָטִיל לְחִוְיָא יְהֵא הֲלָכָה דִּילֵהּ וְכַמָּה הֲלָכוֹת פְּסוּקוֹת אִנּוּן דְּאִתְּמַר בְּכָל חַד הֲלָכָה כִּפְלוֹנִי וְאִנּוּן (תהלים מא) בְּתוּלוֹת אַחֲרֶיהָ רְעוּתֶיהָ דִּבְרַתָּא דְּמַלְכָּא אֲבָל בְּרַתָּא דְּמַלְכָּא עֲלַהּ אִתְּמַר (משלי לא) רַבּוֹת בָּנוֹת עָשׂוּ חַיִל וְאַתְּ עָלִית עַל כֻּלָּנָה. וְאִיהִי אֲרוּסָה לְמֹשֶׁה הֲלָכָה לְמֹשֶׁה מִסִּינַי וְעַד לָאו אִיהִי נְשׂוּאָה לֵהּ עַד דְּיִקְטוֹל לְחִוְיָא וְיֵעוּל לְאַרְעָא קַדִּישָׁא. דִּבְגִין דָּא לָא עָאל לְאַרְעָא קַדִּישָׁא עַד דְּיִזְכֶּה לָהּ דְּמִדִּתְרֵין לוּחִין אִתְּבָּרוּ פָּרְחָא מִנֵּהּ וּבְגָלוּתָא רְבִיעָאָה יִזְכֶּה לָהּ וּבְגִינָהּ יִזְכֶּה לְאַעֲלָא לְאַרְעָא קַדִּישָׁא.</p>"],[9514015266,"<p>קוּם אַנְתְּ רָעֲיָא מְהֵימָנָא, דִּבְגִינָךְ אִתְּמַר (שמות ב) וַיִּפֶן כֹּה וָכֹה וַיַּךְ אֶת הַמִּצְרִי. דְּבִשְׁמָא דְּאִמָּא עִלָּאָה דְּאִיהִי ןִ' תַּרְעִין, מָחִית לֵהּ דְּאִתְרְמִיזוּ בְּכֹ\"ה. וָכֹ\"ה אַתְוָן דִּמְיַחֲדִין בְּהוֹן לְקוּדְשָׁא בְּרִיךְ הוּא תְּרֵין זִמְנִין בְּכָל יוֹמָא שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד, דְּאִית בְּשִׁית תֵּיבִין כ\"ה אַתְוָן, וּתְרֵין זִמְנִין אִנּוּן ןִ'. בְּאִלֵּין חַמְשִׁין מָחֵי לְפַרְעֹה וּבְכָל עֲבָדָיו חַמְשִׁין מַכּוֹת.</p>"],[9514015267,"<p>קוּם לְגַבֵּהּ בְּחוּטְרָא דִּילָךְ, לְמַחֲאָה לֵהּ כְּכַלְבָּא, דְּהָכֵי אוֹרְחָא דְּכַלְבָּא לְמַחֲאָה לֵהּ בְּחוּטְרָא. וְאוֹרְחָא דְּעַבְדָּא לְמַחֲאָה לֵהּ בְּחוּטְרָא כְּכַלְבָּא, בְּגִין דְּעָלֵהּ אִתְּמַר (משלי כט) בִּדְבָרִים לֹא יוּסַר עֶבֶד. בְּקַדְמִיתָא מָחִית לֵהּ עַל יַמָּא. כְּעָן קוּם מָחֵי לֵהּ בְּיַמָּא דְּאוֹרַיְתָא בְּקֻלְמוֹס דִּילָךְ בִּדְרוֹעָא דִּילָךְ בְּיָד דִּילָךְ. דְּאִתְּמַר בֵּהּ (שמות יד) וַיֵּט מֹשֶׁה אֶת יָדוֹ עַל הַיָּם (שמות) דְּהָא בִּימִינָהּ אִתְבַּקְּעָא יַמָּא. בִּשְׂמָאלָא אִתְחַזְרַת יַבָּשָׁה. הָדָא הוּא דִּכְתִיב וּבְנֵי יִשְׂרָאֵל הָלְכוּ בַּיַּבָּשָׁה בְּתוֹךְ הַיָּם (שם). בְּעַמּוּדָא דְּאֶמְצָעִיתָא נָשַׁפְתָּ בְּרוּחֲךָ כִּסָּמוֹ יָם. קוּם נָצַח קְרָבִין דְּהָא בְּרַתָּא דְּמַלְכָּא דִּילָךְ אִיהִי וְלֵךְ אִתְחַזְרַת. וְלֹא עוֹד אֶלָּא כַּמָּה דֻּבִּים וּזְאֵבִים דְּעִרְבּוּבְיָא מִתְכַּנְּשִׁין בְּגָלוּתָא לְמֵיכַל עָאנָא דִּילָךְ, דְּאִתְּמַר בְּהוֹן (יחזקאל לד) וָאַתֶּן צֹאנִי צֹאן מַרְעִיתִי. קוּם נָטִיל קִירְטָא דִּילָךְ לְגַבַּיְהוּ דְּהָא קִירְטָא דָּוִד אִתְּמַר בָּהּ (שמואל א, יז) וַיִּבְחַר לוֹ חֲמִשָּׁה חַלּוּקֵי אֲבָנִים מִן הַנַּחַל. נָטִיל לוֹן בַּחֲמִשָּׁה תֵּיבִין, דְּאִנּוּן שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה'. וְכַד שַׁוֵּי לוֹן בְּקִירְטָא, אִתְעֲבִידוּ אֶחָד, אַבְנָא חֲדָא, וְקָטִיל לִפְלִישְׁתָּאָה. וְהַאי אַבְנָא עֲלַהּ אִתְּמַר (דניאל ב) וְאַבְנָא דִּי מְחָת לְצַלְמָא הֲוַת לְטוּר רַב וּמָלְאָה כָּל אַרְעָא. הָדָא הוּא דִּכְתִיב (יחזקאל ג) מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ. וּבְגִינֵהּ אִתְּמַר (תהלים קיח) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה. מֵאֵת ה' הָיְתָה זֹאת. וּבְגִינָהּ אָמַר דָּוִד (שם כז) אִם תַּחֲנֶה עָלַי מַחֲנֶה לֹא יִירָא לִבִּי וְגוֹ' (שם). בָּזֹאת אֲנִי בּוֹטֵחַ וְאַל יִתְהַלֵּל הַמִּתְהַלֵּל כִּי אִם בָּזֹאת יִתְהַלֵּל הַמִּתְהַלֵּל. (איכה ג) זֹאת אָשִׁיב אֶל לִבִּי עַל כֵּן אוֹחִיל. וְיַעֲקֹב בְּגִין דַּהֲוָה יְדַע דְּאִיהִי עִקָּרָא דְּכֹלָּא, אוֹלִיף לֵהּ לִבְנוֹי. הָדָא הוּא דִּכְתִיב (בראשית מט) וְזֹאת אֲשֶׁר דִּבֵּר לָהֶם אֲבִיהֶם, וּמֹשֶׁה רַבֵּנוּ עָלָיו הַשָּׁלוֹם מִינֵהּ קַבִּיל אוֹרַיְתָא. הָדָא הוּא דִּכְתִיב (דברים מד) וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה. וְאַהֲרֹן בָּהּ עָאל לְקֹדֶשׁ קָדְשִׁין, וְאִתְקַבֵּל קָרְבָּנֵהּ. הָדָא הוּא דִּכְתִיב (ויקרא טז) בָּזֹאת יָבֹא אֶל הַקֹּדֶשׁ. זֹאת אֲשֶׁר לַלְּוִיִּם. וּבְגִינַהּ אִתְּמַר (זכריה ג) מִשָּׁם רוֹעֶה אֶבֶן יִשְׂרָאֵל. (באשית מט) עַל אֶבֶן אַחַת שִׁבְעָה עֵינַיִם.</p>"],[9514015268,"<p>זַכָּאָה אִיהוּ מָאן דְּשַׁוִּי לָהּ בְּקִירְטָא דִּילֵהּ, דְּאִיהִי פּוּמוֹי, בִּקְרִיאַת שְׁמַע, וְזָרִיק לָהּ לְגַבֵּי שָׁמַיִם דְּסַמָּאֵ\"ל. דִּבְגִינֵהּ אִתְּמַר (ירמיה ב) שׁוֹמוּ שָׁמַיִם עַל זֹאת. וּבָהּ כִּי שָׁמַיִם דִּילֵהּ בֶּעָשָׁן נִמְלָחוּ וְהָאָרֶץ כַּבֶּגֶד תִּבְלֶה. וְאַנְתְּ רָעֲיָא מְהֵימָנָא, קוּם טֹל קִירְטָא דִּילָךְ. דְּלַאֲתַר עִלָּאָה אַנְתְּ סָלִיק לֵהּ, יַתִּיר מִדָּוִד וּמִכָּל נְבִיאַיָּא וְחַכְמַיָּא דְּכָל דָּרָא וְדָרָא. וְהַאי אִיהִי קִירְטָא דִּילָךְ. זַרְקָא מֻקָּף שׁוֹפָר הוֹלֵךְ סְגוֹלְתָּא. דְּאַבְנָא דָּא מִפּוּמָךְ סַלְקָא לְאָתָא דְּאִתְּמַר בֵּהּ בַּמֻּפְלָא מִמְּךָ אַל תִּדְרֹשׁ וּבַמְכֻסֶּה מִמְּךָ אַל תַּחֲקֹר. וְאִיהִי שְׁמָא דְּכֶתֶר עִלָּאָה דְּאִיהוּ חָכְמָה קְדוּמָה. דְּהָכֵי סָלִיק חָכְמָה לְחֻשְׁבַּן שְׁמָא קַדִּישָׁא, עִם עֶשֶׂר אַתְוָן בִּכְלָלָא, דְּאִנּוּן יוּ'ד הֵ'י וָא'ו הֵ'י. דְּתַמָּן תְּלָת יוּדִי\"ן דְּאִנּוּן שְׁמָא דְּאַכְתַּר לִשְׁמָא דְּחָכְמָה זְעֵירָא. דָּא כָּלִיל עֶשֶׂר מֵעֵלָּא לְתַתָּא. וְחָכְמָה זְעֵירָא כָּלִיל עֶשֶׂר מִתַּתָּא לְעֵלָּא. עֶשֶׂר בִּגְבוּרָא מֵעֵלָּא סְגוֹלְתָּא, דְּמִתַּמָּן אִתְקְרִיאַת שְׁכִינְתָּא סְגֻלַּת מְלָכִים, וְאִיהִי שַׂנָּאָה (שצאה) לְאֻמִּין דְּעָלְמָא. אִיהִי אַבְנָא חֲדָא כְּלִילָא מֵעֶשֶׂר אַתְוָן מִתַּתָּא לְעֵלָּא דִּרְמִיזִין בְּיוּ'ד הֵ'א וָא'ו הֵ'א. תְּלָת אַלְפִין אִלֵּין דְּחָכְמָה זְעֵירָא דְּתַמָּן כ\"ח מ\"ה. דְּהַאי אִיהוּ שְׁמָא דְּסָלִיק מָ\"ה בְּחֻשְׁבָּן. וְתַלְיָן מִנֵּהּ כ\"ח אַתְוָן דְּאִנּוּן יוּ'ד וָא'ו דָּלֶ'ת, הֵ'א אָלֶ'ף, וָא'ו אָלֶ'ף וָא'ו הֵ'א אָלֶ'ף. וּתְלָת אַלְפִין דְּהַאי שְׁמָא, אִלֵּין דְּסַלְקִין אֶהְיֶה תְּלָת זִמְנִין, כְּחֻשְׁבָּן דְּרָמִיז קוּדְשָׁא בְּרִיךְ הוּא לֵךְ בִּשְׁלִיחוּתְךָ, לְאַפָּקָא לְיִשְׂרָאֵל מִמִּצְרַיִם. הָדָא הוּא דִּכְתִיב (שמות ג) וַיֹּאמֶר אֱלֹהִים אֶל מֹשֶׁה אֶהְיֶה אֲשֶׁר אֶהְיֶה כֹּה תֹּאמַר אֶל בְּנֵי יִשְׂרָאֵל אֶהְיֶה שַׁלְּחֵנִי אֲלֵיכֶם. וּבֵהּ אִשְׁתְּמוֹדַע דְּהוּא מֻפְלָא וּמְכֻסֶּה מִסִּטְרָא דְּעִלַּת כָּל עִלָּאִין, דְּאִתְּמַר בֵּהּ בְּג' יוֹדִין דִּסְגוֹלְתָּא אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן וּמִבִּלְעֲדַי אֵין אֱלֹהִים. וּמִסִּטְרָא דְּעִלַּת כָּל עִלָּאִין אִתְקְרִיאַת שְׁכִינְתָּא אֱמוּנָה דְּיִשְׂרָאֵל. וְהַאי אַבְנָא חֲדָא י' בְּחֻשְׁבָּנָא עֶשֶׂר, וְאִית לָהּ קוֹצָא לְעֵלָּא וְקוֹצָא לְתַתָּא. וְנִקּוּדָא בְּאֶמְצָעִיתָא וְכֹלָּא אֶחָד. וּמִתַּמָּן קָרָא לְמֹשֶׁה לְעַמּוּדָא דְּאֶמְצָעִיתָא בְּי\"ג מְכִילָן דְּרַחֲמֵי. דְּמָאן דְּקָרָא בְּאִלֵּין י\"ג מְכִילָן דְּרַחֲמֵי לְעִלַּת כָּל הָעִלּוֹת. לֹא יַחֲזֹר רֵיקָם בִּצְלוֹתֵהּ. וְכַד אִיהוּ רָכִיב עַל אַבְנָא חֲדָא לֵית מְמָנָא וְשֻׂלְטָן דְּבִשְׁמַיָּא וְאַרְעָא, דְּקַיְּמָא קַמֵּי הַאי אַבְנָא. דִּבְהַהוּא זִמְנָא אִתְּמַר בְּסַמָּאֵ\"ל (עובדיה א) אִם תַּגְבִּיהַּ כַּנֶּשֶׁר וְאִם בֵּין כּוֹכָבִים שִׂים קִנֶּךָ וְגוֹ'. וְהָכֵי י' תַּתָּאָה סְלִיקַת לְי\"ג מְכִילָן, וּרְמִיזָן בְּאָת א' י' לְעֵלָּא וי' לְתַתָּא, חָכְמָה בָּרֹאשׁ וְחָכְמָה בַּסּוֹף. ו' כְּרִיכָא דְּתַרְוַיְהוּ.</p>"],[9514015269,"<p>קוּם נָטִיל אַבְנָא וְכָרִיךְ לָהּ בְּהַהוּא חוּט דְּזַרְקָא דְּאִיהוּ אָרִיךְ אַנְפִּין בַּעְלָהּ וַדַּאי וָא\"ו אֲרִיכָא דְּאִם בַּר נָשׁ לָא בָּרִיךְ לָהּ ב\"ה י' בְּאַבְנִין בְּרֵישׁ טַבַּעְתָּא, דְּעָלֵהּ אִתְּמַר תְּהֵא מְקֻדֶּשֶׁת לִי בְּטַבַּעַת זֹאת. וּבִרְצוּעָה דְּאִיהִי קֶשֶׁר תְּפִלִּין תְּפִלָּה די'ד דְּאִיהִי כְּרִיכָא בְּאֶצְבְּעָא, לָא אִסְתַּלְּקַת. וְכַד אִיהִי כְּרִיכָא עַל רֵישָׁא דְּאָת ו' אִתְקְרִיאַת תָּגָא דס\"ת. וּבְגִינַהּ אִתְּמַר כָּל הַמִּשְׁתַּמֵּשׁ בְּתָגָא חֲלָף. אִיהִי אֶבֶן מְכֻלֶּלֶת וּמְעֻטֶרֶת עַל כָּל אַתְוָן. אִיהִי עֲטָרָה עַל כָּל רֵישָׁא דְּצַדִּיק, כְּמָה דְּאוֹקְמוּהּ מ\"מ, הָעוֹלָם הַבָּא אֵין בּוֹ לֹא אֲכִילָה וְלֹא שְׁתִיָּה אֶלָּא צַדִּיקִים יוֹשְׁבִים וְעַטְרוֹתֵיהֶם בְּרָאשֵׁיהֶם. וְאִיהִי כֶּתֶר תּוֹרָה וְכֶתֶר כְּהֻנָּה וְכֶתֶר מַלְכוּת בִּתְלָת אַנְפִּין דְּשִׁי\"ן. מִן מֹשֶׁה אִשְׁתְּמוֹדַע בִּשְׁמָךְ רָעֲיָא מְהֵימָנָא. בִּתְלָת אַתְוָן אִתְעַטְרַת לְמֶהֱוֵי כֶּתֶר עַל רֵישָׁא דְּכֻלְּהוּ דְּכֹהֲנִים וּלְוִיִּם וְיִשְׂרְאֵלִים אִתְעַטְרַת עַל כֻּלְּהוּ. וְכַד סְלִיקַת בְּמַחֲשָׁבָה אִיהִי אַבְנָא חֲדָא כְּלִילָא מֵעֶשֶׂר סְפִירָן דְּאִנּוּן יוּ\"ד הֵ\"א וָא\"ו הֵ\"א. מַחֲשָׁבָה וַדַּאי אִיהִי חָכְמָה מ\"ה חש\"ב וְתִשְׁכַּח לָהּ תַּמָּן. וּמִסִּטְרָא דְּכֶתֶר תָּגָא אִתְקְרִיאַת, וּבָהּ עָלוּ יִשְׂרָאֵל בְּמַחֲשָׁבָה. דְּמַחֲשָׁבָה אִתְעֲבִידַת לֵהּ מֶרְכָּבָה. וְכַד סְלִיקָא לְגַבֵּי עִלַּת כָּל עִלָּאִין, אִתְעֲבִידַת תָּגָא בְּלֹא שִׁתּוּפָא דְּאִתְכְּלַל לְמֶהֱוֵי מֶרְכָּבָה לְהַהוּא דְּלֵית לֵהּ חֻשְׁבָּן וְשִׁתּוּף. וְכַד אִית בְּיִשְׂרָאֵל מַשְׂכִּילִים וְזַרְקִין לֵהּ בְּדִבּוּרָא דִּצְלוֹתָן בְּקִירְטָא דִּילְהוֹן, וְסַלְקִין לָהּ בְּמַחֲשָׁבָה עַד, הַהוּא מֻפְלָא דְּאִיהוּ עַל הַכֶּתֶר, מִיָּד נַעֲנִים. הָדָא הוּא דִּכְתִיב (תהילים צ״א:ט״ו) כִּי יָדַע שמ'י שֵׁם י' תָּגָא דְּזַרְקָא, יִקְרָאֵנִי וְאֶעֱנֵהוּ עִמּוֹ אָנֹכִי וְגוֹ'. בְּהַהוּא חוּט דְּאִיהוּ כְּרִיכוּ דִּילָהּ, דְּבֵהּ צָרִיךְ לְאַרְכָה לָהּ עַד דְּסָלִיק לָהּ עַד עִלַּת כָּל עִלָּאִין, וְנָחִית בָּהּ לְקַבְּלָא צְלוֹתְהוֹן. זַכָּאָה אִיהוּ מָאן דְּסָלִיק תְּלָת צְלוֹתִין לְגַבֵּהּ בִּתְלָת נִקּוּדִין דִּסְגוֹלְתָּא. דְּמִנְּהוֹן אִתְמְשָׁכוּ תְּלָת טִפִּין דִּתְלָת מֹחִין עִלָּאִין. דְּכַד בַּר נָשׁ אִתְמְשַׁךְ זֶרַע מִנֵּהּ, אִלֵּין טִפִּין דְּאִתְמְשָׁכוּ מִנֵּהּ, אִנּוּן מִשּׁוּפְרֵי שׁוּפְרֵי דְּמֹחָא מֻבְחָר מִכֹּלָּא. הָכֵי כְּגַוְנָא דָּא, כַּד קוּדְשָׁא בְּרִיךְ הוּא אוֹרִית בְּבַר נָשׁ. תְּלָת קְטִירִין דְּאִנּוּן נִשְׁמְתָא וְרוּחָא וְנַפְשָׁא מִשּׁוּפְרֵי שׁוּפְרֵי דִּילֵהּ, יָהִיב לוֹן דְּאִנּוּן מִתְּלָתדִּסְגוֹלְתָּא דְּאִתְרְמִיזוּ בְּשֵׁם יוּ\"ד הֵ\"י וָא\"ו הֵ\"י. וּבְגִין דָּא אָמַר לוֹן, (דברים כ״ו:י״ח) וּבְךָ בָּחַר ה' לִהְיוֹת לוֹ לְעַם סְגֻלָּה.</p>"],[9514015270,"<p>בְּהַהוּא זִמְנָא דְּנַפְקוּ מִלֵּין אִלֵּין מִפּוּמוֹי דְּבוּצִינָא קַדִּישָׁא, נְחִיתַת שְׁכִינְתָּא וּנְשִׁיקַת לֵהּ וְכָל אִנּוּן מָארֵי מְתִיבָתָן בָּרִיכוּ לֵהּ, וְרָעֲיָא מְהֵימָנָא. בְּרִיךְ לֵהּ וְנָשִׁיק לֵהּ. בְּהַהוּא זִמְנָא סָבָא חֲדָא אִזְדְּמַן לְגַבֵּהּ. פָּתַח וְאָמַר נָשְׁקוּ בַּר דְּאִיהוּ סֹלֶת נְקִיָּה, טִפָּה קַדִּישָׁא דָּא דְּאוֹרַיְתָא דְּמֹשֶׁה דְּאִתְיְהִיב לָן עַל יְדֵהּ, דְּלָא הֲוָה בֵּהּ פְּסֹלֶת דְּמֹץ וְתֶבֶן. דְּמָאן דְּלֵית פְּסֹלֶת בְּנִשְׁמָתֵהּ, אִיהוּ בָּרָא דְּקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּהּ. דְּאִית בַּר מֵהַהוּא חִטָה דְּאִתְּמַר בָּהּ אִילָן דְּאָכַל אָדָם קַדְמָאָה חִטָה הֲוָה.</p>"],[9514015271,"<p>ח\"ט מֹץ וְתֶבֶן. דִּבְגִינֵהּ אָמַר דָּוִד (תהילים נ״א:ז׳) הֵן בְּעָוֹן חוֹלַלְתִּי וְגוֹ'. וּבְזִמְנָא דְּאָת ה' דְּאִיהִי חֲמִשָּׁה מִינֵי נַהֲמָא, אִיהִי בְּכִסּוּיָא דָּרַת בֵּין רַשִּׁיעַיָּא בְּגָלוּתָא, דְּאִתְּמַר עָלַיְהוּ (תהילים א׳:ד׳) לֹא כֵן הָרְשָׁעִים כִּי אִם כַּמֹּץ אֲשֶׁר תִּדְּפֶנּוּ רוּחַ (א'). י' דְּאִיהִי מַעֲשֶׂה דִּילֵהּ לֹא אִתְחַבְּרַת עִמֵּהּ. וּבְגִין דָּא מֹץ וְתֶבֶן פְּטוּרִים מִן הַמַּעֲשֵׂר. וּבְגִין דָּא נָשְׁקוּ בַּר. נָשְׁקוּ בַּר. דְּשִׂפְוָן עִלָּאִין דְּרָעֲיָא מְהֵימָנָא דְּאִנּוּן שַׁקְיוּ דִּילְהוֹן בִּתְרֵי סַמְכֵי קְשׁוֹט, דְּאִנּוּן לִמּוּדֵי ה'. וְצַדִּיק אִיהוּ לְשׁוֹן לִמּוּדִים, אִיהוּ לָשׁוֹן לְעֵלָּא, וְאוֹת בְּרִית לְתַתָּא. וְעוֹד נָשְׁקוּ בַּר בְּשִׂפְוָן עִלָּאָה שְׁכִינְתָּא עִלָּאָה, דְּהָכֵי סְלִיקַת שְׁכִינָה כְּחֻשְׁבַּן שָׂפָ\"ה. חוּט דְּאַסְחַר עָלֵהּ, אִיהוּ הַהוּא כְּרִיכוּ, חוּט דְּזַרְקָא דְּאַסְחַר שָׂפָה אִיהוּ חוּט שֶׁל חֶסֶד. וְאִיהוּ חוּט דְּדַהֲבָא. וְאִיהוּ קַו יָרֹק מִסִּטְרָא דִּתְיוּבְתָּא דְּאַסְחַר כָּל עָלְמָא. תְּלָת חוּטִין אִנּוּן לְעֵלָּא דְּסָחֲרִין לְבַת עֵינָא, דְּעָלַיְהוּ אִתְּמַר (שיר השירים ז׳:ה׳) עֵינַיִךְ בְּרֵכוֹת בְּחֶשְׁבּוֹן עַל שַׁעַר בַּת רַבִּים. מַאי בַּת רַבִּים, בַּת עַיִן אִלֵּין תְּלָת אֲבָהָן תְּלָת גְּוָנִין אִנּוּן דְּעֵינָא. עֵינָא דְּמַיָּא דְּלֵית לָהּ הֶפְסֵק עֵין הַמַּיִם. וּמִתַּמָּן נָשְׁקוּ בַּר לְאַנְהָרָא עָלְמִין בְּרָזִין סְתִימִין דְּאוֹרַיְתָא. בְּהַהוּא זִמְנָא קָם הַהוּא סָבָא וְנָטַל קִירְטָא בִּידוֹי. פָּתַח וְאָמַר, בּוּצִינָא קַדִּישָׁא עַד כְּעַן הֲוָה קִירְטָא בִּידָךְ. מִכָּאן וְאֵילָךְ הָא אִסְתַּלְּקַת בְּעִלָּאִין. נָטוּר גַּרְמָךְ מֵאַבְנִין דִּילָהּ. דְּהָא בְּפוּמָא דְּצַדִּיקִים אִיהִי מִסְתַּלְּקָא בִּצְלוֹתִין דִּילְהוֹן לְגַבֵּי בַּעְלָהּ וּבְעוֹבָדִין דִּילְהוֹן דְּהַאי אַבְנָא כַּד נַחְתַּת לְתַתָּאה אִיהִי אֶבֶן בֹּחַן, דְּעָלֵהּ אִתְּמַר (תהילים י״א:ה׳) ה' צַדִּיק יִבְחַן וּבָהּ נִתְנַסּוּ אֲבָהָן. וּבְגִין דָּא אִתְּמַר (תהילים קי״ח:כ״ב) אֶבֶן מָאֲסוּ הַבּוֹנִים דְּאִנּוּן אֲבָהָן.</p>"],[9514015272,"<p>וְכַד נַחְתַּת לְתַתָּא נַחְתַּת כְּגַוְנָא דָּא הוה'י וְכַד אִסְתַּלְּקַת, אִתְּמַר בָּהּ אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה, כְּגַוְנָא דָּא יהו'ה. בָּהּ נִתְנַסָּה אַבְרָהָם בָּעֲשָׂרָה נִסְיוֹנוֹת. וּבְזִמְנָא נִתְנַסָּא בָּהּ בַּר נָשׁ, אִיהוּ מָאִיךְ. וּלְבָתַר דְּקָאִים בְּנִסְיוֹנָא דִילֵהּ, אִיהִי אִסְתַּלְּקַת בֵּהּ לְגַבֵּי בַּעְלָהּ, דְּאִיהִי יהו'ה. בְּהַהוּא זִמְנָא אִסְתְּלַק בָּהּ בַּר נָשׁ עַל כָּל אִנּוּן דַּרְגִּין וממן דְּאִתְנַסֵּי בְּהוֹן בַּר נָשׁ. וְכַד חָזָא סַמָּאֵ\"ל דְּיַהֲבִין לֵהּ רְשׁוּ עַל צַדִּיק לְמֶהֱוֵי לֵהּ. נִסָּיוֹן, וְחָזָא דְּאִיהוּ קָאִים בְּקִיּוּמָא אִיהוּ אָמַר (אסתר ה׳:י״ג) וְכָל זֶ'ה אֵינֶנּ'וּ שׁוֶֹ'ה לִ'י. וְאִי תֵּימָא דְּעַל מָרְדְּכַי אָמַר לֵהּ הָמָן. וַדַּאי הָמָן דֻּגְמָא דְּסַמָּאֵ\"ל הֲוָה לֵהּ, דְּבֵהּ אִתְלַבַּשׁ וַעֲשָׂרָה כִּתְרִין תַּתָּאִין אִתְלַבְּשׁוּ בְּעֶשֶׂר בְּנוֹי וּבְגִין דְּקָאִים מָרְדְּכַי בְּנִסְיוֹנָא, יָהַב לוֹן קוּדְשָׁא בְּרִיךְ הוּא בִּידֵהּ. עאכ\"ו מָאן דְּאִתְנַסָּא בְּגִין שְׁכִינְתָּא בְּגָלוּתָא. בְּגִין דְּנָחְתִין עָלַהּ עֶשֶׂר סְגֻלּוֹת דִּשְׁמָא דְּכִתְרָא, דְּאִנּוּן יוּ\"ד הֵ\"י וָא\"ו הֵ\"י, דְּאִנּוּן סְפִירָן מַלְיָן סְגֻלּוֹת, דְּסָחֲרִין לְכִתְרָא עִלָּאָה דְּמַלְכָּא וּמַטְרוֹנִיתָא. וְהַאי אִיהוּ כֶּתֶר עִלָּאָה דְּאִתְּמַר בֵּהּ בְּיוֹם שַׁבָּת בִּקְדֻשָּׁה כֶּתֶר יִתְּנוּ לְךָ ה' אֱלֹהֵינוּ. מָאן ה' אֱלֹהֵינוּ, אַבָּא וְאִימָּא בֵּהּ מַכְתִּירִין לְעַמּוּדָא דְּאֶמְצָעִיתָא וּשְׁכִינְתָּא דְּאִיהִי קְדֻשָּׁה. וְאִתְּמַר בָּהּ קְדֻשָּׁה לְךָ יְשַׁלְּשׁוּ. וְאִנּוּן קק\"ק תְּלָת אֲבָהָן ה' צְבָאוֹת. מָאן צְבָאוֹת נֶצַח וָהוֹד. מְלֹא כֹּל, דָּא צַדִּיק, בֵּהּ מְלֹא כֹּל הָאָרֶץ כְּבוֹדוֹ דְּאִיהִי שְׁכִינְתָּא. וּמָאן דְּאִיהוּ מִתְּלָת אֲבָהָן לֹא צָרִיךְ לְאִתְנַסְּאָה. דְּמָאן דְּאִיהוּ מִגִּזְעוֹי וּמִשָּׁרְשׁוֹי, לֵית בֵּהּ סְפֵקָא דְּקָאִים בְּנִסְיוֹנָא. וְאִי תֵּימָא דְּאַבְרָהָם לֹא אִתְנַסָּא בִּשְׁמָא דְּכִתְרָא אֶלָּא בְּמִדַּת חֶסֶד, וְיִצְחָק בְּמִדַּת גְּבוּרָה, וְיַעֲקֹב בְּמִדַּת תִּפְאֶרֶת, וּשְׁכִינְתָּא מֵאִלֵּין תְּלָת סִטְרִין אִתְקְרִיאַת לוֹן אֶבֶן בֹּחַן. שַׁפִּי'ר אִיהוּ וּמָאן דְּיִתְנַסֶּה מִלּוּלָא בַּעֲשָׂרָה אָתְוָן דְּסָחֲרִין לְכִתְרָא. וְכֵיוָן דְּהָכֵי, הוּא יָכִיל לְאִתְנַסְּאָה. וּמָאן דְּיִתְנַסָּא תַּמָּן, לֵית סוֹף לְנִסְיוֹנָא דִּילֵהּ. הָדָא הוּא דִּכְתִיב (איכה ב׳:י״ג) מָה אֲעִידֵךְ מָה אֲדַמֶּה לָךְ. דְּלֵית יָכִיל לְאִתְדַּמְּאָה נִסְיוֹנָא דִּילָךְ לְמַ'ה דְּאִיהוּ יוּ\"ד הֵ\"א וָא\"ו בִּתְלָת אֲבָהָן. הֵ'א בְּמַלְכוּתָא, בָּתַר דְּנִסְיוֹנָא דִּילָךְ בָּאֵין סוֹף (שם) כִּי גָּדוֹל כַּ'יָּם שִׁבְרֵךְ מִ'י יִרְפָּא לָךְ. הַהוּא דְּאִיהוּ מֻפְלָא וּמְכֻסֶּה וּבֵהּ תִּסְתַּלַּק לְאֵ'ם, כְּמָא דִּתְבִירוּ דִּילָךְ לֵית לִי' סוֹף. וּכְעָן בּוּצִינָא קַדִּישָׁא, טֹל אַבְנָא לְגַבָּךְ דְּאַנְתְּ יָכִיל לְמִסְבַּל לֵהּ, וְאִית לָךְ חֵילָא. וְאִי תֵּימָא דְּאַנְתְּ בִּלְחוֹדָךְ אִיהוּ דְּאַזְרִיקַת לָךְ. לֹא. אֶלָּא אֲפִלּוּ לַאֲבָהָן וּלְכָל מַשִּׁרְיָן דְּנִשְׁמָתִין דִּמְקַנְּנִין עִמָּךָ בְּדִיּוֹקְנָא דִּילָךְ, כְּרָעֲיָא מְהֵימָנָא דְּאִית לֵהּ תְּרֵי פַּרְצוּפִין, חַד לְעֵלָּא וְחַד לְתַתָּא, לָקֳבֵל מֶרְכַּבְתָּא עִלָּאָה וּמֶרְכַּבְתָּא תַּתָּאָה. וּבְגִינַיְהוּ אִתְּמַר (בראשית א׳:כ״ז) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם אֱלֹהִים. בְּצַלְמוֹ בְּדִיּוֹקְנָא דִּלְעֵלָּא בְּצֶלֶם אֱלֹהִים דִּיּוֹקְנָא לְתַתָּא. וּבְגִין דָּא כָּפַל שְׁמֵהּ תְּרֵין זִמְנִין מֹשֶׁ\"ה מֹשֶׁ\"ה הָדָא הוּא דִּכְתִיב (שמות ב׳:ט״ו) וַיֹּאמֶר מֹשֶׁה מֹשֶׁה. וּכְמָה דְּכָלִיל פַּרְצוּפִין דִּבְרִיאָה הָכֵי כְּלִילָן בֵּהּ פַּרְצוּפִין דַּאֲצִילוּת. אָמַר לֵהּ בּוּצִינָא קַדִּישָׁא סָבָא סָבָא, יְדַעְנָא בָּךְ דְּאַנְתְּ הוּא מִסִּטְרָא דְּסָבָא עִלָּאָה דְּאִיהוּ יִשְׂרָאֵל דִּלְעֵלָּא. וְהַאי אַבְנָא דִּילָךְ אֲנָן מְקַבְּלִין לֵהּ בְּרַעֲוָא דְּלֵית סוֹף וְתַכְלִית לְנִסְיוֹנִין דִּילֵהּ. בְּגִין יְקָרָא דִּשְׁכִינְתָּא דְּאִתְּמַר בֵּהּ (בראשית מ) מִשָּׁם רוֹעֵה אֶבֶן יִשְׂרָאֵל. בְּגִין לְאַחֲזָרָא לָהּ סְגוֹלְתָּא לְשַׁרְיָא עֲלָךְ. וּבְגִין דְּיִשְׁרֵי עֲלֵהּ עִלַּת עַל כָּל עִלָּאִין.</p>"],[9514015273,"<p>אָמַר הַהוּא סָבָא בּוּצִינָא קַדִּישָׁא יוּ\"ד הֵ\"י וָא\"ו הֵ\"י אִיהוּ עֶשֶׂר אַתְוָן. וְחֻשְׁבָּנֵהּ ס\"ג. בֵּהּ נָטִיל נוּקְמָא מִן ג\"ס רוּחָא דְּאִתְּמַר בֵּהּ כִּי גָאֹה גָאָה. בְּגִין דְּמִנֵּהּ קָא אַתְיָן עִרְבּוּבְיָא בִּישָׁא. דְּאִתְּמַר בְּהוֹן (תהילים נ״ג:ד׳) הַכֹּל סָג יַחְדָּיו נֶאֱלָחוּ אֵין עוֹשֶׂה טוֹב אֵין גַּם אֶחָד. וְעֶשֶׂר אַתְוָן עִם ס\"ג הֵם ג\"ע וְהַאי אִיהוּ שְׁלַח נָא יָדְךָ. וג\"ע בְּכָל אֲשֶׁר לוֹ. וּבוּצִינָא קַדִּישָׁא בָּתַר דְּקַבָּלְתוּן הַאי אֶבֶן טוֹלוּ לָהּ לְגַבַּיְכוּ, דְּלָא תָּזוּז מִנְּכוֹן. עֲלָהּ אִתְּמַר (תהילים ס״ח:י״ד) אִם תִּשְׁכְּבוּן בֵּין שְׂפָתַיִם. זַכָּאָה אִיהוּ מָאן דְּשָׁכִיב אִימָּא עִלָּאָה בֵּין שִׂפְוָן דִּילֵהּ וּבְגִינָהּ אִתְּמַר (שם סח) אִם תִּשְׁכְּבוּן בֵּין שְׂפָתַיִם אַל תִּקְרִי אִם אֶלָּא אֵם. וּתְרֵין אִנּוּן אֵם עִלָּאָה אֵם תַּתָּאָה שְׁכִינְתָּא עִלָּאָה שְׁכִינְתָּא תַּתָּאָה. דְּעָלֵהּ אִתְּמַר (דברים כ״ב:ז׳) שְׁלַח תִּשְׁלָח תְּרֵין שְׁלוּחִין. לְקָבְלַיְהוּ אִתְּמַר (רות א׳:י״ט) וַתֵּלַכְנָה שְׁתֵּיהֶן. זַכָּאָה אִיהוּ מָאן דְּשָׁכִיב לוֹן בְּשִׂפְוָן דִּילֵהּ, בִּצְלוֹתָא בְּאוֹרַיְתָא בִּקְרִיאַת שְׁמַע, בִּצְלוֹתָא בְּהַשְׁכִּיבֵנוּ, דְּתַמָּן קוּדְשָׁא בְּרִיךְ הוּא דְּאִתְּמַר בֵּהּ הַשְׁכִּיבֵנוּ אָבִינוּ לְשָׁלוֹם וְגוֹ', וְעַל שְׁכִינְתָּא אִתְּמַר וּפְרֹשׂ עָלֵינוּ סֻכַּת שְׁלוֹמֶךָ, תְּרֵין שְׁלוֹמֵי חַד לָקֳבֵל שְׁכִינְתָּא עִלָּאָה, וְחַד לָקֳבֵל שְׁכִינְתָּא תַּתָּאָה. חַד אִיהוּ בַּעַל הַבַּיִת, וּבְגִינֵהּ אִתְּמַר הַשְׁכִּיבֵנוּ אָבִינוּ לְשָׁלוֹם וְדָא עַמּוּדָא דְּאֶמְצָעִיתָא. וְתִנְיָנָא אִיהוּ אֹרַח. עַל תַּרְוַיְהוּ אִתְּמַר בַּעַל הַבַּיִת בּוֹצֵעַ וְאוֹרֵחַ מְבָרֵךְ.</p>"],[9514015274,"<p>וּמִסִּטְרָא דְּאוֹרֵחַ אִתְקְרִיאַת שְׁכִינְתָּא מְלוֹן אוֹרְחִים. הָדָא הוּא דִּכְתִיב (ירמיהו ט׳:א׳) מִי יִתְּנֵנִי בַּמִּדְבָּר מְלוֹן אוֹרְחִים. וּבְגִינֵהּ אִתְּמַר וַיָּלֶן שָׁם. וְאַמַּאי כִּי בָא הַשֶּׁמֶשׁ, דְּאִתְכְּנַשׁ מִנֵּהּ הַהוּא דְּאִתְּמַר בֵּהּ (תהלים פד) כִּי שֶׁמֶשׁ וּמָגֵן ה' אֱלֹהִים. וְאִשְׁתְּאָרַת שְׁכִינְתָּא בַּחֲשׁוֹכָא בְּגָלוּתָא. וּמִסִּטְרָא דְּנֶצַח וָהוֹד אִתְקְרִיאַת נְבוּאָה. וּמִסִּטְרָא דִּתְלָת אֲבָהָן דְּאִתְקְרִיאוּ אֶל אֱלֹהִים ה', דְּאִנּוּן הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא, אתקריא' גְּדֻלָּה גְּבוּרָה תִּפְאֶרֶת וּבְאִלֵּין תְּלָת שְׁמָהָן אִיהִי סַהִידַת עַל הַוָּיָתֵהּ, וֵאלֹהוּתֵהּ, וִיכוֹלְתֵהּ עַל כָּל עָלְמִין. וּמִסִּטְרָא דְּאִמָּא עִלָּאָה אִתְקְרִיאַת אֵם תְּשׁוּבָה יהו'ה, דְּאַחֲזֵי עַל כִּנּוּי וַהֲוָיָה דְּמָארֵי עָלְמִין מָארֵי דְּכָל כִּנּוּיִין וְכָל הַוְיָן. דְּכָל כִּנּוּיִין וְכָל הַוְיָן אִנּוּן כִּנּוּיִין לֵהּ, וְאִיהוּ לָאו אִיהוּ כִּנּוּי. וְאִתְקְרִיאַת מָ\"ה מִסִּטְרָא דְּחָכְמָה דְּאִתְּמַר (דברים י׳:י״ב) מַה ה' אֱלֹהֶיךָ שֹׁאֵל מֵעִמָּךְ כִּי אִם לְיִרְאָה. דְּאִם לֵית חָכְמָה לֵית דְּחִילוּ. וְאִם לֵית דְּחִילוּ לֵית חָכְמָה. וּבְהַאי. מָ\"ה מֵעִיד עַל עִלַּת כָּל עִלָּאִין, כִּי לֹא יָדְעוּ מַ\"ה הוּא. וּמִסִּטְרָא דְּחָכְמָה אִנּוּן נִקּוּדִין. כְּגַוְנָא דָּא י' קוֹצָא דִּלְתַתָּא וְקוֹצָא דִּלְעֵלָּא, וְנִקּוּדָא דְּאֶמְצָעִיתָא אַחֲזֵי עַל כֶּתֶר עִלָּאָה, דְּבֵהּ תְּלָת קְטִירִין יְ\"יָ וְאִנּוּן רְמִיזִין בְּיוּ\"ד הֵ\"י וָא\"ו הֵ\"י. וְכָל אָת אַחֲזֵי ד' אַתְוָן, דְּאִנּוּן יְבָרֶכְךָ יהו'ה, יָאֶר יהו'ה יִשָּׂא יהו'ה י\"ב אַתְוָן דְּתַלְיָן מִן י'. יוּ\"ד וּבֵהּ אִנּוּן תְּלָת עֶשֶׂר מְכִילָן חַד. כְּגַוְנָא דָּא י' קוֹצָא לְעֵלָּא, חַד, וְקוֹצָא לְתַתָּא, תְּרֵין. וּנְקֻדָּה בְּאֶמְצָעִיתָא, הָא תְּלָת. וְאוֹת י' בְּחֻשְׁבָּנֵהּ עֶשֶׂר, הא י\"ג מְכִילָן דְּרַחֲמֵי, דְּאִתְּמַר בְּהוֹן בַּעֲשָׂרָה מַאֲמָרוֹת נִבְרָא הָעוֹלָם. וּמַה תַּלְמוּד לוֹמַר, וַהֲלֹא בְּמַאֲמָר אֶחָד יָכוֹל לְהִבָּרְאוֹת. וּמִסִּטְרָא דִּנְקֻדִּין אִתְקְרִיאַת שְׁכִינְתָּא תַּתָּאָה בַּת קוֹל, כְּמָא דְּאוֹקִימְנָא, כְּגַוְנָא דָּא א.</p>"],[9514015275,"<p>וּמִסִּטְרָא דְּטַעֲמֵי אִתְקְרִיאַת שְׁכִינְתָּא מַחֲשָׁבָה כְּגַוְנָא דָּא א. וְכֹלָּא אִתְרְמִיז בְּאָת אָלֶף. בָּהּ אִתְרְמִיזוּ טַעֲמֵי לְעֵלָּא נִקּוּדִין לְתַתָּא, אַתְוָן בְּאֶמְצָעִיתָא, וְכֹלָּא אִיהוּ עֶשֶׂר אֲמִירָן, עֲשֶׂרֶת הַדִּבְּרוֹת, וְשִׁית יוֹמֵי בְּרֵאשִׁית, וְאִנּוּן כ\"ו כְּחֻשְׁבַּן יהו'ה, דְּכָלִיל טַעֲמֵי וְנִקּוּדֵי וְאַתְוָן כְּגַוְנָא דָּא יְהוָֹ\"ה וְאִנּוּן טַעֲמֵי וְנִקּוּדֵי מַיִן עִלָּאֵי, כְּגַוְנָא דָּא א. מַיִן נוּקְבִין כְּגַוְנָא דָּא א. רָקִיעַ דְּאֶמְצָעִיתָא כָּלִיל כָּל אַתְוָן. בְּגִינֵהּ אִתְּמַר (בראשית א׳:ו׳) יְהִי רָקִיעַ בְּתוֹךְ הַמַּיִם וִיהִי מַבְדִּיל בֵּין מַיִם לְמַיִם. רָקִיעַ בְּהִפּוּךְ אַתְוָן עִקָּר. וְהַאי אִיהוּ עִקַּר הָאֱמוּנָה. וְעָלֵהּ אִתְּמַר (יחזקאל א׳:כ״ב) וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ, דְּאִיהוּ רְקִיעָא דִּבְכִתְרָא עִלָּאָה, דְּאִיהוּ מֶרְכָּבָה לְהַהוּא דְּאִתְקְרֵי עִקַּר הָאֱמוּנָה, עִלַּת עַל כָּל עִלָּאִין טָמִיר וְגָנִיז. וְעוֹד שְׁכִינְתָּא מִסִּטְרָא דִּנְקֻדֵּי אִיהִי בְּרַתָּא דְּקוּדְשָׁא בְּרִיךְ הוּא הֲדֹם רַגְלָיו, וּמִסִּטְרָא דְּטַעֲמֵי אִתְקְרִיאַת אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ. וּבְצֵרוּפִין וְהַוְיָן אִשְׁתְּמוֹדְעַת בְּרַתָּא דְּמַלְכָּא. כְּגַוְנָא דָּא הוה'י, מִסִּטְרָא דָּא אִיהִי הֲדֹם רַגְלָיו, וּמִסִּטְרָא דיהו'ה אִתְקְרִיאַת פַּרְצוּף וְאִתְקְרִיאַת אַנְפּוֹי. וּמִסִּטְרָא דִּתְרֵין נִקּוּדִין אִלֵּין דְּאִנּוּן פַּרְצוּף וְזָנָב אִתְקְרִיאַת א. בְּרֵישָׁא דִּנְקֻדָּא עִלָּאָה אִיהִי רֵישָׁא וּבִנְקֻדָּא תַּתָּאָה סֵיפָא. וְרָזָא דְּמִלָּה חָכְמָה בָּרֹאשׁ וְחָכְמָה בַּסּוֹף. בְּב' נִקּוּדִין אִלֵּין. אַחֲזֵי עַל עִלַּת הָעִלּוֹת דְּאִיהוּ רִאשׁוֹן וְאַחֲרוֹן. הָדָא הוּא דִּכְתִיב (ישעיהו מ״ד:ו׳) אֲנִי רִאשׁוֹן וַאֲנִי אַחֲרוֹן. וָא\"ו בְּאֶמְצָעִיתָא דִּתְרֵין יוֹדִין אַחֲזֵי עַל עִלַּת כָּל עִלָּאִין דְּלֵית אֱלָהָא בַּר מִנֵּהּ. הָדָא הוּא דִּכְתִיב (שם) וּמִבִּלְעֲדַי אֵין אֱלֹהִים. וּבְגִין דִּשְׁכִינְתָּא אִיהִי כְּלִילָא מֵעִלָּאִין וְתַתָּאִין, אִתְקְרִיאַת בִּשְּׁמָא דְּעִלָּאִין וְתַתָּאִין. הָדָא הוּא דִּכְתִיב (שם מ) לְכֻלָּם בְּשֵׁם יִקְרָא. לְכֻלְּהוּ עִלָּאִין וְתַתָּאִין בִּשְׁכִינְתָּא אִתְקְרִיאוּ, דְּאִתְקְרִיאַת שָׁם דִּבְגִינֵהּ אָמַר לְמֹשֶׁה רַבֵּנוּ עָלָיו הַשָּׁלוֹם (שמות ל״ג:י״ז) וְאֶדָּעֲךָ בְּשֵׁם. אִישׁ לֹא נֶעְדָּר מִכֻּלְּהוּ עִלָּאִין וְתַתָּאִין דְּלָא אִתְקְרִיאַת בְּהוֹן. בְּעִלָּאִין הָא אוֹקִימְנָא דְּאִתְקְרִיאַת בִּשְׁמָא דְּכָל סְפִירָה וּסְפִירָה, בַּהֲוַיָּתָה בִּנְקֻדָּתָהּ וּבִשְׁמָהָן דְּכֻלְּהוּ כִּנּוּיִים. וְאִתְקְרִיאַת בִּשְׁמָא דְּתַתָּאִין כִּסֵּא שָׂרָף מַלְאָךְ אוֹפַן. כִּסֵּא (תהילים ק״ג:י״ט) ה' בַּשָּׁמַיִם הֵכִין כִּסְאוֹ. מַאי שָׁמַיִם, דָּא עַמּוּדָא דְּאֶמְצָעִיתָא. וּבְגִין דָּא סָמִיךְ לֵהּ (שם) וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה.</p>"],[9514015276,"<p>מִסִּטְרָא דְּשָׁמַיִם אִתְקְרִיאַת שָׁמַיְמָה. הָדָא הוּא דִּכְתִיב (בראשית ט״ו:ה׳) הַבֵּט נָא הַשָּׁמַיְמָה. וּכְמָא דְּאִיהִי אִתְקְרִיאַת בִּשְׁמָא דְּעִלָּאִין וְתַתָּאִין, הָכֵי אִתְקְרֵי עַמּוּדָא דְּאֶמְצָעִיתָא בְּעִלָּאִין וְתַתָּאִין, דְּאִיהִי בְּכֹלָּא חַד כְּמִדָּתֵהּ וְאִיהִי שִׁעוּר קוֹמָתֵהּ. וְאִתְקְרִיאַת שָׂרָף. הָדָא הוּא דִּכְתִיב (ישעיה ז) וַיָּעָף אֵלַי אֶחָד מִן הַשְּׂרָפִים. כְּגַוְנֵי דְּמַלְאָךְ דְּאִתְקְרֵי שָׂרָף וְאִתְקְרִיאַת מַלְאָךְ. הָדָא הוּא דִּכְתִיב (בראשית מ״ח:ט״ז) הַמַּלְאָךְ הַגֹּאֵל אוֹתִי מִכָּל רָע. וַיִּסַּע מַלְאַךְ הָאֱלֹהִים. וּמַלְאַךְ פָּנָיו הוֹשִׁיעָם. וְאִתְקְרִיאַת מַלְאָךְ עַל שֵׁם מְטַטְרוֹן כַּד אִיהִי עֲבִידְתָּא בֵּהּ שְׁלִיחוּתָא דְּבַעְלָהּ. וְאִתְקְרִיאַת אוֹפַן עַל שֵׁם סנדלפו\"ן כַּד שֻׁלְטָנוּתָהּ בֵּהּ עַל תַּתָּאִין. וְאִתְקְרִיאַת מֶרְכָּבָה עַל שֵׁם ד' חֵיוָן דְּמֶרְכַּבְתָּא דִּלְתַתָּא. כַּד שֻׁלְטָנוּתָהּ עָלַיְהוּ כְּמָא דְּאוֹקִימְנָא (תהילים ק״ג:י״ט) וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה. אִתְקְרִיאַת דְּמוּת אָדָם, דְּמוּת אַרְיֵה, דְּמוּת שׁוֹר, דְּמוּת נֶשֶׁר בְּהוֹן וּבְאִלֵּין דִּמְיוֹנוֹת אתחזיא' לְתַתָּאִין דְּאִנּוּן עֲבָדָיו הַנְּבִיאִים. הָדָא הוּא דִּכְתִיב (הושע י״ב:י״א) וּבְיַד נְבִיאִים אֲדַמֶּה. וְאִית נְבִיאִים דְּאִנּוּן מִמֶּרְכָּבָה עִלָּאָה דְּאִתְקְרִיאוּ בָּנִים. כְּגַוְנָא דָּא מָאן דְּדָחִיל לְקוּדְשָׁא בְּרִיךְ הוּא שַׁרְיָא י' בְּלִבֵּהּ. וּמָאן דְּרָחִים לֵהּ שַׁרְיָא ה' בְּמֹחֵהּ. וְעַל אִלֵּין תְּרֵין אַתְוָן אִתְּמַר (דברים כ״ט:כ״ח) הַנִּסְתָּרוֹת לַה' אֱלֹהֵינוּ. דְּמָאן דְּדָחִיל לְקוּדְשָׁא בְּרִיךְ הוּא אוֹ רָחִים לֵהּ סָתִים אִיהוּ מִבְּנֵי נָשָׁא. וְהַנִּגְלוֹת אִנּוּן ו'ה. מָאן דְּאִתְעַסָּק בַּתּוֹרָה שַׁרְיָא ו' בְּפוּמֵהּ. וּמָאן דְּעָסִיק בְּמִצְוָה שַׁרְיָא ה' בִּרְמַ\"ח אֵבָרִים דִּילֵהּ. וּמִצְוָה כְּלִילָא מִדּ' אַתְוָן כְּגַוְנָא דְּצִיצִית דְּאִתְּמַר בֵּהּ (במדבר טז) וְעָשׂוּ לָהֶם צִיצִית, וְאוֹקְמוּהּ מ\"מ כָּל הַפּוֹחֵת לֹא יִפְחוֹת מִזּ', וְכָל הַמּוֹסִיף לֹא יוֹסִיף עַל י\"ג. וְאִנּוּן חַ\"י בֵּין קְשָׁרִים וְחֻלְיָן לַכֹּל, סִטְרָא סַלְקִין עָ\"ב. עָלַיְהוּ אִתְּמַר (ישעיהו ט״ז:ה׳) וְהוּכַן בַּחֶסֶד כִּסֵּא. חֶסֶ'ד בְּגִימַטְרִיָּא עָ\"ב. וּבוּצִינָא קַדִּישָׁא אָמַר כָּל מָאן דְּמַנַּח תְּפִלִּין וְצִיצִית, כְּאִלּוּ מְקַיִּם תַּרְיַ\"ג מִצְוֹת דְּאוֹרַיְתָא. וְלֹא עוֹד אֶלָּא בְּצִיצִית כָּאֵלוּ מְתַקֵּן כֻּרְסֵא לְקוּדְשָׁא בְּרִיךְ הוּא. בִּתְפִלִּין דְּאִנּוּן שֵׁם יהו'ה כְּאִלּוּ נָחִית יהו'ה עַל כֻּרְסֵא.</p>"],[9514015277,"<p>אִי הָכֵי אַמַּאי אִתְּמַר אֵין חָבוּשׁ מַתִּיר עַצְמוֹ מִבֵּית הָאֲסוּרִים. אֶלָּא וַדַּאי תְּרֵין רָזִין עִלָּאִין הָכָא. חַד דְּפֻרְקָנָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא וּשְׁכִינְתָּא וְאַבָּא וְאִימָּא דְּאִנּוּן יהו'ה, לֹא תַּלְיָא אֶלָּא בְּעִלַּת כָּל עִלָּאִין, דְּאִיהוּ מֻפְלָא וּמְכֻסֶּה בְּכִתְרָא עִלָּאָה. וְחַד דְמִסִּטְרָא דְּצַדִּיקִים גְּמוּרִים לָאו אִיהוּ חָבוּשׁ וְאָסוּר בְּגָלוּתָא, אֶלָּא אִיהוּ אָסוּר וְחָבוּשׁ עִמָּהֶם בִּרְחִימוּ, קָשִׁיר עִמְּהוֹן בַּחֲבִיבוּתָא. הָדָא הוּא דִּכְתִיב (בראשית מ״ד:ל׳) וְנַפְשׁוֹ קְשׁוּרָה בְּנַפְשׁוֹ. חָבוּשׁ עִמְּהוֹן בְּכֻרְסֵא דִּמְתַקְּנִין לֵהּ וּבְמֶרְכָּבָה דִּילֵהּ, בְּכַמָּה שִׁירִין וְתֻשְׁבְּחָן דְּקָא נַחְתִּין עָלַיְהוּ כַּמָּה מַשִּׁרְיָן דְּקוּדְשָׁא בְּרִיךְ הוּא. דְּאִתְּמַר בְּהוֹן (יחזקאל א׳:כ״ד) וָאֶשְׁמַע אֶת קוֹל כַּנְפֵיהֶם. וּבְיִשְׁתַּבַּח אַתְיָן שְׂרָפִים, נַחְתִּין לֵהּ בְּכַמָּה מַשִּׁרְיָן, דְּאִנּוּן שְׂרָפִים וְחַיּוֹת וְאוֹפַנִּים. וּבִצְלוֹתָא קוֹל דְּמָמָה דַּקָּה. כְּמַה דְּאוֹקְמוּהּ (מלכים א, יח) וְהִנֵּה ה' עוֹבֵר רוּחַ גְּדוֹלָה וְחָזָק מְפָרֵק הָרִים וְגוֹ'. דִּצְלוֹתָא בַּחֲשַׁאי אִיהִי קוֹל דְּמָמָה דַּקָּה. וּבְגִין דְּתַמָּן אָתָא מַלְכָּא, צָרִיךְ לְמֵיקָם בְּגִינֵהּ. וּבְגִין דָּא אִתְקְרִיאַת צְלוֹתָא עֲמִידָה. וּבְגִין דָּא חַי עָלְמִין כָּלִיל חַ\"י בִּרְכָּאן, בֵּהּ מִתְיַחֵד קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּהּ. יאהדונהי דְּסָלִיק בְּחֻשְׁבַּן אָמֵן. וּבֵהּ צָרִיךְ לְמִכְרַע עַד שֶׁיִּתְפַּקְּקוּ חַ\"י חֻלְיוֹת שֶׁבַּשִּׁדְרָה. וְהָכֵי אוֹקְמוּהּ מָארִי מַתְנִיתִין. וּבִתְלָת קַדְמָאִין צָרִיךְ לְתַקְּנָא שִׁבְחוֹי, לְאַעֲלָא לְתַרְעָא דְּמַלְכָּא בְּהֵיכָלֵהּ, דְּאִיהִי אדנ'י. דְּהָכֵי סָלִיק הֵיכָ\"ל כְּחֻשְׁבַּן אֲדֹנָ\"י. בָּתַר דְּעָאל תַּמָּן וְיִשְׁאַל שְׁאֵלָתוֹי בי\"ב בִּרְכָּאן דְּאִנּוּן ו'ו. לְבָתַר יַהֲבִין לֵהּ שְׁאֵלָתוֹי בִּתְלָת בַּתְרָאִין, דְּתַמָּן צַדִּיק בֵּין תְּרֵין שִׂפְוָן לְשׁוֹן לִמּוּדִים, וּבֵהּ שְׁכִינְתָּא אִיהִי קַבָּלָה. מִסִּטְרָא דְּאִלֵּין צַדִּיקַיָּא, אִיהוּ אָסוּר וְחָבוּשׁ דִּמְתַקְּנִין לֵהּ כֻּרְסֵא, עִם מֶרְכַּבְתָּא דִּילֵהּ וּמַשִּׁרְיָתָה מִסִּטְרָא דְּעֵץ הַחַיִּים. אֲבָל מִסִּטְרָא דְּעֵץ הַדַּעַת טוֹב וָרָע, דְּקָשִׁיר לוֹן בַּיֵּצֶר הַטוֹב, לְמֶהֱוֵי עֵזְר בַּהֲדַיְהוּ, וְקָשִׁיר לֵהּ לַיֵּצֶר הָרָע לְמֶהֱוֵי כַּחֲמוֹר לְמַשּׂאוֹי תְּחוֹתַיְהוּ, חֲמוֹר נוֹשֵׂא סְפָרִים. מִסִּטְרָא דְּבֵינוֹנִים אִיהוּ אָסוּר וְחָבוּשׁ בְּגָלוּתָא. דְּעָלַיְהוּ אִתְּמַר בְּיוֹמִין דְּחֹל הָיָה כְּשׁוֹר לַחֲרֹשׁ וְכַחֲמוֹר לְמַשּׂאוֹי. בְּרַשִּׁיעַיָּא אִתְּמַר (איכה א׳:י״ד) נְתָנַנִי ה' בְּיָדִי לֹא אוּכַל קוּם. דִּרְצוּעִין דִּתְפִלִּין אִנּוּן כַּחֲבָלִים לְקַרְנוֹי דְּסַמָּאֵ\"ל שׁוֹר מוּעָד דְּלָא יְשֵׁיצֵי לוֹן, וּתְפִלָּה דְּיָד קָשִׁיר לְרַגְלוֹי וּמָאן דְּלָא מָנַח תְּפִלִּין, עָלֵהּ אִתְּמַר מִשּׁוֹר מוּעָד הַרְחֵק מִמֶּנּוּ כִּמְלֹא עֵינָיו, דְּמִנֵּהּ תַּלְיָן אֲבוֹת נְזִיקִין צִיצִית מַשּׂאוֹי עַל חֲמוֹר נוֹאֵף. נָחָשׁ בְּגִינֵהּ אִתְּמַר אֲפִלּוּ נָחָשׁ כָּרוּךְ עַל עֲקֵבוֹ לֹא יַפְסִיק. וְד' בָּתֵּי תְּפִלִּין אִנּוּן כְּהֵיכָלָא לְד' אַתְוָן מָאן הֵיכָלָא דָּא אֲדֹנָ\"י דְּהָכֵי סָלִיק כְּחֻשְׁבַּ\"ן הֵיכָ\"ל. וְאִנּוּן ד' פַּרְשַׁיָּן ד' אַתְוָן דיהו\"ה כַּגְּוָנָא דְּאַנְפִּין דְּחֵיוָן. וּבָתִּים ד' לָקֳבֻלִ גַּדְפִּין דְּחֵיוָן, וְאִנּוּן כְּגַוְנָא דְּנִקּוּדִין וְאַתְוָן דְּאִנּוּן דְּכַר וְנוּקְבָא. תְּרֵין רְצוּעִין לָקֳבֵל כַּנְפֵי יוֹנָה רְצוּעָה דְּיָד לְאַקַּשְׁרָא לָהּ וְדָא שְׁכִינְתָּא דְּאִתְּמַר בָּהּ יוֹנָתִי. וּתְרֵין אִנּוּן יוֹנִים דְּכַר וְנוּקְבָא. מָאן דְּבָעֵי לְצַיְּדָא לֵהּ צֵדָה דְּתַרְוַיְהוּ, נָטִיל נוּקְבָא וְקָשִׁיר לָהּ עִמֵּהּ וּמִיָּד יְקָרֵי לְדִבּוּרָא וְיֵתֵי.</p>"],[9514015278,"<p>וְהָכֵי צְרִיכִין יִשְׂרָאֵל לְנַטְלָא יוֹנָה קַדִּישָׁא מִצְוָה שְׁכִינְתָּא, לְקַשְּׁרָה לָהּ בְּקִשּׁוּרָא דִּתְפִלִּין, וּמִיָּד יְקָרֵי לְבַעְלָהּ דְּאִיהוּ יִשְׂרָאֵל דִּלְעֵלָּא עַמּוּדָא דְּאֶמְצָעִיתָא. וּבְגִין דָּא תַּקִּינוּ לְמִקְרֵי שְׁמַע יִשְׂרָאֵל בְּקָלָא עִם מִצְוַת תְּפִלִּין. וּמִיָּד דְּנָחִית לְגַבָּהּ, צָרִיךְ לְקַשְּׁרָא לֵהּ עִמֵּהּ לְמֶהֱוֵי חָבוּשׁ עִמֵּהּ בִּרְצוּעָה דִּתְפִלִּין דְּיָד, כְּמָא דְּאוֹקְמוּהּ מ\"מ. (יחזקאל כ״ד:י״ז) פְּאֵרְךָ חָבוּשׁ עָלֶיךָ, אֵלּוּ תְּפִלִּין כְּמָא דְּאוֹקְמוּהּ לְעֵיל. וּמִיָּד דְּקָשִׁיר לוֹן צָרִיךְ לְיַחֲדָא לוֹן בְּיִחוּדָא דְּאֶחָד א\"ח עִם ד', דְּאִיהִי כְּלִילָא מֵאַרְבַּע פַּרְשִׁיַּן דִּתְפִלִּין, וְאִיהִי רְבִיעִית לְד' אַתְוָן דְּקוּדְשָׁא בְּרִיךְ הוּא. ה' רְבִיעָאָה שְׁלִימוּ דְּשֵׁם יהו'ה, וְאִיהִי קוֹצָא דְּאָת דָּלֶ\"ת עֲשִׂירִית לא\"ח, דְּאִיהוּ תֵּשַׁע בְּחֻשְׁבָּן, וּבָהּ אִשְׁתְּלִים לַעֲשָׂרָה. כְּגַוְנָא דָּא יוּ\"ד הֵ\"א וָא\"ו הֵ\"א, וְהָא אוֹקְמוּהּ. וּבְגִין דָּא תַּקִּינוּ לְמִקְרֵי קְרִיאַת שְׁמַע בִּתְפִלִּין. וְאוֹקְמוּהּ מ\"מ, דְּמָאן דְּקָארֵי קְרִיאַת שְׁמַע בְּלֹא תְּפִלִּין, כְּאִלּוּ סָהִיר סַהֲרוּתָא דְּשִׁקְרָא. וְקִשּׁוּרָא דְּקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתָּא צַדִּיק אוֹת דִּתְפִלִּין. וּבְהַהוּא זִמְנָא דְּקָשִׁיר לוֹן בֵּהּ לְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּהּ, מָאן דְּשָׂח בֵּינְתַיִם עֲבֵרָה הִיא בְּיָדוֹ. וּתְפִלִּין דְּרֵישָׁא אִיהוּ תְּפִלִּין אִימָּא דְּקַשְּׁרַת לֵהּ לְקוּדְשָׁא בְּרִיךְ הוּא. עֲלָהּ אִתְּמַר וּבִזְרוֹעַ עֻזּוֹ. כְּמָא דְּאוֹקְמוּהוּ מ\"מ (ישעיהו ס״ב:ח׳) נִשְׁבַּע ה' בִּימִינוֹ זוֹ תּוֹרָה, וּבִזְרוֹעַ עֻזּוֹ אֵלּוּ תְּפִלִּין שֶׁבָּרֹאשׁ. גְּבוּרָה אִיהוּ זְרוֹע דִּילֵהּ וְאִיהִי עֻזּוֹ, וְהָא אוֹקְמוּהּ. וּשְׁכִינַת עֻזּוֹ בְּגַבְהֵי מְרוֹמִים, הוּא אֱלֹהֵינוּ מִסִּטְרָא דִּילֵהּ תְּפִלָּה דְּיָד אֵינָהּ מְעַכֶּבֶת שֶׁל רֹאשׁ וְכוּ'. דְּכָל חַד אִיהִי מִצְוָה בִּפְנֵי עַצְמָהּ. מִסִּטְרָא דְּאִמָּא אִנּוּן הֲוָיוֹת בְּאֶמְצַע כְּמָא דְּאוֹקְמוּהּ. וְהָא אִתְּמַר. וּבְגִין דְּלָא בְּקִיאִין אִלֵּין דְּדָרָא בַּתְרָאָה, שַׁוְיָן תְּרֵין זוּגִין דִּתְפִלִּין, דְּלָא יַדְעִין בְּרָזָא דָּא. וְעוֹד מָאן דְּשַׁוֵּי תְּפִלִּין כַּדְקָא חֲזֵי, הַאי אִיהוּ מְקַיִּם מִצְוָה בְּמַאֲמָרָהּ. וּכְגַוְנָא דְּצַדִּיק אִיהוּ אוֹת דְּאָחִיד בֵּין קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּהּ, הָכֵי אִיהוּ אָחִיד בְּתַרְוַיְהוּ בְּחַ\"י בִּרְכָּאן דִּצְלוֹתָא. וְאִתְּמַר בִּתְפִלִּין שָׂח בֵּינְתַיִם עֲבֵרָה הִיא בְּיָדוֹ. וְאִתְּמַר בִּצְלוֹתָא וַאֲפִלּוּ נָחָשׁ עַל עֲקֵבוֹ לֹא יַפְסִיק. זַכָּאָה פּוּמָא דְּבִצְלוֹתָא עָבִיד בֵּהּ מִשְׁכָּב לִשְׁכִינְתָּא וְהָא אִיהוּ. (תהילים ס״ח:י״ד) אִם תִּשְׁכְּבוּן בֵּין שְׁפַתָּיִם דִּבְהוֹן אֲדֹנָי שְׂפָתַי תִּפְתָּח לְמִשְׁכְּבָא בְּהוֹן אִימָּא עִלָּאָה דְּאִתְּמַר בֵּהּ (דברים כ״ב:ו׳) וְהָאֵם רוֹבֶצֶת עַל הָאֶפְרוֹחִים. דִּבְזִמְנָא דְּאִיהִי פְּרִישַׁת גַּדְפָּהָא עַל גּוֹזָלַיָּא, דְּאִנּוּן יִשְׂרָאֵל, בְּשַׁבָּתוֹת וְיוֹמִין טָבִין כְּמָא דְּאוֹקְמוּהּ הַפּוֹרֵשׂ סֻכַּת שָׁלוֹם עָלֵינוּ, אִשְׁתְּכָחוּ בְּחֵירוּ מִכָּל אֻמִּין דְּעָלְמָא. וּבְגִין דָּא בְּשַׁבָּתוֹת וְיוֹמִין טָבִין דְּאִיהִי רוֹבֶצֶת עַל יִשְׂרָאֵל, לֵית לוֹן דְּחִילוּ מִכָּל מְקַטְרְגִין דְּעָלְמָא. וְכַד יֵיתֵי יוֹמִין דְּחֹל אִתְּמַר בּוֹ (שם) שַׁלַּח תְּשַׁלַּח אֶת הָאֵם.</p>"],[9514015279,"<p>וּמַאי אִית בֵּין שְׁכִינְתָּא עִלָּאָה לְתַתָּאה דְּכֹלָּא חַד. אֶלָּא שְׁכִינְתָּא תַּתָּאָה אִיהִי כְּיוֹנָה, וְאִתְּמַר בָּהּ (תהילים ס״ח:י״ד) כַּנְפֵי יוֹנָה נֶחְפָּה בַּכֶּסֶף, צָרִיךְ לְכַסָּאָה לָהּ, דְּאִיהִי יִרְאָה וּדְחִילוּ אִשְׁתְּכַח מִסִּטְרָאָה. בְּגִין דְּאִנְטִילַת מִסִּטְרָא דִּגְבוּרָה, דְּתַמָּן סַמָּאֵ\"ל לְמִתְבַּע דִּינִין. וּבְגִין דָּא צָרִיךְ לְכַסָּאָה לָהּ מִכַּמָּה מָארֵי דְּדִינִין, דְּלָא אִשְׁתְּמוֹדְעִין בֵּהּ. וּבְמַאי בְּכֶסֶף דְּאִיהוּ יְמִינָא. דִּבְגִינֵהּ אִתְּמַר כָּל הָעוֹסֵק בַּתּוֹרָה בַּלַּיְלָה הַקּוּדְשָׁא בְּרִיךְ הוּא מוֹשֵׁךְ עָלָיו שֶׁל חוּט חֶסֶד בַּיּוֹם. וּבְגִין דָּא נֶחְפָּה בַּכֶּסֶף לְרַשְּׁמָא לָהּ מִסִּטְרָא דְּרַחֲמֵי, דְּלָא יִשְׁתְּמוֹדָעִין בָּהּ מָארֵי דְּדִינָא. אֲבָל אִימָּא עִלָּאָה אַיֵּה כְּנִשְׁרָא דְּלָא דְּחִילַת מִכָּל עוֹפִין דִּלְעֵלָּא. וְגַדְפִּין דִּילֵהּ אִנּוּן מִסּוֹף עָלְמָא וְעַד סוֹף עָלְמָא. וּבְגִינַהּ אִתְּמַר (דברים ל״ב:י״א) כַּנֶּשֶׁר יָעִיר קִנּוֹ, וְדָא יְרוּשָׁלַםִ. וְעָלֵהּ אִתְּמַר (שם כב) כִּי יִקָּרֵא קַן צִפּוֹר. דְּקֵן דִּילָהּ אִיהִי יְרוּשָׁלַםִ דִּלְעֵלָּא. וְקֵן דְּצִפּוֹר יְרוּשָׁלַםִ דִּלְתַתָּא. זַכָּאָה פּוּמָא דְּאִיהוּ קֵן דִּילֵהּ. זַכָּאָה אוֹרַיְתָא וּצְלוֹתָא דְּאִיהִי קֵן לָהּ. זַכָּאָה נִשְׁמָתָא דְּאִיהִי קֵן דִּילֵהּ. דְּכַד אִיהִי מְקַנְּנָא תַּמָּן לֹא דְּחִילַת מִכָּל מְקַטְרְגִין דְּעָלְמָא. וּבְגִין דָּא אִתְקְרִיאַת נִשְׁמַת כָּל חַי, אִיהִי מְקַנֶּנֶת בִּצְלוֹתָא דְּשַׁבָּת וְצַדִּיק. מִסִּטְרָא דִּילֵהּ אִתְקְרֵי יוֹם הַשְּׁבִיעִי כַּד חָשְׁבִין יוֹמִין מֵאִימָּא עִלָּאָה. וְאִיהִי יוֹמָא קַדְמָאָה דְּפֶסַח. וְיוֹמָא קַדְמָאָה דְּסֻכּוֹת. וּשְׁכִינְתָּא תַּתָּאָה חַג שְׁמִינִי עֲצֶרֶת וְאִיהִי יוֹם מַתַּן תּוֹרָה וְאִיהִי יוֹם הַכִּפּוּרִים. כָּל צְלוֹתִין דְּכָל שַׁבָּתוֹת וְיוֹמִין טָבִין צְרִיכִין לְמֶעֱבַד לֵהּ. וְהַאי אִיהוּ דְּאָמַר קְרָא (ויקרא כ״ג:ד׳) אֵלֶּה מוֹעֲדֵי ה' מִקְרָאֵי קֹדֶשׁ אֲשֶׁר תִּקְרְאוּ אוֹתָם בְּמוֹעֲדָם. מַאי מוֹעֲדָם. אִימָּא עִלָּאָה. וְצָרִיךְ לְאַכְלְלָא בָּהּ עֶשֶׂר סְפִירוֹת.</p>"],[9514015280,"<p>וְכַד אִיהִי סְלִיקַת, אִיהִי סְלִיקַת עַל עַמּוּדָא דְּאֶמְצָעִיתָא. וּבְגִין דָּא אָמַר שְׁלֹמֹה (משלי ל׳:י״ט) דֶּרֶךְ הַנֶּשֶׁר בַּשָּׁמַיִם. עֲבִידַת אוֹרְחָא תַּמָּן וְלֹא אִשְׁתְּמוֹדְעַת בֵּהּ אֶלָּא לְבַעְלָהּ. וַיֵּדַע אָדָם עוֹד אֶת אִשְׁתּוֹ אֶלָּא דְּסָלִיק לֵהּ עִטְרָא עַל רֵישֵׁהּ תְּפִלִּין עַל הָרֹאשׁ. וְכַד סְלִיקַת כַּמָּה חַיָּלִין סְלִיקִין עִמֵּהּ. וְכַד נְחִיתַת כַּמָּה חַיָּלִין נַחְתִּין עִמָּהּ, וְאִתְקְרִיאוּ נְשָׁמוֹת יְתֵרוֹת דְּיַרְתִין עַמָּא קַדִּישָׁא. וּבְהוֹן אִית לוֹן נַיְיחָא לְיִשְׂרָאֵל בְּשַׁבָּתוֹת וְיוֹמִין טָבִין. וְיוֹנָה קַדִּישָׁא בְּכָל שִׁית יוֹמִין דְּחֹל. אַזְלָא מְנַדְּדָא מִדּוֹךְ לְדוֹךְ. וְאִם אַשְׁכְּחַת צַדִּיק בְּעָלְמָא אִתְדַּבְּקַת בֵהּ. אִם לָאו אִתְחַזְרַת לְקִנָּהָא וְאִתְטַמְּרָה תַּמָּן, בְּהַהוּא אֲתַר דְּאִתְקְרֵי קַן צִפּוֹר. וּמַאי נִיהוּ קֵן דִּילֵהּ מְטַטְרוֹ\"ן דִּי שְׁמֵהּ שַׁדָּ\"י, דְּאִיהוּ נָטִיר תַּרְעָא דְּאִתְּמַר בֵּהּ (תהילים קי״ח:כ׳) זֶה הַשַּׁעַר לַה'. וּבְגִין דָּא בִּמְזוּזָה שַׁדָּי מִלְּבַר יהו'ה מִלְּגָאו. דשס\"ד מַלְאֲכֵי חַבָּלָה אִנּוּן כְּחֻשְׁבַּן יוֹמֵי שִׁתָּא שְסָ\"ה חָסֵר חַד. דָּא אִיהוּ יוֹם הַכִּפּוּרִים דְּלֵית לַשָּׂטָן שׁוֹלְטָן עָלֵהּ הַשָּׂטָן הָכֵי סָלִיק שס\"ד. בַּאֲתַר דִּמְזוּזָה תַּמָּן, לֹא אִית לֵהּ רְשׁוּ לְקָרְבָא. וּבְגִין דָּא (דברים י״א:כ׳) וּכְתַבְתָּם עַל מְזוּזוֹת בֵּיתֶךָ מְזוּזֹת זָז מָוֶת. וּבְגִין דָּא כַּד לָא אִשְׁתְּכַחַת אֲתַר, אִתְחַזְרַת לְקִנָּהָא דְּאִיהוּ מְטַטְרוֹ\"ן, דְּחֻשְׁבָּנֵהּ שַׁדָּ\"י, דְּתַמָּן יהו'ה מָארֵי דְּיוֹנָה קַדִּישָׁא. וּבְשַׁבָּת דְּתַמָּן צַדִּיק, וַתָּבֹא אֵלָיו הַיּוֹנָה לְעֵת עֶרֶב. בְּגִין דְּאִיהוּ יִחוּדָא דְּקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּהּ. וְכַד אִית צַדִּיק לְתַתָּא, אִיהוּ בַּאֲתַר דְּיוֹם הַשַּׁבָּת, דְּאִיהוּ שַׁדָּי דִּלְעֵלָּא, וּבֵהּ אִתְיַחֲדַת קוּדְשָׁא בְּרִיךְ הוּא. וְתַמָּן אַשְׁכַּחַת נַיְיחָא, וְלָא אַזְלַת מְטַלְטְלָא מִדּוֹךְ לְדוֹךְ וּמֵאֲתַר לַאֲתַר. וּמָאן אִיהוּ צַדִּיק דְּאִיהִי אִתְדַּבְּקַת בֵּהּ הַהוּא דְּאִיהוּ כְּלִיל מִכָּל מִדּוֹת דְּקוּדְשָׁא בְּרִיךְ הוּא. דְּאִתְּמַר בֵּהּ וַיְכֻלּוּ כָּלִיל כֹּלָּא. דְּכָל סְפִירָן בֵּהּ אִתְכְּלִילוּ דְּאִיהוּ חָסִיד וְגָמִיל חֶסֶד עִם שְׁכִינְתָּא, וְיָהִיב לָהּ תֻּקְפָא בִּגְבוּרָה. וְהָכֵי בְּכָל סְפִירָה וּסְפִירָה יָהִיב לָהּ תֻּקְפָא. אִיהִי אִתְדַּבְּקַת וְלֹא תָּזוּז מִנֵּהּ בְּכָל שִׁית יוֹמֵי שַׁבְּתָא. וּבְגִינֵהּ אִתְּמַר עַל צַדִּיק א' הָעוֹלָם עוֹמֵד. אִיהוּ עַמּוּד סָבִיל כֹּלָּא. וּבֵהּ כַּנְפֵי יוֹנָה נֶחְפָּה בַּכֶּסֶף. אַיֵּה מְכַסִּיאַת עָלֵהּ בְּגַדְפָּהָא, וְאַגִּינַת עָלֵהּ מִכָּל מְקַטְרְגִין דְּעָלְמָא. וּבְגִינֵהּ אִתְּמַר (תהלים כה) לֹא יִתֵּן לְעוֹלָם מוֹט לַצַּדִּיק. לֹא יְאֻנֶּה לַצַּדִּיק כָּל אָוֶן. לֹא רָאִיתִי צַדִּיק נֶעֱזָב וְזַרְעוֹ מְבַקֵּשׁ לָחֶם. וּבֵהּ אִתְחֲזֵי קֶשֶׁת דְּפֻרְקָנָא בְּגַוְנוֹי נְהִירִין. וּמִיָּד (בראשית ט׳:ט״ז) וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם. וְלֹא תֵצֵא כְּצֵאת הָעֲבָדִים מִסִּטְרָא דְּקֶשֶׁת דְּאִיהוּ עֶבֶד. וְעוֹד זַרְקָא. הָא אֵלִיָּהוּ נָחִית וְכַמָּה מַשִּׁרְיָן עִמֵּהּ דְּמַלְאָכִין וְנִשְׁמָתִין.</p>"],[9514015281,"<p>פָּתַח וְאָמַר בּוּצִינָא קַדִּישָׁא הָא כַּמָּה מַשִּׁרְיָן דְּמַלְאֲכֵי חַבָּלָה קָא מַחְתִּין עַל עָאנָא. אִימָּא לְרָעֲיָא דְּזָרִיק אַבְנָא מִקִּירְטָא קַדִּישָׁא לְגַבַּיְהוּ. (חסר כאן) אִתְרְמִיז בְּכֶתֶר עִלָּאָה כְּגַוְנָא דָּא יוּ'ד הֵ'י וָא'ו הֵ'י דְּסָלִיק אֶהְיֶה תְּלָת זִמְנִין. וְאִיהוּ אֲשֶׁ\"ר רֹא\"שׁ דְּאֶהְיֶ\"ה אֶהְיֶ\"ה כְּלָלָא דְּמ\"ב. וְאִיהוּ כָּלִיל עֶשֶׂר אֲמִירָן. כְּגַוְנָא דָּא אָלֶ\"ף הֵ\"א יוּ\"ד הֵ\"א. וְכַמָּה אִנּוּן סְפִירָן פְּנִימָאִין וְכַמָּה סְפִירָן אֲחוֹרִיִּים, וְאִנּוּן דָּא עַל גַּב דָּא. הָדָא הוּא דִּכְתִיב כִּי גָּבֹהַּ מֵעַל גָּבֹהַּ שׁוֹמֵר וּגְבוֹהִים עֲלֵיהֶם. וּבְגִינַיְהוּ אִתְּמַר וְכַמָּה פָּנִים לַפָּנִים הַנּוֹרָאִים, וְכַמָּה אֲחוֹרִיִּים לַאֲחוֹרִים דְּלָאו הַנִּרְאִים, וְאִנּוּן פְּנִימִיִּים אִלֵּין יוּ'ד הֵ'י וָא'ו הֵ'י. יוּ'ד הֵ'י וָי'ו הֵ'י. יוּ'ד הֵ'א וָא'ו הֵ'א, אֲחוֹרִים, אִנּוּן י' י'ה יה'ו יהו'ה א' א\"ה אה\"י אהי'ה. א' א'ד אד'נ אדנ'י. כַּד אִנּוּן פְּנִימִיִּים מִלְּעֵלָּא כְּגוֹן טַעֲמֵי עַל אַתְוָן, אִנּוּן דְּכוֹרִין. וְכַד פְּנִימִיִּים אִנּוּן לְתַתָּא בְּגִין נִקּוּדִין תְּחוֹת אַתְוָן, אִנּוּן נוּקְבִין. וְכֻלְּהוּ אִשְׁתְּמוֹדָעוּ בְּרָזָא דָּא. כַּד אֶהְיֶ'ה עַל יהו'ה אִנּוּן נוּקְבָא. כֶּתֶר יִתְּנוּ לְךָ ה' אֱלֹהֵינוּ. וּבְכָל אֲתַר כֶּתֶר אִימָּא, וְתַרְוַיְהוּ אַרְמִיזוּ בְּשֵׁם אֲדֹנָ\"י א' אֶהְיֶ'ה י' יהו'ה. וְהָכֵי כַּד אדנ'י עַל יהו'ה אִיהוּ נוּקְבָא בַּת. כְּגַוְנָא דְּטִפָּה דִּדְכוֹרָא כַּד אַקְדִּים לְטִפָּה דְּנוּקְבָא, אִיהוּ בַּת. וְכַד נוּקְבָא אַקְדִימַת לִדְכוֹרָא אִיהוּ בֵּן. הָדָא הוּא דִּכְתִיב (בראשית ב׳:ד׳) בְּיוֹם עֲשׂוֹת יהו'ה אֱלֹהִי\"ם אֶרֶץ וְשָׁמַיִם. וּבְגִין דָּא עֶשֶׂר סְפִירוֹת מִסִּטְרָא דְּאֶהְיֶה מַתְחִילִים בְּאָת א', וְאִיהוּ ב' כֶּתֶר כְּחֻשְׁבַּן חַיָּ'ה וּמִתְפַּשְּׁטִין מִנֵּהּ עֶשֶׂר הַוְיָן, וְאִנּוּן הֶיֶה הָיָה אֶהְיֶה כְּגַוְנָא דְּאַתְוָן דְּאִנּוּן יְהוָֹ\"ה מֶלֶךְ יְהוָֹ\"ה מֶלֶךְ יְהוָֹ\"ה יִמְלֹךְ. דִּנְקֻדָּה דִּלְהוֹן הֶוֶה הָיָה וְיִהְיֶה דַּהֲוָיָה דָּא מַסְהִיד עַל עִלַּת כָּל עִלָּאִין, דְּאִיהוּ הָיָה קֹדֶם כֹּל הֲוָיָה, וְיִהְיֶה בָּתַר כָּל הֲוָה עַד אֵין סוֹף. וּמִסִּטְרָא דַּאֲדֹנָ\"י אִתְקְרֵי אֵין דְּאִתְרְמִיז בַּאֲרֹנָ\"י דְּאַסְהִיד עָלֵהּ דְּאִיהוּ אַחֲרִית עַד אֵין סוֹף וְתַכְלִית. וָאֱהִי סָהִיר עַל קַדְמוּתוֹ דְּלֵית קַדְמוֹן עָלֵהּ. וְסִימָנִיךְ דַּאֲחוֹרֵי' א\"י א\"י אֶהְיֶ\"ה יְהוָֹ\"ה. אֲדֹנָ\"י יְהוָֹה. אִנּוּן עֲשָׂרָה עֲשָׂרָה אַרְבַּע אַרְבַּע. אַרְבַּע רָשֻׁיּוֹת דְּשַׁבָּת דְּלֵית זָר בֵּינַיְהוּ, וְאִנּוּן תְּרֵין דְּכַר וְנוּקְבָא חַד לִימִינָא. וּדְכַר וְנוּקְבָא חַד לִשְׂמָאלָא. וּפָנַי לֹא יֵרָאוּ. י'א י'א יְהוָֹה אֱלֹהֵינוּ יְהוָֹה אֶחָד, וְכָל שְׁמָא רָחְבּוֹ אַרְבַּע וְגָבְהוֹ עֲשָׂרָה וְסַלְקִין אַרְבַּע אַרְבַּע לע\"ב, וְתַלְיָן מֵעֶשֶׂר. כְּגַוְנָא דָּא יוּ\"ד הֵ\"י וָי\"ו הֵ\"י. וְאִנּוּן יוּ\"ד עֶשְׂרִין. ה'י ה'י תְּלָתִין. וָי\"ו עֶשְׂרִין וּתְרֵין. סַלְקִין עָ\"ב.</p>"],[9514015282,"<p>כְּגַוְנָא דְּעֶשֶׂר אַתְוָן דְּאִנּוּן י' י'ה יה'ו הו'ה וְסַלְקִין לע\"ב. לֵית שְׁמָא בֵּין מע\"ב בֵּין ממ\"ב דְּלָא תַּלְיָא מֵעֶשֶׂר סְפִירָן. כְּגַוְנָא דְּכָל סְפִירָא אִתְכְּלִילָא מֵעֶשֶׂר סְפִירָן. אֲבָל עכ\"ד דְּתַלְיָן מֵעֶשֶׂר סְפִירָן, כָּל שְׁמָהָן צָרִיךְ כָּל חַד לְאִשְׁתְּמוֹדְעָא לֵהּ בִּסְפִירָא דִּילֵהּ. כְּגוֹן חֶסֶ'ד דְּסָלִיק ע'ב, בֵּהּ צָרִיךְ לְאִשְׁתְּמוֹדְעָא ע'ב הֲוָיוֹת דְּאִשְׁתְּכָחוּ מִשְּׁמָא דָּא, דְּאִיהוּ יוּד הֵי וָיו הֵי וְאִלֵּין אִנּוּן יהו הוה והי היה והו הוי ויו יוה והו ויה יהי היו יוי הוה והו והי ויו יוי היו יהה הוי והה הוו ויה יוו יוה ויי יהו היי ייה יהה והה יוו ויי ההי יוה ההו ויה היו ווי יהו ייו ייה הוי ההי ייה ווה ההו ייו ווי היו ווה יהו ייה הוי והי ייו ייה הוי ייו ייה הוי והי ייו ייו ויי ההו ייה והה ההו ייו ויו (אמ\"ז עין בתקונים ח\"א יש עוד ב' נסחאות אחרות גם בס' הפרדס שער פרטי השמות דקכ\"ג יש דרך אחר ואולי שהם בחינות שונות זו מזו אבל מה שצ\"ע הוא שלא יש בנסח זה כי אם ע\"א שמות) הָא הָכָא עָ\"ב הַוְיָן דְּאִתְּמַר בְּהוֹן יְהִי כָּךְ וִיהִי כָּךְ. אִלֵּין אִנּוּן בִּנְיָנָא דְּנִשְׁמָתָא. וְעָלַיְהוּ אִתְּמַר (תהלים כט) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה.</p>"],[9514015283,"<p>כָּל י' אִיהִי אַבְנָא וְאִיהִי יְסוֹדָא דְּבִנְיָנָא מִסִּטְרָא דְּצַדִּיק יְסוֹד עוֹלָם, דְּאִיהוּ יוֹם הַז' דְּבֵהּ וַיְכֻלּוּ, אִיהוּ כָּלִיל עָ\"ב הֲוָיוֹת. וְכָל ה' בִּנְיָנָא דְּבֵיתָא. כְּגוֹן בְּחָכְמָה יִבְנֶה בַּיִת. דְּצַדִּיק קִשּׁוּרָא דִּילֵהּ בְּחָכְמָה דְּאִיהִי י' עִלָּאָה. וְצַדִּיק אִיהוּ י' זְעֵירָא. שְׁכִינְתָּא תַּתָּאָה בֵּית ה' תַּתָּאָה וְדָא אִתְבְּנִיאַת בְּה' עִלָּאָה. ו' עַמּוּד סָבִיל כֹּלָּא וְאִיהוּ עַמּוּדָא דְּאֶמְצָעִיתָא אָרֹךְ בֵּין אַבָּא וְאִמָּא. וְאִיהוּ ו' זְעֵירָא בְּצַדִּיק. ה' דְּאִיהִי בֵּית ב'. אֶלָּא כְּגַוְנָא דְּאִית ג' גגין בְּדָא, הָכֵי אִית תְּלָת גַּגִּין בְּדָא, וְכָל נְקֻדָּה בְּאֶמְצָעִיתָא דְּכָל תֵּבָה, צָרִיךְ לְאַרְכָּא בָּהּ וּלְסַלְקָא בְּתִפְאֶרֶת וּלְאַכְלְלָא בָּהּ עֶשֶׂר סְפִירוֹת.</p>"],[9514015284,"<p>וְכָל נְקֻדָּה לְעֵלָּא מִן צָרִיךְ לְסַלְקָא מַחֲשָׁבוֹתֵהּ בְּכֶתֶר, וּלְנַחְתָּא לָהּ עַד מַלְכוּת. וְהָכֵי בְּכָל תֵּבָה וְתֵבָה. דִּתְנוּעָה דְּנִקּוּדֵי אִנּוּן בַּאֲתַר דְּטַעֲמֵי. וְכַד אִית טַעֲמֵי דְּאִנּוּן כִּתְרִין עַל אַתְוָן, לֹא צָרִיךְ לְמֶעֱבַד תְּנוּעָה בְּאָת מִן תֵּבָה, אֶלָּא בְּהַהִיא דְּתָגָא עָלַהּ. וְעוֹד שְׁכִינְתָּא אע\"ג דְּאִיהִי כְּלִילָא מֵעֶשֶׂר סְפִירוֹת וּבָהּ אִתְקְרִיאוּ כֻּלְּהוּ אֲחוֹרַיִם. הָכֵי כַּד מִתְיַחֲדִים בָּהּ סְפִירָן דְּאִנּוּן פְּנִימִיִּים, כָּל סְפִירָאָן אִתְקְרִיאוּ מִסִּטְרָא פְּנִימִיִּים. וְאִית סְפִירָאָן דְּאִנּוּן לִפְנַי לִפְנִים. וְכַד אִתְכְּלִילָן בָּהּ כָּל סְפִירָן, אִתְקְרִיאוּ לִפְנַי וְלִפְנִים. וּפְנִימִיִּים וּפְנִימִיִּים דִּפְנִימִיִּים וַאֲחוֹרִיִּים כֻּלְּהוּ אִנּוּן חַד. וְלָאו אִנּוּן כְּגַוְנָא דְּבַר נָשׁ דְּגוּפֵהּ מִינָא חֲדָא, וְנִשְׁמָתֵהּ מִינָא אָחֳרָא, אֲבָל לְעֵלָּא כֹּלָּא חַד. אֶלָּא כָּל נְהוֹרָא וְכָל דַּרְגָּא דְּאִיהִי יַתִּיר, קְרִיבָא לְעִלַּת כָּל עִלָּאִין. אִתְקְרִיאַת לִפְנַי וְלִפְנִים. וְעוֹד שְׁכִינְתָּא אִתְקְרִיאַת פַּרְדֵּס דְּאוֹרַיְתָא, עַל שֵׁם דְּאִיהִי כְּלִילָא 'מִפְּשָׁט 'רְאִיָּה' 'דְּרָשָׁה 'סוֹד דְּאוֹרַיְתָא דָּא הוּא סִימָן פַּרְדֵּס. וְאִתְקְרִיאַת עֵץ חַיִּים מִסִּטְרָא דְּצַדִּיקִים גְּמוּרִים דְּלֵית בְּהוֹן פְּסֹלֶת. וּמִסִּטְרָא דְּכַמָּה אִילָנִין אִנּוּן, דִּמְאִיבָא דִּילְהוֹן אִשְׁתְּמוֹדְעַת שְׁכִינְתָּא בֵּינְהוֹן כְּפוּם עוֹבָדֵיהוֹן. כְּגוֹן אֱגוֹז דְּאִיבָא דִּילָהּ סְתִימָא וַחֲתוּמָה, הַאי אִיהוּ רָמִיז לִשְׁכִינְתָּא דְּאִתְּמַר בָּהּ (שיר השירים ד׳:י״ב) גַּן נָעוּל אֲחֹתִי כַּלָּה גַּל נָעוּל מַעְיָן חָתוּם. כְּגָוָן יַיִן דְּאִיהוּ סָתוּם וְחָתוּם, דְּלָא אִתְהַנְּיָן מִנֵּהּ רַשִּׁיעַיָּא, וְלָא אִתְנְבַךְ, הָכֵי נַמֵּי אִיהִי שְׁכִינְתָּא סְתִימָא וַחֲתִימָא בֵּין רַשִּׁיעַיָּא דְּלָא אִתְהַנְּיָן מִנַּהּ. וְאוֹר דִּילַהּ אִתְּמַר בֵּהּ (שמות ב׳:ב׳) וַתֵּרֶא אֹתוֹ כִּי טוֹב הוּא וַתִּצְפְּנֵהוּ. וְהָכֵי אוֹרַיְתָא רָזִין דִילָהּ סְתִימִין וַחֲתִימִין דְּלָא אִתְהַנְּיָן מִנְּהוֹן רַשִּׁיעַיָּא. וּבְגִין דָּא אֱכֹל דְּבַשׁ וְשָׁתֵי חַמְרָא וְאַל תְּלַמְּדֵהוּ לַגּוֹי. ועכ\"ד.</p>"],[9514015285,"<p>דְּבַשׁ מָצָאתָ אָכֹל דַּיֶּךָ. דִּבְמַה (משלי כ״ה:ט״ז) שֶּׁהֻרְשֵׁיתָ הִתְבּוֹנֵן וְאֵין לְךָ עֵסֶק בַּנִּסְתָּרוֹת. וּכְגַוְנָא דְּמֹחָא דֶּאֱגוֹז סָתִים הָכֵי אִיהִי שְׁכִינְתָּא סְתִימָא. וְאִיהִי אֲסוּרָא בְּגָלוּתָא בֵּין רַשִּׁיעַיָּא. וּבְגִינַיְהוּ אִתְּמַר (איכה א׳:י״ד) נְתָנַנִי ה' בִּידֵי לֹא אוּכַל קוּם. דִּבְהוֹן אִיהִי סוֹגֶרֶת וּמְסֻגֶּרֶת. וּבֵין צַדִּיקַיָּא לֵית בָּהּ פְּסֹלֶת. וּבַבֵּינוֹנִיִּים מָארֵי תְּיוּבְתָּא אִיהִי סַמָּאֵ\"ל אָסִיר בַּפְּסֹלֶת דְּתַמְרָא דְּאִיהוּ אָסִיר וְסָתִים מִלְּגָאו וְלֵית לֵהּ רְשׁוּ לְשַׁלְטָאָה. וְעוֹד מִסִּטְרָא דְּבֵינוֹנִיִּים אִיהִי כְּשׁוֹשַׁנָּה בֵּין הַחוֹחִים, כְּגַוְנָא דִּירוּשְׁלֵם דְּאִתְּמַר (יחזקאל ה׳:ה׳) זֹאת יְרוּשָׁלַםִ בֵּין הַגּוֹיִם שַׂמְתִּיהָ וּסְבִיבוֹתֶיהָ אֲרָצוֹת. דָּא הִיא שְׁכִינְתָּא שָׁרְשָׁא דְּאִילָנָא בְּגוֹ גּוֹבִין, דְּאִנּוּן עֶשֶׂר כִּתְרִין תַּתָּאִין, דְּאִתְּמַר בְּהוֹן הַשּׁוֹכֵן אִתָּם בְּתוֹךְ טֻמְאָתָם. וְאִנּוּן אַרְעִין דְּשִׁפְחָה שֶׁמַּטְרוֹנִיתָא, דְּעָלַיְהוּ אִתְּמַר וּסְבִיבוֹתֶיהָ אֲרָצוֹת. וְלֹא עוֹד אֶלָּא כָּל מְזוֹנִין דְּחַמְרֵי וְכַלְבֵי, דְּאִנּוּן חַיָּלִין דְּסַמָּאֵ\"ל וְנָחָשׁ דְּשָׁלְטִין בְּמִשְׁמָרוֹת דְּלֵילְיָא, כְּמָא דְּאוֹקְמוּהּ מ\"מ, מִשְׁמָרָה רִאשׁוֹנָה חֲמוֹר נוֹעֵר. שְׁנִיָּה כְּלָבִים צוֹעֲקִים, כֻּלְּהוּ הֲווֹ צָוְחִין לְגַבֵּי מַטְרוֹנִיתָא, לְמֵיהַב לוֹן מְזוֹנָא לְקַיִּם בְּהוֹן וּמַלְכוּתוֹ בַּכֹּל מָשָׁלָה. הָא שְׁכִינְתָּא כְּלִילָא מֵעִלָּאִין וְתַתָּאִין אִיהִי מַבּוּעָא דְּאִילָנָא מִסִּטְרָא דְּאָת י'. וְאִיהִי מְקוֹר מַיִם חַיִּים מִסִּטְרָא דְּכֶתֶר, מְקוֹרָא דְּלֵית לֵהּ סוֹף. וְאִיהִי יַמָּא דְּאוֹרַיְתָא מִסִּטְרָא דְּאִמָּא עִלָּאָה, וּבָהּ מִתְפַּלְּגִין שֶׁבַע סְפִירָן לְז' נַחֲלִין. הָדָא הוּא דִּכְתִיב (ישעיהו י״א:ט״ו) וְהִכָּהוּ לְשִׁבְעָה נְחָלִים. וְאִיהִי איבא דְּאִילָנָא מִסִּטְרָא דְּאָת י'. וְאִיהִי גּוּפָא דְּאִילָנָא מִסִּטְרָא דְּאָת ו'. וְאִיהִי עַנְפִּין דְּאִילָנָא מִסִּטְרָא דְּאָת ה' עִלָּאָה. וְאִיהִי שֹׁרֶשׁ' דְּאִילָנָא מִסִּטְרָא דְּאָת ה' תַּתָּאָה דְּאִיהִי גַּן, דְּבֵהּ נָטַע אִילָנָא מִסִּטְרָא דַּאֲדֹנָ\"י. וְאִיהִי אָדָם דְּאִתְּמַר בֵּהּ (בראשית י) וַיִּטַע ה' אֱלֹהִים גַּן בְּעֵדֶן מִקֶּדֶם וַיָּשֶׂם שָׁם אֶת הָאָדָם אֲשֶׁר יָצַר. אִיהִי אָדָם מִסִּטְרָא דִּשְׁמָא מְפָרֵשׁ יוּ\"ד הֵ\"א וָא\"ו הֵ\"א אִיהִי כְּלִילָא מִכָּל שְׁמָהָן עִלָּאִין. וּבְגִין דְּאִיהִי כְּלִילָא מֵעִלָּאִין וְתַתָּאִין, שַׁרְיָא עָלַהּ עִלַּת כָּל עִלָּאִין ובי' שֻׁלְטָנוּתָא עַל כֹּלָּא. קוּם אֵלִיָּהוּ לְשַׁבְּחָא לְעִלַּת כָּל עִלָּאִין, דְּאַתְּ תְּהֵא אַקְדִּים לְכָל נְבִיאָה בְּדָרָא דִּמְשִׁיחָא. דְּאִית לְמָאן דְּאַתְּ עָתִיד לְאִתְגַּלָּאָה לֵהּ מִסִּטְרָא דְּנִשְׁמָתֵהּ בַּשֵּׂכֶל דִּילֵהּ. וְאִית לְמָאן דְּאַתְּ עָתִיד לְאִתְגַּלְּיָא לֵהּ פָּנִים בְּפָנִים מִסִּטְרָא דְּגוּפֵהּ, מִסִּטְרָא דְּנִשְׁמָתֵהּ בַּשֵּׂכֶל דִּילֵהּ וְאִית לְמָאן דְּאַתְּ עָתִיד לְאִתְגַּלְּיָא לֵהּ.</p>"],[9514015286,"<p>קוּם אַפְתַּח מִלִּין קַמֵּי שְׁכִינְתָּא. מִיָּד פָּתַח וְאָמַר. וְהַמַּשְׂכִילִים יַזְהִרוּ. מָאן מַשְׂכִּילִים. אִלֵּין דְּאִית בְּהוֹן שֵׂכֶל לְמִנְדַּע לְמָארֵי עָלְמִין, דְּאִיהוּ עָלִית כָּל עִלָּאִין בִּשְׁכִינְתָּא, דְּאִתְּמַר בָּהּ (תהילים קי״ח:כ׳) זֶה הַשַּׁעַר לַה' צַדִּיקִים יָבֹאוּ בּוֹ. שַׁעַר בְּהִפּוּךְ אַתְוָן עֶשֶׂר כְּלִילָא מֵעֶשֶׂר סְפִירָן. וּמִסִּטְרָא דִּילְהוֹן אִיהִי גְּבוּל. כְּגוֹן יַמָּא דְּאִתְּמַר בֵּהּ (ירמיהו ה׳:כ״ב) אֲשֶׁר שַׂמְתִּי חוֹל גְּבוּל לַיָּם. הָכֵי אִיהִי גְּבוּל וּתְחוּם לִשְׁמָא דיהו'ה, דְּאִיהִי רְשׁוּת הַיָּחִיד דִּתְחוּמֵהּ, אִיהוּ שְׁמוֹנָה אֲלָפִים אַמָּה, אֲלָפִים לְכָל סִטְרָא. וְאִנּוּן, יאהדונהי. וּרְשׁוּת אִיהִי לַיָּחִיד דְּאִיהוּ רָחְבּוֹ דַּק וְגָבְהוֹ עֲשָׂרָה אִיהִי גְּבוּל לְיַמָּא דְּאוֹרַיְתָא, דְּאִיהִי אִימָּא עִלָּאָה דְּגַלְגַּלּוֹי דְּאִשְׁתְּכָחוּ מִן חָכְמָה, דְּאִיהוּ כָּל הָעִלּוֹת דְּלֵית לְעֵלָּא מִנֵּהּ, לֵית לָהּ גְּבוּל מִסִּטְרֵהּ, וְלֵית לָהּ תְּחוּם מִסִּטְרֵהּ וְלֹא רְשׁוּת עָלֵהּ, וְלֹא בַּר מִנֵּהּ. וְלֵית לֵהּ מִדָּה וְשִׁעוּר. וְלֹא עוֹד אֶלָּא מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא אִית לָהּ שִׁתּוּף וְחִבּוּר, כְּגוֹן דְּכַר וְנוּקְבָא דְּאִיהִי דַּק וְשִׁתּוּפָא דִּילֵהּ א'ח וְתַרְוַיְהוּ אֶ'חָד אֲבָל מִסִּטְרָא דְּעִלַּת כִּלְ הָעִלּוֹת. אֶחָד בְּלֹא שִׁתּוּף. וְלֹא עוֹד אֶלָּא מִסִּטְרָא דְּאֶחָד, אִיהִי ד' עִמֵּהּ י\"ג אֶחָ'ד הַמָּנוּי. אֲבָל מִסִּטְרָא דְּעִלַּת עַל כָּל עִלָּאִין אִיהִי אֶחָד. וְלֹא כְּכָל אֶחָד הַכִּנּוּי וְהַמִּנּוּי דְּאִיהוּ כִּנּוּי ליהו'ה. אֱלֹהִים וַדַּאי הָכֵי סְלִיקַת בְּחֻשְׁבָּן כִּנּוּ\"י. וּמִסִּטְרָא דְּמָארֵי עַל כֹּלָּא לֵית לֵהּ כִּנּוּ\"י. וְעֹד מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָעִיתָא אִתְקְרִיאַת. בֵּית קִבּוּל דִּלְזִמְנִין נָחִית לָהּ נְבִיעוּ. וְאִיהִי מְלֵאָה דְּהָכֵי אַתְוָן דֵּאלֹהִים מְלֵאָ\"ה. וּלְזִמְנִין אִיהִי יְבֵשָׁה כְּגוֹן (רות א׳:כ״א) אֲנִי מְלֵאָה הָלַכְתִּי וְרֵיקָם הֱשִׁיבַנִי ה'. וּמִסִּטְרָא דְּעִלַּת עַל כָּל עִלָּאִין לֹא יֶחְסַר וְלֹא יַעְדִּיף. נְבִיעוּ נְהוֹרֵהּ דְּכָל סְפִירָן מְקַבְּלִין דֵּין מִדֵּין. וְיַכְלִינָן לְמֶעֱבַד תַּמָּן דִּמְיוֹן כְּגַוְנָא דִּנְבִיעוּ דְּמַיִן, דְּאַשְׁקֵי לְאִילָנָא וְאִם חָסֵר הַהוּא נְבִיעוּ מִנֵּהּ, אִיהוּ חָרֵב וְיָבֵשׁ. כְּגַוְנָא דְּנָהָר דְּאִתְּמַר בֵּהּ אָזְלוּ מַיִם מִנִּי יָם וְגוֹ'.</p>"],[9514015287,"<p>אֲבָל בְּעִלַּת עַל כָּל עִלָּאִין לְיָת לְעֵלָּא מִנֵּהּ דְּאוֹסִיף בֵּהּ וְגָרַע בֵּהּ דִּבְכָל סְפִירָן אִיהוּ גָּרַע נְבִיעוּ מִנְּהוֹן, וְאוֹסִיף לוֹן נְבִיעוּ. כְּגַוְנָא דִּשְׁכִינְתָּא דִּלְזִמְנִין אִיהִי מְלֵאָה. וּלְזִמְנִין אִיהִי חֲסֵרָה וְהָכֵי כָּל סְפִירָה וּסְפִירָה. וְאִיהוּ דְּאוֹסִיף וְגָרַע בְּכֻלְּהוּ, וְלֵית עָלֵהּ דְּאוֹסִיף וְגָרַע. וְלֹא עֹד אֶלָּא אִיהוּ אֲפִלּוּ תֵּשַׁע סְפִירָן דְּאִנּוּן כְּלָלָא דא\"ח, דְּאִיהוּ עַמּוּדָא דְּאֶמְצָעִיתָא כָּלִיל מֵאִנּוּן תֵּשַׁע. וְעִלַּת עַל כָּל עִלָּאִין לֹא נָחִית עָלֵהּ יִחוּדֵהּ, עַד דְּאַפִּיק לֵהּ בַּת זוּגֵהּ כְּלִילָא מֵעֶשֶׂר סְפִירָן, וּבְגִינַהּ נָחִית עָלֶיהָ יִחוּדֵהּ בְּגִין דְּתְהֵא חֲבִיבָה עָלֵהּ. וְאִיהוּ דְּאָחִיד בְּתַרְוַיְהוּ. וּבְגִין כָּךְ אִנּוּן א\"ח ד'. דְּאִית שִׁתּוּפָא דְּתַרְוַיְהוּ כְּגוֹן צַדִּיק דְּאִתְּמַר בֵּהּ כִּי כֹּל בַּשָּׁמַיִם וּבָאָרֶץ, וְתִרְגֵּם אֻנְקְלוֹס דְּאָחִיד בִּשְׁמַיָּא וּבְאַרְעָא. שִׁתּוּפָא דִּילֵהּ כְּגַוְנָא דִּבְרִית מִלָּה דְּאָחִיד בִּדְכַר וְנוּקְבָא, וְאִיהוּ לְזִמְנִין יְדִיעָן אִית זִוּוּגָא, וּלְזִמְנִין אַפְרָשׁוּתָא. כְּגוֹן אַהֲרֹן כַּהֲנָא דְּאִתְּמַר בֵּהּ (ויקרא ט״ז:ב׳) וְאַל יָבֹא בְּכָל עֵת אֶל הַקֹּדֶשׁ. וְזִמְנִין בְּזֹאת יָבוֹא אַהֲרֹן אֶל הַקֹּדֶשׁ כְּגַוְנָא דְּאִתְּתָא דִּלְזִמְנִין אִיהִי נִדָּה מְרַחֲקָא מִבַּעְלָהּ, וּלְזִמְנִין אִיהִי דַּכְיָא מֻתֶּרֶת לְבַעְלָהּ, אֲבָל כַּד עִלַּת עַל כָּל עִלָּאִין, בֵּינַיְהוּ לֵית תַּמָּן נִדּוֹת וְלֹא רִחוּק, וְלֹא קִצּוּץ, וְלֹא פֵּרוּד, וְאִיהוּ דְּקָשַׁר עֶשֶׂר סְפִירָן פְּנִימִיִּים וְעֶשֶׂר סְפִירָן חִיצוֹנִיִּים לְגַבַּיְהוּ. וּבְגִין דְּאִיהוּ מִלְּגָאו שַׁוֵּי אֱמוּנָה דְּיִשְׂרָאֵל בְּהוֹן, בְּהַהִיא דְּהִיא קִשּׁוּרָא בְּכֻלְּהוּ פְּנִימִיִּים וְחִיצוֹנִיִּים דְּאִיהִי כְּלִילָא מֵעִלָּאִין וְתַתָּאִין, עַד דְּלֵית סוֹף וְתַכְלִית. וּבְגִין דָּא קָרָא לָהּ אֱמוּנָה דְּיִשְׂרָאֵל דְּבָהּ אִשְׁתְּמוֹדָעוּ עִלָּאִין וְתַתָּאִין, וְעִלַּת עַל כָּל עִלָּאִין. וּמָאן דִּמְיַחֵד לֵהּ בָּהּ, כְּאִלּוּ מְיַחֵד לֵהּ וְאַמְלִיךְ לֵהּ עַל כָּל עִלָּאִין וְתַתָּאִין. קָמַת שְׁכִינְתָּא מִכֻּרְסֵא דִּילֵהּ וּנְשִׁיקַת לֵהּ, וְרָעֲיָא מְהֵימָנָא נָשִׁיק לֵהּ, וְכָל עִלָּאִין וְתַתָּאִין בָּרִיכוּ לֵהּ וִיהָבוּ לֵהּ נַבְזַבְזָן. ע\"כ רָזָא דְּיִחוּדָא. מִכָּאן וְאֵילָךְ סִתְרֵי אוֹרַיְתָא וְטַעֲמֵי אוֹרַיְתָא.</p>"],[9514015288,"<p>קוּם בּוּצִינָא קַדִּישָׁא אַפְתַּח מִלִּין קַמֵּי שְׁכִינְתָּא, לְנַחְתָּא נְבִיעוּ לְגַבָּהּ מִמִּשְׁחָא קַדִּישָׁא, דְּאִתְּמַר בֵּהּ (שמות כ״ז:כ׳) שֶׁמֶן זַיִת זַךְ כַּתִּית לַמָּאוֹר לְהַעֲלוֹת נֵר תָּמִיד. דְּאִיהִי שְׁכִינְתָּא דְּאִתְּמַר בָּהּ (משלי כו) נֵר ה' נִשְׁמַת אָדָם. בְּגִינַהּ אִתְּמַר אֵשׁ תָּמִיד תּוּקַד עַל הַמִּזְבֵּחַ לֹא תִכְבֶּה. וְהָכֵי לֹא תִכְבֶּה נִשְׁמָתֵהּ דְּמָאן דְּיִתְעַסֵּק בָּהּ תָּמִיד. אַל תִּתְּנוּ דֹּמִּי לְקוּדְשָׁא בְּרִיךְ הוּא עַד דְּיִתְּעַר לְגַבָּהּ. דְּשַׂרְגָּא לֵית שְׁכִיבוּ לַגַּבֵּהּ הָדָא הוּא דִּכְתִיב לְמַעַן יְזַמֶּרְךָ כָּבוֹד וְלֹא יִדֹּם. דְּאִיהִי כָּבוֹד דִּילֵהּ יְקָרָה הִיא מִפְּנִינִים וְכָל חֲפֵצִים לֹא יִשְׁווּ בָּהּ.</p>"],[9514015289,"<p>קָם בּוּצִינָא קַדִּישָׁא פָּתַח וְאָמַר, בְּרֵאשִׁית בָּרָא אֱלֹהִים. רִבּוֹן עָלְמָא יְהֵא רַעֲוָא דִּילָךְ לְקַיְּמָא בִּי וְאָנֹכִי אֶהְיֶה עִם פִּיךָ וְהוֹרֵתִי אֲשֶׁר תְּדַבֵּר. דְּלֹא בְּגִין יְקָרָא דִּילִי עֲבִידְנָא, אֶלָּא לְאַפְתְּחָא מִלִּין קַמֵּי שְׁכִינְתָּךְ. פָּתַח וְאָמַר זִמְנָא תִּנְיָנָא. סוֹ'ד ה' לִירֵאָיו. אִיהוּ ע' אַנְפִּין דְּסִתְרֵי תּוֹרָה דְּצָרִיךְ לְפָרְשָׁא בְּהוֹן ע' זִמְנִין בְּעוֹבָדָא דְּפָרָשָׁתָא דָּא דִּבְרֵאשִׁית.</p>"],[9514015290,"<p>בְּרֵאשִׁית זִמְנִין סַגִּיאִין אִנּוּן בְּאוֹרַיְתָא רֵאשִׁית, וְכָל חַד אִתְפְּרַשׁ בְּאַתְרֵהּ. קַדְמָאָה אִיהוּ (משלי ח) ה' קָנָנִי רֵאשִׁית דַּרְכּוֹ. דָּא אוֹרַיְתָא דְּאִית בֵּהּ טַעֲמֵי וְנִקּוּדֵי וְאַתְוָן. וְכַמָּה פִּקּוּדִין דַּעֲשֵׂה וְלֹא תַעֲשֶׂה דְּכֻלְּהוּ תַּלְיָן בְּשֵׁם יהו'ה. הָדָא הוּא דִּכְתִיב זֶה שְׁמִי לְעֹלָם וְזֶה זִכְרִי לְדֹר וָדֹר. שְׁמִי עִם י'ב שְסָ\"ה. זִכְרִי עִם ו'ה רמ\"ח. שְסָ\"ה מִשְּׂמָאלָא, מִדְּחִילוּ דִּגְבוּרָה אִתְיְהִיבוּ פַּחַד יִצְחָק. רמ\"ח מִימִינָא, מֵרְחִימוּ דְּדַרְגָּא דְּאַבְרָהָם דְּאִתְּמַר בֵּהּ (ירמיה ב) אַהֲבַת עוֹלָם אֲהַבְתִּיךְ עַל כֵּן מְשַׁכְתִּיךְ חֶסֶד. עַמּוּדָא דְּאֶמְצָעִיתָא כָּלִיל תַּרְוַיְהוּ. וּבְגִין דָּא אִתְקְרֵי בְּשֵׁם יהו'ה. אֲבָל יְמִינָא אֵ\"ל נָטִיל עִמֵּהּ וָ\"ה הָדָא הוּא דִּכְתִיב אֱלוֹהַּ מִתֵּימָן יָבוֹא. שְׂמָאלָא נָטִיל עִמֵּהּ י'ה מִן אֱלֹהִים, עַמּוּדָא דְּאֶמְצָעִיתָא נָטִיל שְׁמָא שְׁלִים. וּבְגִין דָּא אֵל אֱלֹהִים ה' דִּבֵּר וַיִּקְרָא אָרֶץ. כָּלִיל לוֹן בְּהַאי קְרָא. וְכָל פִּקּוּדָא אִית לֵהּ טַעְמָא יְדִיעָא לְעֵלָּא, וְאַגְרָא דִּילֵהּ יְדִיעַ לְאִנּוּן דְּיַדְעִין רָזִין סְתִימִין דְּמָארֵיהוֹן. לָא אִתְכַּסְּיָא מִנְּהוֹן כָּל רָז. הָדָא הוּא דִּכְתִיב (דניאל ד) וְכָל רָז לָא אָנִיס לָךְ. וְכָל אוֹת וְאוֹת דְּאוֹרַיְתָא, וְקוֹצָא דִּילֵהּ וּנְקֻדָּה דִּילֵהּ וְטַעְמֵי דִּילֵהּ, אִית לוֹן רָזִין סְתִימִין לְעֵלָּא. וְהַמַּשְׂכִּילִים אִשְׁתְּמוֹדְעָן בְּהוֹן דְּאִית בְּהוֹן חֵילָא לְמֵיקָם בְּהֵיכָלָא דְּמַלְכָּא. כְּגַוְנָא דְּאִתְּמַר בַּחֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה (שם א) וַאֲשֶׁר כֹּחַ בָּהֶם לַעֲמֹד בְּהֵיכַל הַמֶּלֶךְ, בַּעֲמִידָה דִּצְלוֹתָא דְּאִיהִי הֵיכַל הַמֶּלֶךְ, כְּלִילָא מִכָּל טַעְמֵי וְנִקּוּדֵי וְאַתְוָן. דְּלֵית יְדִיעָה כִּידִיעָה דִּנְקֻדֵּי וְטַעְמֵי דְּאַתְוָן, לְאִשְׁתְּמוֹדְעָא בְּהוֹן סְגוֹלְתָּא, דְּאִתְּמַר בֵּהּ זַרְקָא מֻקָּף שׁוֹפָר הוֹלֵךְ סְגוֹלְתָא. וְכֻלְּהוּ אִתְרְמִיזוּ בְּהַוְיָן כְּגַוְנָא דָּא י'י'י' ה'ה'ה' ו'ו'ו' ה'ה'ה'. בְּכָל אֲתַר דאנון תְּלָת יוּדִי\"ן כַּחֲדָא רְמִיזִין י'י'י' לִסְגוֹלְתָא, דְּאִיהִי שְׁכִינְתָּא כְּלִילָא מִן חָכְמָה חָסֵר נֶצַח. חָכְמוֹת בַּחוּץ תָּרֹנָּה. וּבְגִינַיְהוּ אוּקְמוּהּ מָארֵי מַתְנִיתִין הָרוֹצֶה לְהַחְכִּים יַדְרִים. דְּכֻלְּהוּ תְּלָתָא אִנּוּן דְּרוֹמִיִּים. גְּבוּרָא הוֹד. וְכֻלְּהוּ לְצָפוֹן. וּבְגִינַיְהוּ אִתְּמַר הָרוֹצֶה לְהַעֲשִׁיר יַצְפִּין. זַכָּאָה אִיהוּ מָאן דִּמְכַוֵּן בְּהוֹן. לְנַחְתָּא חָכְמְתָא וְעוּתְרָא לִשְׁכִינְתָּא, דְּאִתְּמַר בָּהּ קְדֻשָּׁה לְךָ יְשַׁלְּשׁוּ. דְּהָכֵי אִיהוּ סְגוֹלְתָא דִּילְהוֹן לְנַחְתָּא חָכְמְתָא וְעוּתְרָא.</p>"]]});
